    fn value_is_v16_bool_mask_const(&self, vid: ValueId, seen: &mut HashSet<ValueId>) -> bool {
        if !seen.insert(vid) {
            return false;
        }

        let is_const = match self.find_value_producer(vid).map(|node| &node.inst) {
            Some(Inst::Const { ty, value }) if Self::is_v16_bool_ty(ty) => {
                Self::constant_bool_mask_lanes(value, 16).is_some()
            }
            Some(Inst::Copy { operand, .. }) => self.value_is_v16_bool_mask_const(*operand, seen),
            _ => false,
        };

        seen.remove(&vid);
        is_const
    }

