    fn validate_bool_condition(&self, context: &str, cond: ValueId) -> Result<(), AdapterError> {
        let cond_ty = self
            .lookup_value_ty(cond)
            .ok_or_else(|| AdapterError::UnknownValue(cond.index()))?;
        if cond_ty != Ty::Bool {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} condition {cond:?} must have type Bool, got {cond_ty:?}"
            )));
        }
        Ok(())
    }

    fn validate_pointer_like_value(
        &self,
        context: &str,
        value: ValueId,
    ) -> Result<(), AdapterError> {
        let value_ty = self
            .lookup_value_ty(value)
            .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
        if !Self::is_pointer_like_ty(&value_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} value {value:?} must have pointer-like type, got {value_ty:?}"
            )));
        }
        Ok(())
    }

    fn validate_select_operands(
        &self,
        ty: &Ty,
        cond: ValueId,
        then_val: ValueId,
        else_val: ValueId,
    ) -> Result<(), AdapterError> {
        let then_ty = self
            .lookup_value_ty(then_val)
            .ok_or_else(|| AdapterError::UnknownValue(then_val.index()))?;
        // Signedness is carried by the consuming opcode, not by the SSA value's
        // type — so a same-width signed/unsigned integer operand selects the same
        // bits as the declared result type (see `validate_binary_operand_tys`,
        // which relaxes the binop operand check identically). Width/shape
        // mismatches still fail closed.
        // Pointer-like carriers (Ptr / Ref / RefMut / PtrConst / PtrMut /
        // Func) are all the same 64-bit address bits — `is_pointer_like_ty`
        // already treats them interchangeably everywhere addresses flow — so
        // selecting between two `Func(_)` references into a `Ptr` result
        // (a dispatch table of named functions) is the address analogue of
        // the integer relaxation above.
        let pointer_like_pair = |operand: &Ty, result: &Ty| {
            Self::is_pointer_like_ty(operand) && Self::is_pointer_like_ty(result)
        };
        if then_ty != *ty
            && !Self::same_width_int_scalar(&then_ty, ty)
            && !pointer_like_pair(&then_ty, ty)
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select then operand type {then_ty:?} does not match result type {ty:?}"
            )));
        }

        let else_ty = self
            .lookup_value_ty(else_val)
            .ok_or_else(|| AdapterError::UnknownValue(else_val.index()))?;
        if else_ty != *ty
            && !Self::same_width_int_scalar(&else_ty, ty)
            && !pointer_like_pair(&else_ty, ty)
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select else operand type {else_ty:?} does not match result type {ty:?}"
            )));
        }

        if Self::is_v16i8_ty(ty) || Self::is_v8i16_ty(ty) {
            return self.validate_narrow_select_condition(ty, cond);
        }

        let cond_ty = self
            .lookup_value_ty(cond)
            .ok_or_else(|| AdapterError::UnknownValue(cond.index()))?;

        if Self::is_v4i32_ty(ty) {
            if !Self::is_v4_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <4 x i32> requires canonical logical <4 x bool> condition, got {cond_ty:?}"
                )));
            }
            let is_compare_mask = self.value_is_v4i32_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v4_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <4 x i32> condition ValueId({}) must be produced by a <4 x i32> ICmp or canonical logical <4 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        if Self::is_v2i64_ty(ty) {
            if !Self::is_v2_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <2 x i64> requires canonical logical <2 x bool> condition, got {cond_ty:?}"
                )));
            }
            let is_compare_mask = self.value_is_v2i64_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v2_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <2 x i64> condition ValueId({}) must be produced by a <2 x i64> ICmp or canonical logical <2 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        if matches!(ty, Ty::Vector(_, _)) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select over unsupported vector shape {ty:?}; only <16 x i8>, <8 x i16>, <4 x i32>, and <2 x i64> vector selects are lowered today"
            )));
        }

        if cond_ty != Ty::Bool {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Select scalar condition must be Bool, got {cond_ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_narrow_select_condition(
        &self,
        payload_ty: &Ty,
        cond: ValueId,
    ) -> Result<(), AdapterError> {
        let cond_ty = self
            .lookup_value_ty(cond)
            .ok_or_else(|| AdapterError::UnknownValue(cond.index()))?;

        if Self::is_v16i8_ty(payload_ty) {
            if !Self::is_v16_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <16 x i8> requires canonical logical <16 x bool> condition, got {cond_ty:?}"
                )));
            }

            let is_compare_mask = self.value_is_v16i8_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v16_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <16 x i8> condition ValueId({}) must be produced by a <16 x i8> ICmp or canonical logical <16 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        if Self::is_v8i16_ty(payload_ty) {
            if !Self::is_v8_bool_ty(&cond_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <8 x i16> requires canonical logical <8 x bool> condition, got {cond_ty:?}"
                )));
            }

            let is_compare_mask = self.value_is_v8i16_icmp_result(cond, &mut HashSet::new());
            let is_const_mask = self.value_is_v8_bool_mask_const(cond, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Select over <8 x i16> condition ValueId({}) must be produced by a <8 x i16> ICmp or canonical logical <8 x bool> constant",
                    cond.index()
                )));
            }
            return Ok(());
        }

        Ok(())
    }

    fn constant_bool_mask_lanes(value: &Constant, lane_count: usize) -> Option<Vec<bool>> {
        let elems = match value {
            Constant::Vector(elems) | Constant::Aggregate(elems) | Constant::Array(elems) => elems,
            _ => return None,
        };
        if elems.len() != lane_count {
            return None;
        }

        elems
            .iter()
            .map(|lane| match lane {
                Constant::Bool(value) => Some(*value),
                Constant::Int(0) => Some(false),
                Constant::Int(1) => Some(true),
                _ => None,
            })
            .collect()
    }

    fn require_v4i32_lane_index(&self, index: ValueId, context: &str) -> Result<u32, AdapterError> {
        let index_ty = self.lookup_value_ty(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3, but index type is unknown"
            ))
        })?;
        if index_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3, got index type {:?}",
                index_ty
            )));
        }

        let lane = self.lookup_const_int(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3"
            ))
        })?;
        if !(0..=3).contains(&lane) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..3, got {lane}"
            )));
        }

        Ok(lane as u32)
    }

    fn require_v2i64_lane_index(&self, index: ValueId, context: &str) -> Result<u32, AdapterError> {
        let index_ty = self.lookup_value_ty(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1, but index type is unknown"
            ))
        })?;
        if index_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1, got index type {:?}",
                index_ty
            )));
        }

        let lane = self.lookup_const_int(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1"
            ))
        })?;
        if !(0..=1).contains(&lane) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires i64 constant lane index 0..1, got {lane}"
            )));
        }

        Ok(lane as u32)
    }

    fn trust_ir_ty_is_pointer_carrier(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Ptr
                | Ty::FatPtr(_)
                | Ty::Func(_)
                | Ty::Ref(_)
                | Ty::RefMut(_)
                | Ty::PtrConst(_)
                | Ty::PtrMut(_)
                | Ty::Rc(_)
                | Ty::Closure(_)
        )
    }

    /// True iff `ty` is an in-memory aggregate type (struct, tuple, array,
    /// record, or tagged-union enum).
    ///
    /// A by-value aggregate CALL ARGUMENT is constructed and carried by ADDRESS:
    /// the frontend materializes the aggregate into a fresh `Alloca` and passes
    /// that pointer (a `Ty::Ptr` value), and the call lowering re-types the LIR
    /// argument Value to the aggregate so ISel applies the System V register-pair
    /// / `sret` classification (see `record_aggregate_call_arg_types`). So when a
    /// callee parameter is declared as one of these aggregate types, the matching
    /// argument's trust_ir type is legitimately a pointer carrier rather than the
    /// aggregate type itself; the signature check accepts that carrier.
    fn trust_ir_ty_is_aggregate(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Struct(_) | Ty::Tuple(_) | Ty::Array(_, _) | Ty::Record(_) | Ty::Enum(_)
        )
    }

    /// Whether an actual argument `Ty` satisfies a declared callee parameter `Ty`
    /// at the trust_ir signature-validation level.
    ///
    /// Exact equality is the common case. Two relaxations cover argument values
    /// that are legitimately carried as a single pointer in a GPR but whose
    /// trust_ir type differs nominally from the declared parameter type:
    ///
    /// 1. **By-value aggregate parameter.** The argument is the address of a
    ///    freshly materialized aggregate (a `Ty::Ptr` from an `Alloca`), while
    ///    the parameter is declared as the aggregate itself. See
    ///    `trust_ir_ty_is_aggregate`.
    /// 2. **Reference / raw-pointer parameter.** A `Ref`/`RefMut`/`Ptr*`/etc.
    ///    parameter is an ABI pointer; the matching argument is also a pointer
    ///    carrier whose specific nominal pointer type (e.g. a bare `Ty::Ptr`
    ///    address vs. a typed `Ty::Ref(..)`) may differ. All pointer carriers
    ///    occupy one GPR, so any pointer-carrier argument satisfies a
    ///    pointer-carrier parameter.
    ///
    /// Both relaxations preserve the argument's machine register class: the ABI
    /// classification is driven by the EXPECTED parameter type, seeded on a
    /// call-site-scoped `Copy` temp (`record_aggregate_call_arg_types`), never
    /// by the argument's own ValueId or actual trust_ir type, so accepting
    /// these carriers cannot change codegen.
    /// A scalar-vs-pointer / scalar-vs-aggregate mismatch (a genuine width/class
    /// error) is still rejected.
    fn call_arg_ty_satisfies_param(actual_ty: &Ty, expected_ty: &Ty) -> bool {
        if actual_ty == expected_ty {
            return true;
        }
        if Self::trust_ir_ty_is_pointer_carrier(actual_ty) {
            return Self::trust_ir_ty_is_aggregate(expected_ty)
                || Self::trust_ir_ty_is_pointer_carrier(expected_ty);
        }
        false
    }

    fn push_unique_value_id(values: &mut Vec<ValueId>, vid: ValueId) {
        if !values.contains(&vid) {
            values.push(vid);
        }
    }

    fn value_is_pointer_carrier(&self, vid: ValueId) -> bool {
        self.lookup_value_ty(vid)
            .is_some_and(|ty| Self::trust_ir_ty_is_pointer_carrier(&ty))
    }

    fn exact_in_bounds_bound(&self, node: &InstrNode) -> Option<Result<u64, ProofDropDiagnostic>> {
        if !node
            .proofs
            .iter()
            .any(|proof| matches!(proof, ProofAnnotation::InBounds))
        {
            return None;
        }

        let bound = match &node.inst {
            Inst::GEP { base, indices, .. } if indices.len() == 1 => {
                self.known_array_bound_for_value(*base)?
            }
            Inst::ExtractElement { array, .. } | Inst::InsertElement { array, .. } => {
                self.known_array_bound_for_value(*array)?
            }
            _ => return None,
        };

        // O0/O1 must be safe when the proof-only guard survives. The late carrier
        // expander materializes the bound into the runtime check, so the maximum
        // bound we may emit is per-target (the arch-aware cap): AArch64 uses
        // `CMP #imm12` (12-bit), x86 can carry any i64 via `MOV r64,imm64 ; CMP`,
        // and RISC-V reconstructs any 32-bit value via `LUI+ADDI`. A larger bound
        // intentionally fails closed with a diagnostic instead of emitting a
        // misencoded check. Defaulting to AArch64 keeps existing callers unchanged.
        let max_bound = self.guard_carrier_arch.max_exact_bound();
        if bound <= max_bound {
            Some(Ok(bound))
        } else {
            Some(Err(ProofDropDiagnostic::with_payload(
                "InBounds",
                format!("bound={bound}"),
                ProofDropCode::Unrepresentable,
                "exact InBounds guard bound exceeds the target's CMP immediate carrier range",
            )))
        }
    }

    fn known_array_bound_for_value(&self, vid: ValueId) -> Option<u64> {
        self.lookup_value_ty(vid)
            .as_ref()
            .and_then(Self::array_bound_from_ty)
    }

    fn array_bound_from_ty(ty: &Ty) -> Option<u64> {
        match ty {
            Ty::Array(_, len) => Some(*len),
            _ => None,
        }
    }

    fn record_exact_in_bounds_proof(&mut self, base: Value, index: Value, bound: u64) {
        self.proof_ctx
            .value_proofs
            .entry(index)
            .or_default()
            .push(Proof::ExactInBounds { base, index, bound });
    }

    /// The discharged-obligation id a node binds to its guard, from a `ProofAnnotation::ProofRef`,
    /// if the producer supplied one. The kernel keeps the guard when this is `None` (fail-safe).
    fn node_obligation_id(node: &InstrNode) -> Option<u64> {
        node.proofs.iter().find_map(|proof| match proof {
            ProofAnnotation::ProofRef(id) => Some(u64::from(id.index())),
            _ => None,
        })
    }

    /// Preserve the historical synthetic-discharge machinery only for this crate's structural
    /// kernel-model tests.  Non-test builds never manufacture authority from a proof label.
    fn node_obligation_id_or_test_model(&mut self, node: &InstrNode) -> Option<u64> {
        if let Some(id) = Self::node_obligation_id(node) {
            return Some(id);
        }
        #[cfg(test)]
        {
            self.proof_ctx.synthesize_discharged_obligation()
        }
        #[cfg(not(test))]
        {
            None
        }
    }

    /// Decide whether a `Load`/`Store` node carries a genuine `ProofAnnotation::NotNull` and, if so,
    /// the discharged-obligation id to bind to the emitted `GuardNull` carrier.
    ///
    /// Returns:
    ///   * `Some(obligation)` — the node IS proof-annotated `NotNull`, so emit the null guard.  The
    ///     optional id is copied only from an explicit upstream `ProofRef`; a bare label stays
    ///     unbound.
    ///   * `None` — the node is NOT proof-annotated `NotNull`; emit NO null guard.
    ///
    /// A `NotNull` label is producer-owned metadata, not a replay result.  Synthesizing a discharged
    /// obligation from it would turn a publicly constructible label into behavioral authority.
    fn memory_ptr_not_null_obligation(&mut self, node: &InstrNode) -> Option<Option<u64>> {
        if !memory_ptr_has_not_null_proof(node) {
            return None;
        }
        Some(self.node_obligation_id_or_test_model(node))
    }

    /// The discharged-obligation id to bind to a `GuardDivZero` carrier emitted for an integer
    /// division/remainder node that carries a genuine `ProofAnnotation::DivNonZero`.
    ///
    /// Bare `DivNonZero` labels remain unbound; only an explicit `ProofRef` is copied as structural
    /// metadata.  Even that reference is non-authoritative until exact validator replay is wired.
    fn divisor_not_zero_obligation(&mut self, node: &InstrNode) -> Option<u64> {
        self.node_obligation_id_or_test_model(node)
    }

    /// The discharged-obligation id to bind to a `GuardShiftRange` carrier emitted for a shift node
    /// that carries a genuine `ProofAnnotation::ShiftInRange`.
    ///
    /// Bare `ShiftInRange` labels remain unbound; see [`Self::divisor_not_zero_obligation`].
    fn shift_in_range_obligation(&mut self, node: &InstrNode) -> Option<u64> {
        self.node_obligation_id_or_test_model(node)
    }

    /// The discharged-obligation id to bind to a `GuardOverflow` carrier emitted for an
    /// `Inst::Overflow` checked add/sub node that carries a genuine, signedness-matching
    /// `ProofAnnotation::NoOverflow` (signed) or `ProofAnnotation::NoWrap` (unsigned).
    ///
    /// Bare NoOverflow/NoWrap labels remain unbound; see
    /// [`Self::divisor_not_zero_obligation`].
    fn overflow_no_overflow_obligation(&mut self, node: &InstrNode) -> Option<u64> {
        self.node_obligation_id_or_test_model(node)
    }

    /// The trust-ir `ValueId` of the INDEX an exact bounds guard is about.
    ///
    /// Mirrors the node shapes [`Self::exact_in_bounds_bound`] resolves a bound for, so the two
    /// always agree on which value the guard constrains. Anything else yields `None`, which the
    /// lattice reads as "no refinement" and therefore keeps the guard.
    fn exact_in_bounds_index_vid(node: &InstrNode) -> Option<ValueId> {
        match &node.inst {
            Inst::GEP { indices, .. } if indices.len() == 1 => indices.first().copied(),
            Inst::ExtractElement { index, .. } | Inst::InsertElement { index, .. } => Some(*index),
            _ => None,
        }
    }

    /// **THE PAYOFF.** Ask the decidable lattice whether this guard's obligation is already
    /// discharged by the refinement predicate its INDEX value declares.
    ///
    /// Returns the minted capability, or `None` — in which case the carrier keeps whatever
    /// obligation binding it had (usually none) and expands to a real runtime check.
    ///
    /// This is not a heuristic and not an inference: it is one call into trust-ir's own total,
    /// solver-free `implies`, over trust-ir's own content-interned tables. trust-cg contributes
    /// no judgement about whether the index is in range; it only asks, and believes `true`.
    fn certify_bounds_guard_from_refinement(
        &mut self,
        node: &InstrNode,
        bound: u64,
        base: Value,
        index: Value,
    ) -> Option<LatticeBoundsCapability> {
        let index_vid = Self::exact_in_bounds_index_vid(node)?;
        let pred = self.refinement_pred_of(index_vid)?;
        let module = self.module?;
        let function = &self.trust_ir_func?.name;
        // Build the env lazily from the module rather than from `proof_ctx.refinement_env`:
        // that field is populated at the END of `translate`, and this runs mid-translation.
        let env = RefinementEnv::from_module(module);
        let capability = lattice_guard::certify_bounds_guard_for_source_carrier(
            &env, pred, bound, function, base, index,
        )?;
        // Belt and braces: a capability that does not replay against the very env it was minted
        // from is a bug in the minter, not an authorization. Refuse it.
        if !capability.replay(&env) {
            return None;
        }
        Some(capability)
    }

    fn append_exact_in_bounds_guard(
        &mut self,
        node: &InstrNode,
        base: Value,
        index: Value,
        instrs: &mut Vec<Instruction>,
    ) {
        match self.exact_in_bounds_bound(node) {
            Some(Ok(bound)) => {
                self.record_exact_in_bounds_proof(base, index, bound);
                // Copy only an explicit upstream ProofRef as structural metadata.  The public
                // InBounds label is not replay authority and never synthesizes a discharged id.
                let label_obligation = self.node_obligation_id_or_test_model(node);
                // ... but a DECIDABLE LATTICE IMPLICATION is exact replay authority. When the
                // index's declared refinement predicate entails `[0, bound-1]`, bind the carrier
                // to the lattice obligation instead: that id names the discharging predicate's
                // content, and the pipeline can hand the kernel matching evidence for it.
                let obligation =
                    match self.certify_bounds_guard_from_refinement(node, bound, base, index) {
                        Some(capability) => {
                            let id = capability.obligation_id();
                            self.proof_ctx.lattice_bounds_capabilities.push(capability);
                            Some(id)
                        }
                        None => label_obligation,
                    };
                instrs.push(Instruction {
                    opcode: Opcode::GuardBoundsCheck { bound, obligation },
                    args: vec![base, index],
                    results: vec![],
                });
            }
            Some(Err(diagnostic)) => self.proof_ctx.diagnostics.push(diagnostic),
            None => {}
        }
    }

    /// OPT-6a — recognize the FRONTEND BOUNDS-CHECK PROBE and resolve its exact
    /// carrier parameters.
    ///
    /// The probe is the rustc-bridge's route into the verified Certified-
    /// Elimination Kernel for a MIR `Assert(BoundsCheck)` whose array length is
    /// a compile-time constant: an `Inst::ICmp { op: Ult, lhs: index, rhs }`
    /// node carrying `ProofAnnotation::InBounds`, where `rhs` is defined by a
    /// plain integer `Inst::Const` (the exact bound). The frontend REPLACES its
    /// eager compare+branch bounds check with this probe, trusting the adapter
    /// to emit a `GuardBoundsCheck` carrier with IDENTICAL trap semantics
    /// (`trap iff !(index <u bound)`), so recognition is a TOTAL, fail-closed
    /// contract:
    ///
    /// * `None` — the node is NOT a probe (no `InBounds` annotation): translate
    ///   as a plain compare, exactly as before.
    /// * `Some(Ok((bound, obligation)))` — emit the carrier alongside the
    ///   compare. `obligation` comes ONLY from an explicit
    ///   `ProofAnnotation::ProofRef` naming a genuine module `ProofObligation`;
    ///   a probe WITHOUT a `ProofRef` yields `obligation: None`, so the kernel
    ///   KEEPS the guard and the pipeline expands it into the real runtime
    ///   check.
    /// * `Some(Err(_))` — the node claims to be a probe but the bound cannot be
    ///   resolved (wrong compare op, vector type, non-constant bound, negative
    ///   bound, or a bound above the target carrier cap): FAIL THE COMPILE
    ///   CLOSED. The frontend already dropped its own compare+branch on the
    ///   promise of a carrier, so silently skipping would DELETE a bounds check
    ///   (the intercept shape-drift miscompile class); an error is the only
    ///   sound answer.
    ///
    /// SOUNDNESS (OPT-6a reviewer-mandated): this frontend-origin channel is
    /// NEVER dischargeable via
    /// [`ProofContext::synthesize_discharged_obligation`]. The synthesized-
    /// `Discharged` doctrine ("InBounds IS the upstream safety proof") is
    /// earned only by producers whose `InBounds` annotation is itself a proof
    /// (the LLVM importer's `getelementptr inbounds` on an array-typed base);
    /// the bridge attaches `InBounds` from its own compile-time reasoning,
    /// which is exactly the claim the kernel exists to CHECK against solver-
    /// discharged evidence, not to trust. An unproven probe therefore keeps
    /// its guard — the refutation tests in
    /// `trust-cg-codegen/tests/guard_bounds_probe_x86.rs` pin this.
    fn frontend_bounds_probe(
        &self,
        node: &InstrNode,
    ) -> Option<Result<(BoundsProbeBound, Option<u64>), AdapterError>> {
        let Inst::ICmp { op, ty, rhs, .. } = &node.inst else {
            return None;
        };
        if !node
            .proofs
            .iter()
            .any(|p| matches!(p, ProofAnnotation::InBounds))
        {
            return None;
        }
        if !matches!(op, ICmpOp::Ult) {
            return Some(Err(AdapterError::UnsupportedInstruction(format!(
                "frontend bounds probe (InBounds-annotated ICmp) must be an unsigned \
                 less-than compare, got ICmp::{op:?}; refusing to drop the carrier \
                 for a bounds check the frontend already elided"
            ))));
        }
        if matches!(ty, Ty::Vector(_, _)) {
            return Some(Err(AdapterError::UnsupportedInstruction(
                "frontend bounds probe (InBounds-annotated ICmp) must be a scalar \
                 compare, got a vector type"
                    .to_string(),
            )));
        }
        let Some(&bound_raw) = self.int_const_values.get(rhs) else {
            // DYNAMIC bound: the length is a runtime value (a heap slice or
            // `Vec`), not an `Inst::Const`. Previously this was a hard error,
            // which is why `while k < v.len() { v[k] }` could never carry a
            // proof-only guard at all and its check stayed frontend control
            // flow. It now yields a Dyn carrier over the SAME trap semantics —
            // `trap iff !(index <u len)` — with the length in a register.
            //
            // This is still fail-safe: an un-discharged obligation keeps the
            // guard exactly as the constant case does. What changes is only
            // that the check becomes VISIBLE to the kernel instead of invisible.
            return Some(Ok((
                BoundsProbeBound::Dyn(*rhs),
                Self::node_obligation_id(node),
            )));
        };
        if bound_raw < 0 {
            return Some(Err(AdapterError::UnsupportedInstruction(format!(
                "frontend bounds probe bound {bound_raw} is negative"
            ))));
        }
        let bound = match u64::try_from(bound_raw) {
            Ok(bound) => bound,
            Err(_) => {
                return Some(Err(AdapterError::UnsupportedInstruction(format!(
                    "frontend bounds probe bound {bound_raw} exceeds u64"
                ))));
            }
        };
        // Per-target carrier-expander cap (Sentinel S5): a surviving carrier must
        // be expandable into a real runtime check, so a bound the expander cannot
        // encode fails closed here rather than emitting a misencoded check.
        let max_bound = self.guard_carrier_arch.max_exact_bound();
        if bound > max_bound {
            return Some(Err(AdapterError::UnsupportedInstruction(format!(
                "frontend bounds probe bound {bound} exceeds the target's carrier \
                 immediate cap {max_bound}"
            ))));
        }
        // ProofRef ONLY. Deliberately NOT falling back to
        // `synthesize_discharged_obligation`: an unbound probe carrier stays
        // undischarged, so the kernel keeps the guard (see SOUNDNESS above).
        let obligation = Self::node_obligation_id(node);
        Some(Ok((BoundsProbeBound::Const(bound), obligation)))
    }

    fn pointer_result_value_ids(&self, node: &InstrNode) -> Vec<ValueId> {
        let mut values = Vec::new();
        for (idx, result) in node.results.iter().copied().enumerate() {
            if self
                .trust_ir_result_type(&node.inst, idx)
                .is_some_and(|ty| Self::trust_ir_ty_is_pointer_carrier(&ty))
            {
                Self::push_unique_value_id(&mut values, result);
            }
        }
        values
    }

    fn pointer_source_value_ids(&self, node: &InstrNode) -> Vec<ValueId> {
        let mut values = Vec::new();
        match &node.inst {
            Inst::Load { ptr, .. }
            | Inst::Store { ptr, .. }
            | Inst::AtomicLoad { ptr, .. }
            | Inst::AtomicStore { ptr, .. }
            | Inst::AtomicRMW { ptr, .. }
            | Inst::CmpXchg { ptr, .. } => {
                Self::push_unique_value_id(&mut values, *ptr);
            }
            Inst::Return { values: returned } => {
                for vid in returned.iter().copied() {
                    if self.value_is_pointer_carrier(vid) {
                        Self::push_unique_value_id(&mut values, vid);
                    }
                }
            }
            Inst::Call { args, .. } | Inst::CallIndirect { args, .. } => {
                for vid in args.iter().copied() {
                    if self.value_is_pointer_carrier(vid) {
                        Self::push_unique_value_id(&mut values, vid);
                    }
                }
                if values.is_empty() {
                    values.extend(self.pointer_result_value_ids(node));
                }
            }
            _ => values.extend(self.pointer_result_value_ids(node)),
        }
        values
    }

    fn value_fact_attachment_value_ids(&self, node: &InstrNode) -> Vec<ValueId> {
        if !node.results.is_empty() {
            return node.results.clone();
        }

        match &node.inst {
            Inst::Store { value, .. } | Inst::AtomicStore { value, .. } => vec![*value],
            Inst::Return { values } => values.clone(),
            _ => Vec::new(),
        }
    }

    fn proof_fact_attachment_value_ids(&self, node: &InstrNode, fact: ProofFact) -> Vec<ValueId> {
        match fact {
            ProofFact::InBounds
            | ProofFact::NoAlias
            | ProofFact::Aligned(_)
            | ProofFact::DataRaceFree
            | ProofFact::ValidDealloc
            | ProofFact::ReadonlyTable
            | ProofFact::AppendOnlyBuffer
            | ProofFact::AtomicSetInsert => self.pointer_source_value_ids(node),
            ProofFact::NoUndef => self.value_fact_attachment_value_ids(node),
            ProofFact::Monotonic
            | ProofFact::NoPanic
            | ProofFact::Deterministic
            | ProofFact::Terminates
            | ProofFact::ParallelMap
            | ProofFact::BoundedLoop(_)
            | ProofFact::DivergenceClass(_) => node.results.clone(),
        }
    }

    fn trust_ir_int_ty_is_signed(ty: &Ty) -> bool {
        // isize is signed pointer-width; usize/char are unsigned.
        matches!(
            ty,
            Ty::I8 | Ty::I16 | Ty::I32 | Ty::I64 | Ty::I128 | Ty::Isize
        )
    }

    fn extend_index_to_i64_if_needed(
        &mut self,
        index_vid: ValueId,
        index_val: Value,
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        let Some(trust_ir_ty) = self.lookup_value_ty(index_vid) else {
            return Ok(index_val);
        };
        let from_ty = self.translate_ty(&trust_ir_ty)?;
        if matches!(from_ty, Type::I64) {
            return Ok(index_val);
        }
        if !matches!(from_ty, Type::B1 | Type::I8 | Type::I16 | Type::I32) {
            return Ok(index_val);
        }

        let extended = self.fresh_value();
        let opcode = if Self::trust_ir_int_ty_is_signed(&trust_ir_ty) {
            Opcode::Sextend {
                from_ty,
                to_ty: Type::I64,
            }
        } else {
            Opcode::Uextend {
                from_ty,
                to_ty: Type::I64,
            }
        };
        instrs.push(Instruction {
            opcode,
            args: vec![index_val],
            results: vec![extended],
        });
        self.define_value_type(extended, Type::I64);
        Ok(extended)
    }

    /// Lower a multi-index `GEP` (e.g. `a[i][j]`, `s.f[k]`) by walking the
    /// aggregate layout one level at a time: the first index strides the
    /// pointee element (ArrayGep), then each subsequent index either strides
    /// an array element (ArrayGep) or selects a struct/tuple/record field
    /// (StructGep). Mirrors the single-index path but threads the running
    /// pointer + type through each level. Fail-closed on non-aggregate types.
    fn translate_multi_index_gep(
        &mut self,
        pointee_ty: &Ty,
        base: ValueId,
        indices: &[ValueId],
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        let mut instrs = Vec::new();
        let mut current_ptr = self.map_value(base);
        let mut current_ty = pointee_ty.clone();

        for (idx, index_vid) in indices.iter().copied().enumerate() {
            let is_final = idx + 1 == indices.len();
            let next_ptr = self.gep_step_result(is_final, dst);

            if idx == 0 {
                // The FIRST index strides the whole pointee — which may itself
                // be an array (`GEP { pointee_ty: [P; 2], indices: [i, j] }`),
                // so the stride is the pointee's AUTHORITATIVE extent, not the
                // natural-C `ArrayGep` one (audit P0/G5).
                let lir_pointee_ty = self.translate_ty(&current_ty)?;
                let index_val = self.map_gep_index(index_vid, &mut instrs)?;
                self.emit_array_element_ptr(
                    &current_ty,
                    &lir_pointee_ty,
                    current_ptr,
                    index_val,
                    next_ptr,
                    &mut instrs,
                )?;
                current_ptr = next_ptr;
                continue;
            }

            match current_ty.clone() {
                Ty::Array(..) => {
                    // Each later array step strides ONE element, at that
                    // element's own authority: `[[P; 2]; 2]` steps 18 then 9,
                    // not the natural-C 32 then 16 (rustc-measured).
                    let elem_ty = self.array_element_ty(&current_ty)?;
                    let lir_elem_ty = self.translate_ty(&elem_ty)?;
                    let index_val = self.map_gep_index(index_vid, &mut instrs)?;
                    self.emit_array_element_ptr(
                        &elem_ty,
                        &lir_elem_ty,
                        current_ptr,
                        index_val,
                        next_ptr,
                        &mut instrs,
                    )?;
                    current_ptr = next_ptr;
                    current_ty = elem_ty;
                }
                Ty::Struct(_) | Ty::Tuple(_) | Ty::Record(_) => {
                    let field_index = self.require_gep_struct_field_index(index_vid)?;
                    let field_ty = self.aggregate_field_ty(&current_ty, field_index as usize)?;
                    let struct_ty = self.translate_ty(&current_ty)?;
                    if let Some(offset) =
                        self.explicit_field_offset(&current_ty, &struct_ty, field_index)?
                    {
                        // The field address is `base + AUTHORITATIVE offset` —
                        // the producer's declared offset, or the PACKED one —
                        // not the natural-C `StructGep`/`offset_of` (aligned)
                        // offset the LIR type would recompute (audit P0/G5).
                        let offset = offset as i64;
                        let off_val = self.fresh_value();
                        self.define_value_type(off_val, Type::I64);
                        instrs.push(Instruction {
                            opcode: Opcode::Iconst {
                                ty: Type::I64,
                                imm: offset,
                            },
                            args: vec![],
                            results: vec![off_val],
                        });
                        instrs.push(Instruction {
                            opcode: Opcode::Iadd,
                            args: vec![current_ptr, off_val],
                            results: vec![next_ptr],
                        });
                    } else {
                        instrs.push(Instruction {
                            opcode: Opcode::StructGep {
                                struct_ty,
                                field_index,
                            },
                            args: vec![current_ptr],
                            results: vec![next_ptr],
                        });
                    }
                    current_ptr = next_ptr;
                    current_ty = field_ty;
                }
                other => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "multi-index GEP cannot index into non-aggregate type {:?} at index {}",
                        other, idx
                    )));
                }
            }
        }

        Ok(instrs)
    }

    fn gep_step_result(&mut self, is_final: bool, dst: Value) -> Value {
        if is_final {
            dst
        } else {
            let value = self.fresh_value();
            self.define_value_type(value, Type::I64);
            value
        }
    }

    fn map_gep_index(
        &mut self,
        index_vid: ValueId,
        instrs: &mut Vec<Instruction>,
    ) -> Result<Value, AdapterError> {
        let index_val = self.map_value(index_vid);
        self.extend_index_to_i64_if_needed(index_vid, index_val, instrs)
    }

    fn array_element_ty(&self, array_ty: &Ty) -> Result<Ty, AdapterError> {
        let Ty::Array(elem_ty_id, _) = array_ty else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP expected array type, got {:?}",
                array_ty
            )));
        };
        self.types
            .get(elem_ty_id.as_usize())
            .cloned()
            .ok_or_else(|| {
                AdapterError::UnsupportedType(format!(
                    "Array(TyId({}), _) — types table {} entries, index out of range",
                    elem_ty_id.index(),
                    self.types.len()
                ))
            })
    }

    fn aggregate_field_ty(
        &self,
        aggregate_ty: &Ty,
        field_index: usize,
    ) -> Result<Ty, AdapterError> {
        match aggregate_ty {
            Ty::Struct(sid) => {
                let sdef = self.structs.iter().find(|s| s.id == *sid).ok_or_else(|| {
                    AdapterError::UnsupportedType(format!("unknown struct {:?}", sid))
                })?;
                sdef.fields
                    .get(field_index)
                    .map(|field| field.ty.clone())
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "multi-index GEP struct field {} out of bounds for {:?}",
                            field_index, aggregate_ty
                        ))
                    })
            }
            Ty::Tuple(fields) => fields.get(field_index).cloned().ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "multi-index GEP tuple field {} out of bounds for {:?}",
                    field_index, aggregate_ty
                ))
            }),
            // A first-class closure is a struct of its captures (in capture
            // declaration order), so its "field" `Ty` is the capture type at
            // that index — resolved from the module `closure_types` table.
            Ty::Closure(cid) => {
                let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
                let def = module.closure_types.get(cid.as_usize()).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "multi-index GEP: closure id {:?} not found in module closure-type table",
                        cid
                    ))
                })?;
                def.captures.get(field_index).cloned().ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "multi-index GEP closure capture {} out of bounds for {:?}",
                        field_index, aggregate_ty
                    ))
                })
            }
            Ty::Record(rid) => {
                let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
                let def = module
                    .records
                    .iter()
                    .find(|def| def.id == *rid)
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "multi-index GEP: record id {:?} not found in module record table",
                            rid
                        ))
                    })?;
                def.fields
                    .get(field_index)
                    .map(|field| field.ty.clone())
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "multi-index GEP record field {} out of bounds for {:?}",
                            field_index, aggregate_ty
                        ))
                    })
            }
            _ => Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP expected struct, tuple, or record type, got {:?}",
                aggregate_ty
            ))),
        }
    }

    fn require_gep_struct_field_index(&self, index_vid: ValueId) -> Result<u32, AdapterError> {
        let Some(index) = self.lookup_const_int(index_vid) else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP struct field index must be a constant, got {:?}",
                index_vid
            )));
        };
        if index < 0 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP struct field index must be non-negative, got {}",
                index
            )));
        }
        u32::try_from(index).map_err(|_| {
            AdapterError::UnsupportedInstruction(format!(
                "multi-index GEP struct field index does not fit u32: {}",
                index
            ))
        })
    }

    /// Resolve the return types for a direct `Call` to the given `FuncId`.
    ///
    /// Looks up the callee function in the module, follows its `FuncTyId`
    /// into `module.func_types`, and translates each `Ty` return to a LIR
    /// `Type`. Returns an empty vec (no type hints) if the callee is not
    /// present in the module (e.g., an imported symbol) — ISel will then
    /// fall back to `value_type()` defaults, matching pre-#381 behavior
    /// for unknown externs.
    fn lookup_callee_return_types(&self, callee: FuncId) -> Vec<Type> {
        self.translate_return_tys(&self.lookup_callee_return_tys(callee))
    }

    fn lookup_callee_return_tys(&self, callee: FuncId) -> Vec<Ty> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let Some(callee_fn) = module.functions.iter().find(|f| f.id == callee) else {
            return Vec::new();
        };
        self.lookup_func_type_return_tys(callee_fn.ty)
    }

    fn lookup_callee_func_ty(&self, callee: FuncId) -> Option<&'a trust_ir::FuncTy> {
        let module = self.module?;
        let callee_fn = module.functions.iter().find(|f| f.id == callee)?;
        module.func_types.get(callee_fn.ty.index() as usize)
    }

    fn validate_call_indirect_signature(
        &self,
        callee: ValueId,
        sig: FuncTyId,
        args: &[ValueId],
        results: &[ValueId],
    ) -> Result<&'a trust_ir::FuncTy, AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let func_ty = module.func_types.get(sig.index() as usize).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "CallIndirect references unregistered FuncTyId({})",
                sig.index()
            ))
        })?;
        if func_ty.is_vararg {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect over variadic FuncTyId({}) is fail-closed until indirect variadic ABI lowering is proven",
                sig.index()
            )));
        }

        let callee_ty = self.lookup_value_ty(callee).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "CallIndirect callee {callee:?} has no known trust_ir type"
            ))
        })?;
        // Accept either a statically-known function symbol (Ty::Func(sig)), a
        // runtime code pointer (Ty::Ptr), or a 64-bit integer holding a code
        // address (Ty::I64 / Ty::U64). The trust-cg frontend is the sole
        // producer of Inst::CallIndirect and emits it only from genuine code
        // pointers — a vtable method-slot load (&dyn dispatch / the std
        // `lang_start` closure vtable) or a MIR FnPtr-typed operand. Such a
        // pointer is usually carried as Ty::Ptr, but a function address loaded
        // out of a vtable / function-pointer table slot is materialized as a
        // pointer-width integer (Ty::I64 from an `Inst::Load { ty: I64 }`), and
        // an integer holding a code address is just as valid an indirect-call
        // target as a Ptr: ISel loads the callee value into a register and
        // emits `call reg` (Opcode::CallIndirect -> X86Opcode::CallR) without
        // ever inspecting the trust_ir callee type, so a Func, a Ptr, and a
        // 64-bit-integer callee all lower to byte-identical machine code. The
        // call ABI is fully constrained by the explicit `sig` plus the arity
        // and per-argument type checks below, so admitting I64/U64 cannot change
        // the emitted instruction stream — only the target address held in the
        // register, which is exactly the runtime code pointer the program
        // computed. Narrow on purpose to pointer-width (64-bit) integers: a
        // sub-64-bit integer would not hold a full code address, so anything
        // other than Func/Ptr/I64/U64 still fails closed. Rejecting Ptr (and now
        // I64) was the over-tightened contract that failed closed on ALL dynamic
        // dispatch and on function-pointer-table indirect calls.
        if callee_ty != Ty::Func(sig)
            && callee_ty != Ty::Ptr
            && callee_ty != Ty::I64
            && callee_ty != Ty::U64
        {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect callee must be a code pointer (Func({}), Ptr, or a 64-bit integer code address I64/U64), got {callee_ty:?}",
                sig.index()
            )));
        }

        if args.len() != func_ty.params.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect argument arity mismatch for FuncTyId({}): got {}, expected {}",
                sig.index(),
                args.len(),
                func_ty.params.len()
            )));
        }
        if results.len() != func_ty.returns.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CallIndirect result arity mismatch for FuncTyId({}): got {}, expected {}",
                sig.index(),
                results.len(),
                func_ty.returns.len()
            )));
        }

        for (index, (arg, expected_ty)) in args.iter().zip(func_ty.params.iter()).enumerate() {
            let actual_ty = self.lookup_value_ty(*arg).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "CallIndirect argument {index} value {arg:?} has no known trust_ir type"
                ))
            })?;
            if !Self::call_arg_ty_satisfies_param(&actual_ty, expected_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "CallIndirect argument {index} type mismatch for FuncTyId({}): got {:?}, expected {:?}",
                    sig.index(),
                    actual_ty,
                    expected_ty
                )));
            }
            self.translate_ty(expected_ty)?;
        }
        for ty in &func_ty.returns {
            self.translate_ty(ty)?;
        }

        Ok(func_ty)
    }

    /// Whether `cc` passes arguments/returns using the platform C register ABI
    /// (AAPCS64 on aarch64), so the adapter's C-ABI classification is a correct
    /// lowering for it:
    /// - `C`: the C ABI itself.
    /// - `Fast` / `Cold`: LLVM optimization-hint conventions. The LangRef lets
    ///   the compiler pick the register assignment; it does NOT mandate a layout
    ///   different from C, so lowering them via the C ABI is always correct (it
    ///   simply forgoes the optimization freedom). trust-cg compiles every edge
    ///   of such a call consistently.
    /// - `Rust`: on aarch64 `extern "Rust"` uses the same AAPCS64 register
    ///   sequence as C for scalars/pointers; aggregate *layout* differences are
    ///   carried by `StructRepr`, not the calling convention, and every edge of a
    ///   Rust-ABI call is compiled here consistently.
    /// - `Swift`: NOT unconditionally C-compatible. The Swift-specific registers
    ///   (self x20, error x21, async x22) are engaged ONLY by
    ///   swiftself/swifterror/swiftasync parameters, and Swift also diverges on
    ///   AGGREGATE params+returns (a >16-byte struct RETURN goes directly in
    ///   x0-x3 under Swift but via sret under C). So Swift is handled separately
    ///   by [`Self::swift_signature_is_c_abi_equivalent`], which admits only the
    ///   scalar subset that is provably identical to C and keeps everything else
    ///   fail-closed. Use [`Self::conv_sig_uses_c_register_abi`] at call/def
    ///   sites, not this function alone.
    fn calling_conv_uses_c_register_abi(cc: CallingConv) -> bool {
        matches!(
            cc,
            CallingConv::C | CallingConv::Fast | CallingConv::Cold | CallingConv::Rust
        )
    }

    /// A non-aggregate scalar that the aarch64 C ABI (AAPCS64) and the Swift
    /// convention pass IDENTICALLY. Verified empirically by disassembling clang's
    /// `swiftcall` against `ccc`: for each of these, both emit byte-for-byte the
    /// same register / stack-spill assignment.
    /// - single-register scalars (i8..i64, u8..u64, f16/f32/f64, bool, ptr) fill
    ///   x0-x7 / v0-v7 then spill to the stack, identically in both;
    /// - `i128`/`u128` use an aligned GPR pair (x0:x1, x2:x3, ...) then a
    ///   16-aligned stack slot, identically in both (verified in-register,
    ///   spilled, and interleaved with scalars).
    ///   AGGREGATES are excluded: Swift returns a >16-byte struct directly in
    ///   x0-x3 whereas C uses sret, so that case genuinely diverges.
    fn is_swift_c_equivalent_scalar(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::I8
                | Ty::I16
                | Ty::I32
                | Ty::I64
                | Ty::I128
                | Ty::U8
                | Ty::U16
                | Ty::U32
                | Ty::U64
                | Ty::U128
                | Ty::F16
                | Ty::F32
                | Ty::F64
                | Ty::Bool
                | Ty::Ptr
        )
    }

    /// Number of Swift RETURN register components for an all-scalar return list
    /// (each scalar = 1 register; `i128`/`u128` = 2 GPRs). Returns `None` if any
    /// return is a non-scalar (aggregate) type. `Unit`/`Never` returns carry no
    /// ABI slot and are skipped.
    ///
    /// Swift's return budget is a SINGLE combined count of 4 (integer 64-bit
    /// words + FP scalar fields); a scalar return sequence whose components sum
    /// to `<= 4` is placed in x0-x3 / v0-v3 by the C register ABI's
    /// `classify_returns` EXACTLY as Swift places it (independent GPR/FPR
    /// counters, field order). A sum of `>= 5` diverges (Swift uses sret) and
    /// must stay fail-closed. See `swift_agg` (Swift aggregate scalarization).
    fn swift_return_register_components(returns: &[Ty]) -> Option<u32> {
        let mut total: u32 = 0;
        for ty in returns {
            if matches!(ty, Ty::Unit | Ty::Never) {
                continue;
            }
            if !Self::is_swift_c_equivalent_scalar(ty) {
                return None;
            }
            total += if matches!(ty, Ty::I128 | Ty::U128) {
                2
            } else {
                1
            };
        }
        Some(total)
    }

    /// True when a `Swift`-convention function with this signature is PROVABLY
    /// lowered identically by the aarch64 C register ABI, so admitting it
    /// (instead of failing closed) cannot miscompile. The subset is: not
    /// variadic, every parameter a single-register scalar
    /// ([`Self::is_swift_c_equivalent_scalar`]), and a return that is an
    /// all-scalar sequence whose Swift register components sum to `<= 4`.
    ///
    /// The Swift-specific registers (self x20, error x21, async x22) never come
    /// into play: they are driven by swiftself/swifterror/swiftasync parameter
    /// attributes, which trust-ir's `ParamAttrs` cannot express. The remaining
    /// Swift↔C divergence is AGGREGATE params/returns (Swift direct-returns a
    /// >16-byte struct in x0-x3; C uses sret). Aggregate-bearing swiftcc
    /// > signatures in the sound implementable subset are SCALARIZED before the
    /// > adapter runs (see the `swift_agg` module / `swift_rewrite_module`), so by
    /// > the time a Swift signature reaches this guard it is already all-scalar;
    /// > aggregate signatures OUTSIDE that subset keep their struct types here and
    /// > are correctly rejected. A multi-value scalar return (produced by that
    /// > scalarization, or written directly) is admitted iff its components sum to
    /// > `<= 4`, matching Swift's return budget.
    /// > (i128/u128 do NOT diverge — verified — and are admitted as scalars.)
    /// > See the empirical ABI checks in `tests/e2e_aarch64_swift_scalar.rs` and
    /// > `tests/e2e_aarch64_swift_aggregate.rs`.
    fn swift_signature_is_c_abi_equivalent(func_ty: &trust_ir::FuncTy) -> bool {
        !func_ty.is_vararg
            && func_ty
                .params
                .iter()
                .all(Self::is_swift_c_equivalent_scalar)
            && matches!(
                Self::swift_return_register_components(&func_ty.returns),
                Some(components) if components <= 4
            )
    }

    /// Whether `(cc, func_ty)` is correctly lowered by the C register ABI: the
    /// always-C conventions (C/Fast/Cold/Rust) for ANY signature, or `Swift`
    /// restricted to its provably C-equivalent scalar subset.
    fn conv_sig_uses_c_register_abi(cc: CallingConv, func_ty: &trust_ir::FuncTy) -> bool {
        Self::calling_conv_uses_c_register_abi(cc)
            || (matches!(cc, CallingConv::Swift)
                && Self::swift_signature_is_c_abi_equivalent(func_ty))
    }

    fn validate_direct_call_signature(
        &self,
        callee: FuncId,
        args: &[ValueId],
        results: &[ValueId],
    ) -> Result<(&'a TrustIrFunction, &'a trust_ir::FuncTy), AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let callee_fn = module
            .functions
            .iter()
            .find(|func| func.id == callee)
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call references unregistered FuncId({})",
                    callee.index()
                ))
            })?;
        let func_ty = module
            .func_types
            .get(callee_fn.ty.index() as usize)
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call references unregistered FuncTyId({}) for FuncId({})",
                    callee_fn.ty.index(),
                    callee.index()
                ))
            })?;
        if !Self::conv_sig_uses_c_register_abi(callee_fn.calling_conv, func_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Call to FuncId({}) uses unsupported calling convention {:?}; Trust-CG lowers C-register-ABI conventions (C/Fast/Cold/Rust, and the scalar-only subset of Swift) and must not silently use the C ABI for a convention/signature with a different register layout (e.g. Swift with aggregate params or returns)",
                callee.index(),
                callee_fn.calling_conv
            )));
        }

        if func_ty.is_vararg {
            if args.len() < func_ty.params.len() {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Call argument arity mismatch for FuncId({}): got {}, expected at least {} fixed arguments",
                    callee.index(),
                    args.len(),
                    func_ty.params.len()
                )));
            }
        } else if args.len() != func_ty.params.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Call argument arity mismatch for FuncId({}): got {}, expected {}",
                callee.index(),
                args.len(),
                func_ty.params.len()
            )));
        }

        if results.len() != func_ty.returns.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Call result arity mismatch for FuncId({}): got {}, expected {}",
                callee.index(),
                results.len(),
                func_ty.returns.len()
            )));
        }

        for (index, (arg, expected_ty)) in args.iter().zip(func_ty.params.iter()).enumerate() {
            let actual_ty = self.lookup_value_ty(*arg).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call argument {index} value {arg:?} has no known trust_ir type"
                ))
            })?;
            if !Self::call_arg_ty_satisfies_param(&actual_ty, expected_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Call argument {index} type mismatch for FuncId({}): got {:?}, expected {:?}",
                    callee.index(),
                    actual_ty,
                    expected_ty
                )));
            }
            self.translate_ty(expected_ty)?;
        }
        for (index, arg) in args.iter().enumerate().skip(func_ty.params.len()) {
            let actual_ty = self.lookup_value_ty(*arg).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Call variadic argument {index} value {arg:?} has no known trust_ir type"
                ))
            })?;
            self.translate_ty(&actual_ty)?;
        }
        for ty in &func_ty.returns {
            self.translate_ty(ty)?;
        }

        Ok((callee_fn, func_ty))
    }

    /// Resolve the return types for a function type by `FuncTyId`.
    ///
    /// Used by `CallIndirect`, where the instruction carries the callee
    /// signature explicitly. Returns an empty vec if any return type
    /// fails to translate (e.g., aggregate returns through opaque types),
    /// preserving the pre-#381 fallback behavior for those cases.
    fn lookup_func_type_returns(&self, sig: FuncTyId) -> Vec<Type> {
        self.translate_return_tys(&self.lookup_func_type_return_tys(sig))
    }

    fn lookup_func_type_return_tys(&self, sig: FuncTyId) -> Vec<Ty> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let idx = sig.index() as usize;
        let Some(func_ty) = module.func_types.get(idx) else {
            return Vec::new();
        };
        func_ty.returns.clone()
    }

    /// Resolve the declared parameter types for a direct `Call` to `callee`,
    /// translated to LIR `Type`. Returns an empty vec (no hints) for an
    /// unknown/imported callee, mirroring `lookup_callee_return_types`.
    ///
    /// Used to seed an aggregate-by-value call ARGUMENT's type on a
    /// call-site-scoped `Copy` temp (see `record_aggregate_call_arg_types`): a
    /// constructed aggregate value is carried by ADDRESS, so its producing
    /// instruction (`Alloca`, `Copy`, `InsertField`, …) leaves it typed as a
    /// pointer/I64. Without this hint ISel's SysV classifier would pass it in
    /// a single GPR instead of the eightbyte register pair / sret slot the
    /// callee's aggregate param ABI expects. The callee's param type IS the
    /// aggregate (the bridge uses the flat integer-lane tuple `slot_ty` for
    /// by-value aggregate params), so recording it here makes the caller- and
    /// callee-side ABI agree.
    fn lookup_callee_param_types(&self, callee: FuncId) -> Vec<Type> {
        let Some(func_ty) = self.lookup_callee_func_ty(callee) else {
            return Vec::new();
        };
        self.translate_param_tys(&func_ty.params)
    }

    /// Resolve the declared parameter types for an indirect call signature,
    /// translated to LIR `Type`. Same fallback semantics as
    /// `lookup_func_type_returns`.
    fn lookup_func_type_param_types(&self, sig: FuncTyId) -> Vec<Type> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let Some(func_ty) = module.func_types.get(sig.index() as usize) else {
            return Vec::new();
        };
        self.translate_param_tys(&func_ty.params)
    }

    /// Resolve the declared trust_ir parameter `Ty`s (signedness-carrying) for an
    /// indirect call signature. Empty on an unresolvable sig. Used by the
    /// `CallIndirect` caller-side narrow-int extension (audit P0/G6), which needs
    /// the source-level signedness (`Ty::I8` vs `Ty::U8`) that is lost once the
    /// param is lowered to the sign-less machine `Type`.
    fn lookup_func_type_param_tys(&self, sig: FuncTyId) -> Vec<Ty> {
        let Some(module) = self.module else {
            return Vec::new();
        };
        let Some(func_ty) = module.func_types.get(sig.index() as usize) else {
            return Vec::new();
        };
        func_ty.params.clone()
    }

    fn translate_param_tys(&self, tys: &[Ty]) -> Vec<Type> {
        let mut out = Vec::with_capacity(tys.len());
        for ty in tys {
            match self.translate_ty(ty) {
                Ok(t) => out.push(t),
                // A param type that fails to translate yields no hints at all,
                // so a partial (mis-indexed) list can never be applied to args.
                Err(_) => return Vec::new(),
            }
        }
        out
    }

    /// Seed the aggregate LIR `Type` of any call argument whose matching
    /// callee parameter type is an aggregate (`Struct`/`Array`/`Enum`) —
    /// CALL-SITE-SCOPED via a fresh `Copy` temp.
    ///
    /// A by-value aggregate argument is a constructed value carried by ADDRESS
    /// (an `Alloca`/`StructGep`/`Copy` chain typed as a pointer). ISel's call
    /// classifier reads `value_type(arg)` to choose the System V eightbyte
    /// register-pair / sret placement; without an aggregate type recorded the
    /// arg would default to a single I64 GPR and miscompile the call.
    ///
    /// The retype must NOT be applied to the argument's own ValueId: that is a
    /// whole-function (global) retype of the fat-ptr slot, and the slot's OTHER
    /// uses in the caller — its own lane-spill address arithmetic
    /// (`Add(PtrToInt(slot), 8)` chains) — then see an aggregate-typed operand
    /// and fail closed in `select_arithmetic` ([TCG-REGALLOC-063]). Instead we
    /// allocate a fresh temp, emit `temp = Copy(orig)` immediately before the
    /// call, retype ONLY the temp, and rewrite the call arg to the temp. The
    /// original slot keeps its I64 pointer-carrier type everywhere else. ISel's
    /// `select_move_reg`/`select_copy` recognize the seeded-aggregate-dest Copy
    /// and ALIAS the temp to the source address operand (zero machine
    /// instructions), so the emitted call code is unchanged.
    ///
    /// Guard (the pointer-carrier contract, see
    /// `is_aggregate_address_passed_ty`): a temp is synthesized only when the
    /// arg's currently-recorded LIR type is `None` or `Type::I64`. An arg
    /// already recorded with exactly `param_ty` (e.g. an aggregate call result
    /// chained into another call) passes through unchanged. ANY other recorded
    /// type is a genuine ABI mismatch — classifying the call by a temp typed
    /// `param_ty` while the source carries a DIFFERENT layout would load the
    /// wrong lanes/register classes — so we fail closed.
    ///
    /// We only handle aggregate params — scalar params keep whatever type their
    /// producing instruction already recorded. `param_tys` may be shorter than
    /// `arg_vals` (variadic tail) or empty (unknown callee); `zip` handles both.
    /// Returns the prologue `Copy` instructions; callers must place them
    /// immediately before the call in the same block.
    fn record_aggregate_call_arg_types(
        &mut self,
        arg_vals: &mut [Value],
        param_tys: &[Type],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let mut copies = Vec::new();
        for (val, param_ty) in arg_vals.iter_mut().zip(param_tys.iter()) {
            if !matches!(
                param_ty,
                Type::Struct(_) | Type::Array(_, _) | Type::Enum { .. }
            ) {
                continue;
            }
            match self.value_types.get(val) {
                // Arg already carries exactly this aggregate type: pass
                // through unchanged (no temp needed).
                Some(recorded) if recorded == param_ty => continue,
                // Untyped or I64 address carrier — the documented contract for
                // a by-value aggregate arg. Scope the retype to a fresh temp.
                None | Some(Type::I64) => {}
                // A different recorded type (another aggregate, F64, I128, …)
                // cannot be blessed as `param_ty` by a temp: ISel would
                // classify the call by the param lanes while the source value
                // carries a different layout/register class. Fail closed.
                Some(other) => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "call argument {val:?} has recorded LIR type {other:?} but the callee \
                         parameter expects by-value aggregate {param_ty:?}; only an I64 \
                         pointer-carrier (or an exact aggregate match) is a sound source for \
                         the System V eightbyte classification"
                    )));
                }
            }
            let temp = self.fresh_value();
            copies.push(Instruction {
                opcode: Opcode::Copy,
                args: vec![*val],
                results: vec![temp],
            });
            self.define_value_type(temp, param_ty.clone());
            *val = temp;
        }
        Ok(copies)
    }

    fn translate_return_tys(&self, tys: &[Ty]) -> Vec<Type> {
        let mut out = Vec::with_capacity(tys.len());
        for ty in tys {
            match self.translate_ty(ty) {
                Ok(t) => out.push(t),
                Err(_) => return Vec::new(),
            }
        }
        out
    }

    // -----------------------------------------------------------------------
    // Top-level translation
    // -----------------------------------------------------------------------

    /// Translate a trust_ir function to an internal LIR Function + ProofContext.
    fn translate(
        &mut self,
        func: &'a TrustIrFunction,
    ) -> Result<(Function, ProofContext), AdapterError> {
        self.value_producers.clear();
        for block in &func.blocks {
            for (param, ty) in &block.params {
                self.value_ty_map.insert(*param, ty.clone());
            }
            for node in &block.body {
                for result in &node.results {
                    // Preserve the previous linear lookup's first-definition
                    // behavior if malformed input reuses an SSA ValueId.
                    self.value_producers.entry(*result).or_insert(node);
                }
                for (idx, result) in node.results.iter().enumerate() {
                    if let Some(ty) = self.trust_ir_result_type(&node.inst, idx) {
                        self.value_ty_map.insert(*result, ty);
                    }
                }
                // OPT-6a: record plain integer-constant definitions so the
                // frontend bounds-probe recognizer can resolve its exact bound.
                if let Inst::Const {
                    value: Constant::Int(v),
                    ..
                } = &node.inst
                    && let [result] = node.results.as_slice()
                {
                    self.int_const_values.insert(*result, *v);
                }
            }
        }

        self.trust_ir_func = Some(func);
        self.next_trust_ir_origin = 0;

        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let func_ty = module
            .func_types
            .get(func.ty.index() as usize)
            .ok_or(AdapterError::InvalidFuncTyId(func.ty.index()))?;
        if !Self::conv_sig_uses_c_register_abi(func.calling_conv, func_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "function {} uses unsupported calling convention {:?}; Trust-CG lowers C-register-ABI conventions (C/Fast/Cold/Rust, and the scalar-only subset of Swift) and must not silently use the C ABI for a convention/signature with a different register layout (e.g. Swift with aggregate params or returns)",
                func.name, func.calling_conv
            )));
        }
        let sig = translate_signature(func, module)?;
        let entry_block = func
            .blocks
            .iter()
            .find(|block| block.id == func.entry)
            .ok_or(AdapterError::UnknownBlock(func.entry.index()))?;
        if entry_block.params.len() != sig.params.len() {
            return Err(AdapterError::EntryParamArityMismatch(
                func.name.clone(),
                entry_block.params.len(),
                sig.params.len(),
            ));
        }
        for (index, ((_, entry_ty), sig_ty)) in
            entry_block.params.iter().zip(sig.params.iter()).enumerate()
        {
            let entry_ty = self.translate_ty(entry_ty)?;
            if entry_ty != *sig_ty {
                return Err(AdapterError::EntryParamTypeMismatch(
                    func.name.clone(),
                    index,
                    entry_ty,
                    sig_ty.clone(),
                ));
            }
        }

        // ISel's formal-argument convention binds signature parameter `i` to
        // internal `Value(i)`. Reserve those values from the ACTUAL entry block
        // before translating any block: trust_ir permits blocks to be stored in
        // non-layout order, and otherwise a non-entry instruction translated
        // first can steal `Value(0)` and alias a formal. The arity/type checks
        // above make this reservation an exact ABI correspondence rather than a
        // positional guess.
        let mut seen_entry_params = HashSet::new();
        for (param, _) in &entry_block.params {
            if !seen_entry_params.insert(*param) {
                return Err(AdapterError::DuplicateBlockParam(
                    entry_block.id.index(),
                    param.index(),
                ));
            }
            self.map_value(*param);
        }
        let param_pointee_types = translate_param_pointee_types(func, module)?;
        self.current_returns = sig.returns.clone();
        // Drop unit/never returns to match the void machine signature (see
        // translate_signature): a `-> ()` function returns no value, so a bare
        // `ret` validates against an empty return-type list.
        self.current_return_tys = func_ty
            .returns
            .iter()
            .filter(|t| !matches!(t, Ty::Unit | Ty::Never))
            .cloned()
            .collect();
        let entry = self.map_block(func.entry);

        let mut lir_func = Function::new(func.name.clone(), sig);
        lir_func.param_pointee_types = param_pointee_types;
        lir_func.entry_block = entry;
        if self.function_requires_stack_protector(func) {
            lir_func.stack_protector = StackProtectorMode::StackGuard;
        }
        let source_debug = extract_source_debug_info(func, module);
        lir_func.debug_meta = FunctionDebugMeta {
            // Prefer the real path the frontend stamped (module `files` table);
            // fall back to a synthetic `<module>.rs` only when the function
            // carries no span (so DWARF still names *something*).
            source_file: source_debug
                .source_file
                .clone()
                .or_else(|| Some(format!("{}.rs", module.name))),
            decl_line: source_debug.decl_line,
            param_names: source_debug.param_names,
            local_variables: Vec::new(),
            struct_types: source_debug.struct_types,
            enum_types: source_debug.enum_types,
        };

        // Extract function-level proof annotations and rich proof facts.
        let func_metadata = extract_function_proof_metadata(func);
        for proof in func_metadata.proofs {
            self.proof_ctx.add_function_proof(proof);
        }
        for fact in func_metadata.facts {
            self.proof_ctx.add_function_fact(fact);
        }
        self.proof_ctx.diagnostics.extend(func_metadata.diagnostics);

        // Thread `noalias` pointer-parameter attributes onto a dedicated channel
        // for the `neon-map` store vectorizer. `attrs.params[i]` describes formal
        // parameter `i` (signature order), which the ISel binds to `Value(i)`, so
        // recording the raw index is enough for the codegen pipeline to resolve
        // the machine vreg. Kept out of `value_facts` so no other proof-consuming
        // pass observes it.
        for (i, pa) in func.attrs.params.iter().enumerate() {
            if pa.noalias {
                self.proof_ctx.noalias_param_indices.push(i);
            }
        }

        // Translate all blocks.
        let mut _blocks_time = 0;
        let mut _insts_time = 0;
        for trust_ir_block in func.blocks.iter() {
            let block_id = self.map_block(trust_ir_block.id);
            let _t = std::time::Instant::now();
            let (basic_block, trust_ir_origins) = self.translate_block(trust_ir_block)?;
            _blocks_time += _t.elapsed().as_millis();
            lir_func.block_order.push(block_id);
            lir_func.trust_ir_origins.insert(block_id, trust_ir_origins);
            lir_func.blocks.insert(block_id, basic_block);
        }
        if _blocks_time > 100 && std::env::var_os("TY_TRUST_CG_JIT_PROFILE").is_some() {
            eprintln!("[JIT Profile] translate blocks total: {}ms", _blocks_time);
        }

        // Post-pass: insert pending phi copies into predecessor blocks.
        //
        // Explicit Phi instructions were lowered to copies that need to be
        // placed at the end of each predecessor block (before terminators).
        // This mirrors how `resolve_block_args` handles block parameters.
        for (pred_trust_ir_block, src, dst) in std::mem::take(&mut self.pending_phi_copies) {
            let pred_lir_block = self.map_block(pred_trust_ir_block);
            if let Some(pred_bb) = lir_func.blocks.get_mut(&pred_lir_block) {
                let copy_inst = Instruction {
                    opcode: Opcode::Copy,
                    args: vec![src],
                    results: vec![dst],
                };
                // Insert before the terminator. Find the last instruction
                // that is a control-flow terminator and insert before it.
                let term_pos = pred_bb.instructions.iter().rposition(|inst| {
                    matches!(
                        inst.opcode,
                        Opcode::Jump { .. }
                            | Opcode::Brif { .. }
                            | Opcode::Return
                            | Opcode::Invoke { .. }
                    )
                });
                match term_pos {
                    Some(pos) => {
                        pred_bb.instructions.insert(pos, copy_inst);
                        // Keep source_locs aligned (phi copies have no source loc).
                        if !pred_bb.source_locs.is_empty() {
                            pred_bb.source_locs.insert(pos, None);
                        }
                        if let Some(origins) = lir_func.trust_ir_origins.get_mut(&pred_lir_block) {
                            origins.insert(pos.min(origins.len()), None);
                        }
                    }
                    None => {
                        pred_bb.instructions.push(copy_inst);
                        if !pred_bb.source_locs.is_empty() {
                            pred_bb.source_locs.push(None);
                        }
                        if let Some(origins) = lir_func.trust_ir_origins.get_mut(&pred_lir_block) {
                            origins.push(None);
                        }
                    }
                }
            }
        }

        // Post-pass: insert extra blocks created by condbr/switch edge splitting.
        //
        // When translate_condbr or the Inst::Switch handler encountered block arguments,
        // they created intermediate copy blocks to ensure copies only execute on
        // the correct control-flow edge (fix for issue #302/#304).
        for (block_id, basic_block) in std::mem::take(&mut self.pending_extra_blocks) {
            let insert_at = edge_copy_target(&basic_block)
                .and_then(|target| {
                    let target_pos = lir_func
                        .block_order
                        .iter()
                        .position(|existing| *existing == target)?;
                    let source_pos = lir_func.block_order.iter().position(|candidate| {
                        lir_func
                            .blocks
                            .get(candidate)
                            .is_some_and(|block| block_targets_block(block, block_id))
                    })?;
                    if source_pos < target_pos {
                        Some(target_pos)
                    } else {
                        None
                    }
                })
                .unwrap_or(lir_func.block_order.len());
            lir_func
                .trust_ir_origins
                .insert(block_id, vec![None; basic_block.instructions.len()]);
            lir_func.block_order.insert(insert_at, block_id);
            lir_func.blocks.insert(block_id, basic_block);
        }

        // Propagate stack slot metadata to the LIR function.
        lir_func.stack_slots = self.stack_slots.clone();
        lir_func.debug_meta.local_variables = self.debug_local_variables.clone();
        lir_func.debug_value_bindings = self.debug_value_bindings.clone();

        // Propagate Value->Type hints (Call/CallIndirect result types, #381)
        // so the pipeline can seed ISel before instruction selection.
        lir_func.value_types = self.value_types.clone();

        // Propagate pure-callee names (#456) so ISel can stamp `Bl` MachInsts
        // targeting these callees with `ProofAnnotation::Pure`.
        lir_func.pure_callees = self.pure_callees.clone();

        // Propagate importer-licensed libm-pure callee names so AArch64 ISel
        // can stamp the emitted `Bl` with `InstFlags::LIBM_PURE_CALL`.
        lir_func.libm_pure_callees = self.libm_pure_callees.clone();

        // Propagate exception-handling structure (Invoke/LandingPad) so ISel
        // can seed `MachFunction.eh_metadata` and the pipeline can emit the
        // LSDA + compact unwind. Empty for functions without EH.
        lir_func.eh_info = self.eh_info.clone();

        // The typed value model, recorded on the channel the adapter already has for value facts.
        self.record_refinement_proofs();

        Ok((lir_func, self.proof_ctx.clone()))
    }

    /// Record every `Ty::Refine`-typed value's predicate on `proof_ctx.value_proofs`, and snapshot
    /// the module's interned lattice tables so a downstream consumer can resolve those ids.
    ///
    /// Runs at the very END of `translate`, deliberately: it reads `self.value_map` (already
    /// populated) instead of calling `map_value`, so it cannot allocate a fresh LIR `Value` and
    /// therefore cannot perturb value numbering, instruction selection, or a single emitted byte.
    /// A value whose `ValueId` never reached the LIR is simply skipped.
    ///
    /// REPRESENTATION PRESERVATION: nothing here touches `value_types` (the LIR type map).
    /// `translate_ty(Refine(b, p))` already produced exactly `translate_ty(b)`, so a module that
    /// adds refinements to an existing module compiles to the same machine types; only this proof
    /// metadata differs.
    fn record_refinement_proofs(&mut self) {
        let Some(module) = self.module else {
            return;
        };
        // Cheap and total: a module with no refinements snapshots two empty vectors, and the
        // scan below finds nothing because no declared type is a `Refine`.
        self.proof_ctx.refinement_env = RefinementEnv::from_module(module);

        let mut refined: Vec<(Value, PredId)> = self
            .value_ty_map
            .iter()
            .filter_map(|(vid, ty)| match ty {
                Ty::Refine(_, pred) => {
                    let value = self.value_map.get(vid).copied()?;
                    Some((value, *pred))
                }
                _ => None,
            })
            .collect();
        // `value_ty_map` is a HashMap, so fix a deterministic order before touching
        // `value_proofs`: a verified compiler's proof metadata must not depend on hash iteration
        // order (it feeds digests and reports downstream).
        refined.sort_unstable_by_key(|(value, pred)| (value.0, pred.index()));
        refined.dedup();
        for (value, pred) in refined {
            self.proof_ctx
                .value_proofs
                .entry(value)
                .or_default()
                .push(Proof::Refinement { pred });
        }
    }

    /// The refinement predicate declared on a trust-ir value's type, if any.
    ///
    /// `None` — including for a value with no recorded type, and for a value typed by a
    /// non-`Refine` `Ty` — reads as [`trust_ir::pred::Pred::Top`]: no information. That is the
    /// load-bearing direction: a DROPPED fact must never read as a satisfied one.
    fn refinement_pred_of(&self, vid: ValueId) -> Option<PredId> {
        match self.value_ty_map.get(&vid) {
            Some(Ty::Refine(_, pred)) => Some(*pred),
            _ => None,
        }
    }

    /// Translate a trust_ir basic block.
    fn translate_block(
        &mut self,
        trust_ir_block: &TrustIrBlock,
    ) -> Result<(BasicBlock, Vec<Option<TrustIrInstId>>), AdapterError> {
        let mut bb = BasicBlock::default();
        let mut trust_ir_origins = Vec::new();

        // Record the block currently being translated so the EH lowering can
        // attribute an `Inst::Invoke`'s throwing call site to the right block.
        self.current_block_id = Some(trust_ir_block.id);

        // Translate block parameters (phi-like).
        for (vid, ty) in &trust_ir_block.params {
            let val = self.map_value(*vid);
            let lir_ty = self.translate_ty(ty)?;
            bb.params.push((val, lir_ty));
        }

        // Translate each instruction in the block body.
        for node in &trust_ir_block.body {
            let origin = TrustIrInstId(self.next_trust_ir_origin);
            self.next_trust_ir_origin = self.next_trust_ir_origin.saturating_add(1);

            // Extract proof annotations from the trust_ir instruction and attach
            // them to the LIR value that carries the proven fact. Result facts
            // such as NoOverflow stay on results; operand facts such as
            // DivNonZero/ShiftInRange/NotNull/InBounds bind to the source value
            // named by the proof payload. Rich facts use a separate
            // fact-specific carrier selection below so pointer/source facts do
            // not get mis-keyed to load or call results.
            let proof_metadata = extract_proof_metadata(node);
            if !proof_metadata.proofs.is_empty() {
                for proof in &proof_metadata.proofs {
                    for vid in proof_attachment_value_ids(node, proof) {
                        let val = self.map_value(vid);
                        self.proof_ctx
                            .value_proofs
                            .entry(val)
                            .or_default()
                            .push(proof.clone());
                    }
                }
            }
            if !proof_metadata.facts.is_empty() {
                for fact in proof_metadata.facts.iter().copied() {
                    let carrier_ids = self.proof_fact_attachment_value_ids(node, fact);
                    if carrier_ids.is_empty() {
                        self.proof_ctx
                            .diagnostics
                            .push(ProofDropDiagnostic::no_carrier(fact));
                        continue;
                    }

                    for vid in carrier_ids {
                        let val = self.map_value(vid);
                        self.proof_ctx
                            .value_facts
                            .entry(val)
                            .or_default()
                            .push(fact);
                    }
                }
            }
            self.proof_ctx
                .diagnostics
                .extend(proof_metadata.diagnostics);

            // Convert trust_ir SourceSpan to SourceLoc for DWARF line numbers.
            let source_loc = node.span.as_ref().map(|span| trust_cg_ir::SourceLoc {
                file: span.file,
                line: span.line,
                col: span.col,
            });
            if let Some(local) = const_value_debug_local(node, origin) {
                self.debug_local_variables.push(local);
            } else if let Some(local) = source_spanned_value_debug_local(node, origin) {
                if let DebugVariableStorage::ProvenanceVar(var_id) = local.storage
                    && let Some(result) = node.results.first().copied()
                {
                    let value = self.map_value(result);
                    self.debug_value_bindings
                        .push(DebugValueBinding { var_id, value });
                }
                self.debug_local_variables.push(local);
            }

            let instrs = self.translate_instruction(node)?;
            let instr_count = instrs.len();
            bb.instructions.extend(instrs);
            // All LIR instructions generated from this trust_ir node share
            // the same source location (one trust_ir node -> N LIR instrs).
            for _ in 0..instr_count {
                bb.source_locs.push(source_loc);
                trust_ir_origins.push(Some(origin));
            }
        }

        Ok((bb, trust_ir_origins))
    }

    fn translate_trust_cg_bitfield_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode(op).map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let result_ty = self.translate_ty(&spec.ty)?;
        let operands = match spec.kind {
            BitfieldKind::Extract | BitfieldKind::Sextract => {
                let operand = op.operands[0];
                self.require_bitfield_operand_type(op, "operand", operand, &result_ty)?;
                vec![self.map_value(operand)]
            }
            BitfieldKind::Insert => {
                let dst = op.operands[0];
                let src = op.operands[1];
                self.require_bitfield_operand_type(op, "dst", dst, &result_ty)?;
                self.require_bitfield_operand_type(op, "src", src, &result_ty)?;
                vec![self.map_value(dst), self.map_value(src)]
            }
        };

        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty);
        let opcode = match spec.kind {
            BitfieldKind::Extract => Opcode::ExtractBits {
                lsb: spec.lsb,
                width: spec.width,
            },
            BitfieldKind::Sextract => Opcode::SextractBits {
                lsb: spec.lsb,
                width: spec.width,
            },
            BitfieldKind::Insert => Opcode::InsertBits {
                lsb: spec.lsb,
                width: spec.width,
            },
        };

        Ok(vec![Instruction {
            opcode,
            args: operands,
            results: vec![result],
        }])
    }

    fn translate_trust_cg_v4i32_mask_extract_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode_v4i32_mask_extract(op)
            .map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let mask_ty = self
            .lookup_value_ty(mask)
            .ok_or_else(|| AdapterError::UnknownValue(mask.index()))?;
        if !Self::is_v4i32_ty(&mask_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) has type {mask_ty:?}; expected <4 x i32>",
                op.qualified_name(),
                mask.index()
            )));
        }

        let result_ty = self.translate_ty(&spec.result_ty)?;
        debug_assert_eq!(result_ty, Type::I32);
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty);

        Ok(vec![Instruction {
            opcode: Opcode::V4I32MaskExtract,
            args: vec![self.map_value(mask)],
            results: vec![result],
        }])
    }

    fn translate_trust_cg_v2i64_mask_extract_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode_v2i64_mask_extract(op)
            .map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let mask_ty = self
            .lookup_value_ty(mask)
            .ok_or_else(|| AdapterError::UnknownValue(mask.index()))?;
        if !Self::is_v2i64_ty(&mask_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) has type {mask_ty:?}; expected <2 x i64>",
                op.qualified_name(),
                mask.index()
            )));
        }

        let result_ty = self.translate_ty(&spec.result_ty)?;
        debug_assert!(matches!(result_ty, Type::I32 | Type::I64));
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty.clone());

        Ok(vec![Instruction {
            opcode: Opcode::V2I64MaskExtract { result_ty },
            args: vec![self.map_value(mask)],
            results: vec![result],
        }])
    }

    fn translate_trust_cg_v2i64_bool_mask_extract_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = bitfield_dialect::decode_v2i64_bool_mask_extract(op)
            .map_err(AdapterError::UnsupportedInstruction)?;
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let mask_ty = self
            .lookup_value_ty(mask)
            .ok_or_else(|| AdapterError::UnknownValue(mask.index()))?;
        if !Self::is_v2_bool_ty(&mask_ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) has type {mask_ty:?}; expected <2 x bool>",
                op.qualified_name(),
                mask.index()
            )));
        }
        if !self.value_is_v2i64_icmp_result(mask, &mut HashSet::new()) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} operand ValueId({}) must be produced by a <2 x i64> ICmp",
                op.qualified_name(),
                mask.index()
            )));
        }

        let result_ty = self.translate_ty(&spec.result_ty)?;
        debug_assert!(matches!(result_ty, Type::I32 | Type::I64));
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty.clone());

        Ok(vec![Instruction {
            opcode: Opcode::V2I64MaskExtract { result_ty },
            args: vec![self.map_value(mask)],
            results: vec![result],
        }])
    }

    fn translate_trust_ir_vector_pack_lanes_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // 64-bit (D-register) `<8 x i8>` pack: hashbrown's `uint8x8_t`
        // control-byte splat (`simd_splat`). Read the DialectInst's RAW result
        // type + operands directly — the strict `decode_with_operand_tys` runs
        // the trust-ir vector-dialect shape gate, which only admits `<8 x i8>`
        // in a co-developed trust-ir; a `vector.pack_lanes` DialectInst
        // round-trips opaquely (its result type and operands survive), so this
        // lowers regardless of which trust-ir the backend links against.
        if let Some(result_ty) = op.result_tys.first()
            && Self::is_v8i8_ty(result_ty)
        {
            return self.translate_v8i8_pack_lanes(op, results);
        }
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::PackLanes(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not a pack_lanes op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let vector_ty = self.translate_ty(&spec.vector_ty)?;
        if vector_ty != Type::V128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} vector type {:?} lowers to unsupported LIR type {:?}",
                op.qualified_name(),
                spec.vector_ty,
                vector_ty
            )));
        }
        let lane_ty = self.translate_ty(&spec.elem_ty)?;

        if Self::is_v4i32_ty(&spec.vector_ty) {
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::V128);
            let args = op
                .operands
                .iter()
                .map(|lane| self.map_value(*lane))
                .collect();
            return Ok(vec![Instruction {
                opcode: Opcode::V4I32PackLanes,
                args,
                results: vec![dst],
            }]);
        }

        if Self::is_v2i64_ty(&spec.vector_ty) {
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::V128);
            let args = op
                .operands
                .iter()
                .map(|lane| self.map_value(*lane))
                .collect();
            return Ok(vec![Instruction {
                opcode: Opcode::V2I64PackLanes,
                args,
                results: vec![dst],
            }]);
        }

        // Narrow <16 x i8> / <8 x i16> pack_lanes lower to the typed
        // V16I8PackLanes / V8I16PackLanes ops: both ISels pack the scalar lanes
        // into a V128 register directly (x86-64 via dword bitfield assembly +
        // MOVD/PUNPCK; AArch64 via NEON DUP/INS), so the adapter must not
        // materialize the lanes through a stack slot.
        if Self::is_v16i8_ty(&spec.vector_ty) || Self::is_v8i16_ty(&spec.vector_ty) {
            let opcode = if Self::is_v16i8_ty(&spec.vector_ty) {
                Opcode::V16I8PackLanes
            } else {
                Opcode::V8I16PackLanes
            };
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::V128);
            let args = op
                .operands
                .iter()
                .map(|lane| self.map_value(*lane))
                .collect();
            return Ok(vec![Instruction {
                opcode,
                args,
                results: vec![dst],
            }]);
        }

        self.translate_vector_pack_lanes_stack(&op.operands, spec.lanes, lane_ty, results)
    }

    /// Lower a `<8 x i8>` `vector.pack_lanes` to the V64 (D-register)
    /// `V8I8PackLanes` op. The eight operands are the byte lanes; when they are
    /// all the same value (a splat) the AArch64 ISel collapses to a single
    /// `dup.8b`. Reads the DialectInst's raw operands (no strict decode) so the
    /// V64 shape need not be admitted by the backend's linked trust-ir.
    fn translate_v8i8_pack_lanes(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }
        if op.operands.len() != 8 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} <8 x i8> pack expects 8 lane operands, got {}",
                op.qualified_name(),
                op.operands.len()
            )));
        }
        for lane in &op.operands {
            let lane_ty = self
                .lookup_value_ty(*lane)
                .ok_or_else(|| AdapterError::UnknownValue(lane.index()))?;
            let lir = self.translate_ty(&lane_ty)?;
            if lir != Type::I8 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} <8 x i8> pack lanes must lower to I8, got {:?}",
                    op.qualified_name(),
                    lir
                )));
            }
        }
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::V64);
        let args = op
            .operands
            .iter()
            .map(|lane| self.map_value(*lane))
            .collect();
        Ok(vec![Instruction {
            opcode: Opcode::V8I8PackLanes,
            args,
            results: vec![dst],
        }])
    }

    fn translate_trust_ir_vector_extract_lane_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::ExtractLane(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not an extract_lane op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let vector = op.operands[0];
        let vector_ty = self.translate_ty(&spec.vector_ty)?;
        if vector_ty != Type::V128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} vector type {:?} lowers to unsupported LIR type {:?}",
                op.qualified_name(),
                spec.vector_ty,
                vector_ty
            )));
        }
        let lane_ty = self.translate_ty(&spec.elem_ty)?;
        let vector_val = self.map_value(vector);

        if Self::is_v4i32_ty(&spec.vector_ty) {
            return self.translate_v4i32_extract_lane_direct(vector_val, spec.lane, results);
        }
        if Self::is_v2i64_ty(&spec.vector_ty) {
            return self.translate_v2i64_extract_lane_direct(vector_val, spec.lane, results);
        }

        self.translate_vector_extract_lane_stack(vector_val, spec.lane, lane_ty, results)
    }

    fn translate_trust_ir_vector_insert_lane_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::InsertLane(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not an insert_lane op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let vector = op.operands[0];
        let value = op.operands[1];
        let vector_ty = self.translate_ty(&spec.vector_ty)?;
        if vector_ty != Type::V128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} vector type {:?} lowers to unsupported LIR type {:?}",
                op.qualified_name(),
                spec.vector_ty,
                vector_ty
            )));
        }
        let lane_ty = self.translate_ty(&spec.elem_ty)?;
        let vector_val = self.map_value(vector);
        let elem_val = self.map_value(value);

        if Self::is_v4i32_ty(&spec.vector_ty) {
            return self
                .translate_v4i32_insert_lane_direct(vector_val, elem_val, spec.lane, results);
        }
        if Self::is_v2i64_ty(&spec.vector_ty) {
            return self
                .translate_v2i64_insert_lane_direct(vector_val, elem_val, spec.lane, results);
        }

        self.translate_vector_insert_lane_stack(vector_val, elem_val, spec.lane, lane_ty, results)
    }

    fn translate_trust_ir_vector_mask_to_bits_dialect_op(
        &mut self,
        op: &DialectInst,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let spec = match self.decode_trust_ir_vector_op_with_operand_tys(op)? {
            vector_dialect::VectorSpec::MaskToBits(spec) => spec,
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} is not a mask_to_bits op",
                    op.qualified_name()
                )));
            }
        };
        if results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} expects exactly one SSA result, got {}",
                op.qualified_name(),
                results.len()
            )));
        }

        let mask = op.operands[0];
        let result_ty = self.translate_ty(&spec.result_ty)?;
        let result = self.map_result(results)?;
        self.define_value_type(result, result_ty.clone());

        if Self::is_v16_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v16i8_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v16_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <16 x i8> ICmp or canonical logical <16 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            if result_ty != Type::I32 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} result type {:?} is unsupported for <16 x bool>; expected i32",
                    op.qualified_name(),
                    spec.result_ty
                )));
            }
            return Ok(vec![Instruction {
                opcode: Opcode::V16I8MaskExtract,
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        if Self::is_v8_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v8i16_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v8_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <8 x i16> ICmp or canonical logical <8 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            if result_ty != Type::I32 {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} result type {:?} is unsupported for <8 x bool>; expected i32",
                    op.qualified_name(),
                    spec.result_ty
                )));
            }
            return Ok(vec![Instruction {
                opcode: Opcode::V8I16MaskExtract,
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        if Self::is_v4_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v4i32_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v4_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <4 x i32> ICmp or canonical logical <4 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            debug_assert_eq!(result_ty, Type::I32);
            return Ok(vec![Instruction {
                opcode: Opcode::V4I32MaskExtract,
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        if Self::is_v2_bool_ty(&spec.mask_ty) {
            let is_compare_mask = self.value_is_v2i64_icmp_result(mask, &mut HashSet::new());
            let is_const_mask = self.value_is_v2_bool_mask_const(mask, &mut HashSet::new());
            if !is_compare_mask && !is_const_mask {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{} operand ValueId({}) must be produced by a <2 x i64> ICmp or canonical logical <2 x bool> constant",
                    op.qualified_name(),
                    mask.index()
                )));
            }
            debug_assert!(matches!(result_ty, Type::I32 | Type::I64));
            return Ok(vec![Instruction {
                opcode: Opcode::V2I64MaskExtract { result_ty },
                args: vec![self.map_value(mask)],
                results: vec![result],
            }]);
        }

        Err(AdapterError::UnsupportedInstruction(format!(
            "{} supports only logical <16 x bool>, <8 x bool>, <4 x bool>, and <2 x bool> masks, got {:?}",
            op.qualified_name(),
            spec.mask_ty
        )))
    }

    fn decode_trust_ir_vector_op_with_operand_tys(
        &self,
        op: &DialectInst,
    ) -> Result<vector_dialect::VectorSpec, AdapterError> {
        let operand_tys = op
            .operands
            .iter()
            .map(|value| {
                self.lookup_value_ty(*value)
                    .ok_or_else(|| AdapterError::UnknownValue(value.index()))
            })
            .collect::<Result<Vec<_>, _>>()?;
        vector_dialect::decode_with_operand_tys(op, &operand_tys)
            .map_err(AdapterError::UnsupportedInstruction)
    }

    fn require_bitfield_operand_type(
        &self,
        op: &DialectInst,
        role: &str,
        value: ValueId,
        expected: &Type,
    ) -> Result<(), AdapterError> {
        let actual_ty = self
            .lookup_value_ty(value)
            .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
        let actual = self.translate_ty(&actual_ty)?;
        if &actual != expected {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{} {role} type mismatch: operand ValueId({}) has {actual:?}, result has {expected:?}",
                op.qualified_name(),
                value.index()
            )));
        }
        Ok(())
    }

    fn require_trust_ir_operand_type(
        &self,
        context: &str,
        role: &str,
        value: ValueId,
        expected: &Ty,
    ) -> Result<(), AdapterError> {
        let actual = self
            .lookup_value_ty(value)
            .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
        if &actual != expected {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} {role} type mismatch: operand ValueId({}) has {:?}, expected {:?}",
                value.index(),
                actual,
                expected
            )));
        }
        Ok(())
    }

    fn is_integer_scalar_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::I8
                | Ty::I16
                | Ty::I32
                | Ty::I64
                | Ty::I128
                | Ty::U8
                | Ty::U16
                | Ty::U32
                | Ty::U64
                | Ty::U128
                // v25 pointer-width integers plus Char's 32-bit unsigned
                // arithmetic carrier (matching the TrustIr interpreter).
                | Ty::Isize
                | Ty::Usize
                | Ty::Char
        )
    }

    fn is_pointer_like_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Func(_)
        )
    }

    /// Exact typed carriers on which importer/rustc-producer `0xFADE`
    /// global-address stubs are meaningful.
    ///
    /// The rustc bridge normally uses `Ptr`, but const operands retain their
    /// faithful thin reference/raw-pointer type when passed through
    /// `emit_const_alloc_addr`. `I64` is the legacy vtable/address carrier.
    /// `Rc` is intentionally absent (its ownership ABI is unsupported), and
    /// `Func` is absent because data-global stubs are not code pointers.
    fn is_imported_global_addr_carrier(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::I64 | Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_)
        )
    }

    /// True iff a by-value parameter of trust-ir type `ty` is carried across the
    /// call boundary by ADDRESS (a constructed aggregate materialized into a stack
    /// slot whose `Ptr` is the argument value). The bridge passes every by-value
    /// aggregate (`Struct`/`Tuple`/`Record`/`Array`/`Enum`) and the boundary slice
    /// fat pointer (`FatPtr`, a `{ data, len }` slot) this way; the argument's
    /// producing instruction (`Alloca`/StructGep/`Copy`) therefore types it as a
    /// `Ptr`. ISel's SysV eightbyte classifier reads the LIR aggregate type seeded
    /// by `record_aggregate_call_arg_types` on a call-site-scoped `Copy` temp
    /// (from the callee param signature) — not the trust-ir `Ptr`, and never the
    /// argument's own ValueId — to place data+len/lanes in the register pair /
    /// sret / stack slot the callee's by-value parameter ABI expects. So a `Ptr`
    /// argument for an aggregate parameter is the established, sound
    /// representation.
    fn is_aggregate_address_passed_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Struct(_)
                | Ty::Tuple(_)
                | Ty::Record(_)
                | Ty::Array(_, _)
                | Ty::Enum(_)
                | Ty::FatPtr(_)
        )
    }

    /// Whether an argument whose producing-instruction trust-ir type is `actual`
    /// satisfies a callee parameter declared as `expected`. Beyond exact equality
    /// this admits the sound mismatches the bridge relies on, both of which the
    /// argument value carries as a plain `Ptr` (an address / pointer carrier):
    ///
    ///   * an aggregate parameter passed BY ADDRESS, where `expected` is an
    ///     aggregate type and the argument is the `Ptr` to its bytes (see
    ///     `is_aggregate_address_passed_ty`); and
    ///   * a reference / raw-pointer parameter (`Ref`/`RefMut`/`PtrConst`/`PtrMut`)
    ///     satisfied by a `Ptr` — every pointer-like type is one 64-bit pointer
    ///     carrier, so a closure env passed as a `Ptr` to a body fn whose param is
    ///     `Ref(Closure)` (the `FnOnce::call_once` ClosureOnceShim chain) is the
    ///     same bits in the same register.
    ///
    /// A `Func(_)` (code-pointer) parameter is deliberately NOT admitted from a
    /// `Ptr`: a raw data pointer must never be used as a call target without
    /// explicit code-pointer provenance (the same fail-closed stance
    /// `CallIndirect` takes). Every other mismatch still fails closed.
    fn call_arg_ty_compatible(actual: &Ty, expected: &Ty) -> bool {
        actual == expected
            || (matches!(actual, Ty::Ptr)
                && (Self::is_aggregate_address_passed_ty(expected)
                    || matches!(
                        expected,
                        Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_)
                    )))
    }

    fn is_float_scalar_ty(ty: &Ty) -> bool {
        matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
    }

    /// Reject BinOps whose operands do not match the declared scalar type, and
    /// pointer arithmetic whose operands are not (Ptr, integer). This is the
    /// fail-closed safety gate that keeps a type-confused `Iadd` over a float
    /// (or mismatched operand widths) from silently lowering.
    fn validate_binop_operand_tys(
        &self,
        op: BinOp,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
    ) -> Result<(), AdapterError> {
        if matches!((op, ty), (BinOp::Add | BinOp::Sub, Ty::Ptr)) {
            let lhs_ty = self.lookup_value_ty(lhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} lhs operand {lhs:?} has no known trust_ir type"
                ))
            })?;
            let rhs_ty = self.lookup_value_ty(rhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} rhs operand {rhs:?} has no known trust_ir type"
                ))
            })?;
            if lhs_ty != Ty::Ptr || !Self::is_integer_scalar_ty(&rhs_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} pointer arithmetic requires declared ty=Ptr, lhs Ptr, and integer scalar rhs; \
                     lhs {lhs:?} has type {lhs_ty:?}, rhs {rhs:?} has type {rhs_ty:?}"
                )));
            }
            return Ok(());
        }

        // A shift's RHS is a COUNT, not a value of the shifted type: in trust_ir
        // (as in Rust MIR and LLVM) the shift amount may be a *different* integer
        // width than the shifted operand — e.g. `i8 >> 1` carries an I32 literal
        // count, and `i64 << (x as u32)` an I32 count. x86-64 takes the count
        // from CL regardless of its declared width (and the ISel `select_shift`
        // moves the amount into the RCX subregister matching its OWN width), so
        // requiring the count to match the shifted type is wrong and would fail a
        // well-typed shift closed. Validate the shifted operand (LHS) against the
        // declared type, but only require the count (RHS) to be an integer scalar.
        if matches!(op, BinOp::Shl | BinOp::LShr | BinOp::AShr) {
            let lhs_ty = self.lookup_value_ty(lhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} lhs operand {lhs:?} has no known trust_ir type"
                ))
            })?;
            if lhs_ty != *ty {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} lhs operand type mismatch: declared ty={ty:?}, \
                     operand {lhs:?} has type {lhs_ty:?}"
                )));
            }
            let rhs_ty = self.lookup_value_ty(rhs).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} rhs (shift count) operand {rhs:?} has no known trust_ir type"
                ))
            })?;
            if !Self::is_integer_scalar_ty(&rhs_ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "BinOp::{op:?} shift count {rhs:?} must be an integer scalar, has type {rhs_ty:?}"
                )));
            }
            return Ok(());
        }

        self.validate_binary_operand_tys(&format!("BinOp::{op:?}"), ty, lhs, rhs)
    }

    fn validate_binary_operand_tys(
        &self,
        context: &str,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
    ) -> Result<(), AdapterError> {
        for (side, value) in [("lhs", lhs), ("rhs", rhs)] {
            let actual_ty = self.lookup_value_ty(value).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "{context} {side} operand {value:?} has no known trust_ir type"
                ))
            })?;

            // Accept an operand whose declared integer type differs from `ty`
            // ONLY in signedness (same bit width, both pure integer scalars):
            // trust_ir carries the bits identically (U64 and I64 are one 64-bit
            // register value) and the signedness of an operation lives in the
            // OPCODE (Sdiv vs Udiv, signed vs unsigned Icmp condition), never the
            // operand type. A width mismatch, or a Bool / pointer vs. integer
            // mismatch, is still rejected.
            if actual_ty != *ty && !Self::same_width_int_scalar(&actual_ty, ty) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "{context} {side} operand type mismatch: declared ty={ty:?}, \
                     operand {value:?} has type {actual_ty:?}"
                )));
            }
        }

        Ok(())
    }

    /// Whether `a` and `b` are pure integer scalar types of the SAME bit width,
    /// differing at most in signedness (e.g. U64 vs I64). Pointers, `Bool`, and
    /// references are deliberately excluded — they require an exact type match.
    fn same_width_int_scalar(a: &Ty, b: &Ty) -> bool {
        fn pure_int_bits(ty: &Ty) -> Option<u32> {
            match ty {
                Ty::I8 | Ty::U8 => Some(8),
                Ty::I16 | Ty::U16 => Some(16),
                Ty::I32 | Ty::U32 => Some(32),
                Ty::I64 | Ty::U64 => Some(64),
                Ty::I128 | Ty::U128 => Some(128),
                Ty::Isize | Ty::Usize => Some(64),
                Ty::Char => Some(32),
                _ => None,
            }
        }
        matches!((pure_int_bits(a), pure_int_bits(b)), (Some(x), Some(y)) if x == y)
    }

    /// Reject scalar BinOps whose declared type is incompatible with the opcode
    /// family (e.g. integer/shift ops over a float type, float ops over an
    /// integer type). Vector shapes are validated by their dedicated typed
    /// lowering arms before this is reached.
    fn validate_scalar_binop_shape(&self, op: BinOp, ty: &Ty) -> Result<(), AdapterError> {
        let supported = match op {
            BinOp::Add | BinOp::Sub if matches!(ty, Ty::Ptr) => true,
            BinOp::Add
            | BinOp::Sub
            | BinOp::Mul
            | BinOp::UDiv
            | BinOp::SDiv
            | BinOp::URem
            | BinOp::SRem
            | BinOp::Shl
            | BinOp::LShr
            | BinOp::AShr => Self::is_integer_scalar_ty(ty),
            BinOp::And | BinOp::Or | BinOp::Xor => {
                matches!(ty, Ty::Bool) || Self::is_integer_scalar_ty(ty)
            }
            // Trust: the BOOLEAN connectives (trust-ir 4b06918). STRICTER than the
            // overloaded And/Or/Xor above, matching trust-ir's own validator, which
            // admits BAnd/BOr/BXor on Bool only -- an integer operand means the
            // frontend picked the wrong opcode.
            BinOp::BAnd | BinOp::BOr | BinOp::BXor => matches!(ty, Ty::Bool),
            // FRem is handled entirely by its dedicated lowering arm above
            // (which returns before this shape gate): f32/f64 call fmod/fmodf,
            // and f16 promotes to f32, calls fmodf, and demotes (fmod is exact).
            // This arm is unreachable for FRem but kept width-accurate.
            BinOp::FRem => matches!(ty, Ty::F16 | Ty::F32 | Ty::F64),
            // FAdd/FSub/FMul/FDiv are correctly-rounded in binary16 on FEAT_FP16
            // (native FADD/FSUB/FMUL/FDIV Hd,Hn,Hm; F32 is exactly 2p+2 wide so
            // even a promote/compute/demote lowering rounds once), and FMin/FMax
            // (FMINNM/FMAXNM Hd) are exact. Width is carried by the Fpr16 operand
            // class in isel; the verifier models binary16 via fp_bitmodel::F16.
            BinOp::FAdd | BinOp::FSub | BinOp::FMul | BinOp::FDiv | BinOp::FMin | BinOp::FMax => {
                matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
            }
        };

        if !supported {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "BinOp::{op:?} declared type is not supported for scalar lowering: {ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_unop_shape(&self, op: UnOp, ty: &Ty, operand: ValueId) -> Result<(), AdapterError> {
        let actual_ty = self.lookup_value_ty(operand).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "UnOp::{op:?} operand {operand:?} has no known trust_ir type"
            ))
        })?;
        if actual_ty != *ty {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "UnOp::{op:?} operand type mismatch: declared ty={ty:?}, \
                 operand {operand:?} has type {actual_ty:?}"
            )));
        }

        let supported = match op {
            UnOp::Neg | UnOp::CtPop => Self::is_integer_scalar_ty(ty),
            // All F16 unary FP ops have native FEAT_FP16 encodings and are exact
            // (FNEG/FABS sign-bit ops; FRINTM/FRINTP/FRINTZ round-to-integral) or
            // correctly-rounded (FSQRT Hd). Width is carried by the Fpr16 operand
            // class; the verifier models binary16 via fp_bitmodel::F16.
            UnOp::FNeg | UnOp::FAbs | UnOp::FSqrt | UnOp::FFloor | UnOp::FCeil | UnOp::FTrunc => {
                matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
            }
            UnOp::Not => matches!(ty, Ty::Bool) || Self::is_integer_scalar_ty(ty),
        };

        if !supported {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "UnOp::{op:?} declared type is not supported for scalar lowering: {ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_icmp_shape(&self, op: ICmpOp, ty: &Ty) -> Result<(), AdapterError> {
        let supported = if Self::is_integer_scalar_ty(ty) {
            true
        } else if matches!(ty, Ty::Bool) {
            matches!(op, ICmpOp::Eq | ICmpOp::Ne)
        } else if Self::is_pointer_like_ty(ty) {
            // A pointer carries its address in an integer register of pointer
            // width, so Eq/Ne AND the UNSIGNED orderings (Ult/Ule/Ugt/Uge) are
            // all meaningful address comparisons — e.g. hashbrown's
            // `RawIterRange::next_impl` computes `current >= end` over two data
            // pointers. Each lowers to the same unsigned-condition `Icmp` over
            // the pointer-width operands as an integer scalar of pointer width;
            // this matches the trust-ir reference semantics, which compares the
            // pointers by address. The SIGNED orderings (Slt/Sle/Sgt/Sge) are
            // deliberately NOT admitted: an address is an unsigned quantity, so
            // a signed pointer ordering is never a well-formed frontend emission
            // — fail closed.
            matches!(
                op,
                ICmpOp::Eq | ICmpOp::Ne | ICmpOp::Ult | ICmpOp::Ule | ICmpOp::Ugt | ICmpOp::Uge
            )
        } else {
            false
        };

        if !supported {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "ICmp::{op:?} declared type must be an integer scalar, Bool Eq/Ne, \
                 pointer-like Eq/Ne, or pointer-like unsigned ordering (Ult/Ule/Ugt/Uge); got {ty:?}"
            )));
        }

        Ok(())
    }

    fn validate_fcmp_shape(&self, ty: &Ty, lhs: ValueId, rhs: ValueId) -> Result<(), AdapterError> {
        if !Self::is_float_scalar_ty(ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "FCmp declared type must be a scalar float, got {ty:?}"
            )));
        }

        for (side, value) in [("lhs", lhs), ("rhs", rhs)] {
            let actual_ty = self.lookup_value_ty(value).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "FCmp {side} operand {value:?} has no known trust_ir type"
                ))
            })?;

            if actual_ty != *ty {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "FCmp {side} operand type mismatch: declared ty={ty:?}, \
                     operand {value:?} has type {actual_ty:?}"
                )));
            }
        }

        Ok(())
    }

    fn is_float_ty(ty: &Ty) -> bool {
        matches!(ty, Ty::F16 | Ty::F32 | Ty::F64)
    }

    fn switch_selector_bits(ty: &Ty) -> Result<u32, AdapterError> {
        match ty {
            // A Rust `bool` is a 1-byte value (guaranteed 0 or 1), and rustc
            // lowers `if` / loop / `assert!` conditions to `switchInt(bool)`.
            // Treat it as an 8-bit selector: the x86 ISel zero-extends the
            // loaded byte and masks it to {0,1} (normalize_condition_operand's
            // B1 path) before the per-case equality compare, so the undefined
            // high bits of the byte are never read. Without this the backend
            // fails closed on essentially every branch/loop in a debug build.
            Ty::Bool => Ok(8),
            Ty::I8 | Ty::U8 => Ok(8),
            Ty::I16 | Ty::U16 => Ok(16),
            Ty::I32 | Ty::U32 => Ok(32),
            Ty::I64 | Ty::U64 => Ok(64),
            Ty::Isize | Ty::Usize => Ok(64),
            Ty::Char => Ok(32),
            Ty::I128 | Ty::U128 => Err(AdapterError::UnsupportedInstruction(format!(
                "unsupported switch selector width for {:?}; only 8/16/32/64-bit integer selectors are lowered today",
                ty
            ))),
            _ => Err(AdapterError::UnsupportedInstruction(format!(
                "non-integer switch selector type: {:?}",
                ty
            ))),
        }
    }

    fn normalize_switch_case_value(
        value: &Constant,
        selector_bits: u32,
    ) -> Result<i64, AdapterError> {
        let Constant::Int(raw) = value else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "non-integer switch case value: {:?}",
                value
            )));
        };

        debug_assert!(matches!(selector_bits, 8 | 16 | 32 | 64));
        let modulus = 1_i128 << selector_bits;
        let sign_bit = 1_i128 << (selector_bits - 1);
        let normalized = raw.rem_euclid(modulus);
        let signed = if selector_bits <= 16 {
            // A narrow (I8/I16) selector is ZERO-extended to a full GPR before
            // the per-case equality compare: `select_switch` runs the selector
            // through `normalize_condition_operand` under the signedness-agnostic
            // `Equal` condition, which selects `Movzx`/`MovzxW`. The case
            // constant must therefore be its ZERO-extended bit pattern, not a
            // sign-extended value — a high-bit case like a `u8` 0xFF (or, in the
            // same byte, an `i8` -1) must compare as 255, the value the widened
            // selector actually holds. Sign-extending it to -1 would emit a
            // `cmp r64, -1` (0xFFFF_FFFF_FFFF_FFFF) that never matches the
            // zero-extended selector (MISCOMPILE #62). `normalized` is already in
            // [0, 2^bits) and fits i64.
            normalized
        } else if normalized >= sign_bit {
            // 32/64-bit selectors are compared at their native width with no
            // widening, so the 2's-complement i64 reinterpretation is bit-exact.
            normalized - modulus
        } else {
            normalized
        };

        i64::try_from(signed).map_err(|_| {
            AdapterError::UnsupportedInstruction(format!(
                "switch case value {} cannot be represented after {}-bit selector normalization",
                raw, selector_bits
            ))
        })
    }

    fn validate_switch_case_values(
        cases: &[trust_ir::SwitchCase],
        selector_bits: u32,
    ) -> Result<Vec<i64>, AdapterError> {
        let mut seen = HashSet::with_capacity(cases.len());
        let mut normalized_values = Vec::with_capacity(cases.len());
        for case in cases {
            let normalized = Self::normalize_switch_case_value(&case.value, selector_bits)?;
            if !seen.insert(normalized) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "duplicate switch case value after {}-bit selector normalization: {:?} normalizes to {}",
                    selector_bits, case.value, normalized
                )));
            }
            normalized_values.push(normalized);
        }
        Ok(normalized_values)
    }

    fn is_integer_like_ty(ty: &Ty) -> bool {
        matches!(
            ty,
            Ty::Bool
                | Ty::I8
                | Ty::I16
                | Ty::I32
                | Ty::I64
                | Ty::I128
                | Ty::U8
                | Ty::U16
                | Ty::U32
                | Ty::U64
                | Ty::U128
                // v25 pointer-width integers and Char's 32-bit unsigned
                // arithmetic/cast carrier.
                | Ty::Isize
                | Ty::Usize
                | Ty::Char
        )
    }

    fn cast_scalar_bits(ty: &Ty) -> Option<u32> {
        match ty {
            Ty::Bool | Ty::I8 | Ty::U8 => Some(8),
            Ty::I16 | Ty::U16 | Ty::F16 => Some(16),
            Ty::I32 | Ty::U32 | Ty::F32 => Some(32),
            Ty::I64 | Ty::U64 | Ty::F64 | Ty::Ptr => Some(64),
            Ty::I128 | Ty::U128 => Some(128),
            Ty::Isize | Ty::Usize => Some(64),
            Ty::Char => Some(32),
            Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Func(_) => Some(64),
            _ => None,
        }
    }

    /// Fail-closed safety gate for casts. Rejects operand/declared-source
    /// mismatches and any cast whose source/destination shapes are invalid for
    /// the requested cast family (wrong-direction resize, non-pointer pointer
    /// casts, etc.). `Transmute`/`ReifyFnPointer` carry their own provenance
    /// checks in `translate_cast` and are passed through here.
    fn validate_cast_shape(
        &self,
        op: &CastOp,
        src_ty: &Ty,
        dst_ty: &Ty,
        operand: ValueId,
    ) -> Result<(), AdapterError> {
        if matches!(op, CastOp::Transmute | CastOp::ReifyFnPointer) {
            return Ok(());
        }

        let actual_ty = self.lookup_value_ty(operand).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "CastOp::{op:?} operand {operand:?} has no known trust_ir type"
            ))
        })?;
        if actual_ty != *src_ty {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "CastOp::{op:?} source type mismatch: declared src_ty={src_ty:?}, \
                 operand {operand:?} has type {actual_ty:?}"
            )));
        }

        let src_bits = Self::cast_scalar_bits(src_ty);
        let dst_bits = Self::cast_scalar_bits(dst_ty);
        let valid = match op {
            CastOp::Trunc => {
                Self::is_integer_like_ty(src_ty)
                    && Self::is_integer_like_ty(dst_ty)
                    && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst < src)
            }
            CastOp::ZExt | CastOp::SExt => {
                if matches!(src_ty, Ty::Bool) {
                    // A `Bool` source is a logical 1-bit value (machine `Type::B1`);
                    // it zero/sign-extends to ANY wider integer, lowering to the
                    // SAME `Uextend`/`Sextend` (from `B1`) already used for
                    // `Bool -> I16/I32/I64`. `cast_scalar_bits` widens `Bool` to 8
                    // for byte-level reasoning, which would spuriously reject the
                    // genuine widening `Bool(B1) -> I8` (both look like 8 bits), so
                    // treat a `Bool` source as the narrowest integer here. `dst`
                    // must be a non-`Bool` integer (a `Bool -> Bool` "extension" is
                    // not a real cast).
                    Self::is_integer_like_ty(dst_ty) && !matches!(dst_ty, Ty::Bool)
                } else {
                    Self::is_integer_like_ty(src_ty)
                        && Self::is_integer_like_ty(dst_ty)
                        && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst > src)
                }
            }
            CastOp::FPTrunc => {
                Self::is_float_ty(src_ty)
                    && Self::is_float_ty(dst_ty)
                    && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst < src)
            }
            CastOp::FPExt => {
                Self::is_float_ty(src_ty)
                    && Self::is_float_ty(dst_ty)
                    && matches!((src_bits, dst_bits), (Some(src), Some(dst)) if dst > src)
            }
            CastOp::FPToSI | CastOp::FPToUI => {
                Self::is_float_ty(src_ty) && Self::is_integer_like_ty(dst_ty)
            }
            // Saturating float->int casts share the FPToSI/FPToUI shape rule.
            // Translation below selects a destination-width-specific audited
            // expansion; this validation must not collapse them into the raw
            // non-saturating cast variants.
            CastOp::FPToSISat | CastOp::FPToUISat => {
                Self::is_float_ty(src_ty) && Self::is_integer_like_ty(dst_ty)
            }
            CastOp::SIToFP | CastOp::UIToFP => {
                Self::is_integer_like_ty(src_ty) && Self::is_float_ty(dst_ty)
            }
            CastOp::PtrToInt => {
                Self::is_pointer_like_ty(src_ty)
                    && Self::is_integer_like_ty(dst_ty)
                    && dst_bits == Some(64)
            }
            CastOp::IntToPtr => {
                Self::is_integer_like_ty(src_ty)
                    && src_bits == Some(64)
                    && Self::is_pointer_like_ty(dst_ty)
            }
            CastOp::PtrToPtr => {
                Self::is_pointer_like_ty(src_ty) && Self::is_pointer_like_ty(dst_ty)
            }
            CastOp::Bitcast => {
                !Self::is_pointer_like_ty(src_ty)
                    && !Self::is_pointer_like_ty(dst_ty)
                    && src_bits.is_some()
                    && src_bits == dst_bits
            }
            // These producer-level casts have no generic scalar shape beyond
            // the dedicated translation checks below.
            CastOp::Transmute | CastOp::ReifyFnPointer => true,
        };

        if valid {
            Ok(())
        } else {
            Err(AdapterError::UnsupportedInstruction(format!(
                "CastOp::{op:?} source/destination shape is invalid or unsupported: \
                 src_ty={src_ty:?} dst_ty={dst_ty:?}; replacement lowering requires \
                 explicit integer/float width, pointer-width, and provenance-compatible cast rules"
            )))
        }
    }

    // -----------------------------------------------------------------------
    // Instruction translation
    // -----------------------------------------------------------------------

    /// Translate a single trust_ir instruction node into one or more LIR instructions.
    ///
    /// All operands in real trust_ir are ValueId (no inline constants),
    /// so there is no operand resolution step.
    fn translate_instruction(
        &mut self,
        node: &InstrNode,
    ) -> Result<Vec<Instruction>, AdapterError> {
        // Real trust_ir uses block parameters for phi semantics, so there is no Inst::Phi arm here.
        match &node.inst {
            Inst::BinOp { op, ty, lhs, rhs } => {
                // `<8 x i8>` (V64 / D-register) bitwise ops — hashbrown's
                // `simd_or` of two `uint8x8_t` control masks lowers here to
                // NEON `orr.8b`. Only the lane-agnostic bitwise ops are
                // covered (the group scan needs OR); arithmetic on V64 has no
                // consumer yet and fails closed below.
                if Self::is_v8i8_ty(ty) {
                    let opcode = match op {
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "<8 x i8> BinOp::{op:?} is not supported by V64 vector lowering \
                                 (only And/Or/Xor are covered)"
                            )));
                        }
                    };
                    self.require_trust_ir_operand_type("<8 x i8>", "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type("<8 x i8>", "rhs", *rhs, ty)?;
                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V64);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v16i8_ty(ty) || Self::is_v8i16_ty(ty) {
                    let (shape, add_opcode, sub_opcode, mul_opcode) = if Self::is_v16i8_ty(ty) {
                        ("<16 x i8>", Opcode::V16I8Add, Opcode::V16I8Sub, Opcode::V16I8Mul)
                    } else {
                        ("<8 x i16>", Opcode::V8I16Add, Opcode::V8I16Sub, Opcode::V8I16Mul)
                    };
                    self.require_trust_ir_operand_type(shape, "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type(shape, "rhs", *rhs, ty)?;
                    let opcode = match op {
                        BinOp::Add => add_opcode,
                        BinOp::Sub => sub_opcode,
                        BinOp::Mul => mul_opcode,
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{op:?} is not supported by typed narrow vector lowering"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v2i64_ty(ty) {
                    let opcode = match op {
                        BinOp::Add => Opcode::V2I64Add,
                        BinOp::Sub => Opcode::V2I64Sub,
                        // <2 x i64> has no single-instruction packed multiply on
                        // SSE2 or NEON; the typed `V2I64Mul` op is lowered by both
                        // ISels through scalar lane extraction, two 64-bit scalar
                        // multiplies, and a vector repack. Emitting the typed op
                        // keeps the adapter free of lane-scalarization memory.
                        BinOp::Mul => Opcode::V2I64Mul,
                        // Bitwise ops are lane-width-agnostic over the 128-bit
                        // register, so they reuse the same covered NEON
                        // AND/ORR/EOR as the V4I32/V16I8 shapes (select_logic
                        // V128 -> NeonAndV/NeonOrrV/NeonEorV).
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "<2 x i64> BinOp::{op:?} is not supported by typed vector lowering"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty) {
                    let shape = if Self::is_v4f32_ty(ty) {
                        "<4 x f32>"
                    } else {
                        "<2 x f64>"
                    };
                    self.require_trust_ir_operand_type(shape, "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type(shape, "rhs", *rhs, ty)?;
                    // Packed FMin/FMax/FRem have no single SSE/NEON opcode wired
                    // here, but the per-lane scalar op IS the packed semantics —
                    // lower lane-wise via a stack round-trip (reusing only proven
                    // opcodes: scalar Fmin/Fmax for min/max, a per-lane fmod/fmodf
                    // CALL for remainder), exactly like packed FSqrt. std::simd
                    // min/max and vectorized fmod reach this.
                    if matches!(op, BinOp::FMin | BinOp::FMax | BinOp::FRem) {
                        return self.translate_packed_fp_binary_via_stack(
                            *op,
                            ty,
                            *lhs,
                            *rhs,
                            &node.results,
                        );
                    }
                    let opcode = match (Self::is_v4f32_ty(ty), op) {
                        (true, BinOp::FAdd) => Opcode::V4F32Fadd,
                        (true, BinOp::FSub) => Opcode::V4F32Fsub,
                        (true, BinOp::FMul) => Opcode::V4F32Fmul,
                        (true, BinOp::FDiv) => Opcode::V4F32Fdiv,
                        (false, BinOp::FAdd) => Opcode::V2F64Fadd,
                        (false, BinOp::FSub) => Opcode::V2F64Fsub,
                        (false, BinOp::FMul) => Opcode::V2F64Fmul,
                        (false, BinOp::FDiv) => Opcode::V2F64Fdiv,
                        // Fail closed for any non-FP / unimplemented packed-FP
                        // shape (e.g. FRem, integer ops on FP vectors): never
                        // silently miscompile.
                        (_, other) => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "{shape} BinOp::{other:?} has no packed SSE floating-point lowering; \
                                 only FAdd/FSub/FMul/FDiv are lowered for packed FP vectors"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if Self::is_v4i32_ty(ty) {
                    self.require_trust_ir_operand_type("<4 x i32>", "lhs", *lhs, ty)?;
                    self.require_trust_ir_operand_type("<4 x i32>", "rhs", *rhs, ty)?;
                    let opcode = match op {
                        BinOp::Add => Opcode::V4I32Add,
                        BinOp::Sub => Opcode::V4I32Sub,
                        BinOp::Mul => Opcode::V4I32Mul,
                        // Bitwise And/Or/Xor over a V128-typed vector are lane
                        // width-agnostic: the scalar Band/Bor/Bxor opcodes
                        // operate bit-for-bit over the whole 128-bit register
                        // (lowered to SSE2 PAND/POR/PXOR), so they correctly
                        // implement the packed <4 x i32> bitwise op.
                        BinOp::And => Opcode::Band,
                        BinOp::Or => Opcode::Bor,
                        BinOp::Xor => Opcode::Bxor,
                        // Lane-wise `<4 x i32>` shifts. trust_ir vector
                        // `BinOp::{Shl,LShr,AShr}` carries a vector RHS (one
                        // count per lane); we emit the generic Ishl/Ushr/Sshr
                        // opcode with both operands typed V128 and let each
                        // backend lower it lane-wise:
                        //   * x86-64 isel recognises a uniform-constant RHS
                        //     (built from a `pack_lanes` of one constant) and
                        //     emits the SMT-verified SSE2 packed-immediate shift
                        //     PSLLD/PSRLD/PSRAD (`proof_x86_v4i32_*_uniform_*`);
                        //     a non-uniform RHS scalarises per lane.
                        //   * AArch64 isel emits the SMT-verified NEON SIMD
                        //     shift-by-immediate SHL/USHR/SSHR.4S for a
                        //     uniform-constant RHS (`proof_vector_{shl,ushr,sshr}_4s`)
                        //     and otherwise fails closed (it never silently
                        //     reinterprets a packed shift as a scalar one).
                        BinOp::Shl => Opcode::Ishl,
                        BinOp::LShr => Opcode::Ushr,
                        BinOp::AShr => Opcode::Sshr,
                        _ => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "<4 x i32> BinOp::{op:?} is not supported by typed vector lowering"
                            )));
                        }
                    };

                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, Type::V128);
                    return Ok(vec![Instruction {
                        opcode,
                        args: vec![self.map_value(*lhs), self.map_value(*rhs)],
                        results: vec![result],
                    }]);
                }
                if matches!(ty, Ty::Vector(_, _)) && !Self::is_v4i32_ty(ty) {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "BinOp::{op:?} over unsupported vector shape {ty:?}; \
                         only <16 x i8>, <8 x i16>, <4 x i32>, <2 x i64>, <4 x f32>, and <2 x f64> vector arithmetic is lowered today"
                    )));
                }

                // Scalar floating-point remainder has no native machine
                // instruction: lower it to a call to the libm `fmod`/`fmodf`
                // symbol (resolved by the linker), matching how scalar FRem is
                // defined for C/Rust. The ISel lowers `Opcode::Call` to BL/CALL.
                if *op == BinOp::FRem {
                    self.validate_binop_operand_tys(*op, ty, *lhs, *rhs)?;
                    // f16 has no dedicated fmod libcall, but `fmod` is EXACT — its
                    // remainder is exactly representable in the source format — so
                    // `f16 rem(a,b) = f16(fmodf(f32(a), f32(b)))`: promote both
                    // operands to f32 (exact, f16 subset f32), call the existing
                    // `fmodf`, demote the result to f16 (exact, the remainder is
                    // f16-representable). No f16 fmod ABI is required.
                    if matches!(ty, Ty::F16) {
                        let lhs_val = self.map_value(*lhs);
                        let rhs_val = self.map_value(*rhs);
                        let a32 = self.fresh_value();
                        self.define_value_type(a32, Type::F32);
                        let b32 = self.fresh_value();
                        self.define_value_type(b32, Type::F32);
                        let r32 = self.fresh_value();
                        self.define_value_type(r32, Type::F32);
                        let result = self.map_result(&node.results)?;
                        self.define_value_type(result, Type::F16);
                        return Ok(vec![
                            Instruction {
                                opcode: Opcode::FPExt,
                                args: vec![lhs_val],
                                results: vec![a32],
                            },
                            Instruction {
                                opcode: Opcode::FPExt,
                                args: vec![rhs_val],
                                results: vec![b32],
                            },
                            Instruction {
                                opcode: Opcode::Call {
                                    name: "fmodf".to_string(),
                                },
                                args: vec![a32, b32],
                                results: vec![r32],
                            },
                            Instruction {
                                opcode: Opcode::FPTrunc,
                                args: vec![r32],
                                results: vec![result],
                            },
                        ]);
                    }
                    let (callee, result_ty) = match ty {
                        Ty::F32 => ("fmodf", Type::F32),
                        Ty::F64 => ("fmod", Type::F64),
                        other => {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "BinOp::FRem requires f16, f32, or f64 operands, got {other:?}"
                            )));
                        }
                    };

                    let lhs_val = self.map_value(*lhs);
                    let rhs_val = self.map_value(*rhs);
                    let result = self.map_result(&node.results)?;
                    self.define_value_type(result, result_ty);
                    return Ok(vec![Instruction {
                        opcode: Opcode::Call {
                            name: callee.to_string(),
                        },
                        args: vec![lhs_val, rhs_val],
                        results: vec![result],
                    }]);
                }

                // Fail-closed safety gates: reject operands that do not match the
                // declared scalar type, and reject opcode/type-family mismatches
                // (e.g. integer/shift ops over a float type) before lowering.
                self.validate_binop_operand_tys(*op, ty, *lhs, *rhs)?;
                self.validate_scalar_binop_shape(*op, ty)?;

                let opcode = match op {
                    BinOp::Add => Opcode::Iadd,
                    BinOp::Sub => Opcode::Isub,
                    BinOp::Mul => Opcode::Imul,
                    BinOp::UDiv => Opcode::Udiv,
                    BinOp::SDiv => Opcode::Sdiv,
                    BinOp::URem => Opcode::Urem,
                    BinOp::SRem => Opcode::Srem,
                    BinOp::FAdd => Opcode::Fadd,
                    BinOp::FSub => Opcode::Fsub,
                    BinOp::FMul => Opcode::Fmul,
                    BinOp::FDiv => Opcode::Fdiv,
                    BinOp::FRem => {
                        unreachable!("FRem is lowered to an fmod/fmodf libcall before generic arithmetic lowering")
                    }
                    BinOp::FMin => Opcode::Fmin,
                    BinOp::FMax => Opcode::Fmax,
                    BinOp::And => Opcode::Band,
                    BinOp::Or => Opcode::Bor,
                    BinOp::Xor => Opcode::Bxor,
                    // Trust: the BOOLEAN connectives lower to the SAME machine
                    // opcodes. That is exact, not an approximation: the shape gate
                    // above admits them on `Ty::Bool` only, whose carrier is 0/1, and
                    // on 0/1 the bitwise instruction computes the logical result. The
                    // distinction these opcodes carry is a VERIFICATION one -- it buys
                    // a reducing denotation instead of an opaque one -- and has no
                    // machine-level consequence here.
                    BinOp::BAnd => Opcode::Band,
                    BinOp::BOr => Opcode::Bor,
                    BinOp::BXor => Opcode::Bxor,
                    BinOp::Shl => Opcode::Ishl,
                    BinOp::LShr => Opcode::Ushr,
                    BinOp::AShr => Opcode::Sshr,
                };

                let lhs_val = self.map_value(*lhs);
                let rhs_val = self.map_value(*rhs);
                let result = self.map_result(&node.results)?;

                let mut insts = Vec::new();
                if integer_div_or_rem_has_nonzero_proof(*op, node) {
                    // DivNonZero IS the upstream safety proof: synthesize (or reuse a ProofRef's)
                    // Discharged obligation so the kernel-gated proof pass can authorize eliminating
                    // the div-zero guard, exactly as NotNull does for the null guard.
                    let obligation = self.divisor_not_zero_obligation(node);
                    insts.push(Instruction {
                        opcode: Opcode::GuardDivZero { obligation },
                        args: vec![rhs_val],
                        results: vec![],
                    });
                }
                if let Some(bitwidth) = shift_has_in_range_proof(*op, ty, node) {
                    // ShiftInRange IS the upstream safety proof: synthesize (or reuse a ProofRef's)
                    // Discharged obligation so the kernel-gated proof pass can authorize eliminating
                    // the shift-range guard, exactly as InBounds does for the bounds guard.
                    let obligation = self.shift_in_range_obligation(node);
                    insts.push(Instruction {
                        opcode: Opcode::GuardShiftRange {
                            bitwidth,
                            obligation,
                        },
                        args: vec![rhs_val],
                        results: vec![],
                    });
                }
                insts.push(Instruction {
                    opcode,
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                });

                Ok(insts)
            }

            Inst::UnOp { op, ty, operand } => {
                // Packed FP negate / abs on a supported FP vector shape lower as
                // a bitwise sign-mask op over the V128 lanes, reusing the
                // already-covered NEON EOR (Bxor) / BIC (BandNot) — no new
                // opcode. `Fneg` flips each lane's sign bit (EOR mask); `Fabs`
                // clears it (BIC mask). Bit-flip negation is the correct IEEE
                // semantics (it yields -0.0 from +0.0, unlike `0 - x`).
                if matches!(op, UnOp::FNeg | UnOp::FAbs)
                    && (Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty))
                {
                    return self.translate_packed_fp_sign_op(*op, ty, *operand, &node.results);
                }
                // Packed integer negate = `0 - v`, reusing the covered per-shape
                // packed subtract. No new opcode.
                if matches!(op, UnOp::Neg)
                    && (Self::is_v16i8_ty(ty)
                        || Self::is_v8i16_ty(ty)
                        || Self::is_v4i32_ty(ty)
                        || Self::is_v2i64_ty(ty))
                {
                    return self.translate_packed_int_neg(ty, *operand, &node.results);
                }
                // Packed bitwise NOT = `v XOR all-ones`, reusing the covered
                // type-agnostic 128-bit EOR (Bxor) — same machinery as packed
                // FNeg's sign-bit EOR. No new opcode.
                if matches!(op, UnOp::Not)
                    && (Self::is_v16i8_ty(ty)
                        || Self::is_v8i16_ty(ty)
                        || Self::is_v4i32_ty(ty)
                        || Self::is_v2i64_ty(ty))
                {
                    return self.translate_packed_int_not(ty, *operand, &node.results);
                }
                // Packed FP sqrt / round (floor/ceil/trunc) over <4 x f32> /
                // <2 x f64>: lane-wise via a stack round-trip (store the vector,
                // apply the SCALAR FP op to each lane in memory, reload). Reuses
                // only already-proven opcodes (StackAddr/Store/ArrayGep/Load +
                // scalar Fsqrt/Ffloor/Fceil/Ftrunc) — per-lane application IS the
                // packed semantics, so no new vector opcode or lowering proof is
                // needed. A later pass may fuse it to NEON FSQRT/FRINTx.
                if matches!(
                    op,
                    UnOp::FSqrt | UnOp::FFloor | UnOp::FCeil | UnOp::FTrunc
                ) && (Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty))
                {
                    return self.translate_packed_unary_via_stack(
                        *op,
                        ty,
                        *operand,
                        &node.results,
                    );
                }
                // Packed integer population count over <16 x i8> / <8 x i16> /
                // <4 x i32> / <2 x i64>: same lane-wise stack round-trip, applying
                // the scalar CtPop per lane. Reuses only proven opcodes.
                if matches!(op, UnOp::CtPop)
                    && (Self::is_v16i8_ty(ty)
                        || Self::is_v8i16_ty(ty)
                        || Self::is_v4i32_ty(ty)
                        || Self::is_v2i64_ty(ty))
                {
                    return self.translate_packed_unary_via_stack(
                        *op,
                        ty,
                        *operand,
                        &node.results,
                    );
                }
                // Fail closed for the REMAINING vector unary ops. Packed FNeg/FAbs,
                // packed FP sqrt/round, packed integer Neg, and packed integer Not
                // (on their supported lane shapes) are already lowered by the
                // early-returns above. The scalar Fneg/Ineg/Bnot/CtPop opcodes
                // operate on a single scalar lane, so emitting them for a V128-typed
                // operand would silently miscompile a packed vector. The still-
                // unlowered packed unary op — integer CtPop — plus any unsupported
                // lane shape are rejected here rather than lowered incorrectly.
                if matches!(ty, Ty::Vector(_, _)) {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "UnOp::{op:?} over vector type {ty:?} has no packed lowering \
                         for this lane shape (packed FNeg/FAbs, FSqrt/floor/ceil/trunc, \
                         integer Neg/Not, and integer CtPop are handled above for their \
                         supported lane shapes; other op/shape combinations are rejected)"
                    )));
                }
                // Fail-closed safety gate: reject operand/declared-type mismatch
                // and opcode/type-family mismatch before scalar lowering.
                self.validate_unop_shape(*op, ty, *operand)?;
                let opcode = match op {
                    UnOp::Neg => Opcode::Ineg,
                    UnOp::FNeg => Opcode::Fneg,
                    UnOp::FAbs => Opcode::Fabs,
                    UnOp::FSqrt => Opcode::Fsqrt,
                    UnOp::FFloor => Opcode::Ffloor,
                    UnOp::FCeil => Opcode::Fceil,
                    UnOp::FTrunc => Opcode::Ftrunc,
                    UnOp::Not => Opcode::Bnot,
                    UnOp::CtPop => Opcode::CtPop,
                };

                let src = self.map_value(*operand);
                let dst = self.map_result(&node.results)?;

                Ok(vec![Instruction {
                    opcode,
                    args: vec![src],
                    results: vec![dst],
                }])
            }

            Inst::Overflow { op, ty, lhs, rhs } => {
                self.translate_overflow(op, ty, *lhs, *rhs, &node.results, node)
            }

            Inst::ICmp { op, ty, lhs, rhs } => {
                // OPT-6a: the frontend bounds-check probe (an `InBounds`-annotated
                // `Ult` compare against a constant bound) ADDITIONALLY emits a
                // proof-only `GuardBoundsCheck` carrier bound to the probe's module
                // obligation (if any) — the rustc-bridge's route into the verified
                // Certified-Elimination Kernel. The compare itself still lowers
                // below (its result is typically dead and DCE-able); the carrier is
                // what the kernel either deletes (obligation discharged) or the
                // pipeline expands into the real CMP+Jcc+UD2 runtime check.
                // Recognition is total and fail-closed: see
                // `frontend_bounds_probe`.
                let probe_carrier = match self.frontend_bounds_probe(node) {
                    Some(Ok((bound, obligation))) => {
                        let index_val = self.map_value(*lhs);
                        Some(match bound {
                            BoundsProbeBound::Const(bound) => Instruction {
                                opcode: Opcode::GuardBoundsCheck { bound, obligation },
                                args: vec![index_val, index_val],
                                results: vec![],
                            },
                            // DYNAMIC length: the bound rides as a third ARG
                            // rather than an opcode field, and lowers to a
                            // TrapBoundsCheckExact whose bound slot is a
                            // register. Same trap semantics, same fail-safe
                            // contract; the only difference is that `v.len()`
                            // is not knowable until runtime.
                            BoundsProbeBound::Dyn(len) => {
                                let len_val = self.map_value(len);
                                Instruction {
                                    opcode: Opcode::GuardBoundsCheckDyn { obligation },
                                    args: vec![index_val, index_val, len_val],
                                    results: vec![],
                                }
                            }
                        })
                    }
                    Some(Err(err)) => return Err(err),
                    None => None,
                };
                // OPT-6b: a RESULT-LESS probe is PROOF-ONLY — the frontend declared
                // the compare's value unobservable (nothing consumes it; the eager
                // bounds branch was replaced by the carrier channel), so lowering a
                // dead flag-materialization (`cmp` + `setcc`, which the machine DCE
                // conservatively keeps as a flag-writer) would tax every loop
                // iteration for nothing. Emit ONLY the carrier: the carrier alone
                // carries the check's full trap semantics — KEPT, it expands into a
                // complete CMP+Jcc+UD2 runtime check with its own compare; DELETED,
                // that deletion is licensed by the kernel against the discharged
                // obligation exactly as for a result-carrying probe. A result-less
                // ICmp that is NOT a recognized probe still fails closed below
                // (`map_result` on an empty result list), unchanged.
                if node.results.is_empty()
                    && let Some(carrier) = probe_carrier {
                        return Ok(vec![carrier]);
                    }
                let cond = match op {
                    ICmpOp::Eq => IntCC::Equal,
                    ICmpOp::Ne => IntCC::NotEqual,
                    ICmpOp::Ult => IntCC::UnsignedLessThan,
                    ICmpOp::Ule => IntCC::UnsignedLessThanOrEqual,
                    ICmpOp::Ugt => IntCC::UnsignedGreaterThan,
                    ICmpOp::Uge => IntCC::UnsignedGreaterThanOrEqual,
                    ICmpOp::Slt => IntCC::SignedLessThan,
                    ICmpOp::Sle => IntCC::SignedLessThanOrEqual,
                    ICmpOp::Sgt => IntCC::SignedGreaterThan,
                    ICmpOp::Sge => IntCC::SignedGreaterThanOrEqual,
                };

                if Self::is_v16i8_ty(ty) || Self::is_v8i16_ty(ty) {
                    return self.translate_narrow_int_vector_icmp(
                        cond,
                        ty,
                        *lhs,
                        *rhs,
                        &node.results,
                    );
                }
                if Self::is_v4i32_ty(ty) {
                    return self.translate_v4i32_icmp(cond, *lhs, *rhs, &node.results);
                }
                if Self::is_v2i64_ty(ty) {
                    return self.translate_v2i64_icmp(cond, *lhs, *rhs, &node.results);
                }
                if Self::is_v8i8_ty(ty) {
                    return self.translate_v8i8_icmp(cond, *lhs, *rhs, &node.results);
                }
                if matches!(ty, Ty::Vector(_, _)) && !Self::is_v4i32_ty(ty) {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "ICmp::{op:?} over unsupported vector shape {ty:?}; \
                         only <16 x i8>, <8 x i16>, <4 x i32>, <2 x i64>, and <8 x i8> vector compares are lowered today"
                    )));
                }

                // Fail-closed safety gate for scalar compares: reject non-integer
                // (and non Bool/pointer Eq/Ne) declared types and operand/declared
                // type mismatches before lowering to a raw Icmp.
                if !matches!(ty, Ty::Vector(_, _)) {
                    self.validate_icmp_shape(*op, ty)?;
                    self.validate_binary_operand_tys("ICmp", ty, *lhs, *rhs)?;
                }

                let lhs_val = self.map_value(*lhs);
                let rhs_val = self.map_value(*rhs);
                let result = self.map_result(&node.results)?;

                let mut instrs = Vec::with_capacity(2);
                // OPT-6a: the probe's carrier precedes its compare, mirroring the
                // GEP channel where the guard precedes the address computation.
                instrs.extend(probe_carrier);
                instrs.push(Instruction {
                    opcode: Opcode::Icmp { cond },
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                });
                Ok(instrs)
            }

            Inst::FCmp { op, ty, lhs, rhs } => {
                let cond = match op {
                    FCmpOp::OEq => FloatCC::Equal,
                    FCmpOp::ONe => FloatCC::NotEqual,
                    FCmpOp::OLt => FloatCC::LessThan,
                    FCmpOp::OLe => FloatCC::LessThanOrEqual,
                    FCmpOp::OGt => FloatCC::GreaterThan,
                    FCmpOp::OGe => FloatCC::GreaterThanOrEqual,
                    FCmpOp::UEq => FloatCC::UnorderedEqual,
                    FCmpOp::UNe => FloatCC::UnorderedNotEqual,
                    FCmpOp::ULt => FloatCC::UnorderedLessThan,
                    FCmpOp::ULe => FloatCC::UnorderedLessThanOrEqual,
                    FCmpOp::UGt => FloatCC::UnorderedGreaterThan,
                    FCmpOp::UGe => FloatCC::UnorderedGreaterThanOrEqual,
                };

                // Fail-closed safety gate: reject non-float declared types and
                // operand/declared type mismatches before lowering to Fcmp.
                self.validate_fcmp_shape(ty, *lhs, *rhs)?;

                let lhs_val = self.map_value(*lhs);
                let rhs_val = self.map_value(*rhs);
                let result = self.map_result(&node.results)?;

                Ok(vec![Instruction {
                    opcode: Opcode::Fcmp { cond },
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                }])
            }

            Inst::Cast {
                op,
                src_ty,
                dst_ty,
                operand,
            } => self.translate_cast(op, src_ty, dst_ty, operand, &node.results),

            Inst::Load {
                ty,
                ptr,
                volatile,
                align,
            } => {
                // Compute the NotNull obligation (synthesizing a Discharged id from the NotNull proof,
                // exactly as InBounds does) BEFORE the `&mut self` call below. `Some(_)` => emit the
                // guard bound to that obligation; `None` => no NotNull proof, emit no guard.
                let not_null = self.memory_ptr_not_null_obligation(node);
                self.translate_load(ty, ptr, *volatile, *align, &node.results, not_null)
            }

            Inst::Store {
                ty,
                ptr,
                value,
                volatile,
                align,
            } => {
                let not_null = self.memory_ptr_not_null_obligation(node);
                self.translate_store(ty, ptr, value, *volatile, *align, not_null)
            }

            Inst::Alloca { ty, count, align } => self.translate_alloc(
                ty,
                count,
                *align,
                &node.results,
                node.span.as_ref().map(|s| s.line),
            ),

            // GEP stride contract (ABI-critical; see `trust-cg-ir` crate docs
            // and issue #475):
            //   result = base + index * sizeof(pointee_ty)
            // Empty `indices` => Copy (identity). Multi-index GEP is not yet
            // lowered. External consumers (ay, ty) depend on this stride
            // convention — changing it is a P0 ABI break.
            Inst::GEP {
                pointee_ty,
                base,
                indices,
                // `inbounds` is an LLVM-style no-wrap optimization hint
                // (trust-ir inst.rs: "backend hint enabling no-wrap GEP
                // folding"). Ignoring it is always sound: lowering already
                // computes `base + index * sizeof(pointee_ty)` with full,
                // conservative integer arithmetic. Honoring the hint could
                // only enable *additional* folding optimizations, never change
                // the required address; declining them is the fail-safe
                // direction. Do not specialize codegen on this flag without an
                // ay-verified no-wrap lowering.
                inbounds: _,
            } => match indices.as_slice() {
                [] => {
                    let src = self.map_value(*base);
                    let dst = self.map_result(&node.results)?;
                    Ok(vec![Instruction {
                        opcode: Opcode::Copy,
                        args: vec![src],
                        results: vec![dst],
                    }])
                }
                [index] => {
                    let base_ptr = self.map_value(*base);
                    let index_val = self.map_value(*index);
                    let dst = self.map_result(&node.results)?;
                    // Propagate the type error rather than falling back to a
                    // 1-byte stride: a GEP over a pointee with no defined CPU
                    // layout (e.g. Ty::Set/Ty::Sequence) must fail closed, not
                    // silently emit byte-stride pointer arithmetic at a
                    // fabricated element size.
                    //
                    // The stride is the AUTHORITATIVE element size: the
                    // producer's declared size when it stated an emittable
                    // layout, the PACKED size for a `#[repr(packed)]` struct
                    // (e.g. `{u8,u32}` is 5 bytes, not 8), and only otherwise
                    // the natural-C `translate_ty(..).bytes()` — otherwise
                    // `&arr[i]` strides past the element (audit P0/G5).
                    let lir_pointee_ty = self.translate_ty(pointee_ty)?;
                    let elem_size =
                        self.aggregate_value_extent(pointee_ty, &lir_pointee_ty)? as i64;

                    let mut instrs = Vec::new();
                    let index_val =
                        self.extend_index_to_i64_if_needed(*index, index_val, &mut instrs)?;
                    self.append_exact_in_bounds_guard(node, base_ptr, index_val, &mut instrs);
                    let scaled_index = if elem_size == 1 {
                        index_val
                    } else {
                        let size_val = self.fresh_value();
                        instrs.push(Instruction {
                            opcode: Opcode::Iconst {
                                ty: Type::I64,
                                imm: elem_size,
                            },
                            args: vec![],
                            results: vec![size_val],
                        });

                        let scaled = self.fresh_value();
                        instrs.push(Instruction {
                            opcode: Opcode::Imul,
                            args: vec![index_val, size_val],
                            results: vec![scaled],
                        });
                        scaled
                    };

                    instrs.push(Instruction {
                        opcode: Opcode::Iadd,
                        args: vec![base_ptr, scaled_index],
                        results: vec![dst],
                    });

                    Ok(instrs)
                }
                _ => self.translate_multi_index_gep(pointee_ty, *base, indices, &node.results),
            },

            Inst::PtrData { ptr_ty, ptr } => self.translate_ptr_data(ptr_ty, ptr, &node.results),

            Inst::PtrMetadata {
                ptr_ty,
                metadata_ty,
                ptr,
            } => self.translate_ptr_metadata(ptr_ty, metadata_ty, ptr, &node.results),

            Inst::PtrFromParts {
                ptr_ty,
                metadata_ty,
                data,
                metadata,
            } => self.translate_ptr_from_parts(ptr_ty, metadata_ty, data, metadata, &node.results),

            Inst::AtomicLoad { ty, ptr, ordering } => {
                self.translate_atomic_load(ty, ptr, ordering, &node.results)
            }

            Inst::AtomicStore {
                ty,
                ptr,
                value,
                ordering,
            } => self.translate_atomic_store(ty, ptr, value, ordering),

            Inst::AtomicRMW {
                op,
                ty,
                ptr,
                value,
                ordering,
            } => self.translate_atomic_rmw(op, ty, ptr, value, ordering, &node.results),

            Inst::CmpXchg {
                ty,
                ptr,
                expected,
                desired,
                success,
                failure,
            } => {
                let lir_ty = self.translate_ty(ty)?;
                let ptr_val = self.map_value(*ptr);
                let exp_val = self.map_value(*expected);
                let des_val = self.map_value(*desired);
                let old_val = self.map_result(&node.results)?;
                let success_ordering = translate_ordering(success);
                let failure_ordering = translate_ordering(failure);

                // Fail closed for the truly invalid cmpxchg failure orderings —
                // THE rule (Rust/LLVM), shared with both ISel gates via
                // `AtomicOrdering::is_valid_cmpxchg_failure`: the failure
                // (load-only) ordering must not be Release/AcqRel, and there is
                // NO other constraint.
                //
                // THREADS: a failure ordering STRONGER than the success ordering
                // is LEGAL Rust/C++17 (`compare_exchange(.., AcqRel, SeqCst)` in
                // std's mutex/rwlock). The isel's opcode choice assumes
                // `failure <= success`, so LIFT the success ordering to cover
                // the failure ordering (`lift_for_cmpxchg_failure`) — a strictly
                // STRONGER single ordering, never weaker, so the emitted machine
                // sequence over-satisfies both paths (on AArch64 LSE the AcqRel
                // and SeqCst mappings are the same `CASAL` family anyway).
                if !failure_ordering.is_valid_cmpxchg_failure() {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CmpXchg failure ordering {failure_ordering:?} is invalid; the \
                         failure ordering must not be Release/AcqRel"
                    )));
                }
                let success_ordering =
                    success_ordering.lift_for_cmpxchg_failure(failure_ordering);
                debug_assert!(success_ordering.allows_cmpxchg_failure(failure_ordering));

                let mut instrs = vec![Instruction {
                    opcode: Opcode::CmpXchg {
                        ty: lir_ty,
                        success: success_ordering,
                        failure: failure_ordering,
                    },
                    args: vec![exp_val, des_val, ptr_val],
                    results: vec![old_val],
                }];

                if let Some(success_vid) = node.results.get(1) {
                    let success_val = self.map_value(*success_vid);
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp { cond: IntCC::Equal },
                        args: vec![old_val, exp_val],
                        results: vec![success_val],
                    });
                }

                Ok(instrs)
            }

            Inst::Fence { ordering } => self.translate_fence(ordering),

            Inst::Br { target, args } => self.translate_br(target, args),

            Inst::CondBr {
                cond,
                then_target,
                then_args,
                else_target,
                else_args,
            } => self.translate_condbr(cond, then_target, then_args, else_target, else_args),

            Inst::Switch {
                value,
                default,
                default_args,
                cases,
                // `exhaustive_enum_unreachable` is a trust-side hint for the
                // native CHC translator (it conjoins `selector ∈ {case values}`
                // into the default arm to prove it UNSAT). It is a VERIFICATION
                // fact, not a codegen change: the CPU `Opcode::Switch` carries no
                // exhaustiveness field and always emits the default fallthrough
                // edge, so the lowered machine code is identical whether the flag
                // is set or not. Bound and intentionally ignored here.
                exhaustive_enum_unreachable: _,
            } => {
                // BUG FIX (issue #304): Same pattern as condbr (#302) — copies
                // for each case must only execute on the correct edge. Create
                // intermediate copy blocks when block arguments are present.

                let mut instrs = Vec::new();
                let selector_ty = self
                    .lookup_value_ty(*value)
                    .ok_or(AdapterError::UnknownValue(value.index()))?;
                let selector_bits = Self::switch_selector_bits(&selector_ty)?;
                let normalized_case_values =
                    Self::validate_switch_case_values(cases, selector_bits)?;
                let selector = self.map_value(*value);

                let default_copies = self.resolve_block_args(*default, default_args)?;

                // Default case: create copy block if there are copies.
                let default_block = if !default_copies.is_empty() {
                    let copy_block_id = self.fresh_block();
                    let real_default_dest = self.map_block(*default);
                    let mut copy_bb = BasicBlock {
                        instructions: default_copies,
                        ..Default::default()
                    };
                    copy_bb.instructions.push(Instruction {
                        opcode: Opcode::Jump {
                            dest: real_default_dest,
                        },
                        args: vec![],
                        results: vec![],
                    });
                    self.pending_extra_blocks.push((copy_block_id, copy_bb));
                    copy_block_id
                } else {
                    self.map_block(*default)
                };

                let mut lir_cases = Vec::with_capacity(cases.len());

                for (case, case_value) in cases.iter().zip(normalized_case_values) {
                    let case_copies = self.resolve_block_args(case.target, &case.args)?;

                    // Each case: create copy block if there are copies.
                    let case_dest = if !case_copies.is_empty() {
                        let copy_block_id = self.fresh_block();
                        let real_case_dest = self.map_block(case.target);
                        let mut copy_bb = BasicBlock {
                            instructions: case_copies,
                            ..Default::default()
                        };
                        copy_bb.instructions.push(Instruction {
                            opcode: Opcode::Jump {
                                dest: real_case_dest,
                            },
                            args: vec![],
                            results: vec![],
                        });
                        self.pending_extra_blocks.push((copy_block_id, copy_bb));
                        copy_block_id
                    } else {
                        self.map_block(case.target)
                    };

                    lir_cases.push((case_value, case_dest));
                }

                instrs.push(Instruction {
                    opcode: Opcode::Switch {
                        cases: lir_cases,
                        default: default_block,
                    },
                    args: vec![selector],
                    results: vec![],
                });

                Ok(instrs)
            }

            Inst::Call { callee, args } => {
                self.validate_direct_call_signature(*callee, args, &node.results)?;
                let mut arg_vals: Vec<Value> = args.iter().map(|vid| self.map_value(*vid)).collect();
                let result_vals = self.map_results(&node.results);
                let callee_name = self
                    .func_names
                    .get(callee)
                    .cloned()
                    .unwrap_or_else(|| format!("__func_{}", callee.index()));

                // Detect memory intrinsics and emit specialized opcodes.
                // These are recognized by name: bare libc names and LLVM
                // intrinsic prefixes (e.g., "llvm.memcpy.p0.p0.i64").
                if is_memcpy_intrinsic(&callee_name) {
                    return Ok(self.mem_intrinsic_instrs(Opcode::Memcpy, arg_vals, &result_vals));
                }
                if is_memmove_intrinsic(&callee_name) {
                    return Ok(self.mem_intrinsic_instrs(Opcode::Memmove, arg_vals, &result_vals));
                }
                if is_memset_intrinsic(&callee_name) {
                    return Ok(self.mem_intrinsic_instrs(Opcode::Memset, arg_vals, &result_vals));
                }
                if let Some(bitwidth) = bitreverse_intrinsic_bitwidth(&callee_name) {
                    return self.translate_bitreverse_intrinsic(bitwidth, &arg_vals, &result_vals);
                }
                if let Some(bitwidth) = objectsize_intrinsic_bitwidth(&callee_name) {
                    return self.translate_objectsize_intrinsic(bitwidth, args, &result_vals);
                }
                if let Some((fp_ty, may_unfuse)) = fma_intrinsic_contract(&callee_name) {
                    return self.translate_fma_intrinsic(
                        fp_ty,
                        may_unfuse,
                        &arg_vals,
                        &result_vals,
                    );
                }

                // Propagate callee return types onto the Call result Values
                // so ISel's `value_type()` returns the true type instead of
                // the I64 fallback (#381). The lookup yields an empty Vec
                // for unknown/extern callees; in that case we leave the
                // types unrecorded and preserve pre-#381 behavior.
                let ret_tys = self.lookup_callee_return_types(*callee);
                for (val, ty) in result_vals.iter().zip(ret_tys.iter()) {
                    self.define_value_type(*val, ty.clone());
                }

                // Seed aggregate callee PARAMETER types onto call-site-scoped
                // Copy temps so a by-value aggregate (carried by address,
                // hence typed as a pointer) is classified by ISel as a System V
                // register-pair / sret argument instead of a single GPR. The
                // returned Copies must execute immediately before the Call.
                let param_tys = self.lookup_callee_param_types(*callee);
                let mut insts = self.record_aggregate_call_arg_types(&mut arg_vals, &param_tys)?;

                // Propagate callee purity onto the LIR Call name so ISel can
                // tag the emitted `Bl` MachInst with `ProofAnnotation::Pure`.
                // Extern/unknown callees (callee not in `pure_func_ids`)
                // default to non-pure. Memory intrinsics above are handled
                // separately and are never tagged pure. (#456)
                if self.pure_func_ids.contains(callee) {
                    self.pure_callees.insert(callee_name.clone());
                }
                // Importer-licensed libm-pure external callees (intrinsic-origin
                // math calls; see `LLVM_LIBM_PURE_FUNCTION_ATTR_TAG`). Disjoint
                // from `pure_func_ids` (which excludes bodyless externals).
                if self.libm_pure_func_ids.contains(callee) {
                    self.libm_pure_callees.insert(callee_name.clone());
                }

                let opcode = if let Some(func_ty) = self.lookup_callee_func_ty(*callee) {
                    if func_ty.is_vararg {
                        Opcode::CallVariadic {
                            name: callee_name,
                            fixed_args: func_ty.params.len() as u32,
                        }
                    } else {
                        Opcode::Call { name: callee_name }
                    }
                } else {
                    Opcode::Call { name: callee_name }
                };

                // Apple arm64 ABI: the CALLER must sign/zero-extend a sub-word
                // integer argument to 32 bits before the call — the mirror of the
                // callee-side return extension (translate_return). Extend each
                // narrow fixed argument per the callee's DECLARED param signedness
                // (Ty::I8 vs Ty::U8), which is lost once lowered to the machine
                // Type; an LLVM-compiled callee at -O2 trusts the extension and
                // reads the register directly. Variadic tail args are promoted by
                // the frontend and left alone. See e2e_aarch64_call_arg_signext.rs.
                //
                // This extension applies ONLY to arguments passed in registers.
                // A narrow argument passed on the STACK is stored at its natural
                // width and packed offset, UNEXTENDED (the callee sign/zero-
                // extends it on load) — clang does exactly this. Extending a
                // stack argument would widen it into a 4-byte slot at the wrong
                // packed offset and clobber the neighbouring argument, so classify
                // against the callee's machine param types and skip stack args.
                // See e2e_aarch64_stack_narrow_args.rs.
                //
                // The extension instructions are appended to `insts`, which
                // already carries THEIRS' aggregate-by-value Copy temps from
                // record_aggregate_call_arg_types; both precede the Call. The
                // param classes are disjoint (aggregate vs narrow-int) so the
                // relative order of the two groups does not matter.
                let callee_param_tys: Vec<Ty> = self
                    .lookup_callee_func_ty(*callee)
                    .map(|ft| ft.params.clone())
                    .unwrap_or_default();
                let arg_locs = crate::abi::AppleAArch64ABI::classify_params(&param_tys);
                for (idx, param_ty) in callee_param_tys.iter().enumerate() {
                    // Only register arguments are caller-extended; stack args keep
                    // their natural width (stored via StrbRI/StrhRI in ISel).
                    if !matches!(arg_locs.get(idx), Some(crate::abi::ArgLocation::Reg(_))) {
                        continue;
                    }
                    let ext = match param_ty {
                        Ty::I8 => Some((Type::I8, true)),
                        Ty::U8 => Some((Type::I8, false)),
                        Ty::I16 => Some((Type::I16, true)),
                        Ty::U16 => Some((Type::I16, false)),
                        _ => None,
                    };
                    if let (Some((from_ty, signed)), Some(&arg_slot)) =
                        (ext, arg_vals.get(idx))
                    {
                        let widened = self.fresh_value();
                        self.define_value_type(widened, Type::I32);
                        let ext_opcode = if signed {
                            Opcode::Sextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        } else {
                            Opcode::Uextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        };
                        insts.push(Instruction {
                            opcode: ext_opcode,
                            args: vec![arg_slot],
                            results: vec![widened],
                        });
                        arg_vals[idx] = widened;
                    }
                }

                insts.push(Instruction {
                    opcode,
                    args: arg_vals,
                    results: result_vals,
                });
                Ok(insts)
            }

            // `calling_conv` (trust_ir v12+) declares the expected ABI of the
            // dynamically-resolved callee. trust-cg lowering currently supports
            // only the C convention for every call edge. The direct `Call` arm
            // already fails closed on non-C edges (via
            // `validate_direct_call_signature`'s callee-convention check and the
            // per-function guard), so the indirect path mirrors those guards
            // here rather than silently using the target default ABI. Revisit
            // when cg grows per-edge ABI selection.
            Inst::CallIndirect { callee, sig, args, calling_conv } => {
                // Admit the Swift scalar subset here too (mirrors the direct-call
                // and per-function guards): a C-ABI lowering is correct for both
                // edges when the signature is scalar-only. Fall back to the
                // convention-only check if the sig can't be resolved.
                let sig_func_ty = self
                    .module
                    .and_then(|m| m.func_types.get(sig.index() as usize));
                let uses_c_abi = match sig_func_ty {
                    Some(ft) => Self::conv_sig_uses_c_register_abi(*calling_conv, ft),
                    None => Self::calling_conv_uses_c_register_abi(*calling_conv),
                };
                if !uses_c_abi {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CallIndirect uses unsupported calling convention {calling_conv:?}; Trust-CG lowers C-register-ABI conventions (C/Fast/Cold/Rust, and the scalar-only subset of Swift) and must not silently use the C ABI for a convention/signature with a different register layout (e.g. Swift with aggregate params or returns)"
                    )));
                }
                self.validate_call_indirect_signature(*callee, *sig, args, &node.results)?;
                let callee_val = self.map_value(*callee);
                let mut arg_vals = vec![callee_val];
                arg_vals.extend(args.iter().map(|vid| self.map_value(*vid)));
                let result_vals = self.map_results(&node.results);

                // Propagate callee return types onto the CallIndirect result
                // Values using the explicit `sig` carried on the trust_ir
                // instruction (#381). Same fallback semantics as Call.
                let ret_tys = self.lookup_func_type_returns(*sig);
                for (val, ty) in result_vals.iter().zip(ret_tys.iter()) {
                    self.define_value_type(*val, ty.clone());
                }

                // Seed aggregate-by-value argument types from the explicit
                // signature (same rationale as the direct-`Call` arm: scoped
                // Copy temps, prepended so they precede the call). The
                // first `arg_vals` entry is the callee pointer, not a call
                // argument, so the param types align with `arg_vals[1..]`.
                let param_tys = self.lookup_func_type_param_types(*sig);
                let mut insts =
                    self.record_aggregate_call_arg_types(&mut arg_vals[1..], &param_tys)?;

                // Apple arm64 ABI caller-side narrow-int extension for register
                // args — the SAME extension the direct `Call` arm performs, which
                // the indirect path previously omitted (audit P0/G6). The callee
                // pointer occupies `arg_vals[0]`, so the declared params align with
                // the argument tail: param `idx` is `arg_vals[idx + 1]`. Extend
                // each narrow fixed argument per the signature's declared
                // signedness (`Ty::I8` vs `Ty::U8`); an LLVM-compiled callee at
                // -O2 trusts the extension and reads the register directly, so a
                // non-canonical narrow value would be read wrong. Only REGISTER
                // args are extended — a narrow STACK arg keeps its natural width
                // (the callee extends it on load), exactly like clang; extending
                // it would clobber the neighbouring packed argument.
                //
                // Appended to `insts` (THEIRS' aggregate Copy temps); both
                // precede the CallIndirect and the param classes are disjoint.
                let callee_param_tys = self.lookup_func_type_param_tys(*sig);
                let arg_locs = crate::abi::AppleAArch64ABI::classify_params(&param_tys);
                for (idx, param_ty) in callee_param_tys.iter().enumerate() {
                    if !matches!(arg_locs.get(idx), Some(crate::abi::ArgLocation::Reg(_))) {
                        continue;
                    }
                    let ext = match param_ty {
                        Ty::I8 => Some((Type::I8, true)),
                        Ty::U8 => Some((Type::I8, false)),
                        Ty::I16 => Some((Type::I16, true)),
                        Ty::U16 => Some((Type::I16, false)),
                        _ => None,
                    };
                    if let (Some((from_ty, signed)), Some(&arg_slot)) =
                        (ext, arg_vals.get(idx + 1))
                    {
                        let widened = self.fresh_value();
                        self.define_value_type(widened, Type::I32);
                        let ext_opcode = if signed {
                            Opcode::Sextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        } else {
                            Opcode::Uextend {
                                from_ty,
                                to_ty: Type::I32,
                            }
                        };
                        insts.push(Instruction {
                            opcode: ext_opcode,
                            args: vec![arg_slot],
                            results: vec![widened],
                        });
                        arg_vals[idx + 1] = widened;
                    }
                }

                insts.push(Instruction {
                    opcode: Opcode::CallIndirect,
                    args: arg_vals,
                    results: result_vals,
                });
                Ok(insts)
            }

            Inst::Return { values } => self.translate_return(values),

            // One coroutine `yield`: save the next resume state into the frame
            // and return the yielded value. Macro-expands into the verified
            // I64 store + return primitives (see `translate_coro_suspend`).
            Inst::CoroSuspend {
                frame,
                state_slot,
                next_state,
                value,
            } => self.translate_coro_suspend(frame, *state_slot, *next_state, value),

            // Exception handling. `Invoke` is a call that may unwind to a
            // landing pad; `LandingPad` reads the unwinder-provided exception
            // pointer + selector; `Resume` re-raises. These lower onto the
            // existing, verified MachIR EH backend (LSDA + compact unwind) via
            // the LIR `Opcode::Invoke`/`LandingPad`/`Resume` and the function's
            // `eh_info`, which ISel forwards to `MachFunction.eh_metadata`.
            Inst::Invoke {
                callee,
                args,
                normal_dest,
                normal_args,
                unwind_dest,
            } => self.translate_invoke(
                *callee,
                args,
                *normal_dest,
                normal_args,
                *unwind_dest,
                &node.results,
            ),
            Inst::LandingPad {
                is_cleanup,
                catch_type_indices,
            } => self.translate_landing_pad(*is_cleanup, catch_type_indices, &node.results),
            Inst::Resume { exn } => self.translate_resume(exn),

            Inst::ExtractField {
                ty,
                aggregate,
                field,
            } => self.translate_field_extract(ty, aggregate, *field, &node.results),

            Inst::InsertField {
                ty,
                aggregate,
                field,
                value,
            } => {
                let struct_ty = self.translate_ty(ty)?;
                // THE INDEX SHIFT, the write-side mirror of the one in
                // `translate_field_extract`: trust-ir indexes a niche enum
                // flatly (element 0 is the discriminant) while its carrier holds
                // the payload at `0..n`. Getting this wrong here STORES to the
                // wrong field. `niche_field_access` also answers the field's
                // trust-ir `Ty`, which `aggregate_field_ty` cannot — it refuses
                // `Ty::Enum` outright, and must keep doing so for the multi-index
                // GEP path that shares it.
                let (field, expected_field_ty) = match self.niche_field_access(ty, *field)? {
                    Some((carrier_index, payload_ty)) => (carrier_index, payload_ty),
                    // Verify the inserted value's trust_ir type matches the
                    // declared field type. Mismatches (e.g. storing an I32 into
                    // an I64 field) are a frontend bug; fail closed rather than
                    // silently emitting a wrong-width store. `aggregate_field_ty`
                    // resolves the field's trust_ir `Ty` for struct/tuple/record
                    // aggregates.
                    None => (*field, self.aggregate_field_ty(ty, *field as usize)?),
                };
                let field_ty = match &struct_ty {
                    Type::Struct(fields) => {
                        fields.get(field as usize).cloned().ok_or_else(|| {
                            AdapterError::UnsupportedInstruction(format!(
                                "struct field {} out of bounds for {:?}",
                                field, struct_ty
                            ))
                        })?
                    }
                    _ => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertField expected struct type, got {:?}",
                            struct_ty
                        )));
                    }
                };
                let value_ty = self.lookup_value_ty(*value).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "InsertField requires field value type, but value {:?} has unknown type",
                        value
                    ))
                })?;
                if value_ty != expected_field_ty {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "InsertField value type {:?} does not match field type {:?} for {:?}",
                        value_ty, expected_field_ty, ty
                    )));
                }
                let base_ptr = self.map_value(*aggregate);
                let field_val = self.map_value(*value);
                let dst = self.map_result(&node.results)?;
                let field_ptr = self.fresh_value();

                // The field sits at the AUTHORITATIVE offset — the producer's
                // declared one, or the PACKED one — which `StructGep` cannot
                // express (symmetric to the field READ in
                // translate_field_extract). A SCALAR field is written with a
                // byte-offset Store, possibly UNALIGNED when the struct is
                // packed; an AGGREGATE field is pointer-represented, so it is
                // byte-copied with Memmove of the field's own authoritative
                // extent from the source aggregate — the write-side mirror of
                // the read, which addresses a nested aggregate field at
                // base+offset. The inner aggregate keeps its own layout, so
                // copying its byte image to that offset is correct, and Memmove
                // is byte-granular (no alignment requirement) and
                // self-copy-safe.
                if let Some(offset) = self.explicit_field_offset(ty, &struct_ty, field)? {
                    let store_align = if self.is_packed_struct_ty(ty) {
                        Some(1)
                    } else {
                        None
                    };
                    let off_val = self.fresh_value();
                    self.define_value_type(off_val, Type::I64);
                    let mut instrs = vec![
                        Instruction {
                            opcode: Opcode::Iconst {
                                ty: Type::I64,
                                imm: offset as i64,
                            },
                            args: vec![],
                            results: vec![off_val],
                        },
                        Instruction {
                            opcode: Opcode::Iadd,
                            args: vec![base_ptr, off_val],
                            results: vec![field_ptr],
                        },
                    ];
                    if matches!(field_ty, Type::Struct(_) | Type::Array(_, _)) {
                        // The copy length is the field's own AUTHORITATIVE
                        // extent, because that is what the containing struct's
                        // authority advanced its running offset by when it
                        // placed the NEXT sibling. `field_ty.bytes()`
                        // (natural-C) would reach past this field and clobber
                        // that sibling — see `aggregate_value_extent`.
                        let len =
                            self.aggregate_value_extent(&expected_field_ty, &field_ty)? as i64;
                        let len_val = self.emit_iconst_i64(len, &mut instrs);
                        instrs.push(Instruction {
                            opcode: Opcode::Memmove,
                            args: vec![field_ptr, field_val, len_val],
                            results: vec![],
                        });
                    } else {
                        instrs.push(Instruction {
                            opcode: Opcode::Store {
                                ty: field_ty,
                                align: store_align,
                            },
                            args: vec![field_val, field_ptr],
                            results: vec![],
                        });
                    }
                    instrs.push(Instruction {
                        opcode: Opcode::Copy,
                        args: vec![base_ptr],
                        results: vec![dst],
                    });
                    return Ok(instrs);
                }

                // Non-packed path: an aggregate FIELD (Struct/Array/Enum) is
                // pointer-represented, so `field_val` is the ADDRESS of the source
                // aggregate — a scalar `Store` would write 8 bytes of that address
                // instead of copying the field's DATA. Lower it as a byte copy:
                // StructGep to the destination field slot, then `Memmove` of
                // `field_ty.bytes()` from the source aggregate. Memmove (not
                // Memcpy) because the source may alias the destination — e.g.
                // `s.f = s.f` extracts a pointer INTO `s` and reinserts it at the
                // same slot (dst == src); memmove is defined for that, memcpy is
                // not. All opcodes used (StructGep/Iconst/Memmove/Copy) are proven.
                if field_ty.is_aggregate() {
                    // The copy length is the field's own AUTHORITATIVE extent,
                    // for the same reason as the explicit-offset arm above: it
                    // is what placed the next sibling.
                    let field_bytes =
                        self.aggregate_value_extent(&expected_field_ty, &field_ty)? as i64;
                    let mut instrs = vec![Instruction {
                        opcode: Opcode::StructGep {
                            struct_ty,
                            field_index: field,
                        },
                        args: vec![base_ptr],
                        results: vec![field_ptr],
                    }];
                    let len_val = self.emit_iconst_i64(field_bytes, &mut instrs);
                    instrs.push(Instruction {
                        opcode: Opcode::Memmove,
                        args: vec![field_ptr, field_val, len_val],
                        results: vec![],
                    });
                    instrs.push(Instruction {
                        opcode: Opcode::Copy,
                        args: vec![base_ptr],
                        results: vec![dst],
                    });
                    return Ok(instrs);
                }

                Ok(vec![
                    Instruction {
                        opcode: Opcode::StructGep {
                            struct_ty,
                            field_index: field,
                        },
                        args: vec![base_ptr],
                        results: vec![field_ptr],
                    },
                    Instruction {
                        opcode: Opcode::Store { ty: field_ty, align: None },
                        args: vec![field_val, field_ptr],
                        results: vec![],
                    },
                    Instruction {
                        opcode: Opcode::Copy,
                        args: vec![base_ptr],
                        results: vec![dst],
                    },
                ])
            }

            Inst::ExtractElement { ty, array, index } => {
                if let Some(array_ty) = self.lookup_value_ty(*array)
                    && matches!(array_ty, Ty::Vector(_, _))
                {
                    if Self::is_v2i64_ty(&array_ty) {
                        return self.translate_v2i64_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    if Self::is_v16i8_ty(&array_ty) {
                        return self.translate_v16i8_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    if Self::is_v8i16_ty(&array_ty) {
                        return self.translate_v8i16_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    if Self::is_v4f32_ty(&array_ty) || Self::is_v2f64_ty(&array_ty) {
                        return self.translate_fp_vector_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    return self.translate_v4i32_extract_element(ty, *array, *index, &node.results);
                }

                // Non-vector ExtractElement dispatches on the SOURCE value's
                // type. An array source uses the bare-pointer array layout; a
                // sequence source uses the length-prefixed stack-buffer layout
                // and fails closed unless the value carries materialized layout
                // provenance. A scalar/pointer or set/record/closure source is
                // rejected so we never lower an element load as bare pointer
                // arithmetic over an unknown layout.
                let array_ty = self.lookup_value_ty(*array).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "ExtractElement requires array or vector source type, but source {:?} has unknown type",
                        array
                    ))
                })?;
                match &array_ty {
                    Ty::Array(elem_ty_id, _) => {
                        let actual_elem_ty =
                            self.types.get(elem_ty_id.as_usize()).ok_or_else(|| {
                                AdapterError::UnsupportedInstruction(format!(
                                    "ExtractElement array element TyId {:?} is not in the module types table",
                                    elem_ty_id
                                ))
                            })?;
                        if actual_elem_ty != ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "ExtractElement declared element type {:?} does not match array element type {:?} for source {:?}",
                                ty, actual_elem_ty, array_ty
                            )));
                        }
                    }
                    Ty::Sequence(_) => {
                        let elem_ty = self.sequence_element_ty(&array_ty)?;
                        if &elem_ty != ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "ExtractElement declared element type {:?} does not match Sequence element type {:?} for source {:?}",
                                ty, elem_ty, array_ty
                            )));
                        }
                        return self.translate_sequence_extract_element(
                            ty,
                            *array,
                            *index,
                            &node.results,
                        );
                    }
                    // A first-class closure is a struct of its captures, so an
                    // ExtractElement over a closure source is a fixed-offset
                    // struct field access (NOT scaled array arithmetic). The
                    // capture index must be a compile-time constant — the
                    // struct-layout byte offset comes from `Type::offset_of` via
                    // `Opcode::StructGep` — so reuse the StructGep + Load path
                    // that struct/tuple/record field extraction uses. The
                    // declared element `ty` is checked against the capture type
                    // so a wrong-width load is never emitted.
                    Ty::Closure(_) => {
                        let field_index = self.require_gep_struct_field_index(*index)?;
                        let capture_ty =
                            self.aggregate_field_ty(&array_ty, field_index as usize)?;
                        if &capture_ty != ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "ExtractElement declared element type {:?} does not match closure capture type {:?} (index {}) for source {:?}",
                                ty, capture_ty, field_index, array_ty
                            )));
                        }
                        return self.translate_field_extract(
                            &array_ty,
                            array,
                            field_index,
                            &node.results,
                        );
                    }
                    Ty::Set(_, _) | Ty::Record(_) => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "ExtractElement over trust_ir#30 aggregate source {:?} is not yet lowered; no CPU layout or element ABI exists",
                            array_ty
                        )));
                    }
                    other => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "ExtractElement requires array or vector source type, got {:?}",
                            other
                        )));
                    }
                }

                let elem_ty = self.translate_ty(ty)?;
                let base_ptr = self.map_value(*array);
                let index_val = self.map_value(*index);
                let dst = self.map_result(&node.results)?;
                let mut instrs = Vec::new();
                let index_val =
                    self.extend_index_to_i64_if_needed(*index, index_val, &mut instrs)?;
                self.append_exact_in_bounds_guard(node, base_ptr, index_val, &mut instrs);

                // An AGGREGATE element (array of structs/arrays) is pointer-
                // represented: its value IS the element's address, so use the
                // ArrayGep result directly with NO Load — symmetric to
                // translate_field_extract's nested-aggregate handling. A scalar
                // Load of a struct type would read only the first 8 bytes (its
                // address image), a silent miscompile.
                if elem_ty.is_aggregate() {
                    self.emit_array_element_ptr(
                        ty,
                        &elem_ty,
                        base_ptr,
                        index_val,
                        dst,
                        &mut instrs,
                    )?;
                    self.define_value_type(dst, elem_ty);
                    return Ok(instrs);
                }

                let elem_ptr = self.fresh_value();
                self.emit_array_element_ptr(
                    ty,
                    &elem_ty,
                    base_ptr,
                    index_val,
                    elem_ptr,
                    &mut instrs,
                )?;

                instrs.push(Instruction {
                    opcode: Opcode::Load { ty: elem_ty, align: None },
                    args: vec![elem_ptr],
                    results: vec![dst],
                });

                Ok(instrs)
            }

            Inst::InsertElement {
                ty,
                array,
                index,
                value,
            } => {
                if matches!(ty, Ty::Vector(_, _)) {
                    if Self::is_v2i64_ty(ty) {
                        return self.translate_v2i64_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    if Self::is_v16i8_ty(ty) {
                        return self.translate_v16i8_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    if Self::is_v8i16_ty(ty) {
                        return self.translate_v8i16_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    if Self::is_v4f32_ty(ty) || Self::is_v2f64_ty(ty) {
                        return self.translate_fp_vector_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    return self.translate_v4i32_insert_element(
                        ty,
                        *array,
                        *index,
                        *value,
                        &node.results,
                    );
                }

                // Non-vector InsertElement dispatches on the SOURCE value's type
                // (not the declared result `ty`): the source layout is what
                // determines how the element is addressed. A sequence source uses
                // the length-prefixed stack-buffer layout; an array source uses
                // the bare-pointer array layout. Anything else (scalar/pointer,
                // set/record/closure) is rejected here so we never lower an
                // element insert as bare pointer arithmetic over an unknown
                // layout.
                let array_ty = self.lookup_value_ty(*array).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "InsertElement requires array or vector source type, but source {:?} has unknown type",
                        array
                    ))
                })?;
                match &array_ty {
                    Ty::Array(_, _) => {
                        if ty != &array_ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "InsertElement declared result type {:?} does not match source aggregate type {:?} for source {:?}",
                                ty, array_ty, array
                            )));
                        }
                    }
                    Ty::Sequence(_) => {
                        if ty != &array_ty {
                            return Err(AdapterError::UnsupportedInstruction(format!(
                                "InsertElement declared result type {:?} does not match source Sequence type {:?} for source {:?}",
                                ty, array_ty, array
                            )));
                        }
                        return self.translate_sequence_insert_element(
                            ty,
                            *array,
                            *index,
                            *value,
                            &node.results,
                        );
                    }
                    Ty::Vector(_, _) => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertElement declared result type {:?} does not match source aggregate type {:?} for source {:?}",
                            ty, array_ty, array
                        )));
                    }
                    Ty::Set(_, _) | Ty::Record(_) | Ty::Closure(_) => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertElement over trust_ir#30 aggregate/closure source {:?} is not yet lowered; no CPU layout or element ABI exists",
                            array_ty
                        )));
                    }
                    other => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "InsertElement requires array or vector source type, got {:?}",
                            other
                        )));
                    }
                };
                let Ty::Array(elem_ty_id, _) = &array_ty else {
                    unreachable!("InsertElement non-array source rejected above");
                };
                let elem_ty = self
                    .types
                    .get(elem_ty_id.as_usize())
                    .ok_or_else(|| {
                        AdapterError::UnsupportedInstruction(format!(
                            "InsertElement array element TyId {:?} is not in the module types table",
                            elem_ty_id
                        ))
                    })?
                    .clone();
                let value_ty = self.lookup_value_ty(*value).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "InsertElement requires element value type, but value {:?} has unknown type",
                        value
                    ))
                })?;
                if value_ty != elem_ty {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "InsertElement value type {:?} does not match array element type {:?} for source {:?}",
                        value_ty, elem_ty, array_ty
                    )));
                }

                let lir_elem_ty = self.translate_ty(&elem_ty)?;
                let base_ptr = self.map_value(*array);
                let index_val = self.map_value(*index);
                let elem_val = self.map_value(*value);
                let dst = self.map_result(&node.results)?;
                let mut instrs = Vec::new();
                let index_val =
                    self.extend_index_to_i64_if_needed(*index, index_val, &mut instrs)?;
                self.append_exact_in_bounds_guard(node, base_ptr, index_val, &mut instrs);

                let elem_ptr = self.fresh_value();
                self.emit_array_element_ptr(
                    &elem_ty,
                    &lir_elem_ty,
                    base_ptr,
                    index_val,
                    elem_ptr,
                    &mut instrs,
                )?;

                // An AGGREGATE element is pointer-represented, so `elem_val` is
                // the ADDRESS of the source aggregate — a scalar Store would write
                // 8 bytes of that address instead of the element's data (a silent
                // miscompile). Byte-copy it with Memmove (self-copy-safe), exactly
                // as the aggregate InsertField path does.
                //
                // The LENGTH is the AUTHORITATIVE extent, and it HAD to move with
                // the stride above rather than after it: once element `i` sits at
                // `i * 9` for `P = #[repr(C,packed)] { a: u8, b: u64 }`, a
                // natural-C 16-byte copy into element 0 covers bytes 0..16 and
                // CLOBBERS the first seven bytes of element 1. (c) MEASURED —
                // this site emitted `Iconst 16` + `Memmove` for a value rustc
                // sizes at 9, and was the last aggregate copy length in the
                // adapter still reading `Type::bytes()`.
                if lir_elem_ty.is_aggregate() {
                    let extent = self.aggregate_value_extent(&elem_ty, &lir_elem_ty)?;
                    let len_val = self.emit_iconst_i64(extent as i64, &mut instrs);
                    instrs.push(Instruction {
                        opcode: Opcode::Memmove,
                        args: vec![elem_ptr, elem_val, len_val],
                        results: vec![],
                    });
                } else {
                    instrs.push(Instruction {
                        opcode: Opcode::Store { ty: lir_elem_ty, align: None },
                        args: vec![elem_val, elem_ptr],
                        results: vec![],
                    });
                }
                instrs.push(Instruction {
                    opcode: Opcode::Copy,
                    args: vec![base_ptr],
                    results: vec![dst],
                });

                Ok(instrs)
            }

            Inst::Const { ty, value } => match value {
                Constant::Int(v) => self.translate_int_const(ty, *v, &node.results),
                // trust-ir v24: the 128-bit-faithful unsigned carrier
                // (canonical iff value > i128::MAX). Validate that spelling,
                // then materialize both physical u64 halves directly so the
                // unsigned value never passes through signed range checking.
                Constant::U128(v) => self.translate_u128_const(ty, *v, &node.results),
                // trust-ir v25 Bytes: the byte-array carrier (string/byte-string
                // literals). Per the reference interpreter, a bytes constant is
                // executable EXACTLY as an `Array` of `U8` ints for a `[u8; N]`
                // declared type — so we reuse the proven aggregate-const path.
                Constant::Bytes { data, utf8 } => {
                    self.translate_bytes_const(ty, data, *utf8, &node.results)
                }
                Constant::Float(v) => self.translate_fconst(ty, *v, &node.results),
                Constant::Bool(b) => {
                    self.translate_const(ty, if *b { 1 } else { 0 }, &node.results)
                }
                Constant::Vector(elems) => self.translate_vector_const(ty, elems, &node.results),
                Constant::Aggregate(elems) | Constant::Array(elems) => {
                    if matches!(ty, Ty::Vector(_, _)) {
                        self.translate_vector_const(ty, elems, &node.results)
                    } else {
                        self.translate_aggregate_const(ty, elems, &node.results)
                    }
                }
                Constant::Closure { func, captures } if captures.is_empty() => {
                    self.translate_function_symbol_const(ty, *func, &node.results)
                }
                Constant::FnDef(func) => {
                    self.translate_function_symbol_const(ty, *func, &node.results)
                }
                // trust_ir#30 aggregate/closure constants — ty-style records,
                // sets, sequences, and captured closure values. Empty
                // closures with `Ty::Func` are handled above as bare function
                // pointers for rustc lang_start.
                // `SymbolAddr` is the relocatable address of a named symbol. As
                // a global-initializer element it lowers to a data relocation in
                // the object writer; as a FUNCTION-BODY constant it materializes
                // that address into an SSA register via a GlobalRef (defined) /
                // ExternRef (external) relocation — the raw-name counterpart of
                // the `FnDef` and `GlobalAddr` paths.
                Constant::SymbolAddr { symbol, addend } => {
                    self.translate_symbol_addr_const(symbol, *addend, &node.results)
                }
                Constant::Record(fields) => self.translate_record_const(ty, fields, &node.results),
                Constant::Sequence(elems) => {
                    self.translate_sequence_const(ty, elems, &node.results)
                }
                Constant::Set(_)
                | Constant::Closure { .. }
                | Constant::PhantomData => Err(AdapterError::UnsupportedInstruction(format!(
                    "trust_ir#30 aggregate/closure constant not yet lowered: {:?}",
                    value
                ))),
            },

            Inst::NullPtr => self.translate_const(&Ty::Ptr, 0, &node.results),

            // A unit `()` or never `!` undef is a ZERO-SIZED value with no
            // machine representation and no bits to be poison — emit nothing.
            // Its type is recorded (value-type inference), so the sole consumer
            // (a `ret`) drops it via the zero-sized-value filter. Every other
            // undef stays fail-closed (must model poison / NoUndef obligations).
            Inst::Undef { ty: Ty::Unit | Ty::Never } => Ok(vec![]),
            Inst::Undef { ty } => Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Undef is fail-closed for {:?}: replacement-grade lowering \
                 must model poison/undef semantics and NoUndef proof obligations \
                 instead of materializing an arbitrary zero value",
                ty
            ))),

            // Materialize Assume as a CHECKED runtime assertion (traps if the
            // assumed condition is false) rather than dropping it: a verified
            // backend must not blindly trust a possibly-wrong assumption (which
            // would be a soundness hole). origin/main dropped it to `Ok(vec![])`.
            Inst::Assume { cond } => {
                self.validate_bool_condition("Inst::Assume", *cond)?;
                Ok(vec![Instruction {
                    opcode: Opcode::Assert,
                    args: vec![self.map_value(*cond)],
                    results: vec![],
                }])
            }

            Inst::Assert { cond } => {
                self.validate_bool_condition("Inst::Assert", *cond)?;
                Ok(vec![Instruction {
                    opcode: Opcode::Assert,
                    args: vec![self.map_value(*cond)],
                    results: vec![],
                }])
            }

            Inst::Unreachable => Ok(vec![Instruction {
                opcode: Opcode::Trap,
                args: vec![],
                results: vec![],
            }]),

            Inst::Copy { ty: _, operand } => {
                // Direct 1:1 mapping: trust_ir Copy -> LIR Copy.
                let src = self.map_value(*operand);
                let dst = self.map_result(&node.results)?;
                Ok(vec![Instruction {
                    opcode: Opcode::Copy,
                    args: vec![src],
                    results: vec![dst],
                }])
            }

            Inst::Select {
                ty,
                cond,
                then_val,
                else_val,
            } => {
                self.validate_select_operands(ty, *cond, *then_val, *else_val)?;
                let is_narrow_select = Self::is_v16i8_ty(ty) || Self::is_v8i16_ty(ty);
                let cond_val = self.map_value(*cond);
                let then_v = self.map_value(*then_val);
                let else_v = self.map_value(*else_val);
                let dst = self.map_result(&node.results)?;
                if is_narrow_select {
                    self.define_value_type(dst, Type::V128);
                }

                Ok(vec![Instruction {
                    opcode: Opcode::Select {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![cond_val, then_v, else_v],
                    results: vec![dst],
                }])
            }

            // Borrow instructions (Rust ownership model) — lowered as no-ops
            // at the machine level. Borrow semantics are verified by the proof
            // system, not enforced by generated code.
            Inst::Borrow { .. } => Err(AdapterError::UnsupportedInstruction(
                "Borrow not lowered: Rust borrow/provenance scope semantics require alias permission tracking and proof discharge, not a pointer copy"
                    .to_string(),
            )),
            Inst::BorrowMut { .. } => Err(AdapterError::UnsupportedInstruction(
                "BorrowMut not lowered: Rust unique-borrow/provenance scope semantics require exclusivity tracking and proof discharge, not a pointer copy"
                    .to_string(),
            )),
            Inst::EndBorrow { .. } => Err(AdapterError::UnsupportedInstruction(
                "EndBorrow not lowered: Rust borrow scope termination requires provenance/alias state tracking"
                    .to_string(),
            )),

            // ARC instructions (Perceus/Swift-style reference counting). In the
            // trust-ir operational model these gate on the `arcRef` permission
            // installed by the producer's RC runtime, so the machine-level
            // lowering is a CALL into that runtime. Retain/Release carry no
            // origin field (unlike `HeapAlloc`), so the adapter routes by the
            // module's own declared RC-runtime imports: a Clean-produced module
            // declares the `clean_inc`/`clean_dec`/`clean_is_exclusive`
            // bodyless-external triple (P1 native ARC; the Clean frontend
            // emits native ARC ops and keeps the triple declared as its
            // RC-runtime provenance). A module that declares no RC runtime
            // fails closed — retaining through the wrong runtime would
            // silently corrupt another runtime's refcount discipline. When a
            // second RC-runtime producer lands (Swift), this routing must
            // grow its triple and fail closed on ambiguity.
            Inst::Retain { ptr } => {
                self.translate_arc_op("Retain", CLEAN_RC_RETAIN, *ptr, &node.results)
            }
            Inst::Release { ptr } => {
                self.translate_arc_op("Release", CLEAN_RC_RELEASE, *ptr, &node.results)
            }
            Inst::IsUnique { ptr } => {
                self.translate_arc_op("IsUnique", CLEAN_RC_IS_UNIQUE, *ptr, &node.results)
            }

            // Heap allocation (trust_ir B2). Box/Vec/String backing and
            // `malloc` route through here. Lowered to a CALL of the allocator
            // function selected by `origin`: the Rust global allocator
            // (`__rust_alloc(size, align)`) or libc (`malloc(size)`). Swift
            // heap allocation has no portable two-argument shim yet and stays
            // fail-closed. See `translate_heap_alloc`.
            Inst::HeapAlloc {
                ty,
                count,
                align,
                origin,
            } => self.translate_heap_alloc(ty, count, *align, *origin, &node.results),

            // Address of a module global (trust_ir B1): the relocatable address
            // of the global's data/rodata symbol, materialized exactly like the
            // imported `Constant::Int` global-address stub via
            // `Opcode::GlobalRef`. See `translate_global_addr`.
            Inst::GlobalAddr { global } => self.translate_global_addr(*global, &node.results),

            // Heap deallocation — fail closed until TrustIr carries enough
            // allocator/layout information to select the correct runtime
            // release path. Lowering this to libc `free` from a bare pointer
            // would be wrong for Rust Box/drop/global-allocator semantics.
            Inst::Dealloc { .. } => Err(AdapterError::UnsupportedInstruction(
                "Dealloc not lowered: allocator identity, layout size/alignment, and Rust \
                 GlobalAlloc/Box release semantics are not wired"
                    .to_string(),
            )),

            // Structural sequence maps (SeqMapAddK / SeqMapNot / the general
            // SeqMap with a first-class `fwd` element function) — element-wise
            // ops with fixed canonical semantics (trust-ir interpret.rs),
            // introduced for the give-back elaborator's loopFwd certification.
            // Lowering them to machine code requires emitting a runtime loop
            // over the materialized length-prefixed sequence buffer (and, for
            // the general form, a call to `fwd` per element), which
            // single-block instruction translation cannot express. Fail closed
            // until a pre-adapter expansion pass (SeqMap -> explicit loop
            // blocks) exists.
            Inst::SeqMapAddK { .. } | Inst::SeqMapNot { .. } | Inst::SeqMap { .. } => {
                Err(AdapterError::UnsupportedInstruction(
                    "structural sequence maps (SeqMapAddK/SeqMapNot/SeqMap) not yet \
                     lowered: element-wise mapping of a runtime sequence needs \
                     loop-block expansion before the adapter"
                        .to_string(),
                ))
            }

            // Binding frames (trust_ir#30 §R4) — typed SSA frames for quantifier
            // lowering. Not yet lowered to machine code. These will need
            // stack-slot (CPU) or per-lane register (GPU) allocation when
            // we wire up TLA+ / Lean-style quantifier codegen.
            Inst::OpenFrame { .. }
            | Inst::BindSlot { .. }
            | Inst::LoadSlot { .. } => Err(AdapterError::UnsupportedInstruction(
                "binding-frame storage ops (OpenFrame/BindSlot/LoadSlot) not yet lowered"
                    .to_string(),
            )),
            // CloseFrame is a lifetime marker: it carries no runtime effect
            // beyond ending the frame scope. Validate the frame handle is a
            // pointer-like value, then emit nothing (the scope end is implied
            // by the surrounding control flow / proof obligations).
            Inst::CloseFrame { frame } => {
                self.validate_pointer_like_value("CloseFrame frame", *frame)?;
                Ok(vec![])
            }

            // Trust Codegen-owned typed dialect ops can lower directly here. Other
            // dialects must be rewritten by the pre-adapter dialect pipeline.
            Inst::DialectOp(op) if vector_dialect::is_pack_lanes_op(op) => {
                self.translate_trust_ir_vector_pack_lanes_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if vector_dialect::is_extract_lane_op(op) => {
                self.translate_trust_ir_vector_extract_lane_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if vector_dialect::is_insert_lane_op(op) => {
                self.translate_trust_ir_vector_insert_lane_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if vector_dialect::is_mask_to_bits_op(op) => {
                self.translate_trust_ir_vector_mask_to_bits_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_bitfield_op(op) => {
                self.translate_trust_cg_bitfield_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_v4i32_mask_extract_op(op) => {
                self.translate_trust_cg_v4i32_mask_extract_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_v2i64_mask_extract_op(op) => {
                self.translate_trust_cg_v2i64_mask_extract_dialect_op(op, &node.results)
            }
            Inst::DialectOp(op) if bitfield_dialect::is_v2i64_bool_mask_extract_op(op) => {
                self.translate_trust_cg_v2i64_bool_mask_extract_dialect_op(op, &node.results)
            }
            Inst::DialectOp(_) => Err(AdapterError::UnsupportedInstruction(
                "DialectOp reached the Trust Codegen adapter without prior \
                     dialect lowering"
                    .to_string(),
            )),
        }
    }

    // Legacy per-kind translation helpers (`translate_binop`, `translate_unop`,
    // `translate_cmp`) were removed during the 2026-04-19 zero-warnings
    // cleanup. trust_ir BinOp / UnOp / ICmp / FCmp are now lowered inline in
    // `translate_instruction` above; the free `translate_int_cmp` /
    // `translate_float_cmp` predicate mappers were removed for the same
    // reason (they only served the deleted `translate_cmp`).

    fn translate_ptr_data(
        &mut self,
        ptr_ty: &Ty,
        ptr: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let src = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        if matches!(ptr_ty, Ty::FatPtr(_)) {
            return self.load_fat_ptr_lane(src, 0, Type::I64, dst);
        }
        if Self::trust_ir_ty_is_pointer_carrier(ptr_ty) {
            return Ok(vec![Instruction {
                opcode: Opcode::Copy,
                args: vec![src],
                results: vec![dst],
            }]);
        }
        Err(AdapterError::UnsupportedInstruction(format!(
            "PtrData requires a pointer-like type, got {ptr_ty:?}"
        )))
    }

    fn translate_ptr_metadata(
        &mut self,
        ptr_ty: &Ty,
        metadata_ty: &Ty,
        ptr: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if matches!(metadata_ty, Ty::Unit) {
            if !Self::trust_ir_ty_is_pointer_carrier(ptr_ty) || matches!(ptr_ty, Ty::FatPtr(_)) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "PtrMetadata unit metadata requires a thin pointer-like type, got {ptr_ty:?}"
                )));
            }
            return Ok(vec![]);
        }

        if !matches!(ptr_ty, Ty::FatPtr(_)) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "PtrMetadata for thin pointer type {ptr_ty:?} must use Unit metadata, got {metadata_ty:?}"
            )));
        }

        let src = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        let metadata_lir_ty = self.translate_ty(metadata_ty)?;
        self.define_value_type(dst, metadata_lir_ty.clone());
        self.load_fat_ptr_lane(src, 1, metadata_lir_ty, dst)
    }

    fn translate_ptr_from_parts(
        &mut self,
        ptr_ty: &Ty,
        metadata_ty: &Ty,
        data: &ValueId,
        metadata: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let data_value = self.map_value(*data);
        let dst = self.map_result(results)?;

        if matches!(metadata_ty, Ty::Unit) {
            if !Self::trust_ir_ty_is_pointer_carrier(ptr_ty) || matches!(ptr_ty, Ty::FatPtr(_)) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "PtrFromParts unit metadata requires a thin pointer-like type, got {ptr_ty:?}"
                )));
            }
            self.define_value_type(dst, Type::I64);
            return Ok(vec![Instruction {
                opcode: Opcode::Copy,
                args: vec![data_value],
                results: vec![dst],
            }]);
        }

        if !matches!(ptr_ty, Ty::FatPtr(_)) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "PtrFromParts for thin pointer type {ptr_ty:?} must use Unit metadata, got {metadata_ty:?}"
            )));
        }

        let metadata_value = self.map_value(*metadata);
        let metadata_lir_ty = self.translate_ty(metadata_ty)?;
        let fat_ptr_ty = Type::Struct(vec![Type::I64, metadata_lir_ty.clone()]);
        let slot = self.alloc_stack_slot(fat_ptr_ty.bytes(), fat_ptr_ty.align());
        self.define_value_type(dst, fat_ptr_ty.clone());

        let metadata_ptr = self.fresh_value();
        self.define_value_type(metadata_ptr, Type::I64);

        Ok(vec![
            Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![dst],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: Type::I64,
                    align: None,
                },
                args: vec![data_value, dst],
                results: vec![],
            },
            Instruction {
                opcode: Opcode::StructGep {
                    struct_ty: fat_ptr_ty,
                    field_index: 1,
                },
                args: vec![dst],
                results: vec![metadata_ptr],
            },
            Instruction {
                opcode: Opcode::Store {
                    ty: metadata_lir_ty,
                    align: None,
                },
                args: vec![metadata_value, metadata_ptr],
                results: vec![],
            },
        ])
    }

    fn load_fat_ptr_lane(
        &mut self,
        base_ptr: Value,
        field_index: u32,
        field_ty: Type,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if field_index > 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "fat pointer lane {field_index} is out of bounds"
            )));
        }
        let aggregate_ty = Type::Struct(vec![Type::I64, field_ty.clone()]);
        let field_ptr = self.fresh_value();
        self.define_value_type(field_ptr, Type::I64);
        Ok(vec![
            Instruction {
                opcode: Opcode::StructGep {
                    struct_ty: aggregate_ty,
                    field_index,
                },
                args: vec![base_ptr],
                results: vec![field_ptr],
            },
            Instruction {
                opcode: Opcode::Load {
                    ty: field_ty,
                    align: None,
                },
                args: vec![field_ptr],
                results: vec![dst],
            },
        ])
    }

    // -----------------------------------------------------------------------
    // Cast operations
    // -----------------------------------------------------------------------

    /// Lower a NARROW saturating float->int cast (`f as i8/i16/i32` or
    /// `f as u8/u16/u32`, LLVM fptosi.sat/fptoui.sat). AArch64 FCVTZS/FCVTZU
    /// saturate at the REGISTER width, so a narrow destination needs an explicit
    /// destination-width clamp. The lowering is a proven-op expansion:
    ///
    ///   tmp   = FcvtToInt/FcvtToUint(f -> i64)     ; NaN->0, saturate i64 range
    ///   min   = (tmp < hi) ? tmp : hi              ; clamp above (signed/unsigned)
    ///   clamp = signed ? ((min > lo) ? min : lo)   ; clamp below (signed only;
    ///                  : min                       ;  FCVTZU already gives >= 0)
    ///   dst   = Trunc(clamp -> dst_width)          ; exact (clamp fits dst)
    ///
    /// Equivalent to Rust's saturating `as`: NaN -> 0, out-of-range clamps to
    /// `dst::MIN`/`dst::MAX`, else round toward zero. Validated exhaustively for
    /// f16 -> i8 (all 65536 inputs) and against a saturating oracle for
    /// f32/f64 -> i8/i16/i32.
    fn translate_narrow_saturating_cast(
        &mut self,
        op: &CastOp,
        src: Value,
        dst_ty: &Ty,
        to: Type,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let signed = matches!(op, CastOp::FPToSISat);
        let (lo, hi): (i64, i64) = match dst_ty {
            Ty::I8 => (i64::from(i8::MIN), i64::from(i8::MAX)),
            Ty::I16 => (i64::from(i16::MIN), i64::from(i16::MAX)),
            Ty::I32 => (i64::from(i32::MIN), i64::from(i32::MAX)),
            Ty::U8 => (0, i64::from(u8::MAX)),
            Ty::U16 => (0, i64::from(u16::MAX)),
            Ty::U32 => (0, i64::from(u32::MAX)),
            other => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "narrow saturating cast: unexpected destination {other:?}"
                )));
            }
        };

        let mut instrs = Vec::new();
        let i64c = |this: &mut Self, imm: i64| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I64);
            (v, imm)
        };

        // tmp = saturating fcvt to i64 (NaN -> 0, saturate at the i64 range).
        let tmp = self.fresh_value();
        self.define_value_type(tmp, Type::I64);
        let fcvt = if signed {
            Opcode::FcvtToInt { dst_ty: Type::I64 }
        } else {
            Opcode::FcvtToUint { dst_ty: Type::I64 }
        };
        instrs.push(Instruction {
            opcode: fcvt,
            args: vec![src],
            results: vec![tmp],
        });

        // min = (tmp <(s/u) hi) ? tmp : hi
        let (hi_c, hi_imm) = i64c(self, hi);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: hi_imm,
            },
            args: vec![],
            results: vec![hi_c],
        });
        let lt_cc = if signed {
            IntCC::SignedLessThan
        } else {
            IntCC::UnsignedLessThan
        };
        let cmp_hi = self.fresh_value();
        self.define_value_type(cmp_hi, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp { cond: lt_cc },
            args: vec![tmp, hi_c],
            results: vec![cmp_hi],
        });
        let min_hi = self.fresh_value();
        self.define_value_type(min_hi, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![cmp_hi, tmp, hi_c],
            results: vec![min_hi],
        });

        // Signed: clamp below by lo. Unsigned: FCVTZU already yields >= 0.
        let clamped = if signed {
            let (lo_c, lo_imm) = i64c(self, lo);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: lo_imm,
                },
                args: vec![],
                results: vec![lo_c],
            });
            let cmp_lo = self.fresh_value();
            self.define_value_type(cmp_lo, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::SignedGreaterThan,
                },
                args: vec![min_hi, lo_c],
                results: vec![cmp_lo],
            });
            let max_lo = self.fresh_value();
            self.define_value_type(max_lo, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![cmp_lo, min_hi, lo_c],
                results: vec![max_lo],
            });
            max_lo
        } else {
            min_hi
        };

        // dst = Trunc(clamped -> dst_width). The clamp guarantees the value fits,
        // so the truncation is exact (no wrap).
        instrs.push(Instruction {
            opcode: Opcode::Trunc { to_ty: to },
            args: vec![clamped],
            results: vec![dst],
        });
        Ok(instrs)
    }

    /// Saturating float -> i128/u128 (`f as i128`/`as u128`), i.e. Rust's
    /// saturating `as`: NaN -> 0, out-of-range clamps to MIN/MAX, else round
    /// toward zero.
    ///
    /// There is no native 128-bit `fcvt`, so this uses the raw `__fix*ti`
    /// libcall plus explicit float-compare bounds. The libcall alone is NOT a
    /// correct saturating cast:
    /// - UNSIGNED: `__fixuns*ti` already clamps `[0, 2^128)` and maps negatives
    ///   to 0; only NaN (which it maps to UMAX) needs correcting to 0.
    /// - SIGNED: `__fix*ti` computes the raw value for exponents `< 128`, so an
    ///   `f` in `[2^127, 2^128)` OVERFLOWS the signed range and wraps (e.g.
    ///   `__fixdfti(2^127)` returns i128::MIN, not MAX). So the signed path must
    ///   bound `f >= 2^127 -> MAX` and `f < -2^127 -> MIN` explicitly, plus
    ///   NaN -> 0. (`2^127` is exactly representable in both f32 and f64.)
    ///
    /// Validated bit-exact against an independent trunc-and-clamp oracle over
    /// the whole magnitude range including the 2^127/2^128 boundaries.
    fn translate_i128_saturating_cast(
        &mut self,
        op: &CastOp,
        src_ty: &Ty,
        dst_ty: &Ty,
        src: Value,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !matches!(src_ty, Ty::F16 | Ty::F32 | Ty::F64) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "saturating {op:?} {src_ty:?} -> {dst_ty:?}: source must be a float (f16/f32/f64)"
            )));
        }
        let signed = matches!(op, CastOp::FPToSISat);
        let dst_lir = self.translate_ty(dst_ty)?;
        let mut instrs = Vec::new();

        // An f16 source has no native fcvt/fcmp path, so widen it to f32 first
        // (mirrors the non-saturating f16->i128 path); the f32 libcall and f32
        // boundary constants then apply. `2^127` is exactly representable in f32,
        // so the saturation bounds stay exact. All downstream uses of `src` and
        // `src_lir` see the widened f32 value / type.
        let (src, src_lir): (Value, Type) = if matches!(src_ty, Ty::F16) {
            let widened = self.fresh_value();
            self.define_value_type(widened, Type::F32);
            instrs.push(Instruction {
                opcode: Opcode::FPExt,
                args: vec![src],
                results: vec![widened],
            });
            (widened, Type::F32)
        } else {
            (src, self.translate_ty(src_ty)?)
        };

        // f16 widened to f32 uses the single-precision libcall.
        let is_f64 = matches!(src_ty, Ty::F64);
        let callee = match (signed, is_f64) {
            (true, false) => "__fixsfti",
            (true, true) => "__fixdfti",
            (false, false) => "__fixunssfti",
            (false, true) => "__fixunsdfti",
        };

        // raw = __fix*ti(f): correct in [MIN, MAX) for signed, [0, 2^128) unsigned.
        let raw = self.fresh_value();
        self.define_value_type(raw, dst_lir.clone());
        instrs.push(Instruction {
            opcode: Opcode::Call {
                name: callee.to_string(),
            },
            args: vec![src],
            results: vec![raw],
        });

        // is_nan = (f `une` f): unordered-not-equal is true iff f is NaN.
        let is_nan = self.fresh_value();
        self.define_value_type(is_nan, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Fcmp {
                cond: FloatCC::UnorderedNotEqual,
            },
            args: vec![src, src],
            results: vec![is_nan],
        });

        // zero (the NaN result).
        let zero = self.fresh_value();
        self.define_value_type(zero, dst_lir.clone());
        instrs.push(Instruction {
            opcode: Opcode::Iconst128 { lo: 0, hi: 0 },
            args: vec![],
            results: vec![zero],
        });

        // `select cond ? then : else` is `Select{NotEqual}` over [cond, then, else].
        let select = |instrs: &mut Vec<Instruction>, cond, then_v, else_v, out| {
            instrs.push(Instruction {
                opcode: Opcode::Select {
                    cond: IntCC::NotEqual,
                },
                args: vec![cond, then_v, else_v],
                results: vec![out],
            });
        };

        let result_before_nan = if signed {
            // 2^127, exactly representable in f32 and f64.
            let two127 = 2.0_f64.powi(127);
            let big_b = self.fresh_value();
            self.define_value_type(big_b, src_lir.clone());
            instrs.push(Instruction {
                opcode: Opcode::Fconst {
                    ty: src_lir.clone(),
                    imm: two127,
                },
                args: vec![],
                results: vec![big_b],
            });
            let small_b = self.fresh_value();
            self.define_value_type(small_b, src_lir.clone());
            instrs.push(Instruction {
                opcode: Opcode::Fconst {
                    ty: src_lir.clone(),
                    imm: -two127,
                },
                args: vec![],
                results: vec![small_b],
            });
            // too_big = f >= 2^127 ; too_small = f < -2^127.
            let too_big = self.fresh_value();
            self.define_value_type(too_big, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::Fcmp {
                    cond: FloatCC::GreaterThanOrEqual,
                },
                args: vec![src, big_b],
                results: vec![too_big],
            });
            let too_small = self.fresh_value();
            self.define_value_type(too_small, Type::B1);
            instrs.push(Instruction {
                opcode: Opcode::Fcmp {
                    cond: FloatCC::LessThan,
                },
                args: vec![src, small_b],
                results: vec![too_small],
            });
            // i128::MAX = 2^127-1 (hi=i64::MAX, lo=-1); i128::MIN = -2^127 (hi=i64::MIN, lo=0).
            let imax = self.fresh_value();
            self.define_value_type(imax, dst_lir.clone());
            instrs.push(Instruction {
                opcode: Opcode::Iconst128 {
                    lo: -1,
                    hi: i64::MAX,
                },
                args: vec![],
                results: vec![imax],
            });
            let imin = self.fresh_value();
            self.define_value_type(imin, dst_lir.clone());
            instrs.push(Instruction {
                opcode: Opcode::Iconst128 {
                    lo: 0,
                    hi: i64::MIN,
                },
                args: vec![],
                results: vec![imin],
            });
            // r1 = too_small ? MIN : raw ; r2 = too_big ? MAX : r1.
            let r1 = self.fresh_value();
            self.define_value_type(r1, dst_lir.clone());
            select(&mut instrs, too_small, imin, raw, r1);
            let r2 = self.fresh_value();
            self.define_value_type(r2, dst_lir.clone());
            select(&mut instrs, too_big, imax, r1, r2);
            r2
        } else {
            // Unsigned: the libcall already clamps magnitude and negatives.
            raw
        };

        // dst = is_nan ? 0 : result_before_nan.
        select(&mut instrs, is_nan, zero, result_before_nan, dst);
        Ok(instrs)
    }

    fn translate_cast(
        &mut self,
        op: &CastOp,
        src_ty: &Ty,
        dst_ty: &Ty,
        operand: &ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let src = self.map_value(*operand);
        let dst = self.map_result(results)?;
        let from = self.translate_ty(src_ty)?;
        let to = self.translate_ty(dst_ty)?;
        // Fail-closed safety gate: reject operand/declared-source mismatches and
        // structurally invalid cast shapes before emitting any lowering.
        self.validate_cast_shape(op, src_ty, dst_ty, *operand)?;
        self.define_value_type(dst, to.clone());

        // Float -> i128/u128: FCVTZS/FCVTZU cannot target a 128-bit register, so
        // route through the compiler-rt `__fix*ti` libcalls (the reverse of the
        // __floattidf/__floattisf `sitofp i128` path). Raw fptosi/fptoui is UB
        // out of range, matching the libcall's out-of-range behavior.
        if matches!(op, CastOp::FPToSI | CastOp::FPToUI) && matches!(dst_ty, Ty::I128 | Ty::U128) {
            let mut instrs = Vec::new();
            // An f16 source is first widened to f32 (a LOSSLESS conversion — every
            // f16 is exactly representable in f32), then converted via the f32
            // libcall. f16 -> f32 -> i128 is exact: the widening rounds nothing,
            // so only the single f32 -> i128 truncation happens, identical to a
            // direct f16 -> i128. (The reverse, i128 -> f16, is NOT done this way:
            // i128 -> f32 -> f16 would double-round.)
            let call_src = if matches!(src_ty, Ty::F16) {
                let widened = self.fresh_value();
                self.define_value_type(widened, Type::F32);
                instrs.push(Instruction {
                    opcode: Opcode::FPExt,
                    args: vec![src],
                    results: vec![widened],
                });
                widened
            } else {
                src
            };
            let callee = match (op, src_ty) {
                (CastOp::FPToSI, Ty::F32 | Ty::F16) => "__fixsfti",
                (CastOp::FPToSI, Ty::F64) => "__fixdfti",
                (CastOp::FPToUI, Ty::F32 | Ty::F16) => "__fixunssfti",
                (CastOp::FPToUI, Ty::F64) => "__fixunsdfti",
                _ => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CastOp::{op:?} {src_ty:?} -> {dst_ty:?}: only f16/f32/f64 -> i128/u128 \
                         are supported"
                    )));
                }
            };
            instrs.push(Instruction {
                opcode: Opcode::Call {
                    name: callee.to_string(),
                },
                args: vec![call_src],
                results: vec![dst],
            });
            return Ok(instrs);
        }

        // i128/u128 -> float: SCVTF/UCVTF cannot SOURCE a 128-bit value — a
        // native `scvtf d0, x0` reads only the LOW 64 bits and silently drops
        // the high half, so `x as f64` was wrong for every i128 outside the
        // i64 range. Route through the compiler-rt `__float*ti` libcalls (the
        // exact reverse of the `__fix*ti` float->i128 path above). The i128
        // argument is passed in the x0:x1 register pair and the float result
        // returned in d0/s0, matching the libcall's ABI.
        if matches!(op, CastOp::SIToFP | CastOp::UIToFP) && matches!(src_ty, Ty::I128 | Ty::U128) {
            // The libcall target width. An f16 destination goes through the f32
            // libcall (there is no __float*ihf) and then demotes f32 -> f16. This
            // is EXACT, not double-rounded: every i128 that yields a FINITE f16
            // (|v| < 65520) is < 2^17, so it is represented exactly in the f32
            // intermediate — only the single f32 -> f16 rounding happens; larger
            // magnitudes overflow to infinity through either width. (Verified
            // equal to the f64-intermediate reference over the boundary region.)
            let call_dst_ty = if matches!(dst_ty, Ty::F16) {
                Ty::F32
            } else {
                dst_ty.clone()
            };
            let callee = match (op, &call_dst_ty) {
                (CastOp::SIToFP, Ty::F32) => "__floattisf",
                (CastOp::SIToFP, Ty::F64) => "__floattidf",
                (CastOp::UIToFP, Ty::F32) => "__floatuntisf",
                (CastOp::UIToFP, Ty::F64) => "__floatuntidf",
                _ => {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CastOp::{op:?} {src_ty:?} -> {dst_ty:?}: only i128/u128 -> f16/f32/f64 \
                         are supported"
                    )));
                }
            };
            if matches!(dst_ty, Ty::F16) {
                // i128 -> f32 (libcall), then demote f32 -> f16.
                let f32_val = self.fresh_value();
                self.define_value_type(f32_val, Type::F32);
                return Ok(vec![
                    Instruction {
                        opcode: Opcode::Call {
                            name: callee.to_string(),
                        },
                        args: vec![src],
                        results: vec![f32_val],
                    },
                    Instruction {
                        opcode: Opcode::FPTrunc,
                        args: vec![f32_val],
                        results: vec![dst],
                    },
                ]);
            }
            return Ok(vec![Instruction {
                opcode: Opcode::Call {
                    name: callee.to_string(),
                },
                args: vec![src],
                results: vec![dst],
            }]);
        }

        let opcode = match op {
            CastOp::SExt => Opcode::Sextend {
                from_ty: from,
                to_ty: to,
            },
            CastOp::ZExt => Opcode::Uextend {
                from_ty: from,
                to_ty: to,
            },
            CastOp::Trunc => Opcode::Trunc { to_ty: to },
            CastOp::FPToSI => Opcode::FcvtToInt { dst_ty: to },
            CastOp::FPToUI => Opcode::FcvtToUint { dst_ty: to },
            // Saturating float->int casts implement Rust `as` semantics:
            // NaN -> 0 and out-of-range values clamp at the DESTINATION width.
            // Select the audited expansion for each supported width; never
            // substitute a raw non-saturating Fcvt operation.
            CastOp::FPToSISat | CastOp::FPToUISat => {
                // Register-width (i64/u64) saturating float->int is EXACTLY the
                // native FCVTZS/FCVTZU: round-toward-zero, NaN -> 0, and saturate
                // at the i64/u64 range — which IS the destination range. So it
                // lowers to the same FcvtToInt/FcvtToUint as the raw cast, with
                // the identical instruction and proof (`f as u64`/`as usize`/
                // `as i64`/`as isize`). Narrow destinations use the explicit
                // audited clamp expansion below because FCVTZS/FCVTZU saturate
                // at register width rather than i8/i16/i32 width.
                match (op, dst_ty) {
                    // isize/usize are pointer-width (64-bit): `f as isize` /
                    // `f as usize` saturate at the i64/u64 range exactly like
                    // the I64/U64 forms.
                    (CastOp::FPToSISat, Ty::I64 | Ty::Isize) => Opcode::FcvtToInt { dst_ty: to },
                    (CastOp::FPToUISat, Ty::U64 | Ty::Usize) => Opcode::FcvtToUint { dst_ty: to },
                    // Narrow (i8/i16/i32 or u8/u16/u32): FCVTZS/FCVTZU to i64
                    // (saturating + NaN->0), then clamp to the destination range,
                    // then truncate. See translate_narrow_saturating_cast.
                    (CastOp::FPToSISat, Ty::I8 | Ty::I16 | Ty::I32)
                    | (CastOp::FPToUISat, Ty::U8 | Ty::U16 | Ty::U32) => {
                        return self.translate_narrow_saturating_cast(op, src, dst_ty, to, dst);
                    }
                    // i128/u128 saturating: no native 128-bit fcvt, so use the
                    // __fix*ti libcall plus explicit float-compare bounds.
                    (CastOp::FPToSISat, Ty::I128) | (CastOp::FPToUISat, Ty::U128) => {
                        return self.translate_i128_saturating_cast(op, src_ty, dst_ty, src, dst);
                    }
                    _ => {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "CastOp::{op:?} to {dst_ty:?} fail-closed: unsupported saturating \
                             float->int destination; src_ty={src_ty:?}"
                        )));
                    }
                }
            }
            CastOp::SIToFP => Opcode::FcvtFromInt { src_ty: from },
            CastOp::UIToFP => Opcode::FcvtFromUint { src_ty: from },
            CastOp::FPExt => Opcode::FPExt,
            CastOp::FPTrunc => Opcode::FPTrunc,
            CastOp::PtrToInt | CastOp::IntToPtr | CastOp::PtrToPtr => {
                // No-op: pointers are already I64. Emit a single Copy pseudo.
                return Ok(vec![Instruction {
                    opcode: Opcode::Copy,
                    args: vec![src],
                    results: vec![dst],
                }]);
            }
            CastOp::Bitcast => Opcode::Bitcast { to_ty: to },
            CastOp::Transmute => {
                let size_detail = if from.bytes() == to.bytes() {
                    "equal-size bit reinterpretation still requires an explicit validity proof"
                } else {
                    "source and destination layout sizes differ"
                };
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "CastOp::Transmute fail-closed: {size_detail}; \
                     src_ty={src_ty:?} src_lir={from:?} src_size={} src_align={} \
                     dst_ty={dst_ty:?} dst_lir={to:?} dst_size={} dst_align={}; \
                     requires trust-ir layout, validity, and pointer-provenance checks before lowering",
                    from.bytes(),
                    from.align(),
                    to.bytes(),
                    to.align(),
                )));
            }
            CastOp::ReifyFnPointer => {
                let actual_ty = self.lookup_value_ty(*operand).ok_or_else(|| {
                    AdapterError::UnsupportedInstruction(format!(
                        "CastOp::ReifyFnPointer operand {operand:?} has no known trust_ir type"
                    ))
                })?;
                if actual_ty != *src_ty {
                    return Err(AdapterError::UnsupportedInstruction(format!(
                        "CastOp::ReifyFnPointer source type mismatch: declared src_ty={src_ty:?}, \
                         operand {operand:?} has type {actual_ty:?}"
                    )));
                }
                // Direction 1 — `Func(_) -> Ptr`: turn a materialized
                // function-symbol/code-pointer value into a raw pointer. Requires
                // the operand to carry materialized code-pointer provenance (a
                // `GlobalRef`/`ExternRef` relocation).
                if matches!(src_ty, Ty::Func(_)) && *dst_ty == Ty::Ptr {
                    if !self.materialized_code_pointer_values.contains(operand) {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "CastOp::ReifyFnPointer fail-closed: operand {operand:?} has Ty::Func \
                             but no materialized function-symbol/code-pointer provenance; arbitrary \
                             function identity materialization still requires code-pointer ABI, \
                             symbol relocation, and proof provenance before lowering"
                        )));
                    }
                    return Ok(vec![Instruction {
                        opcode: Opcode::Copy,
                        args: vec![src],
                        results: vec![dst],
                    }]);
                }
                // Direction 2 — `Ptr -> Func(sig)`: assert that an incoming raw
                // pointer IS a code pointer of `sig`. The bridge emits this ONLY
                // for a callee whose Rust type is a genuine `ty::FnPtr` (a `fn(..)`
                // value the type system guarantees points at code) — the
                // `FnOnce::call_once` FnPtrShim receiver that `lang_start`'s chain
                // invokes to run `main`. `ReifyFnPointer` is the explicit
                // provenance-carrying cast, so trusting that frontend assertion is
                // consistent with `Transmute`/`ReifyFnPointer`'s provenance model.
                // Lower as a register move (both carriers are a 64-bit pointer); the
                // result is now a `Func(sig)` value `CallIndirect` accepts, and we
                // record its code-pointer provenance.
                if matches!(src_ty, Ty::Ptr) && matches!(dst_ty, Ty::Func(_)) {
                    if let Some(result) = results.first() {
                        self.materialized_code_pointer_values.insert(*result);
                    }
                    return Ok(vec![Instruction {
                        opcode: Opcode::Copy,
                        args: vec![src],
                        results: vec![dst],
                    }]);
                }
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "CastOp::ReifyFnPointer fail-closed: src_ty={src_ty:?} src_lir={from:?} \
                     dst_ty={dst_ty:?} dst_lir={to:?}; supported only for Ty::Func(_) <-> Ty::Ptr \
                     code-pointer reification"
                )));
            }
        };

        Ok(vec![Instruction {
            opcode,
            args: vec![src],
            results: vec![dst],
        }])
    }

    /// Lower `llvm.fma` / `llvm.fmuladd` to distinct LIR contracts. Both select
    /// an initial single-rounding AArch64 `FMADD`, but only fusion-licensed
    /// `llvm.fmuladd` may later become separate `Fmul` + `Fadd`; strict IEEE
    /// `llvm.fma` must remain fused.
    fn translate_fma_intrinsic(
        &mut self,
        fp_ty: Type,
        may_unfuse: bool,
        args: &[Value],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if args.len() != 3 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(
                "llvm.fma/fmuladd expects three arguments and one result".to_string(),
            ));
        }
        let dst = results[0];
        self.define_value_type(dst, fp_ty);
        Ok(vec![Instruction {
            opcode: if may_unfuse {
                Opcode::Fmuladd
            } else {
                Opcode::Fma
            },
            args: vec![args[0], args[1], args[2]],
            results: vec![dst],
        }])
    }

    fn translate_bitreverse_intrinsic(
        &mut self,
        bitwidth: u16,
        args: &[Value],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if args.len() != 1 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "llvm.bitreverse.i{} expects one argument and one result",
                bitwidth
            )));
        }

        let ty = match bitwidth {
            32 => Type::I32,
            64 => Type::I64,
            other => {
                return Err(AdapterError::UnsupportedBitWidth(other));
            }
        };
        let dst = results[0];
        self.define_value_type(dst, ty.clone());

        let (swap_steps, final_shift): (&[(u8, i64)], u8) = match bitwidth {
            32 => (
                &[
                    (1, 0x5555_5555),
                    (2, 0x3333_3333),
                    (4, 0x0f0f_0f0f),
                    (8, 0x00ff_00ff),
                ],
                16,
            ),
            64 => (
                &[
                    (1, 0x5555_5555_5555_5555),
                    (2, 0x3333_3333_3333_3333),
                    (4, 0x0f0f_0f0f_0f0f_0f0f),
                    (8, 0x00ff_00ff_00ff_00ff),
                    (16, 0x0000_ffff_0000_ffff),
                ],
                32,
            ),
            _ => unreachable!(),
        };

        let mut instrs = Vec::new();
        let mut current = args[0];
        for &(shift, mask) in swap_steps {
            let shift_val = self.bitreverse_iconst(&mut instrs, &ty, i64::from(shift));
            let mask_val = self.bitreverse_iconst(&mut instrs, &ty, mask);
            let right = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Ushr,
                args: vec![current, shift_val],
                results: vec![right],
            });
            let right_masked = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![right, mask_val],
                results: vec![right_masked],
            });
            let left_masked = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Band,
                args: vec![current, mask_val],
                results: vec![left_masked],
            });
            let left = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Ishl,
                args: vec![left_masked, shift_val],
                results: vec![left],
            });
            let combined = self.bitreverse_tmp(&ty);
            instrs.push(Instruction {
                opcode: Opcode::Bor,
                args: vec![right_masked, left],
                results: vec![combined],
            });
            current = combined;
        }

        let final_shift_val = self.bitreverse_iconst(&mut instrs, &ty, i64::from(final_shift));
        let right = self.bitreverse_tmp(&ty);
        instrs.push(Instruction {
            opcode: Opcode::Ushr,
            args: vec![current, final_shift_val],
            results: vec![right],
        });
        let left = self.bitreverse_tmp(&ty);
        instrs.push(Instruction {
            opcode: Opcode::Ishl,
            args: vec![current, final_shift_val],
            results: vec![left],
        });
        instrs.push(Instruction {
            opcode: Opcode::Bor,
            args: vec![right, left],
            results: vec![dst],
        });

        Ok(instrs)
    }

    fn translate_objectsize_intrinsic(
        &mut self,
        bitwidth: u16,
        args: &[ValueId],
        results: &[Value],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if bitwidth != 64 {
            return Err(AdapterError::UnsupportedBitWidth(bitwidth));
        }
        if args.len() != 4 || results.len() != 1 {
            return Err(AdapterError::UnsupportedInstruction(
                "llvm.objectsize.i64.p0 expects one pointer argument, three i1 mode bits, and one result"
                    .to_string(),
            ));
        }

        let min = self.lookup_const_bool(args[1]).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "llvm.objectsize min mode bit must be a constant i1".to_string(),
            )
        })?;
        let null_unknown = self.lookup_const_bool(args[2]).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "llvm.objectsize null_unknown mode bit must be a constant i1".to_string(),
            )
        })?;
        let dynamic = self.lookup_const_bool(args[3]).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "llvm.objectsize dynamic mode bit must be a constant i1".to_string(),
            )
        })?;

        if dynamic {
            return Err(AdapterError::UnsupportedInstruction(
                "llvm.objectsize dynamic=true mode is unsupported".to_string(),
            ));
        }
        if min || !null_unknown {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "unsupported llvm.objectsize mode bits: min={}, null_unknown={}, dynamic={}; \
                 only min=false, null_unknown=true, dynamic=false is lowered",
                min, null_unknown, dynamic
            )));
        }

        let dst = results[0];
        self.define_value_type(dst, Type::I64);
        Ok(vec![Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: -1,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    fn bitreverse_iconst(&mut self, instrs: &mut Vec<Instruction>, ty: &Type, imm: i64) -> Value {
        let value = self.bitreverse_tmp(ty);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: ty.clone(),
                imm,
            },
            args: vec![],
            results: vec![value],
        });
        value
    }

    fn bitreverse_tmp(&mut self, ty: &Type) -> Value {
        let value = self.fresh_value();
        self.define_value_type(value, ty.clone());
        value
    }

    // -----------------------------------------------------------------------
    // Memory operations
    // -----------------------------------------------------------------------

    fn translate_load(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        volatile: bool,
        align: Option<u64>,
        results: &[ValueId],
        not_null_guard: Option<Option<u64>>,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let explicit_align = validate_explicit_memory_align("Load", align, lir_ty.align())?;
        let ptr_val = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        let mut insts = Vec::new();

        if let Some(obligation) = not_null_guard {
            insts.push(Instruction {
                opcode: Opcode::GuardNull { obligation },
                args: vec![ptr_val],
                results: vec![],
            });
        }

        if volatile {
            // A volatile load is an observable access (MMIO / signal
            // visibility): emit the distinct `VolatileLoad` opcode, which isel
            // lowers to a byte-identical machine load classified as a memory
            // barrier so the optimizer never elides/CSEs/forwards/hoists it.
            // A 128-bit integer is represented as a pair of 64-bit GPRs by
            // both native backends. Lowering it would therefore turn one
            // source volatile event into two architectural accesses, which is
            // observably wrong for MMIO. Reject it at the public boundary
            // until a target has an exact single-access scalar lowering.
            if matches!(ty, Ty::I128 | Ty::U128) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Load of {ty:?} is not supported: the native \
                     backends would split one volatile event into two 64-bit accesses"
                )));
            }
            // Aggregates aren't a volatile-scalar shape — reject them.
            if lir_ty.is_aggregate() {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Load of an aggregate type {lir_ty:?} is not supported; \
                     volatile applies to scalar MMIO-style accesses"
                )));
            }
            let mut vinsts = insts;
            vinsts.push(Instruction {
                opcode: Opcode::VolatileLoad {
                    ty: lir_ty,
                    align: explicit_align,
                },
                args: vec![ptr_val],
                results: vec![dst],
            });
            return Ok(vinsts);
        }

        // Loading an AGGREGATE is a BY-VALUE copy: aggregates are pointer-
        // represented, so allocate a fresh stack slot, Memmove the aggregate's
        // bytes into it, and return the slot address. A scalar Load would read
        // only the first 8 bytes (its address image), and returning the SOURCE
        // pointer would alias the source (mutating the loaded value would corrupt
        // memory). The fresh slot gives correct value semantics. Rust decomposes
        // aggregate loads upstream, so this only affects producers that emit
        // `Load { ty: <aggregate> }` directly.
        if lir_ty.is_aggregate() {
            // The SLOT keeps the natural-C size: `emitted <= natural` holds for
            // every layout authority (the domination gate in
            // [`crate::declared_layout`]), so the natural size always has room.
            // The COPY LENGTH is the authoritative extent — reading the natural
            // length out of a value the authority sizes smaller would read past
            // it, and `ptr_val` may be a FIELD address handed back by the
            // explicit-offset `ExtractField` arm.
            let slot = self.alloc_stack_slot(lir_ty.bytes(), lir_ty.align());
            self.define_value_type(dst, lir_ty.clone());
            insts.push(Instruction {
                opcode: Opcode::StackAddr { slot },
                args: vec![],
                results: vec![dst],
            });
            let len = self.aggregate_value_extent(ty, &lir_ty)? as i64;
            let len_val = self.emit_iconst_i64(len, &mut insts);
            insts.push(Instruction {
                opcode: Opcode::Memmove,
                args: vec![dst, ptr_val, len_val],
                results: vec![],
            });
            return Ok(insts);
        }

        insts.push(Instruction {
            opcode: Opcode::Load {
                ty: lir_ty,
                align: explicit_align,
            },
            args: vec![ptr_val],
            results: vec![dst],
        });
        Ok(insts)
    }

    fn translate_store(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        value: &ValueId,
        volatile: bool,
        align: Option<u64>,
        not_null_guard: Option<Option<u64>>,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let annotated_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let val = self.map_value(*value);
        // A vector store's WIDTH follows the stored value's LIR type, not the
        // `<N x bool>` annotation. This resolves the mask-width ambiguity: an
        // `<8 x bool>` value produced by a `<8 x i8>` compare is V64 (`str d`),
        // while an `<8 x bool>` from an `<8 x i16>` compare is V128 (`str q`) —
        // `translate_ty` cannot tell them apart from the bool-vector type alone,
        // but the producing ICmp defined the value's V64/V128 LIR type. For
        // every non-vector store the value type equals the annotation (trust-ir
        // validation guarantees it), so this is a no-op there.
        let lir_ty = match self.value_types.get(&val) {
            Some(vt @ (Type::V64 | Type::V128)) => vt.clone(),
            _ => annotated_ty,
        };
        let explicit_align = validate_explicit_memory_align("Store", align, lir_ty.align())?;
        let mut insts = Vec::new();

        if let Some(obligation) = not_null_guard {
            insts.push(Instruction {
                opcode: Opcode::GuardNull { obligation },
                args: vec![ptr_val],
                results: vec![],
            });
        }

        if volatile {
            // A volatile store is an observable access — emit the distinct
            // `VolatileStore` barrier opcode (see the volatile Load path).
            if matches!(ty, Ty::I128 | Ty::U128) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Store of {ty:?} is not supported: the native \
                     backends would split one volatile event into two 64-bit accesses"
                )));
            }
            if lir_ty.is_aggregate() {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "volatile Store of an aggregate type {lir_ty:?} is not supported; \
                     volatile applies to scalar MMIO-style accesses"
                )));
            }
            let mut vinsts = insts;
            vinsts.push(Instruction {
                opcode: Opcode::VolatileStore {
                    ty: lir_ty,
                    align: explicit_align,
                },
                args: vec![val, ptr_val],
                results: vec![],
            });
            return Ok(vinsts);
        }

        // An AGGREGATE value is pointer-represented, so `val` is the ADDRESS of
        // the source aggregate — a scalar Store would write 8 bytes of that
        // address rather than the aggregate's DATA (a silent miscompile). Copy
        // the bytes with Memmove (self-copy-safe). Rust decomposes aggregate
        // stores into scalar/memcpy ops upstream, so this only affects producers
        // that emit `Store { ty: <aggregate> }` directly; it is a proven-opcode
        // byte copy, symmetric to the aggregate InsertField/InsertElement paths.
        //
        // The length is the PACKED extent for a packed struct: `ptr_val` may be
        // a packed FIELD address (the packed `ExtractField` arm hands back
        // `base + packed_offset` for an aggregate field), and a natural-C length
        // there would reach past the field into the sibling
        // `packed_struct_layout` now places at the packed offset — see
        // `aggregate_value_extent`.
        if lir_ty.is_aggregate() {
            let len = self.aggregate_value_extent(ty, &lir_ty)? as i64;
            let len_val = self.emit_iconst_i64(len, &mut insts);
            insts.push(Instruction {
                opcode: Opcode::Memmove,
                args: vec![ptr_val, val, len_val],
                results: vec![],
            });
            return Ok(insts);
        }

        insts.push(Instruction {
            opcode: Opcode::Store {
                ty: lir_ty,
                align: explicit_align,
            },
            args: vec![val, ptr_val],
            results: vec![],
        });
        Ok(insts)
    }

    fn translate_atomic_load(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        ordering: &MemoryOrdering,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        validate_atomic_load_ordering(ordering)?;
        let lir_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let dst = self.map_result(results)?;
        let lir_ordering = translate_ordering(ordering);

        Ok(vec![Instruction {
            opcode: Opcode::AtomicLoad {
                ty: lir_ty,
                ordering: lir_ordering,
            },
            args: vec![ptr_val],
            results: vec![dst],
        }])
    }

    fn translate_atomic_store(
        &mut self,
        ty: &Ty,
        ptr: &ValueId,
        value: &ValueId,
        ordering: &MemoryOrdering,
    ) -> Result<Vec<Instruction>, AdapterError> {
        validate_atomic_store_ordering(ordering)?;
        let lir_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let val = self.map_value(*value);
        let lir_ordering = translate_ordering(ordering);

        Ok(vec![Instruction {
            opcode: Opcode::AtomicStore {
                ty: lir_ty,
                ordering: lir_ordering,
            },
            args: vec![val, ptr_val],
            results: vec![],
        }])
    }

    fn translate_atomic_rmw(
        &mut self,
        op: &TrustIrAtomicRmwOp,
        ty: &Ty,
        ptr: &ValueId,
        value: &ValueId,
        ordering: &MemoryOrdering,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let ptr_val = self.map_value(*ptr);
        let val = self.map_value(*value);
        let dst = self.map_result(results)?;
        let lir_ordering = translate_ordering(ordering);
        let lir_op = translate_atomic_rmw_op(op)?;

        Ok(vec![Instruction {
            opcode: Opcode::AtomicRmw {
                op: lir_op,
                ty: lir_ty,
                ordering: lir_ordering,
            },
            args: vec![val, ptr_val],
            results: vec![dst],
        }])
    }

    // `translate_cmpxchg` was removed during the 2026-04-19 zero-warnings
    // cleanup — CmpXchg is lowered inline in `translate_instruction` above.

    fn translate_fence(
        &mut self,
        ordering: &MemoryOrdering,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ordering = translate_ordering(ordering);

        Ok(vec![Instruction {
            opcode: Opcode::Fence {
                ordering: lir_ordering,
            },
            args: vec![],
            results: vec![],
        }])
    }

    fn translate_alloc(
        &mut self,
        ty: &Ty,
        count: &Option<ValueId>,
        explicit_align: Option<u64>,
        results: &[ValueId],
        decl_line: Option<u32>,
    ) -> Result<Vec<Instruction>, AdapterError> {
        let explicit_align = validate_explicit_alloca_align(explicit_align)?;
        let lir_ty = self.translate_ty(ty)?;
        let alloca_result_vid = results
            .first()
            .copied()
            .ok_or(AdapterError::MissingResult)?;
        let dst = self.map_result(results)?;
        // `StackAddr` materializes an address regardless of the allocated
        // element type. Seed the carrier explicitly so an aggregate alloca can
        // never reach a memory opcode typed as the aggregate itself.
        self.define_value_type(dst, Type::I64);

        // Compute allocation size metadata. For `count: None`, allocate one
        // element. For `count: Some(vid)`, look up `vid`'s producer in the
        // trust_ir function: if it is an Inst::Const with a non-negative integer,
        // fold it statically and allocate `count * element_size` bytes. If the
        // count is dynamic but every observed use has a bounded footprint, keep
        // the existing fixed-slot escape hatch. Otherwise record runtime-size
        // provenance so lower-layer consumers can distinguish this from an
        // ordinary fixed frame slot.
        //
        // #339 Finding 2: the previous implementation always allocated exactly
        // one element's worth of bytes, so a `count = 10` request received
        // only 8 bytes. Storing to element 2+ stomped adjacent stack slots.
        //
        // Most tla-trust_ir aggregate allocations still use constant counts, so the
        // constant-folding path handles the default case. Runtime counts are
        // accepted in two stages: bounded-use inference keeps producing fixed
        // slots (Issue #520 escape hatch), while the general case now produces
        // explicit runtime-sized metadata for the later frame/runtime work.
        //
        // Runtime-sized code generation now depends on preserving this slot
        // metadata through the downstream StackAddr paths. AArch64 and x86-64
        // ISel inspect `StackSlotAllocationKind` to choose between fixed frame
        // addresses and runtime StackAlloc cursor materialization, and the
        // public compiler dispatchers must seed that metadata before ISel.
        // THE EXTENT HERE IS DELIBERATELY NATURAL-C, NOT THE LAYOUT AUTHORITY.
        //
        // Every ADDRESS the byte path computes now comes from
        // [`crate::declared_layout`] — declared offsets, packed offsets, packed
        // array strides — and every by-value COPY length comes from
        // `aggregate_value_extent`. This slot does not, and the gap is measured,
        // one-directional and safe: the authority only ever SHRINKS an object
        // relative to natural C (`Alloca { ty: [P; 2] }` reserves 32 while the
        // packed image is 18), so every authoritative address lands strictly
        // inside the slot. That is the domination invariant, pinned in
        // `tests/packed_array_stride.rs` and `tests/packed_nested_layout.rs`.
        //
        // Moving it is an OVER-ALLOCATION traded for a possible OUT-OF-BOUNDS
        // write, and it cannot be done at these four sites alone
        // (`translate_alloc`'s size and align here, `translate_heap_alloc`'s
        // below). The blocker is STRUCTURAL, not a missed call site:
        //
        //   `abi.rs::classify_params` / `classify_returns` take `&[Type]` — the
        //   LIR types off `sig.params`, after the `StructId` and the module
        //   tables are gone. They size every by-value aggregate with
        //   `ty.bytes()` and decide reg-pair vs stack on `size <= 16`. There is
        //   nothing left there to resolve against a layout authority, so a
        //   value passed by value out of a SHRUNK slot would be read at its
        //   natural-C width — an out-of-bounds READ, and for `__rust_alloc` a
        //   heap one.
        //
        // So the order is: give the ABI classifier an authority-aware input
        // FIRST (a cross-crate signature change), then move all four extents in
        // one commit. A benign over-allocation is strictly better than a
        // partial change that trades it for memory corruption.
        let element_size = lir_ty.bytes();
        let align = explicit_align
            .map(|explicit| lir_ty.align().max(explicit))
            .unwrap_or_else(|| lir_ty.align());
        let slot = match count {
            None => self.alloc_stack_slot(element_size, align),
            Some(vid) => {
                if let Some(n) = self.lookup_const_int(*vid) {
                    let size = self.checked_static_alloca_size(element_size, n)?;
                    self.alloc_stack_slot(size, align)
                } else if let Some(bytes) =
                    self.infer_bounded_alloca_size_from_uses(alloca_result_vid)
                {
                    self.alloc_stack_slot(bytes, align)
                } else {
                    let lir_count = self.map_value(*vid);
                    self.alloc_runtime_stack_slot(
                        StackSlotSizeSource::Value(lir_count.0),
                        element_size,
                        align,
                    )
                }
            }
        };

        match self.fixed_scalar_alloca_debug_local(ty, count, slot) {
            Ok((debug_ty, var_id)) => {
                self.debug_local_variables.push(DebugLocalVariable {
                    name: format!("local_{}", slot),
                    ty: debug_ty,
                    storage: DebugVariableStorage::ProvenanceVar(var_id),
                    decl_line: decl_line.unwrap_or(0),
                });
            }
            Err(_reason) => {}
        }

        Ok(vec![Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Build the LIR for a libc `mem*` intrinsic (`Memcpy`/`Memmove`/`Memset`).
    ///
    /// The C library `memcpy`/`memmove`/`memset` all RETURN the destination
    /// pointer (`args[0]`). When the trust-ir call binds a result value, define
    /// it as a `Copy` of the destination AFTER the memory op, so a downstream
    /// use of `%r = call @memcpy(dst, …)` sees the correct pointer instead of an
    /// undefined vreg. The void `llvm.mem*.*` intrinsic form carries no result
    /// (`result_vals` empty), so no `Copy` is emitted and its lowering is
    /// unchanged.
    fn mem_intrinsic_instrs(
        &mut self,
        opcode: Opcode,
        arg_vals: Vec<Value>,
        result_vals: &[Value],
    ) -> Vec<Instruction> {
        let dest = arg_vals.first().copied();
        let mut instrs = vec![Instruction {
            opcode,
            args: arg_vals,
            results: vec![],
        }];
        if let (Some(&dst), Some(dest)) = (result_vals.first(), dest) {
            // The returned dest pointer is an I64 address.
            self.define_value_type(dst, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Copy,
                args: vec![dest],
                results: vec![dst],
            });
        }
        instrs
    }

    /// Lower `Inst::GlobalAddr { global }` to the address of the named module
    /// global symbol.
    ///
    /// This is the in-body counterpart of the imported `Constant::Int`
    /// global-address stub handled by `decode_imported_global_addr`/
    /// `translate_int_const`: it resolves the `GlobalId` to the global's
    /// symbol name and emits `Opcode::GlobalRef { name }`, which x86-64 ISel
    /// (`select_global_ref`) materializes as a RIP-relative `LeaRip` against a
    /// dedicated GlobalRef relocation. The address is linker-resolved, so this
    /// is verified by link+run rather than an SMT proof.
    fn translate_global_addr(
        &mut self,
        global: GlobalId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let module = self.module.ok_or(AdapterError::ModuleNotSet)?;
        let idx = global.index() as usize;
        let global_def = module.globals.get(idx).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "GlobalAddr references missing global index {}",
                idx
            ))
        })?;
        let name = global_def.name.clone();
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        // Thread-local globals resolve through the target's TLS access path, not
        // a plain symbol reference. The access dialect is object-format policy
        // ([`TlsDialect`], set by the compiler driver from the target triple):
        //
        //  * Mach-O (Darwin/AArch64): the TLV-descriptor sequence
        //    (`select_tls_ref`, `TlsModel::Tlv`) — ADRP/LDR to the
        //    `tlv_descriptor`, load the thunk, and call it (returns the
        //    variable's address). The object emitter materializes the
        //    descriptor in `__thread_vars`.
        //  * ELF (Linux/AArch64): the local-exec sequence
        //    (`TlsModel::LocalExec`, no pre-resolved offset) — MRS TPIDR_EL0
        //    plus two linker-patched TPREL adds
        //    (`R_AARCH64_TLSLE_ADD_TPREL_HI12`/`_LO12_NC`); definitions land
        //    in `.tdata`, imports become undefined `STT_TLS` symbols.
        //
        // Either way a backend without the corresponding TLS object path
        // fails closed on the resulting `Opcode::TlsRef`/fixup, so a TLS
        // global is never silently miscompiled into a non-TLS reference.
        if global_def.tls.is_some() {
            let model = match self.tls_dialect {
                TlsDialect::MachOTlv => TlsModel::Tlv,
                TlsDialect::ElfLocalExec => TlsModel::LocalExec,
                TlsDialect::ElfInitialExec => TlsModel::InitialExec,
            };
            return Ok(vec![Instruction {
                opcode: Opcode::TlsRef {
                    name,
                    model,
                    local_exec_offset: None,
                },
                args: vec![],
                results: vec![dst],
            }]);
        }

        // An initializer-less global with external visibility is a cross-object
        // DATA IMPORT (e.g. `extern { static FOO: i32 }` resolved from another
        // object or a dylib). The object emitter marks it an undefined-external
        // symbol (compiler.rs `is_import: true`), so a DIRECT page reference
        // (`GlobalRef` -> ADRP@PAGE + ADD@PAGEOFF) is a relocation against an
        // undefined/interposable symbol: a static-link error, or the wrong
        // address under two-level-namespace interposition. macOS requires such a
        // reference to be GOT-INDIRECT (@GOTPAGE/@GOTPAGEOFF) — exactly the
        // `ExternRef` sequence (`select_extern_ref`) already used for imported
        // FUNCTIONS. A DEFINED global (has an initializer) keeps the direct
        // `GlobalRef`. An Internal/Private initializer-less global is refused
        // later at object emission (BSS/zero-fill is not wired), so only the
        // external import is special-cased here.
        if global_is_external_data_import(global_def) {
            return Ok(vec![Instruction {
                opcode: Opcode::ExternRef { name },
                args: vec![],
                results: vec![dst],
            }]);
        }

        Ok(vec![Instruction {
            opcode: Opcode::GlobalRef { name },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Lower `Inst::HeapAlloc { ty, count, align, origin }` to a CALL of the
    /// allocator function selected by `origin`.
    ///
    /// Computes `size = count * sizeof(ty)` (constant-folded when `count` is a
    /// statically known integer, otherwise an emitted `Imul`) and `align`
    /// (`align` override or the natural alignment of `ty`), then calls:
    ///
    ///   * `AllocOrigin::RustHeap` -> `__rust_alloc(size: usize, align: usize)
    ///     -> *mut u8` (the Rust global allocator; the bridge/test driver
    ///     provides the shim forwarding to the system allocator).
    ///   * `AllocOrigin::CMalloc`  -> `malloc(size: usize) -> *mut void`
    ///     (libc; `align` is dropped — libc `malloc` already returns memory
    ///     suitably aligned for any fundamental type, so a natural-alignment
    ///     request is satisfied).
    ///   * `AllocOrigin::SwiftHeap` -> fail-closed: there is no portable
    ///     two-argument Swift heap-allocation shim yet, and we must never
    ///     miscompile by routing a Swift allocation to the wrong runtime.
    ///   * `AllocOrigin::CleanHeap` -> fail-closed for the same reason: Clean's
    ///     Perceus RC cells are allocated through the `clean_alloc_ctor`
    ///     runtime (refcount-managed, freed on `Release`->zero exactly like
    ///     `SwiftHeap`), and no portable shim is wired into this path yet.
    ///
    /// The returned pointer is the call's I64 result vreg. Correctness of the
    /// allocation itself rests on trusting the external allocator (exactly like
    /// the i128-division compiler-rt libcall and the memcpy/memmove/memset
    /// intrinsic calls); the abstract heap semantics are covered by the
    /// trust-ir Lean spec, so there is no per-call SMT proof for the external
    /// CALL. A `malloc`/`__rust_alloc` request for `0` bytes is implementation
    /// defined but never miscompiled — the size is passed through unchanged.
    fn translate_heap_alloc(
        &mut self,
        ty: &Ty,
        count: &Option<ValueId>,
        align: Option<u64>,
        origin: AllocOrigin,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        // NATURAL-C, deliberately — the other half of the extent bundle
        // documented at `translate_alloc`'s slot computation. `__rust_alloc`
        // over-allocates (32 bytes for a `[P; 2]` whose real extent is 18)
        // exactly as the stack slot does, and for exactly the same reason: the
        // C register-ABI classifier in `abi.rs` sizes by-value aggregates from
        // the bare LIR `Type` and would read a shrunk allocation at its
        // natural-C width. Shrinking here without giving that classifier an
        // authority-aware input turns a benign over-allocation into a heap
        // out-of-bounds read. These two lines move with those four, or not at
        // all.
        let element_size = lir_ty.bytes();
        let natural_align = lir_ty.align();
        // The effective alignment is the explicit override or the element's
        // natural alignment, whichever applies. `align` from trust_ir is the
        // requested allocation alignment.
        let effective_align = align
            .map(|a| {
                u32::try_from(a).map_err(|_| {
                    AdapterError::UnsupportedInstruction(format!(
                        "HeapAlloc alignment {a} exceeds u32 range"
                    ))
                })
            })
            .transpose()?
            .unwrap_or(natural_align);

        // Select the allocator symbol from the allocation origin. Unsupported
        // origins fail closed rather than route an allocation to the wrong
        // runtime.
        let alloc_symbol = match origin {
            AllocOrigin::RustHeap => "__rust_alloc",
            AllocOrigin::CMalloc => "malloc",
            AllocOrigin::SwiftHeap => {
                return Err(AdapterError::UnsupportedInstruction(
                    "HeapAlloc with AllocOrigin::SwiftHeap not yet lowered (fail-closed): \
                     Swift ARC heap allocation has no portable shim yet"
                        .to_string(),
                ));
            }
            AllocOrigin::CleanHeap => {
                // Clean's Perceus RC cells are allocated through the
                // `clean_alloc_ctor` runtime (refcount-managed, freed on
                // `Release`→zero exactly like SwiftHeap), not via a single
                // portable alloc symbol. No direct shim yet: fail closed
                // rather than route the allocation to the wrong runtime.
                return Err(AdapterError::UnsupportedInstruction(
                    "HeapAlloc with AllocOrigin::CleanHeap not yet lowered (fail-closed): \
                     Clean Perceus RC heap cells use the clean_alloc_ctor runtime, \
                     which has no portable shim yet"
                        .to_string(),
                ));
            }
        };

        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I64);

        let mut instrs = Vec::new();

        // Compute the byte size operand. Fold a statically known count; for a
        // dynamic count emit `size = count * element_size` (i64 multiply).
        let size_val = match count {
            None => self.emit_iconst_i64(element_size as i64, &mut instrs),
            Some(vid) => {
                if let Some(n) = self.lookup_const_int(*vid) {
                    if n < 0 {
                        return Err(AdapterError::UnsupportedInstruction(format!(
                            "HeapAlloc with negative count {n}"
                        )));
                    }
                    let total = (element_size as u128)
                        .checked_mul(n as u128)
                        .filter(|t| *t <= u64::MAX as u128)
                        .ok_or_else(|| {
                            AdapterError::UnsupportedInstruction(format!(
                                "HeapAlloc size overflow: {element_size} * {n}"
                            ))
                        })?;
                    self.emit_iconst_i64(total as i64, &mut instrs)
                } else {
                    // Dynamic count: extend to i64 and multiply by the element
                    // size. `extend_index_to_i64_if_needed` produces a 64-bit
                    // count regardless of the source integer width so the
                    // multiply matches the usize size argument.
                    let count_val = self.map_value(*vid);
                    let count_i64 =
                        self.extend_index_to_i64_if_needed(*vid, count_val, &mut instrs)?;
                    if element_size == 1 {
                        count_i64
                    } else {
                        let size_const = self.emit_iconst_i64(element_size as i64, &mut instrs);
                        let scaled = self.fresh_value();
                        self.define_value_type(scaled, Type::I64);
                        instrs.push(Instruction {
                            opcode: Opcode::Imul,
                            args: vec![count_i64, size_const],
                            results: vec![scaled],
                        });
                        scaled
                    }
                }
            }
        };

        // Build the allocator call argument list per the selected ABI.
        let call_args = match origin {
            AllocOrigin::RustHeap => {
                let align_val = self.emit_iconst_i64(effective_align as i64, &mut instrs);
                vec![size_val, align_val]
            }
            // libc `malloc(size)`; alignment satisfied by malloc's fundamental
            // alignment guarantee.
            AllocOrigin::CMalloc => vec![size_val],
            AllocOrigin::SwiftHeap => unreachable!("SwiftHeap fails closed above"),
            AllocOrigin::CleanHeap => unreachable!("CleanHeap fails closed above"),
        };

        // Reuse the external-CALL relocation path (same machinery as the
        // i128-division compiler-rt libcall and memcpy/memmove/memset
        // intrinsics): a direct call by symbol name resolved by the linker.
        instrs.push(Instruction {
            opcode: Opcode::Call {
                name: alloc_symbol.to_string(),
            },
            args: call_args,
            results: vec![dst],
        });

        Ok(instrs)
    }

    /// Emit an i64 `Iconst` into `instrs` and return its result Value.
    fn emit_iconst_i64(&mut self, imm: i64, instrs: &mut Vec<Instruction>) -> Value {
        let v = self.fresh_value();
        self.define_value_type(v, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iconst { ty: Type::I64, imm },
            args: vec![],
            results: vec![v],
        });
        v
    }

    /// True iff the module declares the Clean RC-runtime import triple as
    /// bodyless externals with the exact expected signatures:
    ///
    ///   * `clean_inc(ptr) -> ()`          — retain: refcount +1
    ///   * `clean_dec(ptr) -> ()`          — release: refcount −1, frees at zero
    ///   * `clean_is_exclusive(ptr) -> u8` — unique? (same polarity as `IsUnique`)
    ///
    /// The triple is all-or-nothing: a partial match is not an RC runtime and
    /// the ARC ops keep failing closed. Signatures are checked (not just
    /// names) so an unrelated same-named import cannot claim the contract.
    fn module_declares_clean_rc_runtime(&self) -> bool {
        let Some(module) = self.module else {
            return false;
        };
        let declares = |name: &str, params: &[Ty], returns: &[Ty]| {
            module.functions.iter().any(|func| {
                func.name == name
                    && is_bodyless_external_declaration(func)
                    && module
                        .func_types
                        .get(func.ty.index() as usize)
                        .is_some_and(|sig| {
                            !sig.is_vararg
                                && sig.params.as_slice() == params
                                && sig.returns.as_slice() == returns
                        })
            })
        };
        declares(CLEAN_RC_RETAIN, &[Ty::Ptr], &[])
            && declares(CLEAN_RC_RELEASE, &[Ty::Ptr], &[])
            && declares(CLEAN_RC_IS_UNIQUE, &[Ty::Ptr], &[Ty::U8])
    }

    /// Lower one ARC op (`Retain`/`Release`/`IsUnique`) to a CALL of the
    /// module-declared Clean RC runtime (see [`Self::module_declares_clean_rc_runtime`]).
    ///
    /// `Retain`/`Release` are void calls of `clean_inc`/`clean_dec`. `IsUnique`
    /// calls `clean_is_exclusive` — the SAME predicate (refcount == 1), so no
    /// negation happens here; Clean's frontend expresses `IsShared` as
    /// `!IsUnique` itself — and normalizes the C `bool` return to a canonical
    /// 0/1 with an explicit `!= 0` byte compare (the same byte-compare idiom
    /// the Clean frontend used pre-native-ARC), so a strict-ABI callee's
    /// unspecified upper bits can never leak into a Bool consumer.
    ///
    /// Like the allocator/memcpy/i128-libcall externals, correctness of the
    /// call target rests on trusting the runtime symbol; the refcount
    /// semantics themselves are covered by the trust-ir Lean ARC model, so
    /// there is no per-call SMT proof for the external CALL.
    fn translate_arc_op(
        &mut self,
        op_name: &str,
        symbol: &str,
        ptr: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !self.module_declares_clean_rc_runtime() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "ARC {op_name} not lowered: the module declares no RC runtime \
                 (a Clean-produced module declares the bodyless-external \
                 {CLEAN_RC_RETAIN}/{CLEAN_RC_RELEASE}/{CLEAN_RC_IS_UNIQUE} import \
                 triple); routing reference-count ops to an undeclared runtime \
                 would corrupt its refcount discipline, so this fails closed"
            )));
        }
        let ptr_val = self.map_value(ptr);
        if symbol != CLEAN_RC_IS_UNIQUE {
            // Retain/Release: a void runtime call.
            return Ok(vec![Instruction {
                opcode: Opcode::Call {
                    name: symbol.to_string(),
                },
                args: vec![ptr_val],
                results: vec![],
            }]);
        }
        // IsUnique: call + normalize the C `bool` (byte) to the Bool result.
        let dst = self.map_result(results)?;
        let raw = self.fresh_value();
        self.define_value_type(raw, Type::I8);
        let zero = self.fresh_value();
        self.define_value_type(zero, Type::I8);
        Ok(vec![
            Instruction {
                opcode: Opcode::Call {
                    name: symbol.to_string(),
                },
                args: vec![ptr_val],
                results: vec![raw],
            },
            Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I8,
                    imm: 0,
                },
                args: vec![],
                results: vec![zero],
            },
            Instruction {
                opcode: Opcode::Icmp {
                    cond: IntCC::NotEqual,
                },
                args: vec![raw, zero],
                results: vec![dst],
            },
        ])
    }

    /// Returns the debug type and synthetic provenance var for the one fixed
    /// scalar alloca shape handled by the #866 bridge. Other shapes are skipped
    /// with typed reasons so later recovery work can widen this deliberately.
    fn fixed_scalar_alloca_debug_local(
        &self,
        ty: &Ty,
        count: &Option<ValueId>,
        slot: u32,
    ) -> Result<(DebugBaseType, TrustIrVarId), AllocaDebugLocalSkipReason> {
        let debug_ty =
            debug_base_type_from_trust_ir(ty).ok_or(AllocaDebugLocalSkipReason::UnsupportedType)?;
        match count {
            None => {}
            Some(vid) => match self.lookup_const_int(*vid) {
                Some(1) => {}
                Some(_) => return Err(AllocaDebugLocalSkipReason::NonScalarElementCount),
                None => return Err(AllocaDebugLocalSkipReason::RuntimeElementCount),
            },
        }
        let var_id = alloca_debug_provenance_var_id(slot)
            .ok_or(AllocaDebugLocalSkipReason::SyntheticVarIdOverflow)?;
        Ok((debug_ty, var_id))
    }

    fn function_requires_stack_protector(&self, func: &TrustIrFunction) -> bool {
        match imported_stack_protector_request(func) {
            ImportedStackProtectorRequest::None => false,
            ImportedStackProtectorRequest::Required => true,
            ImportedStackProtectorRequest::Eligible => {
                self.imported_ssp_body_requires_stack_guard(func)
            }
        }
    }

    fn imported_ssp_body_requires_stack_guard(&self, func: &TrustIrFunction) -> bool {
        for block in &func.blocks {
            for node in &block.body {
                let Inst::Alloca { ty, count, .. } = &node.inst else {
                    continue;
                };
                let Some(alloca_result) = node.results.first().copied() else {
                    return true;
                };
                if self.imported_ssp_alloca_requires_stack_guard(alloca_result, ty, count) {
                    return true;
                }
            }
        }
        false
    }

    fn imported_ssp_alloca_requires_stack_guard(
        &self,
        alloca_result: ValueId,
        ty: &Ty,
        count: &Option<ValueId>,
    ) -> bool {
        let Some(static_size) = self.static_alloca_size_bytes(ty, count) else {
            return true;
        };
        if self.is_protected_imported_ssp_alloca(ty, count, static_size) {
            return true;
        }
        self.alloca_pointer_has_unsafe_stack_protector_use(alloca_result, static_size)
    }

    fn static_alloca_size_bytes(&self, ty: &Ty, count: &Option<ValueId>) -> Option<u32> {
        let element_size = self.translate_ty(ty).ok()?.bytes();
        let element_count = match count {
            None => 1,
            Some(vid) => self.lookup_const_int(*vid)?,
        };
        if element_count < 0 {
            return None;
        }
        let element_count = u32::try_from(element_count).ok()?;
        element_size.checked_mul(element_count)
    }

    fn is_protected_imported_ssp_alloca(
        &self,
        ty: &Ty,
        count: &Option<ValueId>,
        static_size: u32,
    ) -> bool {
        let element_count = count
            .and_then(|vid| self.lookup_const_int(vid))
            .unwrap_or(1);
        let fixed_scalar = element_count <= 1 && is_stack_protector_scalar_alloca_ty(ty);
        !fixed_scalar && static_size >= IMPORTED_STACK_PROTECTOR_BUFFER_BYTES
    }

    fn alloca_pointer_has_unsafe_stack_protector_use(
        &self,
        alloca_result: ValueId,
        static_size: u32,
    ) -> bool {
        let Some(func) = self.trust_ir_func else {
            return true;
        };
        let static_size = i128::from(static_size);

        for block in &func.blocks {
            for node in &block.body {
                match &node.inst {
                    Inst::Load { ty, ptr, .. } | Inst::AtomicLoad { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::Store { ty, ptr, value, .. }
                    | Inst::AtomicStore { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            alloca_result,
                            &mut HashSet::new(),
                        ) {
                            return true;
                        }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::AtomicRMW { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            alloca_result,
                            &mut HashSet::new(),
                        ) {
                            return true;
                        }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::CmpXchg {
                        ty,
                        ptr,
                        expected,
                        desired,
                        ..
                    } => {
                        if self.any_value_derived_from_alloca([*expected, *desired], alloca_result)
                        {
                            return true;
                        }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) && self
                            .alloca_access_end_bytes(alloca_result, *ptr, ty)
                            .is_none_or(|end| end > static_size)
                        {
                            return true;
                        }
                    }
                    Inst::Call { callee, args } => {
                        for (arg_index, arg) in args.iter().enumerate() {
                            if self.value_definitely_derived_from_alloca(
                                *arg,
                                alloca_result,
                                &mut HashSet::new(),
                            ) && !self.direct_call_allows_stack_pointer_arg(
                                *callee,
                                arg_index,
                                *arg,
                                alloca_result,
                                static_size,
                            ) {
                                return true;
                            }
                        }
                    }
                    Inst::CallIndirect { callee, args, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *callee,
                            alloca_result,
                            &mut HashSet::new(),
                        ) || args.iter().any(|arg| {
                            self.value_definitely_derived_from_alloca(
                                *arg,
                                alloca_result,
                                &mut HashSet::new(),
                            )
                        }) {
                            return true;
                        }
                    }
                    Inst::Return { values } => {
                        if self.any_value_derived_from_alloca(values.iter().copied(), alloca_result)
                        {
                            return true;
                        }
                    }
                    Inst::Br { args, .. } => {
                        if self.any_value_derived_from_alloca(args.iter().copied(), alloca_result) {
                            return true;
                        }
                    }
                    Inst::CondBr {
                        then_args,
                        else_args,
                        ..
                    } => {
                        if self.any_value_derived_from_alloca(
                            then_args.iter().chain(else_args).copied(),
                            alloca_result,
                        ) {
                            return true;
                        }
                    }
                    Inst::Switch {
                        default_args,
                        cases,
                        ..
                    } => {
                        if self.any_value_derived_from_alloca(
                            default_args
                                .iter()
                                .copied()
                                .chain(cases.iter().flat_map(|case| case.args.iter().copied())),
                            alloca_result,
                        ) {
                            return true;
                        }
                    }
                    Inst::Cast {
                        op: CastOp::PtrToInt,
                        operand,
                        ..
                    } if self.value_definitely_derived_from_alloca(
                        *operand,
                        alloca_result,
                        &mut HashSet::new(),
                    ) =>
                    {
                        return true;
                    }
                    Inst::BinOp { lhs, rhs, .. }
                    | Inst::ICmp { lhs, rhs, .. }
                    | Inst::Overflow { lhs, rhs, .. }
                        if self.any_value_derived_from_alloca([*lhs, *rhs], alloca_result) =>
                    {
                        return true;
                    }
                    Inst::Retain { ptr }
                    | Inst::Release { ptr }
                    | Inst::Dealloc { ptr }
                    | Inst::IsUnique { ptr }
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            alloca_result,
                            &mut HashSet::new(),
                        ) =>
                    {
                        return true;
                    }
                    _ => {}
                }
            }
        }

        false
    }

    fn direct_call_allows_stack_pointer_arg(
        &self,
        callee: FuncId,
        arg_index: usize,
        arg: ValueId,
        alloca_result: ValueId,
        static_size: i128,
    ) -> bool {
        let callee_name = self
            .func_names
            .get(&callee)
            .map(String::as_str)
            .unwrap_or("");
        if is_stack_pointer_readonly_intrinsic(callee_name) {
            return true;
        }
        if self.external_func_ids.contains(&callee) {
            return false;
        }

        let Some(arg_offset) =
            self.pointer_offset_from_alloca_bytes(arg, alloca_result, &mut HashSet::new())
        else {
            return false;
        };
        let mut seen_direct_call_args = HashSet::new();
        let Some(callee_end) = self.infer_direct_callee_pointer_max_end_bytes(
            callee,
            arg_index,
            &mut seen_direct_call_args,
        ) else {
            return false;
        };
        arg_offset
            .checked_add(callee_end)
            .is_some_and(|end| end <= static_size)
    }

    fn any_value_derived_from_alloca<I>(&self, values: I, alloca_result: ValueId) -> bool
    where
        I: IntoIterator<Item = ValueId>,
    {
        values.into_iter().any(|value| {
            self.value_definitely_derived_from_alloca(value, alloca_result, &mut HashSet::new())
        })
    }

    fn value_definitely_derived_from_alloca(
        &self,
        value: ValueId,
        alloca_result: ValueId,
        seen: &mut HashSet<ValueId>,
    ) -> bool {
        if value == alloca_result {
            return true;
        }
        if !seen.insert(value) {
            return false;
        }

        let derived = match self.find_value_producer(value).map(|node| &node.inst) {
            Some(Inst::Copy { operand, .. })
            | Some(Inst::Cast { operand, .. })
            | Some(Inst::Borrow { ptr: operand })
            | Some(Inst::BorrowMut { ptr: operand }) => {
                self.value_definitely_derived_from_alloca(*operand, alloca_result, seen)
            }
            Some(Inst::GEP { base, .. }) => {
                self.value_definitely_derived_from_alloca(*base, alloca_result, seen)
            }
            Some(Inst::Select {
                then_val, else_val, ..
            }) => {
                self.value_definitely_derived_from_alloca(*then_val, alloca_result, seen)
                    || self.value_definitely_derived_from_alloca(*else_val, alloca_result, seen)
            }
            _ => false,
        };

        seen.remove(&value);
        derived
    }

    /// Look up the `Inst::Const` producer of a ValueId in the current trust_ir
    /// function. Returns `Some(value)` only when the producer is a statically
    /// foldable integer expression that fits in `i64`; otherwise returns
    /// `None` (producer is dynamic, non-integer, or out of i64 range).
    ///
    /// Cost: linear scan over the function body. Acceptable because Alloca
    /// counts are rare (one per aggregate construction) and `count` is always
    /// defined immediately before.
    fn lookup_const_int(&self, vid: ValueId) -> Option<i64> {
        let mut seen = HashSet::new();
        let value = self.lookup_const_int_inner(vid, &mut seen)?;
        i64::try_from(value).ok()
    }

    fn lookup_const_bool(&self, vid: ValueId) -> Option<bool> {
        let mut seen = HashSet::new();
        self.lookup_const_bool_inner(vid, &mut seen)
    }

    fn lookup_const_bool_inner(&self, vid: ValueId, seen: &mut HashSet<ValueId>) -> Option<bool> {
        if !seen.insert(vid) {
            return None;
        }
        let node = self.find_value_producer(vid)?;
        let value = match &node.inst {
            Inst::Const {
                value: Constant::Bool(value),
                ..
            } => Some(*value),
            Inst::Const {
                ty: Ty::Bool,
                value: Constant::Int(0),
            } => Some(false),
            Inst::Const {
                ty: Ty::Bool,
                value: Constant::Int(1),
            } => Some(true),
            Inst::Copy { operand, .. } => self.lookup_const_bool_inner(*operand, seen),
            _ => None,
        };
        seen.remove(&vid);
        value
    }

    /// Compute the byte size for a statically known alloca count, rejecting
    /// negative counts, overflow, and runaway frame sizes.
    fn checked_static_alloca_size(&self, element_size: u32, n: i64) -> Result<u32, AdapterError> {
        if n < 0 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Alloca with negative count {}",
                n
            )));
        }
        // Hard cap at 1 MiB per static allocation. Anything larger should go
        // through heap allocation; catching it here prevents runaway stack
        // frame sizes from a mis-lowered trust_ir program.
        const MAX_ALLOCA_BYTES: u128 = 1 << 20;
        let total = (element_size as u128)
            .checked_mul(n as u128)
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "Alloca size overflow: {} * {}",
                    element_size, n
                ))
            })?;
        if total > MAX_ALLOCA_BYTES {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Alloca size {} exceeds {}-byte static limit",
                total, MAX_ALLOCA_BYTES
            )));
        }
        Ok(total as u32)
    }

    /// Find the defining instruction for a trust_ir `ValueId`.
    fn find_value_producer(&self, vid: ValueId) -> Option<&'a InstrNode> {
        self.value_producers.get(&vid).copied()
    }

    /// Recursively fold a small integer-expression DAG rooted at `vid`.
    ///
    /// This stays intentionally narrow: constants, copies, simple integer
    /// binops, and integer casts. That covers the non-direct-const count
    /// shapes ty emits around bounded aggregate temporaries without trying to
    /// become a general trust_ir evaluator inside the adapter.
    fn lookup_const_int_inner(&self, vid: ValueId, seen: &mut HashSet<ValueId>) -> Option<i128> {
        if !seen.insert(vid) {
            return None;
        }
        let node = self.find_value_producer(vid)?;
        let value = match &node.inst {
            Inst::Const {
                value: Constant::Int(v),
                ..
            } => Some(*v),
            Inst::Copy { operand, .. } => self.lookup_const_int_inner(*operand, seen),
            Inst::BinOp { op, lhs, rhs, .. } => {
                let lhs_val = self.lookup_const_int_inner(*lhs, seen)?;
                let rhs_val = self.lookup_const_int_inner(*rhs, seen)?;
                match op {
                    BinOp::Add => lhs_val.checked_add(rhs_val),
                    BinOp::Sub => lhs_val.checked_sub(rhs_val),
                    BinOp::Mul => lhs_val.checked_mul(rhs_val),
                    BinOp::UDiv | BinOp::SDiv => {
                        if rhs_val == 0 {
                            None
                        } else {
                            lhs_val.checked_div(rhs_val)
                        }
                    }
                    BinOp::URem | BinOp::SRem => {
                        if rhs_val == 0 {
                            None
                        } else {
                            lhs_val.checked_rem(rhs_val)
                        }
                    }
                    BinOp::And => Some(lhs_val & rhs_val),
                    BinOp::Or => Some(lhs_val | rhs_val),
                    BinOp::Xor => Some(lhs_val ^ rhs_val),
                    BinOp::Shl => {
                        let shift = u32::try_from(rhs_val).ok()?;
                        lhs_val.checked_shl(shift)
                    }
                    BinOp::LShr => {
                        let shift = u32::try_from(rhs_val).ok()?;
                        Some(((lhs_val as u128).checked_shr(shift)?) as i128)
                    }
                    BinOp::AShr => {
                        let shift = u32::try_from(rhs_val).ok()?;
                        lhs_val.checked_shr(shift)
                    }
                    _ => None,
                }
            }
            Inst::Cast {
                op,
                src_ty,
                dst_ty,
                operand,
            } => {
                let src_val = self.lookup_const_int_inner(*operand, seen)?;
                self.fold_integer_cast(*op, src_ty, dst_ty, src_val)
            }
            _ => None,
        };
        seen.remove(&vid);
        value
    }

    /// Fold an integer cast on a statically known value.
    fn fold_integer_cast(&self, op: CastOp, src_ty: &Ty, dst_ty: &Ty, value: i128) -> Option<i128> {
        let src_bits = Self::int_ty_bits(src_ty)?;
        let dst_bits = Self::int_ty_bits(dst_ty)?;
        match op {
            CastOp::Trunc => Some(Self::truncate_to_bits(value, dst_bits)),
            CastOp::ZExt => Some(Self::zero_extend_bits(value, src_bits)),
            CastOp::SExt => Some(Self::sign_extend_bits(value, src_bits)),
            CastOp::Bitcast | CastOp::PtrToInt | CastOp::IntToPtr => {
                if src_bits == dst_bits {
                    Some(Self::truncate_to_bits(value, dst_bits))
                } else {
                    None
                }
            }
            _ => None,
        }
    }

    /// Infer a bounded static alloca size from the actual access pattern when
    /// the count expression itself is not directly foldable.
    ///
    /// This is a conservative escape hatch for ty aggregate temporaries:
    /// if every use stays inside a statically-known byte footprint, we can
    /// allocate that footprint as an ordinary fixed stack slot without adding
    /// a full runtime-sized frame path. In addition to in-function loads and
    /// stores, this follows direct same-module calls when the pointer argument
    /// remains bounded in the callee as well.
    fn infer_bounded_alloca_size_from_uses(&self, alloca_result: ValueId) -> Option<u32> {
        let mut seen_direct_call_args = HashSet::new();
        let max_end_bytes =
            self.infer_bounded_pointer_max_end_bytes(alloca_result, &mut seen_direct_call_args)?;
        if max_end_bytes <= 0 {
            return None;
        }

        u32::try_from(max_end_bytes).ok()
    }

    /// Compute the maximum end offset reached by all bounded uses of a root
    /// pointer inside the current function. `Some(0)` means the pointer never
    /// escaped or touched memory; `None` means a use escaped the bounded subset.
    fn infer_bounded_pointer_max_end_bytes(
        &self,
        root_ptr: ValueId,
        seen_direct_call_args: &mut HashSet<(FuncId, usize)>,
    ) -> Option<i128> {
        let func = self.trust_ir_func?;
        let mut max_end_bytes: i128 = 0;

        for block in &func.blocks {
            for node in &block.body {
                match &node.inst {
                    Inst::Load { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                    }
                    Inst::Store { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            return None;
                        }
                    }
                    Inst::AtomicLoad { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                    }
                    Inst::AtomicStore { ty, ptr, value, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                        if self.value_definitely_derived_from_alloca(
                            *value,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            return None;
                        }
                    }
                    Inst::AtomicRMW { ty, ptr, .. } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                    }
                    Inst::CmpXchg {
                        ty,
                        ptr,
                        expected,
                        desired,
                        ..
                    } => {
                        if self.value_definitely_derived_from_alloca(
                            *ptr,
                            root_ptr,
                            &mut HashSet::new(),
                        ) {
                            let end = self.alloca_access_end_bytes(root_ptr, *ptr, ty)?;
                            max_end_bytes = max_end_bytes.max(end);
                        }
                        if self.any_value_derived_from_alloca([*expected, *desired], root_ptr) {
                            return None;
                        }
                    }
                    Inst::Call { callee, args } => {
                        for (arg_index, arg) in args.iter().enumerate() {
                            if !self.value_definitely_derived_from_alloca(
                                *arg,
                                root_ptr,
                                &mut HashSet::new(),
                            ) {
                                continue;
                            }
                            let arg_offset = self.pointer_offset_from_alloca_bytes(
                                *arg,
                                root_ptr,
                                &mut HashSet::new(),
                            )?;
                            let callee_end = self.infer_direct_callee_pointer_max_end_bytes(
                                *callee,
                                arg_index,
                                seen_direct_call_args,
                            )?;
                            let total_end = arg_offset.checked_add(callee_end)?;
                            max_end_bytes = max_end_bytes.max(total_end);
                        }
                    }
                    Inst::CallIndirect { callee, args, .. }
                        if self.value_definitely_derived_from_alloca(
                            *callee,
                            root_ptr,
                            &mut HashSet::new(),
                        ) || args.iter().any(|arg| {
                            self.value_definitely_derived_from_alloca(
                                *arg,
                                root_ptr,
                                &mut HashSet::new(),
                            )
                        }) =>
                    {
                        return None;
                    }
                    Inst::Return { values }
                        if values.iter().any(|value| {
                            self.value_definitely_derived_from_alloca(
                                *value,
                                root_ptr,
                                &mut HashSet::new(),
                            )
                        }) =>
                    {
                        return None;
                    }
                    _ => {}
                }
            }
        }

        Some(max_end_bytes)
    }

    /// Follow a direct same-module call and compute the bounded footprint of
    /// the callee parameter that receives the pointer argument.
    fn infer_direct_callee_pointer_max_end_bytes(
        &self,
        callee: FuncId,
        arg_index: usize,
        seen_direct_call_args: &mut HashSet<(FuncId, usize)>,
    ) -> Option<i128> {
        let module = self.module?;
        let callee_func = module.functions.iter().find(|func| func.id == callee)?;
        let entry_block = callee_func
            .blocks
            .iter()
            .find(|block| block.id == callee_func.entry)
            .or_else(|| callee_func.blocks.first())?;
        let param_vid = entry_block.params.get(arg_index)?.0;
        let key = (callee, arg_index);
        if !seen_direct_call_args.insert(key) {
            return None;
        }

        let mut nested =
            TrustIrAdapter::new_with_types(self.structs, self.types, self.func_names.clone());
        nested.module = self.module;
        nested.enums = self.enums;
        nested.trust_ir_func = Some(callee_func);
        let max_end = nested.infer_bounded_pointer_max_end_bytes(param_vid, seen_direct_call_args);
        seen_direct_call_args.remove(&key);
        max_end
    }

    /// Compute the end byte offset for a load/store-like access through a
    /// pointer derived from `alloca_result`.
    fn alloca_access_end_bytes(
        &self,
        alloca_result: ValueId,
        ptr: ValueId,
        ty: &Ty,
    ) -> Option<i128> {
        let offset =
            self.pointer_offset_from_alloca_bytes(ptr, alloca_result, &mut HashSet::new())?;
        if offset < 0 {
            return None;
        }
        let access_bytes = i128::from(self.translate_ty(ty).ok()?.bytes());
        offset.checked_add(access_bytes)
    }

    /// Resolve `ptr_vid` to a constant byte offset from `alloca_result`.
    fn pointer_offset_from_alloca_bytes(
        &self,
        ptr_vid: ValueId,
        alloca_result: ValueId,
        seen: &mut HashSet<ValueId>,
    ) -> Option<i128> {
        if ptr_vid == alloca_result {
            return Some(0);
        }
        if !seen.insert(ptr_vid) {
            return None;
        }

        let node = self.find_value_producer(ptr_vid)?;
        let offset = match &node.inst {
            Inst::Copy { operand, .. } => {
                self.pointer_offset_from_alloca_bytes(*operand, alloca_result, seen)
            }
            Inst::GEP {
                pointee_ty,
                base,
                indices,
                // Optimization hint only; offset-from-alloca analysis uses the
                // same conservative `base + index * elem_bytes` arithmetic
                // irrespective of `inbounds`. See the lowering site above.
                inbounds: _,
            } => match indices.as_slice() {
                [] => self.pointer_offset_from_alloca_bytes(*base, alloca_result, seen),
                [index] => {
                    let base_offset =
                        self.pointer_offset_from_alloca_bytes(*base, alloca_result, seen)?;
                    let idx = self.lookup_const_int(*index)?;
                    if idx < 0 {
                        None
                    } else {
                        let elem_bytes = i128::from(self.translate_ty(pointee_ty).ok()?.bytes());
                        base_offset.checked_add(i128::from(idx).checked_mul(elem_bytes)?)
                    }
                }
                _ => None,
            },
            _ => None,
        };

        seen.remove(&ptr_vid);
        offset
    }

    /// Integer bit width for the trust_ir scalar integer/pointer types used in
    /// count expressions.
    fn int_ty_bits(ty: &Ty) -> Option<u32> {
        match ty {
            Ty::Bool => Some(1),
            Ty::I8 | Ty::U8 => Some(8),
            Ty::I16 | Ty::U16 => Some(16),
            Ty::I32 | Ty::U32 => Some(32),
            Ty::I64 | Ty::U64 | Ty::Ptr => Some(64),
            Ty::I128 | Ty::U128 => Some(128),
            Ty::Isize | Ty::Usize => Some(64),
            Ty::Char => Some(32),
            Ty::Ref(_)
            | Ty::RefMut(_)
            | Ty::PtrConst(_)
            | Ty::PtrMut(_)
            | Ty::Rc(_)
            | Ty::Func(_) => Some(64),
            _ => None,
        }
    }

    fn truncate_to_bits(value: i128, bits: u32) -> i128 {
        if bits >= 128 {
            value
        } else if bits == 0 {
            0
        } else {
            let mask = (1u128 << bits) - 1;
            ((value as u128) & mask) as i128
        }
    }

    fn zero_extend_bits(value: i128, bits: u32) -> i128 {
        Self::truncate_to_bits(value, bits)
    }

    fn sign_extend_bits(value: i128, bits: u32) -> i128 {
        if bits >= 128 {
            value
        } else if bits == 0 {
            0
        } else {
            let truncated = Self::truncate_to_bits(value, bits) as u128;
            let sign_bit = 1u128 << (bits - 1);
            if truncated & sign_bit == 0 {
                truncated as i128
            } else {
                (truncated | !((1u128 << bits) - 1)) as i128
            }
        }
    }

    // -----------------------------------------------------------------------
    // Overflow-checked arithmetic (Inst::Overflow)
    // -----------------------------------------------------------------------

    /// Build the SIGNED i128 checked-multiply expansion:
    /// `result = a * b` (low 128 bits) and
    /// `flag = (b != 0 && result /s guarded_b != a) || (a == MIN && b == -1)`,
    /// where `guarded_b = (b == 0 || (a == MIN && b == -1)) ? 1 : b` avoids the
    /// __divti3 divide-by-zero AND MIN/-1 division-overflow UB. See
    /// translate_overflow for the correctness argument; every op is a proven
    /// primitive (Imul, i128 Iconst128/Icmp/Select/Sdiv, bool Band/Bor).
    fn build_i128_signed_mul_overflow(
        &mut self,
        a: Value,
        b: Value,
        result: Value,
        flag: Value,
    ) -> Vec<Instruction> {
        let mut instrs = Vec::new();
        let fresh_i128 = |this: &mut Self| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I128);
            v
        };
        let fresh_b1 = |this: &mut Self| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::B1);
            v
        };
        let icmp = |instrs: &mut Vec<Instruction>, cond, x, y, dst| {
            instrs.push(Instruction {
                opcode: Opcode::Icmp { cond },
                args: vec![x, y],
                results: vec![dst],
            });
        };
        let iconst128 = |instrs: &mut Vec<Instruction>, lo, hi, dst| {
            instrs.push(Instruction {
                opcode: Opcode::Iconst128 { lo, hi },
                args: vec![],
                results: vec![dst],
            });
        };
        let bool_op = |instrs: &mut Vec<Instruction>, opcode, x, y, dst| {
            instrs.push(Instruction {
                opcode,
                args: vec![x, y],
                results: vec![dst],
            });
        };

        // result = a *s b  (low 128 bits)
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![a, b],
            results: vec![result],
        });
        let zero = fresh_i128(self);
        iconst128(&mut instrs, 0, 0, zero);
        let one = fresh_i128(self);
        iconst128(&mut instrs, 1, 0, one);
        let min = fresh_i128(self);
        iconst128(&mut instrs, 0, i64::MIN, min); // i128::MIN = 0x8000..._0000...
        let neg1 = fresh_i128(self);
        iconst128(&mut instrs, -1, -1, neg1); // i128 -1

        let b_is_zero = fresh_b1(self);
        icmp(&mut instrs, IntCC::Equal, b, zero, b_is_zero);
        let a_is_min = fresh_b1(self);
        icmp(&mut instrs, IntCC::Equal, a, min, a_is_min);
        let b_is_neg1 = fresh_b1(self);
        icmp(&mut instrs, IntCC::Equal, b, neg1, b_is_neg1);
        // min_neg1 = (a == MIN) && (b == -1)  -- the division-overflow / smulo case
        let min_neg1 = fresh_b1(self);
        bool_op(&mut instrs, Opcode::Band, a_is_min, b_is_neg1, min_neg1);
        // avoid_div = (b == 0) || min_neg1
        let avoid_div = fresh_b1(self);
        bool_op(&mut instrs, Opcode::Bor, b_is_zero, min_neg1, avoid_div);
        // safe_b = avoid_div ? 1 : b
        let safe_b = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![avoid_div, one, b],
            results: vec![safe_b],
        });
        // q = result /s safe_b
        let q = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Sdiv,
            args: vec![result, safe_b],
            results: vec![q],
        });
        // div_ovf = (b != 0) && (q != a)
        let b_nz = fresh_b1(self);
        icmp(&mut instrs, IntCC::NotEqual, b, zero, b_nz);
        let q_ne_a = fresh_b1(self);
        icmp(&mut instrs, IntCC::NotEqual, q, a, q_ne_a);
        let div_ovf = fresh_b1(self);
        bool_op(&mut instrs, Opcode::Band, b_nz, q_ne_a, div_ovf);
        // flag = div_ovf || min_neg1
        bool_op(&mut instrs, Opcode::Bor, div_ovf, min_neg1, flag);
        instrs
    }

    /// Build the unsigned u128 checked-multiply expansion: `result = a * b`
    /// (low 128 bits) and `flag = (a != 0) && (result / max(a, 1) != b)`. See
    /// translate_overflow for the correctness argument; every op (Imul, i128
    /// Iconst128/Icmp/Select/Udiv, bool Band) is an already-proven primitive.
    fn build_u128_mul_overflow(
        &mut self,
        a: Value,
        b: Value,
        result: Value,
        flag: Value,
    ) -> Vec<Instruction> {
        let mut instrs = Vec::new();
        let fresh_i128 = |this: &mut Self| {
            let v = this.fresh_value();
            this.define_value_type(v, Type::I128);
            v
        };
        // result = a *u b  (low 128 bits)
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![a, b],
            results: vec![result],
        });
        let zero = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Iconst128 { lo: 0, hi: 0 },
            args: vec![],
            results: vec![zero],
        });
        let one = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Iconst128 { lo: 1, hi: 0 },
            args: vec![],
            results: vec![one],
        });
        // a_is_zero = (a == 0)
        let a_is_zero = self.fresh_value();
        self.define_value_type(a_is_zero, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp { cond: IntCC::Equal },
            args: vec![a, zero],
            results: vec![a_is_zero],
        });
        // safe_a = (a == 0) ? 1 : a   (avoid __udivti3 divide-by-zero UB)
        let safe_a = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Select {
                cond: IntCC::NotEqual,
            },
            args: vec![a_is_zero, one, a],
            results: vec![safe_a],
        });
        // q = result /u safe_a
        let q = fresh_i128(self);
        instrs.push(Instruction {
            opcode: Opcode::Udiv,
            args: vec![result, safe_a],
            results: vec![q],
        });
        // a_nz = (a != 0)
        let a_nz = self.fresh_value();
        self.define_value_type(a_nz, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp {
                cond: IntCC::NotEqual,
            },
            args: vec![a, zero],
            results: vec![a_nz],
        });
        // q_ne_b = (q != b)
        let q_ne_b = self.fresh_value();
        self.define_value_type(q_ne_b, Type::B1);
        instrs.push(Instruction {
            opcode: Opcode::Icmp {
                cond: IntCC::NotEqual,
            },
            args: vec![q, b],
            results: vec![q_ne_b],
        });
        // flag = a_nz && q_ne_b
        instrs.push(Instruction {
            opcode: Opcode::Band,
            args: vec![a_nz, q_ne_b],
            results: vec![flag],
        });
        instrs
    }

    /// Translate `Inst::Overflow { op, ty, lhs, rhs }` to a value +
    /// overflow-flag pair. The previous implementation hardcoded the flag to
    /// `Iconst B1 imm=0`, silently dropping every TLA+ runtime overflow check
    /// (issue #339). We now emit the actual overflow condition for signed
    /// integer arithmetic.
    ///
    /// Supported widths: I8, I16, I32, I64. I128 is not yet supported.
    ///
    /// Semantics (produce true iff overflow occurred):
    /// - Add: `overflow = (~(lhs ^ rhs) & (lhs ^ sum)) < 0`  (sign bit set)
    /// - Sub: `overflow = ((lhs ^ rhs) & (lhs ^ diff)) < 0`
    /// - Mul (narrow <=32-bit): sign-extend both operands to the next-wider
    ///   type, multiply there, and check that the wide product equals the
    ///   sign-extension of the narrow product.
    /// - Mul (I64): use the SDIV identity
    ///   `overflow = (rhs != 0 AND result / rhs != lhs) OR
    ///              (lhs == I64::MIN AND rhs == -1)`.
    ///   Relies on AArch64 SDIV-by-zero returning 0 (LIR matches this), so
    ///   the `rhs != 0` guard is sufficient; AArch64 `I64::MIN / -1` returns
    ///   `I64::MIN` (no trap), hence the special case. Reference: ARMv8
    ///   SDIV instruction definition and LLVM CodeGen i64 smulo expansion.
    fn translate_overflow(
        &mut self,
        op: &OverflowOp,
        ty: &Ty,
        lhs: ValueId,
        rhs: ValueId,
        results: &[ValueId],
        node: &InstrNode,
    ) -> Result<Vec<Instruction>, AdapterError> {
        if !Self::is_integer_scalar_ty(ty) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Overflow requires a TrustIr arithmetic integer type, got {ty:?}"
            )));
        }
        let lir_ty = self.translate_ty(ty)?;
        // i128/u128 checked MUL needs the full 256-bit product (no register-pair
        // mul-high idiom is wired yet), so it stays fail-closed. Checked ADD/SUB,
        // however, decompose into the width-generic bit-pattern fallback below
        // over already-proven i128 primitives — Iadd/Isub (ADDS+ADC register
        // pair), i128 Icmp, and i128 Bxor/Bnot/Band (register-pair logic) — none
        // of which need a wider type, so they lower and prove exactly like the
        // I8/I16/I32 fallback at width 128.
        if !matches!(
            lir_ty,
            Type::I8 | Type::I16 | Type::I32 | Type::I64 | Type::I128
        ) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Overflow on non-integer type {:?}",
                ty
            )));
        }

        let lhs_val = self.map_value(lhs);
        let rhs_val = self.map_value(rhs);
        let result = self.map_result(results)?;
        let flag_vid = results.get(1).copied().ok_or(AdapterError::MissingResult)?;
        let flag = self.map_value(flag_vid);

        // usize and Char are unsigned (pointer-width / 32-bit Unicode-scalar
        // carriers); isize is signed. Getting this wrong flips the overflow
        // condition for the very common `usize` checked-add idiom.
        let is_unsigned = matches!(
            ty,
            Ty::U8 | Ty::U16 | Ty::U32 | Ty::U64 | Ty::U128 | Ty::Usize | Ty::Char
        );

        // i128/u128 checked MUL via a division check on the LOW 128-bit product
        // (no 256-bit product needed). UNSIGNED: overflow iff `a != 0 && p/a != b`
        // (with no overflow `p = a*b` so `p/a == b`; with overflow `p = a*b -
        // k*2^128`, k>=1, and `a < 2^128` forces `floor(p/a) <= b-1 < b`). SIGNED:
        // overflow iff `(b != 0 && p /s b != a) || (a == MIN && b == -1)` (same
        // magnitude argument — `|k*2^128/b| >= 1` forces `p/s b != a` — plus the
        // one division-overflow case). Both divide by a guarded operand to avoid
        // the __udivti3/__divti3 divide-by-zero (and MIN/-1 division-overflow) UB.
        if lir_ty == Type::I128 && matches!(op, OverflowOp::MulOverflow) {
            return Ok(if is_unsigned {
                self.build_u128_mul_overflow(lhs_val, rhs_val, result, flag)
            } else {
                self.build_i128_signed_mul_overflow(lhs_val, rhs_val, result, flag)
            });
        }

        // ---------------------------------------------------------------------
        // Overflow-elimination production fast-exit (#29).
        //
        // Real Trust programs express checked add/sub via this `Inst::Overflow`
        // idiom. The legacy lowering below ALWAYS materializes a runtime overflow
        // CHECK (CheckedSadd/CSET for I64, bit-pattern for I8/16/32) entangled
        // with the value, so overflow elimination can never fire even when the
        // node carries a DISCHARGED no-overflow proof. When (and ONLY when) such
        // a proof is present, route the check through the self-contained
        // `GuardOverflow` carrier the kernel gate can eliminate, while keeping
        // the (value, did_overflow) contract: the value is a plain wrapping
        // Iadd/Isub and the flag is provably-false (the proof guarantees no
        // overflow, so the observable overflow boolean is definitively `false`).
        //
        // FAIL-SAFE / DEFAULT-TO-KEEP: this is a STRICT extension. The branch is
        // taken ONLY when EVERY one of these holds; on ANY failure we fall
        // through to the unchanged legacy lowering, which always traps/flags on a
        // genuine overflow (safe):
        //   (a) target == AArch64 — the ONLY arch with an overflow carrier
        //       (TrapOverflowExact). x86/RISC-V have none, so they MUST keep the
        //       legacy path (a GuardOverflow there would be unrepresentable).
        //   (b) op has a carrier op-tag: Add/Sub at width 32|64, or Mul at width
        //       64 ONLY (task #30; SMULH/UMULH are 64-bit-result-only, so I32 mul
        //       stays on the legacy wide-multiply bit-pattern path).
        //   (c) width is 32 or 64 — the only widths `pack_overflow_tag` accepts.
        //       I8/I16 have no carrier op-tag and stay on the legacy bit-pattern
        //       path. (lir_ty is already restricted to I8/I16/I32/I64 above.)
        //   (d) the node carries a genuine, signedness-MATCHING discharged
        //       no-overflow annotation (`NoOverflow` for signed, `NoWrap` for
        //       unsigned). `Wrapping` is NEVER treated as no-overflow.
        let carrier_width: Option<u16> = match lir_ty {
            Type::I32 => Some(32),
            Type::I64 => Some(64),
            _ => None,
        };
        let carrier_op = match (is_unsigned, op) {
            (false, OverflowOp::AddOverflow) => Some(trust_cg_ir::OverflowOp::SignedAdd),
            (false, OverflowOp::SubOverflow) => Some(trust_cg_ir::OverflowOp::SignedSub),
            (true, OverflowOp::AddOverflow) => Some(trust_cg_ir::OverflowOp::UnsignedAdd),
            (true, OverflowOp::SubOverflow) => Some(trust_cg_ir::OverflowOp::UnsignedSub),
            // Mul has a carrier (task #30) but ONLY at width 64: the KEPT expansion uses the
            // SMULH/UMULH mul-high idiom, and SMULH/UMULH are 64-bit-result-only (no 32-bit
            // variant). I32 (and narrower) mul therefore has NO correct SMULH-based expansion and
            // MUST stay on the legacy division-free wide-multiply bit-pattern path. Gating mul to
            // I64 here keeps `carrier_width`'s I32 => Some(32) from ever packing a width-32 mul tag.
            (false, OverflowOp::MulOverflow) if lir_ty == Type::I64 => {
                Some(trust_cg_ir::OverflowOp::SignedMul)
            }
            (true, OverflowOp::MulOverflow) if lir_ty == Type::I64 => {
                Some(trust_cg_ir::OverflowOp::UnsignedMul)
            }
            // Mul at any non-I64 width — keep legacy (no 32-bit SMULH/UMULH).
            (_, OverflowOp::MulOverflow) => None,
        };
        // The observable overflow flag (result[1]) is DEAD iff nothing in the
        // function consumes it. The carrier path folds the flag to constant-false
        // (sound under the discharged proof), but we ONLY take it when the flag is
        // dead so that any node whose overflow boolean is genuinely consumed keeps
        // the legacy entangled ADDS/SUBS+CSET lowering byte-for-byte (DEFAULT TO
        // KEEP). If the function context is unavailable (defensive), treat the flag
        // as live and keep legacy.
        let flag_is_dead = self
            .trust_ir_func
            .is_some_and(|f| !value_is_used_in_func(f, flag_vid));
        if flag_is_dead
            && self.guard_carrier_arch == GuardCarrierArch::AArch64
            && let (Some(width), Some(carrier_op)) = (carrier_width, carrier_op)
            && overflow_has_no_overflow_proof(node, is_unsigned)
            // Replacing an observable checked-overflow operation with a wrapping value plus a
            // proof-driven carrier is behavior-changing when the annotation is forged.  Keep the
            // legacy lowering until an exact validator replay capability is wired end to end.
            && (crate::guard_evidence::validator_guard_replay_authority_available() || cfg!(test))
        {
            let op_tag = trust_cg_ir::pack_overflow_tag(carrier_op, width);
            // Copy an explicit ProofRef only.  A NoOverflow/NoWrap label never synthesizes a
            // discharged obligation.
            //
            // Attach a QF_BV `ProofFormula` to the obligation. HONEST STATUS (downgraded
            // 2026-06-18): this is a REFLEXIVITY TAUTOLOGY `(not (= (bvop a b) (bvop a b)))`,
            // NOT a lowering-correctness identity — it is built from the IR op-tag only and
            // never references the machine instructions, so it cannot catch a lowering error
            // (see `overflow_carrier_reflexivity_formula`). The clean C1 path re-derives it to
            // `trust_count == 0`, but that count certifies a tautology and is VACUOUS as a
            // statement about lowering correctness. The `clean_cic_lineage_digest` derived from
            // it discriminates the (op,width) LABEL only, and no consumer gates on it.
            let was_synthesized_before = self.proof_ctx.synthesized_discharged.len();
            let obligation = self.overflow_no_overflow_obligation(node);
            if let Some(obligation_id) = obligation {
                // Record the formula only for ids the adapter SYNTHESIZED here (an upstream
                // ProofRef already owns a module obligation, with its own formula slot).
                let just_synthesized = self.proof_ctx.synthesized_discharged.len()
                    > was_synthesized_before
                    && self.proof_ctx.synthesized_discharged.last().copied() == Some(obligation_id);
                if just_synthesized {
                    let formula =
                        ProofContext::overflow_carrier_reflexivity_formula(carrier_op, width);
                    self.proof_ctx
                        .record_synthesized_obligation_formula(obligation_id, formula);
                }
            }

            // Seed the OPERAND value-proofs that the codegen proof-annotation binder
            // (`apply_guard_proof_annotations`) consumes: it stamps
            // `NoSignedOverflow`/`NoUnsignedOverflow` onto the `TrapOverflowExact` carrier ONLY when a
            // carrier-binding no-overflow proof is keyed to the carrier's lhs OR rhs vreg AND the
            // op-tag signedness matches. The trust-ir `NoOverflow`/`NoWrap` annotation lands on
            // result[0] (the sum), not the operands, so without this the binder never matches THIS
            // carrier and the kernel gate keeps it.
            //
            // NO OVER-ELIMINATION: we seed `Proof::CarrierNoOverflow` (NOT `Proof::NoOverflow`). The
            // carrier-only variant is EXCLUDED from the general value-proof loop
            // (`select_proof_annotation`), so it can NEVER be stamped onto an operand's *defining*
            // instruction — in particular it can never reach the legacy `apply_no_overflow`
            // ADDS/SUBS→ADD/SUB syntactic eliminator and delete an UNRELATED operation's overflow
            // check (e.g. the inner panic-add of `(a + b).overflowing_add(c)`). A genuine on-op
            // `Proof::NoOverflow` (keyed to the arithmetic op's own result) stays eligible for that
            // loop, so legacy overflow elimination is preserved exactly.
            //
            // SOUNDNESS: the seeded proof's `signed` flag is the SAME signedness folded into `op_tag`
            // (signed for a signed op, unsigned for an unsigned op), so a signed proof can never bind
            // an unsigned carrier and vice versa; and it is only seeded inside this branch, i.e. ONLY
            // when a genuine signedness-matching discharged no-overflow annotation is present on the
            // node. The carrier's AUTHORIZATION to be deleted is bound SEPARATELY by the op's
            // `obligation` field via ISel `guard_obligations` + the kernel gate; this seed only drives
            // candidate SELECTION (annotating the carrier), never authorization.
            let proof_signed = !is_unsigned;
            for operand in [lhs_val, rhs_val] {
                self.proof_ctx
                    .value_proofs
                    .entry(operand)
                    .or_default()
                    .push(Proof::CarrierNoOverflow {
                        signed: proof_signed,
                    });
            }

            let value_opcode = match op {
                OverflowOp::AddOverflow => Opcode::Iadd,
                OverflowOp::SubOverflow => Opcode::Isub,
                // Mul carrier (task #30): the value is a plain wrapping Imul (low 64 bits), the
                // same low product the MUL in the carrier's KEPT mul-high expansion computes. Only
                // reachable when carrier_op admitted a width-64 mul above.
                OverflowOp::MulOverflow => Opcode::Imul,
            };

            return Ok(vec![
                // 1. Plain wrapping value op into result[0] — NEVER touched by
                //    carrier elimination; identical wrap semantics to the legacy
                //    arithmetic op.
                Instruction {
                    opcode: value_opcode,
                    args: vec![lhs_val, rhs_val],
                    results: vec![result],
                },
                // 2. The OVERFLOW check, decoupled into a self-contained carrier
                //    (no results). The kernel gate eliminates it iff the bound
                //    obligation is discharged; otherwise it expands to a trapping
                //    ADDS/SUBS+B.VC/B.VS+BRK that re-derives the overflow.
                Instruction {
                    opcode: Opcode::GuardOverflow { op_tag, obligation },
                    args: vec![lhs_val, rhs_val],
                    results: vec![],
                },
                // 3. The observable overflow flag (result[1], Ty::Bool -> B1).
                //    Under a DISCHARGED no-overflow proof the op provably never
                //    overflows, so the flag is definitively `false`. Binding it to
                //    a constant `0` preserves the (value, did_overflow=false)
                //    contract for any downstream flag consumer.
                Instruction {
                    opcode: Opcode::Iconst {
                        ty: Type::B1,
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![flag],
                },
            ]);
        }

        // Fast path (#474): I64/U64 overflow maps directly to a single
        // Checked{S,U}{add,sub,mul} LIR op that ISel lowers to the canonical
        // AArch64 idiom:
        //   sadd -> ADDS + CSET VS
        //   ssub -> SUBS + CSET VS
        //   smul -> MUL + SMULH + ASR + CMP + CSET NE
        //   uadd -> ADDS + CSET HS
        //   usub -> SUBS + CSET LO
        //   umul -> MUL + UMULH + CMP #0 + CSET NE
        // The bit-pattern fallback below is retained for I8/I16/I32 (which
        // the existing ISel patterns do not yet recognise for the native
        // flag idiom).
        if lir_ty == Type::I64 {
            let checked_opcode = match (is_unsigned, *op) {
                (false, OverflowOp::AddOverflow) => Opcode::CheckedSadd,
                (false, OverflowOp::SubOverflow) => Opcode::CheckedSsub,
                (false, OverflowOp::MulOverflow) => Opcode::CheckedSmul,
                (true, OverflowOp::AddOverflow) => Opcode::CheckedUadd,
                (true, OverflowOp::SubOverflow) => Opcode::CheckedUsub,
                (true, OverflowOp::MulOverflow) => Opcode::CheckedUmul,
            };
            return Ok(vec![Instruction {
                opcode: checked_opcode,
                args: vec![lhs_val, rhs_val],
                results: vec![result, flag],
            }]);
        }

        let mut instrs = Vec::new();
        let arith_opcode = match op {
            OverflowOp::AddOverflow => Opcode::Iadd,
            OverflowOp::SubOverflow => Opcode::Isub,
            OverflowOp::MulOverflow => Opcode::Imul,
        };

        // 1. Emit the value result (wrapping arithmetic).
        instrs.push(Instruction {
            opcode: arith_opcode,
            args: vec![lhs_val, rhs_val],
            results: vec![result],
        });

        if is_unsigned {
            match op {
                OverflowOp::AddOverflow => {
                    // Unsigned add overflows iff the wrapped result is below
                    // either operand. Compare against lhs.
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp {
                            cond: IntCC::UnsignedLessThan,
                        },
                        args: vec![result, lhs_val],
                        results: vec![flag],
                    });
                }
                OverflowOp::SubOverflow => {
                    // Unsigned sub overflows iff it borrows, i.e. lhs < rhs.
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp {
                            cond: IntCC::UnsignedLessThan,
                        },
                        args: vec![lhs_val, rhs_val],
                        results: vec![flag],
                    });
                }
                OverflowOp::MulOverflow => {
                    let wide_ty = match &lir_ty {
                        Type::I8 => Type::I16,
                        Type::I16 => Type::I32,
                        Type::I32 => Type::I64,
                        _ => unreachable!("unsigned overflow fallback is only used below U64"),
                    };

                    let lhs_wide = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Uextend {
                            from_ty: lir_ty.clone(),
                            to_ty: wide_ty.clone(),
                        },
                        args: vec![lhs_val],
                        results: vec![lhs_wide],
                    });
                    let rhs_wide = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Uextend {
                            from_ty: lir_ty.clone(),
                            to_ty: wide_ty.clone(),
                        },
                        args: vec![rhs_val],
                        results: vec![rhs_wide],
                    });
                    let product_wide = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Imul,
                        args: vec![lhs_wide, rhs_wide],
                        results: vec![product_wide],
                    });
                    let product_trunc = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Trunc {
                            to_ty: lir_ty.clone(),
                        },
                        args: vec![product_wide],
                        results: vec![product_trunc],
                    });
                    let product_roundtrip = self.fresh_value();
                    instrs.push(Instruction {
                        opcode: Opcode::Uextend {
                            from_ty: lir_ty.clone(),
                            to_ty: wide_ty,
                        },
                        args: vec![product_trunc],
                        results: vec![product_roundtrip],
                    });
                    instrs.push(Instruction {
                        opcode: Opcode::Icmp {
                            cond: IntCC::NotEqual,
                        },
                        args: vec![product_wide, product_roundtrip],
                        results: vec![flag],
                    });
                }
            }

            return Ok(instrs);
        }

        // 2. Emit the overflow flag using op-specific bit-pattern checks.
        match op {
            OverflowOp::AddOverflow => {
                // tmp1 = lhs XOR rhs
                let tmp1 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, rhs_val],
                    results: vec![tmp1],
                });
                // tmp2 = NOT tmp1
                let tmp2 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bnot,
                    args: vec![tmp1],
                    results: vec![tmp2],
                });
                // tmp3 = lhs XOR sum
                let tmp3 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, result],
                    results: vec![tmp3],
                });
                // tmp4 = tmp2 AND tmp3  (sign bit set iff overflow)
                let tmp4 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Band,
                    args: vec![tmp2, tmp3],
                    results: vec![tmp4],
                });
                // flag = Icmp Slt(tmp4, 0)  — produces B1
                let zero = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Iconst {
                        ty: lir_ty.clone(),
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![zero],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Icmp {
                        cond: IntCC::SignedLessThan,
                    },
                    args: vec![tmp4, zero],
                    results: vec![flag],
                });
            }
            OverflowOp::SubOverflow => {
                // tmp1 = lhs XOR rhs
                let tmp1 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, rhs_val],
                    results: vec![tmp1],
                });
                // tmp2 = lhs XOR diff
                let tmp2 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Bxor,
                    args: vec![lhs_val, result],
                    results: vec![tmp2],
                });
                // tmp3 = tmp1 AND tmp2  (sign bit set iff overflow)
                let tmp3 = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Band,
                    args: vec![tmp1, tmp2],
                    results: vec![tmp3],
                });
                // flag = Icmp Slt(tmp3, 0)
                let zero = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Iconst {
                        ty: lir_ty.clone(),
                        imm: 0,
                    },
                    args: vec![],
                    results: vec![zero],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Icmp {
                        cond: IntCC::SignedLessThan,
                    },
                    args: vec![tmp3, zero],
                    results: vec![flag],
                });
            }
            OverflowOp::MulOverflow => {
                // DIVISION-FREE signed multiply-overflow, mirroring the unsigned
                // wide-multiply check above with SIGN extension: sign-extend both
                // operands to the next-wider type, multiply there, truncate to the
                // narrow type and sign-extend back; overflow iff the wide product
                // differs from that round-trip.
                //
                // The previous check used the SDIV identity (`result / rhs != lhs`)
                // and relied on AArch64 SDIV-by-zero returning 0. On x86-64 IDIV
                // by zero TRAPS (#DE -> SIGFPE), so `x.overflowing_mul(0)` /
                // `x.checked_mul(0)` crashed instead of reporting no overflow
                // (MISCOMPILE #67). The wide-multiply check never divides and is
                // correct for every operand, including 0 and INT_MIN * -1 (I64 is
                // handled by the native CheckedSmul idiom above; I8/I16/I32 always
                // have a strictly-wider type to multiply in).
                let wide_ty = match &lir_ty {
                    Type::I8 => Type::I16,
                    Type::I16 => Type::I32,
                    Type::I32 => Type::I64,
                    _ => unreachable!("signed overflow mul fallback is only used below I64"),
                };
                let lhs_wide = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Sextend {
                        from_ty: lir_ty.clone(),
                        to_ty: wide_ty.clone(),
                    },
                    args: vec![lhs_val],
                    results: vec![lhs_wide],
                });
                let rhs_wide = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Sextend {
                        from_ty: lir_ty.clone(),
                        to_ty: wide_ty.clone(),
                    },
                    args: vec![rhs_val],
                    results: vec![rhs_wide],
                });
                let product_wide = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Imul,
                    args: vec![lhs_wide, rhs_wide],
                    results: vec![product_wide],
                });
                let product_trunc = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Trunc {
                        to_ty: lir_ty.clone(),
                    },
                    args: vec![product_wide],
                    results: vec![product_trunc],
                });
                let product_roundtrip = self.fresh_value();
                instrs.push(Instruction {
                    opcode: Opcode::Sextend {
                        from_ty: lir_ty.clone(),
                        to_ty: wide_ty,
                    },
                    args: vec![product_trunc],
                    results: vec![product_roundtrip],
                });
                instrs.push(Instruction {
                    opcode: Opcode::Icmp {
                        cond: IntCC::NotEqual,
                    },
                    args: vec![product_wide, product_roundtrip],
                    results: vec![flag],
                });
            }
        }

        Ok(instrs)
    }

    // -----------------------------------------------------------------------
    // Control flow
    // -----------------------------------------------------------------------

    fn translate_br(
        &mut self,
        target: &BlockId,
        args: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let mut instrs = Vec::new();

        // Emit copies for block arguments -> block parameters.
        instrs.extend(self.resolve_block_args(*target, args)?);

        let dest = self.map_block(*target);
        instrs.push(Instruction {
            opcode: Opcode::Jump { dest },
            args: vec![],
            results: vec![],
        });

        Ok(instrs)
    }

    fn translate_condbr(
        &mut self,
        cond: &ValueId,
        then_target: &BlockId,
        then_args: &[ValueId],
        else_target: &BlockId,
        else_args: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let mut instrs = Vec::new();
        let cond_val = self.map_value(*cond);

        // When block arguments are present, copies must only execute on the
        // correct control-flow edge. We create intermediate "copy blocks"
        // that perform the copies and then jump to the real target.
        //
        // BUG FIX (issue #302): Previously, copies for BOTH branches were
        // emitted unconditionally before the Brif. When different values
        // are passed to the same block parameter via different edges, the
        // last copy always wins — producing wrong code.

        let then_copies = self.resolve_block_args(*then_target, then_args)?;
        let else_copies = self.resolve_block_args(*else_target, else_args)?;

        let then_dest = if !then_copies.is_empty() {
            // Create an intermediate block for then-branch copies.
            let copy_block_id = self.fresh_block();
            let real_then_dest = self.map_block(*then_target);
            let mut copy_bb = BasicBlock {
                instructions: then_copies,
                ..Default::default()
            };
            copy_bb.instructions.push(Instruction {
                opcode: Opcode::Jump {
                    dest: real_then_dest,
                },
                args: vec![],
                results: vec![],
            });
            self.pending_extra_blocks.push((copy_block_id, copy_bb));
            copy_block_id
        } else {
            self.map_block(*then_target)
        };

        let else_dest = if !else_copies.is_empty() {
            // Create an intermediate block for else-branch copies.
            let copy_block_id = self.fresh_block();
            let real_else_dest = self.map_block(*else_target);
            let mut copy_bb = BasicBlock {
                instructions: else_copies,
                ..Default::default()
            };
            copy_bb.instructions.push(Instruction {
                opcode: Opcode::Jump {
                    dest: real_else_dest,
                },
                args: vec![],
                results: vec![],
            });
            self.pending_extra_blocks.push((copy_block_id, copy_bb));
            copy_block_id
        } else {
            self.map_block(*else_target)
        };

        instrs.push(Instruction {
            opcode: Opcode::Brif {
                cond: cond_val,
                then_dest,
                else_dest,
            },
            args: vec![cond_val],
            results: vec![],
        });

        Ok(instrs)
    }

    /// A value of unit `()` or never `!` type is zero-sized: it occupies no ABI
    /// slot and is dropped from argument/return lists.
    fn is_zero_sized_value(&self, v: ValueId) -> bool {
        matches!(self.lookup_value_ty(v), Some(Ty::Unit) | Some(Ty::Never))
    }

    fn translate_return(&mut self, values: &[ValueId]) -> Result<Vec<Instruction>, AdapterError> {
        self.validate_return_signature(values)?;
        // Drop zero-sized (unit/never) return values: a `ret ()` is a void return
        // matching the unit-filtered signature (see translate_signature).
        let values: Vec<ValueId> = values
            .iter()
            .copied()
            .filter(|v| !self.is_zero_sized_value(*v))
            .collect();
        let values = values.as_slice();

        // Apple arm64 ABI: the CALLEE must extend a narrow integer return value
        // (i8/i16/u8/u16) to 32 bits — sign-extend for signed types (SXTB/SXTH),
        // zero-extend for unsigned (UXTB/UXTH) — so an LLVM-compiled caller reads
        // the canonical value. (Standard AAPCS64 makes the caller narrow; Apple
        // diverges.) trust-ir carries the signedness here via the return `Ty`
        // (Ty::I8 vs Ty::U8); it is gone once lowered to the machine `Type`, so
        // materialize the extension now. See e2e_aarch64_narrow_int_diff.rs.
        let return_tys = self.current_return_tys.clone();
        let mut instrs = Vec::new();
        let mut args: Vec<Value> = Vec::with_capacity(values.len());
        for (vid, ret_ty) in values.iter().zip(return_tys.iter()) {
            let mapped = self.map_value(*vid);
            let ext = match ret_ty {
                Ty::I8 => Some((Type::I8, true)),
                Ty::U8 => Some((Type::I8, false)),
                Ty::I16 => Some((Type::I16, true)),
                Ty::U16 => Some((Type::I16, false)),
                _ => None,
            };
            match ext {
                Some((from_ty, signed)) => {
                    let widened = self.fresh_value();
                    self.define_value_type(widened, Type::I32);
                    let opcode = if signed {
                        Opcode::Sextend {
                            from_ty,
                            to_ty: Type::I32,
                        }
                    } else {
                        Opcode::Uextend {
                            from_ty,
                            to_ty: Type::I32,
                        }
                    };
                    instrs.push(Instruction {
                        opcode,
                        args: vec![mapped],
                        results: vec![widened],
                    });
                    args.push(widened);
                }
                None => args.push(mapped),
            }
        }

        instrs.push(Instruction {
            opcode: Opcode::Return,
            args,
            results: vec![],
        });
        Ok(instrs)
    }

    fn validate_return_signature(&self, values: &[ValueId]) -> Result<(), AdapterError> {
        // Zero-sized (unit/never) return values carry no ABI slot and are dropped
        // (translate_return), so validate the arity/types of the REMAINING values
        // against the unit-filtered return-type list.
        let values: Vec<ValueId> = values
            .iter()
            .copied()
            .filter(|v| !self.is_zero_sized_value(*v))
            .collect();
        let values = values.as_slice();
        if values.len() != self.current_return_tys.len() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Inst::Return arity mismatch: got {}, expected {} from current function signature",
                values.len(),
                self.current_return_tys.len()
            )));
        }

        for (index, (value, expected)) in values.iter().zip(&self.current_return_tys).enumerate() {
            self.translate_ty(expected)?;
            let actual = self
                .lookup_value_ty(*value)
                .ok_or_else(|| AdapterError::UnknownValue(value.index()))?;
            // A by-value aggregate / slice-fat-pointer RETURN is carried by ADDRESS:
            // the returned value is the `Ptr` to the aggregate's slot bytes, and the
            // verified SysV aggregate-return classifier loads its lanes into RAX:RDX
            // (<=16 B) or copies via sret — exactly the caller-side
            // `is_aggregate_address_passed_ty` convention, just on the return edge.
            // Accept a `Ptr` for an aggregate-typed return; every other mismatch
            // still fails closed.
            if !Self::call_arg_ty_compatible(&actual, expected) {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Inst::Return value {index} type mismatch: operand ValueId({}) has {:?}, expected {:?} from current function signature",
                    value.index(),
                    actual,
                    expected
                )));
            }
        }
        Ok(())
    }

    /// Lower `Inst::CoroSuspend { frame, state_slot, next_state, value }` — one
    /// coroutine `yield` — by MACRO-EXPANDING it into the already-verified
    /// store+return primitives (trust-ir inst.rs §coroutines). No new machine
    /// codegen is introduced: a `CoroSuspend` is operationally exactly
    ///
    /// ```text
    /// store i64 `next_state` into `frame[state_slot]`   ; record resume state
    /// return `value`                                    ; hand value to resumer
    /// ```
    ///
    /// The frame is a caller-owned aggregate of I64 elements, so the state field
    /// lives at byte offset `state_slot * 8` from `frame` — the same
    /// `base + index * sizeof(I64)` address arithmetic the single-index `GEP`
    /// arm emits, specialized here to the compile-time slot index. The trailing
    /// `Return` reuses `translate_return`, so the yielded value inherits the
    /// full return-signature validation (arity + type) every other return edge
    /// gets. Because this expands only into the I64 `Store` and `Return`
    /// lowerings, its correctness reduces to those per-instruction proofs.
    fn translate_coro_suspend(
        &mut self,
        frame: &ValueId,
        state_slot: u32,
        next_state: i64,
        value: &ValueId,
    ) -> Result<Vec<Instruction>, AdapterError> {
        const I64_BYTES: i64 = 8;

        let frame_ptr = self.map_value(*frame);
        let mut instrs = Vec::new();

        // Address of the state field: `frame + state_slot * 8`. A zero slot is
        // the frame base itself, so no address arithmetic is emitted; otherwise
        // materialize the constant byte offset and add it to the frame pointer,
        // mirroring the single-index GEP `base + index*elem_size` lowering.
        let slot_ptr = if state_slot == 0 {
            frame_ptr
        } else {
            let byte_offset = (state_slot as i64).checked_mul(I64_BYTES).ok_or_else(|| {
                AdapterError::UnsupportedInstruction(format!(
                    "CoroSuspend state_slot {state_slot} overflows an i64 byte offset"
                ))
            })?;
            let offset_val = self.fresh_value();
            self.define_value_type(offset_val, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: byte_offset,
                },
                args: vec![],
                results: vec![offset_val],
            });

            let addr = self.fresh_value();
            self.define_value_type(addr, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iadd,
                args: vec![frame_ptr, offset_val],
                results: vec![addr],
            });
            addr
        };

        // Materialize the i64 `next_state` constant and store it into the slot.
        // Frame state fields are I64 elements, so this is a plain 8-byte store —
        // the exact `Opcode::Store { ty: Type::I64 }` other I64 stores emit.
        let state_val = self.fresh_value();
        self.define_value_type(state_val, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: next_state,
            },
            args: vec![],
            results: vec![state_val],
        });
        instrs.push(Instruction {
            opcode: Opcode::Store {
                ty: Type::I64,
                align: None,
            },
            args: vec![state_val, slot_ptr],
            results: vec![],
        });

        // Return the yielded value. Reuse `translate_return` so the yielded
        // operand goes through the same return-signature validation as any
        // other return edge.
        instrs.extend(self.translate_return(std::slice::from_ref(value))?);
        Ok(instrs)
    }

    /// Lower `Inst::Invoke` — a call that may unwind to a landing pad.
    ///
    /// Emits the LIR `Opcode::Invoke { name, normal_dest, unwind_dest }`, which
    /// ISel lowers to the SAME `Bl` a `Call` lowers to plus a branch to the
    /// normal continuation (so it inherits the verified direct-call lowering),
    /// and records — in the function's `eh_info` — that this block's call site
    /// may unwind to `unwind_dest`. The codegen pipeline turns `eh_info` into
    /// the LSDA call-site table + compact unwind after block layout.
    ///
    /// The callee's return values bind `results` (same as `Inst::Call`); the
    /// normal edge carries `normal_args` to `normal_dest`'s block params. When
    /// `normal_args` is non-empty the copies must run only on the normal edge,
    /// so they go in a fresh edge block that the invoke's `normal_dest` points
    /// at, which then jumps to the real normal destination (mirroring the
    /// `condbr` edge-copy pattern).
    /// Select the EH personality for this function. If the enclosing module
    /// declares a function named `RUST_EH_PERSONALITY` (the rustc bridge's
    /// marker for Rust unwinding), use the Rust personality; otherwise the C++
    /// default. The frontend owns this choice via the declared symbol set, so
    /// no IR field or API change is needed.
    fn default_eh_personality(&self) -> String {
        if self
            .func_names
            .values()
            .any(|name| name == RUST_EH_PERSONALITY)
        {
            RUST_EH_PERSONALITY.to_string()
        } else {
            DEFAULT_EH_PERSONALITY.to_string()
        }
    }

    fn translate_invoke(
        &mut self,
        callee: FuncId,
        args: &[ValueId],
        normal_dest: BlockId,
        normal_args: &[ValueId],
        unwind_dest: BlockId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // Validate the call edge exactly as a direct `Call` would (arity +
        // callee convention + signature), so an invoke is held to the same
        // ABI guards as every other call site.
        self.validate_direct_call_signature(callee, args, results)?;

        let mut arg_vals: Vec<Value> = args.iter().map(|vid| self.map_value(*vid)).collect();
        let result_vals = self.map_results(results);
        let callee_name = self
            .func_names
            .get(&callee)
            .cloned()
            .unwrap_or_else(|| format!("__func_{}", callee.index()));

        // Propagate callee return / aggregate-param types onto the result and
        // (via call-site-scoped Copy temps) the argument Values — same
        // reasoning as the direct-`Call` arm: keeps ISel's `value_type()` and
        // ABI classification correct. The Copies are plain instructions
        // prepended ahead of the `Invoke` terminator in the same block; EH
        // call-site tracking is block-level and unaffected.
        let ret_tys = self.lookup_callee_return_types(callee);
        for (val, ty) in result_vals.iter().zip(ret_tys.iter()) {
            self.define_value_type(*val, ty.clone());
        }
        let param_tys = self.lookup_callee_param_types(callee);
        let mut insts = self.record_aggregate_call_arg_types(&mut arg_vals, &param_tys)?;

        // The throwing call site is the trust_ir block we are translating. Map
        // both it and the landing-pad block to their LIR blocks and record the
        // EH call site so the pipeline can emit the LSDA entry. The personality
        // is function-level (not on the Invoke); default it when EH first
        // appears (see `DEFAULT_EH_PERSONALITY`).
        let call_block = self
            .current_block_id
            .map(|bid| self.map_block(bid))
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(
                    "Invoke encountered outside a block context".to_string(),
                )
            })?;
        let unwind_lir = self.map_block(unwind_dest);
        if self.eh_info.personality.is_none() {
            self.eh_info.personality = Some(self.default_eh_personality());
        }
        self.eh_info.call_sites.push(crate::function::EhCallSite {
            call_block,
            landing_pad_block: unwind_lir,
        });

        // The normal continuation. When there are block args on the normal
        // edge, route through a fresh edge block that performs the copies and
        // then jumps to the real normal destination, so the copies execute
        // only on the non-throwing path.
        let normal_copies = self.resolve_block_args(normal_dest, normal_args)?;
        let real_normal_dest = self.map_block(normal_dest);
        let invoke_normal_dest = if normal_copies.is_empty() {
            real_normal_dest
        } else {
            let edge_block = self.fresh_block();
            let mut edge_bb = BasicBlock {
                instructions: normal_copies,
                ..Default::default()
            };
            edge_bb.instructions.push(Instruction {
                opcode: Opcode::Jump {
                    dest: real_normal_dest,
                },
                args: vec![],
                results: vec![],
            });
            self.pending_extra_blocks.push((edge_block, edge_bb));
            edge_block
        };

        insts.push(Instruction {
            opcode: Opcode::Invoke {
                name: callee_name,
                normal_dest: invoke_normal_dest,
                unwind_dest: unwind_lir,
            },
            args: arg_vals,
            results: result_vals,
        });
        Ok(insts)
    }

    /// Lower `Inst::LandingPad` — the entry of an exception handler / cleanup
    /// block. Emits the LIR `Opcode::LandingPad`, which ISel lowers to reads of
    /// the unwinder-provided exception pointer (X0) and type selector (X1) into
    /// the two results, and records the pad (catch types / cleanup flag) in the
    /// function's `eh_info` so the pipeline can build the LSDA action table.
    fn translate_landing_pad(
        &mut self,
        is_cleanup: bool,
        catch_type_indices: &[u32],
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // The pad produces (exception-ptr: Ptr/I64, selector: I32). Type them
        // so ISel's value_type() is correct for any downstream use.
        let result_vals = self.map_results(results);
        if let Some(exn) = result_vals.first() {
            self.define_value_type(*exn, Type::I64);
        }
        if let Some(sel) = result_vals.get(1) {
            self.define_value_type(*sel, Type::I32);
        }

        // Record this landing-pad block in the function EH info. The current
        // block is the pad block.
        let pad_block = self
            .current_block_id
            .map(|bid| self.map_block(bid))
            .ok_or_else(|| {
                AdapterError::UnsupportedInstruction(
                    "LandingPad encountered outside a block context".to_string(),
                )
            })?;
        self.eh_info
            .landing_pads
            .push(crate::function::EhLandingPad {
                block: pad_block,
                catch_type_indices: catch_type_indices.to_vec(),
                is_cleanup,
            });
        if self.eh_info.personality.is_none() {
            self.eh_info.personality = Some(self.default_eh_personality());
        }

        Ok(vec![Instruction {
            opcode: Opcode::LandingPad {
                is_cleanup,
                catch_type_indices: catch_type_indices.to_vec(),
            },
            args: vec![],
            results: result_vals,
        }])
    }

    /// Lower `Inst::Resume` — re-raise the in-flight exception to the host
    /// unwinder. Emits the LIR `Opcode::Resume`, which ISel lowers to a call to
    /// `_Unwind_Resume(exn)` (it does not return).
    fn translate_resume(&mut self, exn: &ValueId) -> Result<Vec<Instruction>, AdapterError> {
        let exn_val = self.map_value(*exn);
        Ok(vec![Instruction {
            opcode: Opcode::Resume,
            args: vec![exn_val],
            results: vec![],
        }])
    }

    // Legacy helpers `translate_call` and `translate_phi` were removed during
    // the 2026-04-19 zero-warnings cleanup — Call and Phi are lowered inline
    // in `translate_instruction` above.

    // -----------------------------------------------------------------------
    // Aggregate operations
    // -----------------------------------------------------------------------

    // `translate_struct_construct` was removed during the 2026-04-19
    // zero-warnings cleanup — Struct construction is lowered inline in
    // `translate_instruction` above.

    /// Translate `Field { ty, value, index }` — extract a struct field.
    ///
    /// Lowering: compute field offset, add to struct base pointer, load the
    /// field value from that address.
    /// A struct with a non-standard (packed) layout: its field offsets differ
    /// from the machine `Type::Struct` model (standard C alignment), which the
    /// GEP/load offset computation uses. Field access on such a struct would
    /// read the wrong bytes, so callers fail closed rather than miscompile.
    fn is_packed_struct_ty(&self, ty: &Ty) -> bool {
        if let Ty::Struct(sid) = ty
            && let Some(sdef) = self.structs.iter().find(|s| s.id == *sid)
        {
            return matches!(sdef.repr, trust_ir::StructRepr::Packed(_));
        }
        false
    }

    /// The module tables the layout authority resolves field types through —
    /// the same tables [`Self::translate_ty`] uses, so the layout it computes
    /// is the layout of the LIR type the byte path actually builds.
    fn layout_tables(&self) -> LayoutTables<'_> {
        let (records, closures): (&[RecordDef], &[ClosureTy]) = match self.module {
            Some(module) => (&module.records, &module.closure_types),
            None => (&[], &[]),
        };
        LayoutTables {
            structs: self.structs,
            types: self.types,
            enums: self.enums,
            records,
            closures,
        }
    }

    /// The niche carrier `ty` lowers to, when `ty` is a `Ty::Enum` with a
    /// NICHE-encoded producer descriptor. `Ok(None)` for every other type.
    ///
    /// This runs the SAME [`niche_enum_carrier`] rule the type translation ran,
    /// with the same tables, so the field types it reports are the fields of the
    /// `Type::Struct` the byte path actually built. Re-running it rather than
    /// caching keeps one rule in one place.
    fn niche_carrier(&self, ty: &Ty) -> Result<Option<NicheCarrier>, AdapterError> {
        let Some(edef) = niche_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        let Some(layout) = edef.layout.as_ref() else {
            return Ok(None);
        };
        let tables = self.layout_tables();
        niche_enum_carrier(
            edef,
            layout,
            tables.structs,
            tables.types,
            tables.enums,
            tables.records,
            tables.closures,
            true,
            1,
        )
        .map(Some)
        .map_err(|reason| niche_enum_refusal(edef.id, edef, reason))
    }

    /// THE INDEX SHIFT — the translation from a trust-ir enum field index to the
    /// carrier field index the emitted code addresses.
    ///
    /// trust-ir indexes an enum aggregate FLATLY: element 0 is the
    /// DISCRIMINANT and element `i > 0` is payload field `i - 1`. The niche
    /// carrier is the payload ALONE, at indices `0..n`, because a niche encoding
    /// has no tag word to occupy element 0. So every field-access site that can
    /// see one must shift, and must refuse element 0.
    ///
    /// Missing the shift is not a diagnostic failure, it is a WRONG ADDRESS: a
    /// two-field payload would answer `ExtractField 1` with field 1's bytes
    /// instead of field 0's, silently, at an offset the producer never stated
    /// for it. (c) MEASURED over the 68-module corpus, across the functions this
    /// admission unblocks: `InsertField` at element `n > 0` 449 times,
    /// `ExtractField` at element `n > 0` 72 times, `ExtractField` at element 0
    /// 26 times, `InsertField` at element 0 never.
    ///
    /// A THIRD indexing site exists and is deliberately NOT shifted: the
    /// multi-index `Inst::GEP` resolves its field types through
    /// [`TrustIrAdapter::aggregate_field_ty`], which refuses `Ty::Enum`
    /// outright, so a GEP with a niche-enum pointee fails closed with that
    /// message rather than addressing an unshifted field. An older count of
    /// "0 such GEPs" was taken while the TYPE itself was refused, so nothing
    /// ever reached the site; (c) RE-MEASURED after this admission, 179 corpus
    /// functions do reach it. Closing it is a separate change with its own
    /// address pins — the refusal is what keeps it honest until then.
    ///
    /// * `Ok(None)` — `ty` is not a niche enum; the caller uses its index
    ///   unchanged. This is every struct, tuple, record, closure and
    ///   Direct-encoded enum, so nothing that worked before moves.
    /// * `Ok(Some((carrier_index, payload_ty)))` — address carrier field
    ///   `carrier_index`, whose trust-ir type is `payload_ty`.
    /// * `Err` — element 0 (the discriminant), a field the descriptor does not
    ///   reach, or a field whose TYPE the variants do not agree on.
    fn niche_field_access(&self, ty: &Ty, field: u32) -> Result<Option<(u32, Ty)>, AdapterError> {
        let Some(carrier) = self.niche_carrier(ty)? else {
            return Ok(None);
        };
        let Some(edef) = niche_enum_def(ty, self.enums) else {
            return Ok(None);
        };
        // ELEMENT 0 IS THE DISCRIMINANT, AND A NICHE ENUM HAS NO TAG LANE.
        // Recovering it means range-testing the niche field against
        // `niche_start .. niche_start + (niche_variants_end -
        // niche_variants_start)`, which TrustCg does not emit. Shifting it to
        // "carrier field -1" is impossible and reading byte 0 as a tag would
        // read PAYLOAD — for `Option<&T>` that is the pointer itself. Refuse.
        if field == 0 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "element 0 of niche-encoded enum {:?} (`{}`) is its DISCRIMINANT, and a niche \
                 encoding stores that in otherwise-invalid values of a payload field rather than \
                 in a tag lane; recovering it needs the niche range test, which TrustCg does not \
                 emit, so refusing rather than reading payload bytes as a tag",
                edef.id, edef.name
            )));
        }
        let index = field - 1;
        let Some(payload_ty) = carrier.payload.get(index as usize) else {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "element {field} of niche-encoded enum {:?} (`{}`) names payload field {index}, \
                 but the carrier (variant {} `{}`) has {} payload fields",
                edef.id,
                edef.name,
                carrier.variant,
                edef.variants[carrier.variant].name,
                carrier.payload.len()
            )));
        };
        if !carrier.resolvable[index as usize] {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "payload field {index} of niche-encoded enum {:?} (`{}`) is declared with \
                 DIFFERENT types by different variants, and ExtractField/InsertField name a field \
                 but not a variant; the carrier (variant {} `{}`) types it {:?}, so accessing it \
                 would hand out another variant's payload at the carrier's extent",
                edef.id,
                edef.name,
                carrier.variant,
                edef.variants[carrier.variant].name,
                payload_ty
            )));
        }
        Ok(Some((index, payload_ty.clone())))
    }

    /// The layout the byte path emits for `ty`, when `ty` is a bare
    /// `Ty::Struct` the struct table resolves.
    ///
    /// `None` for every other shape — `Ty::Tuple`, `Ty::Record`, `Ty::Closure`,
    /// `Ty::Array`, `Ty::Enum` — because the producer states no offsets for
    /// them and the byte path synthesizes their layout in declaration order.
    /// Those keep the natural-C fallback unchanged.
    fn emitted_layout(&self, ty: &Ty) -> Result<Option<EmittedStructLayout>, AdapterError> {
        let tables = self.layout_tables();
        match struct_def_for_ty(ty, tables.structs) {
            Some(sdef) => Ok(Some(emitted_struct_layout(sdef, tables)?)),
            None => Ok(None),
        }
    }

    /// The byte offset field `index` of `ty` sits at, **when the adapter has to
    /// materialise it itself** rather than leaving it to `Opcode::StructGep`.
    ///
    /// `StructGep` is resolved downstream by natural-C `Type::offset_of`
    /// (`isel.rs:9306`, `x86_64_isel.rs:13208`) on a LIR `Type::Struct` that
    /// carries no repr and no offsets, so it can only ever express the
    /// recomputed layout. Whenever the authority for `ty`
    /// ([`crate::declared_layout`]) puts the field somewhere else, the adapter
    /// must compute `base + offset` explicitly — exactly the move the packed
    /// lane already makes.
    ///
    /// * `Some(offset)` — emit `Iconst` + `Iadd`. The authority is the
    ///   producer's declared layout, or the packed layout.
    /// * `None` — **THE NAMED FALLBACK**: emit `StructGep` unchanged. Either no
    ///   authority above natural C exists for `ty` (no declared layout, not
    ///   packed), or the declared offset is *provably the same address*
    ///   `StructGep` computes, in which case the existing encoding is kept so
    ///   the emitted stream stays byte-identical for the structs that already
    ///   agreed.
    ///
    /// A packed struct with no declared layout always takes the explicit form,
    /// unconditionally, exactly as it did before this method existed.
    fn explicit_field_offset(
        &self,
        ty: &Ty,
        lir_ty: &Type,
        index: u32,
    ) -> Result<Option<u64>, AdapterError> {
        let Some(layout) = self.emitted_layout(ty)? else {
            return Ok(None);
        };
        let offset = *layout.offsets.get(index as usize).ok_or_else(|| {
            AdapterError::UnsupportedType(format!(
                "field index {index} out of bounds for {ty:?} ({} fields laid out)",
                layout.offsets.len()
            ))
        })?;
        match layout.source {
            LayoutSource::NaturalC => Ok(None),
            LayoutSource::Packed => Ok(Some(offset)),
            LayoutSource::Declared => {
                if lir_ty.offset_of(index as usize).map(u64::from) == Some(offset) {
                    Ok(None)
                } else {
                    Ok(Some(offset))
                }
            }
        }
    }

    /// The element stride for an array of `ty`, **when the adapter has to
    /// materialise it itself** rather than leaving it to `Opcode::ArrayGep`.
    ///
    /// The `ArrayGep` twin of [`Self::explicit_field_offset`], with the same
    /// rule and the same named fallback: `ArrayGep` strides by natural-C
    /// `elem_ty.bytes()`, so an authority that sizes the element differently
    /// has to be spelled out as `base + index * stride`.
    ///
    /// `ty` is what one step of the index moves over — the pointee of a
    /// single-index `GEP`, or the ELEMENT of the array an `ArrayGep` walks. It
    /// may itself be a `Ty::Array` (`&[[P; 2]]`, or the outer step of
    /// `GEP { pointee_ty: [P; 2], indices: [i, j] }`), which is why the array
    /// case is answered here rather than left to the struct table: an array's
    /// stride is its ELEMENT's authoritative stride times the count, and (c)
    /// MEASURED `size_of::<[P; 2]>() == 18` where the natural-C carrier is 32.
    fn explicit_element_stride(&self, ty: &Ty, lir_ty: &Type) -> Result<Option<u64>, AdapterError> {
        if matches!(ty, Ty::Array(_, _)) {
            // The authority for an array is entirely its element's. Spell the
            // stride out only when it actually differs from the natural-C one
            // `ArrayGep` would compute, so every array of natural-C elements
            // keeps the exact encoding it had.
            let extent = self.aggregate_value_extent(ty, lir_ty)?;
            return Ok((extent != u64::from(lir_ty.bytes())).then_some(extent));
        }
        let Some(layout) = self.emitted_layout(ty)? else {
            return Ok(None);
        };
        match layout.source {
            LayoutSource::NaturalC => Ok(None),
            LayoutSource::Packed => Ok(Some(layout.size)),
            LayoutSource::Declared if layout.size != u64::from(lir_ty.bytes()) => {
                Ok(Some(layout.size))
            }
            LayoutSource::Declared => Ok(None),
        }
    }

    /// Emit the address of element `index_val` of an array whose elements are
    /// `elem_ty` — as `Opcode::ArrayGep` when natural-C is the authority, and
    /// as explicit `base + index * stride` arithmetic when it is not.
    ///
    /// THE ONE PLACE the array-element stride is materialised for a runtime
    /// index. `ArrayGep` carries only a repr-less LIR `Type`, so the isel can
    /// resolve it no way but natural-C `elem_ty.bytes()`; whenever
    /// [`Self::explicit_element_stride`] names a different stride the opcode
    /// simply cannot express the address and the arithmetic has to be written
    /// out — exactly the move the single-index `Inst::GEP` path already makes.
    fn emit_array_element_ptr(
        &mut self,
        elem_ty: &Ty,
        lir_elem_ty: &Type,
        base_ptr: Value,
        index_val: Value,
        dst: Value,
        instrs: &mut Vec<Instruction>,
    ) -> Result<(), AdapterError> {
        let Some(stride) = self.explicit_element_stride(elem_ty, lir_elem_ty)? else {
            instrs.push(Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: lir_elem_ty.clone(),
                },
                args: vec![base_ptr, index_val],
                results: vec![dst],
            });
            return Ok(());
        };
        let size_val = self.fresh_value();
        self.define_value_type(size_val, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Iconst {
                ty: Type::I64,
                imm: stride as i64,
            },
            args: vec![],
            results: vec![size_val],
        });
        let scaled = self.fresh_value();
        self.define_value_type(scaled, Type::I64);
        instrs.push(Instruction {
            opcode: Opcode::Imul,
            args: vec![index_val, size_val],
            results: vec![scaled],
        });
        instrs.push(Instruction {
            opcode: Opcode::Iadd,
            args: vec![base_ptr, scaled],
            results: vec![dst],
        });
        Ok(())
    }

    /// How many bytes a BY-VALUE copy of an aggregate `ty` must move.
    ///
    /// The AUTHORITATIVE extent, from the one authority selector
    /// ([`crate::declared_layout::emitted_value_extent`]): the producer's
    /// declared size when it stated an emittable layout, else the
    /// [`packed_struct_layout`] size for a `#[repr(packed(N))]` struct, else
    /// natural-C `lir_ty.bytes()` — i.e. exactly the extent
    /// [`packed_struct_layout`] advances a containing packed struct's running
    /// offset by, since that walk now asks the same selector for each field.
    ///
    /// That equality is the point, and it is a SAFETY obligation, not tidiness.
    /// Before packed nesting was fixed, `packed_struct_layout` advanced by the
    /// natural `Type::bytes()`, so a natural-C-lengthed `Memmove` into a packed
    /// field landed exactly flush against the next sibling: `#[repr(packed)]
    /// { h: u8, inner: P, t: u8 }` put `t` at 17 and the 16-byte copy into
    /// `inner` at offset 1 covered bytes 1..17. Once the advance is `P`'s real
    /// 9 bytes, rustc's `t@10` is what gets emitted (measured) and that same
    /// 16-byte copy would CLOBBER `t`. So every write extent for an aggregate
    /// of packed type has to move with the layout, in the same change.
    ///
    /// Copying the packed extent rather than the natural one also leaves the
    /// destination's trailing padding stale. That is sound: those bytes are not
    /// part of the value under either authority, no read path addresses them,
    /// and the natural-C slot that holds them is still the larger of the two
    /// (the domination invariant), so nothing reads past the object.
    fn aggregate_value_extent(&self, ty: &Ty, lir_ty: &Type) -> Result<u64, AdapterError> {
        emitted_value_extent(ty, lir_ty, self.layout_tables())
    }

    fn translate_field_extract(
        &mut self,
        ty: &Ty,
        value: &ValueId,
        index: u32,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let struct_ty = self.translate_ty(ty)?;
        // THE INDEX SHIFT. A niche-encoded `Ty::Enum` lowers to the payload
        // struct ALONE, so trust-ir's flat element `i` is carrier field `i - 1`
        // and element 0 (the discriminant) has no carrier field at all. Without
        // this the arm below would take the `Type::Struct` path with trust-ir's
        // index and read the WRONG FIELD — see `niche_field_access`. Every other
        // type answers `None` and keeps its index untouched.
        let index = match self.niche_field_access(ty, index)? {
            Some((carrier_index, _)) => carrier_index,
            None => index,
        };
        let base_ptr = self.map_value(*value);
        let dst = self.map_result(results)?;
        let mut instrs = Vec::new();

        // Determine the field's scalar type for the load.
        let field_ty = match &struct_ty {
            Type::Struct(field_types) => {
                if (index as usize) < field_types.len() {
                    field_types[index as usize].clone()
                } else {
                    return Err(AdapterError::UnsupportedType(format!(
                        "field index {} out of bounds for struct with {} fields",
                        index,
                        field_types.len()
                    )));
                }
            }
            _ => {
                return Err(AdapterError::UnsupportedType(format!(
                    "field extract on non-struct type: {:?}",
                    ty
                )));
            }
        };

        // The field sits at the AUTHORITATIVE offset — the producer's declared
        // one, or the PACKED one — which the machine `Type::Struct` layout
        // (declaration-ordered standard C alignment) does not reproduce.
        // Compute the offset explicitly and do a byte-offset load rather than a
        // type-offset StructGep + load; the load is marked possibly-UNALIGNED
        // only when the struct is packed, since a declared offset from rustc is
        // always properly aligned for the field's own type.
        if let Some(offset) = self.explicit_field_offset(ty, &struct_ty, index)? {
            let load_align = if self.is_packed_struct_ty(ty) {
                Some(1) // packed field may be unaligned
            } else {
                None
            };
            let off_val = self.fresh_value();
            self.define_value_type(off_val, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: offset as i64,
                },
                args: vec![],
                results: vec![off_val],
            });
            // An aggregate field's value IS its address (base + packed offset) —
            // no Load, like the non-packed nested case; subsequent accesses
            // recurse on the pointer using the inner struct's own layout. A
            // scalar field is loaded (possibly unaligned) from that address.
            if matches!(field_ty, Type::Struct(_) | Type::Array(_, _)) {
                instrs.push(Instruction {
                    opcode: Opcode::Iadd,
                    args: vec![base_ptr, off_val],
                    results: vec![dst],
                });
                self.define_value_type(dst, field_ty);
                return Ok(instrs);
            }
            let field_ptr = self.fresh_value();
            self.define_value_type(field_ptr, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iadd,
                args: vec![base_ptr, off_val],
                results: vec![field_ptr],
            });
            instrs.push(Instruction {
                opcode: Opcode::Load {
                    ty: field_ty,
                    align: load_align,
                },
                args: vec![field_ptr],
                results: vec![dst],
            });
            return Ok(instrs);
        }

        // When the extracted field is ITSELF an aggregate (a nested struct/array
        // field), its value has no single-register representation — like every
        // aggregate value in this backend it is carried by ADDRESS. So compute
        // the field's address with StructGep and use it DIRECTLY as the result,
        // with NO Load. A subsequent ExtractField/Store/return on this value
        // recurses on the pointer (StructGep operates on the aggregate operand as
        // an address, exactly as it does for the incoming struct argument). A
        // scalar field, by contrast, is loaded into the destination register.
        // (Loading an aggregate field as a scalar previously read only part of it
        // and then accessed the rest out of bounds — a crash.)
        if matches!(field_ty, Type::Struct(_) | Type::Array(_, _)) {
            instrs.push(Instruction {
                opcode: Opcode::StructGep {
                    struct_ty,
                    field_index: index,
                },
                args: vec![base_ptr],
                results: vec![dst],
            });
            self.define_value_type(dst, field_ty);
            return Ok(instrs);
        }

        let load_ptr = self.fresh_value();
        instrs.push(Instruction {
            opcode: Opcode::StructGep {
                struct_ty,
                field_index: index,
            },
            args: vec![base_ptr],
            results: vec![load_ptr],
        });

        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: field_ty,
                align: None,
            },
            args: vec![load_ptr],
            results: vec![dst],
        });

        Ok(instrs)
    }

    // Legacy helpers `translate_array_index`, `translate_call_indirect`,
    // `translate_select`, and `translate_gep` were removed during the
    // 2026-04-19 zero-warnings cleanup — Index, CallIndirect, Select, and
    // GetElementPtr are lowered inline in `translate_instruction` above.

    // -----------------------------------------------------------------------
    // Constants
    // -----------------------------------------------------------------------

    fn translate_const(
        &mut self,
        ty: &Ty,
        value: i64,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let dst = self.map_result(results)?;

        Ok(vec![Instruction {
            opcode: Opcode::Iconst {
                ty: lir_ty,
                imm: value,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Validate TrustIr's one-spelling rule for the wide unsigned carrier.
    fn validate_canonical_u128(ty: &Ty, value: u128) -> Result<(), AdapterError> {
        if !matches!(ty, Ty::U128) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Constant::U128 requires declared type U128, got {ty:?}"
            )));
        }
        if value <= i128::MAX as u128 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "non-canonical Constant::U128({value}); values representable as i128 \
                 must use Constant::Int"
            )));
        }
        Ok(())
    }

    /// Materialize a canonical `Constant::U128` without routing its upper-half
    /// bit pattern through the signed `Constant::Int` validation path.
    fn translate_u128_const(
        &mut self,
        ty: &Ty,
        value: u128,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let dst = self.map_result(results)?;
        self.translate_u128_const_into(ty, value, dst)
    }

    fn translate_u128_const_into(
        &mut self,
        ty: &Ty,
        value: u128,
        dst: Value,
    ) -> Result<Vec<Instruction>, AdapterError> {
        Self::validate_canonical_u128(ty, value)?;
        let lo = (value & u128::from(u64::MAX)) as u64;
        let hi = (value >> 64) as u64;
        self.define_value_type(dst, Type::I128);
        Ok(vec![Instruction {
            opcode: Opcode::Iconst128 {
                lo: lo as i64,
                hi: hi as i64,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    /// Translate an `Inst::Const { value: Constant::Int(i128), ty }` while
    /// validating that the value fits into the target type's representable
    /// range. The previous implementation did `*v as i64`, silently
    /// truncating any value outside `i64::MIN..=i64::MAX` — issue #339
    /// Finding 3.
    ///
    /// Values representable by one 64-bit carrier use `Opcode::Iconst`; wider
    /// I128/U128 values use `Opcode::Iconst128` with independent low/high
    /// halves. Canonical `Constant::U128` values take the dedicated unsigned
    /// path above instead of being reinterpreted as a signed `Constant::Int`.
    fn translate_int_const(
        &mut self,
        ty: &Ty,
        value: i128,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        // Importers use this in-band encoding with thin pointer/reference
        // carriers and the legacy I64 address carrier (notably the rustc
        // bridge's vtable path). Restrict decoding to those deliberate
        // carriers so ordinary U64/U128/Usize constants whose high bits happen
        // to be `0xFADE` remain numeric data instead of becoming addresses.
        if Self::is_imported_global_addr_carrier(ty)
            && let Some((name, offset, is_external_import)) =
                self.decode_imported_global_addr(value)?
        {
            let dst = self.map_result(results)?;
            self.define_value_type(dst, Type::I64);
            // An external DATA import (e.g. `@__stderrp` from libSystem) has no
            // link-time address in this object: a direct ADRP@PAGE+ADD@PAGEOFF
            // reference is a static-link error. Route it GOT-indirect via
            // `ExternRef` (ADRP@GOTPAGE + LDR@GOTPAGEOFF), exactly as
            // `translate_global_addr` does for the `Inst::GlobalAddr` form. A
            // DEFINED (initializer-bearing) global keeps the direct `GlobalRef`.
            let base_opcode = if is_external_import {
                Opcode::ExternRef { name }
            } else {
                Opcode::GlobalRef { name }
            };
            // Zero addend: the bare symbol address IS the result.
            if offset == 0 {
                return Ok(vec![Instruction {
                    opcode: base_opcode,
                    args: vec![],
                    results: vec![dst],
                }]);
            }
            // Non-zero addend (a GEP folded into the global-address stub, e.g.
            // `&extern_arr[3]`): the base reference materializes the symbol's
            // BASE address; the addend must be ADDED to that address AFTER it is
            // formed. It must NOT be folded into the relocation — for `ExternRef`
            // the @GOTPAGEOFF reloc addresses the GOT SLOT (not the symbol), so a
            // baked-in addend would displace the wrong thing, and for `GlobalRef`
            // the opcode carries no addend field at all. So emit the bare base
            // ref into a temp, materialize the offset as an ordinary `Iconst`,
            // and `Iadd` — the same base+const-offset shape the GEP lowering
            // uses. The offset is a `u32` BYTE offset (the importer's stub
            // synthesizer, `global_addr_stub`, restricts it to `0..=u32::MAX` and
            // fails closed on negatives / out-of-range), so `i64::from(offset)`
            // reproduces it exactly (non-negative, no sign extension) and `Iconst`
            // materialization (movz/movk) covers the whole range — there is no
            // add-immediate range limit and no residual fail-closed case.
            let base = self.fresh_value();
            self.define_value_type(base, Type::I64);
            let off_val = self.fresh_value();
            self.define_value_type(off_val, Type::I64);
            return Ok(vec![
                Instruction {
                    opcode: base_opcode,
                    args: vec![],
                    results: vec![base],
                },
                Instruction {
                    opcode: Opcode::Iconst {
                        ty: Type::I64,
                        imm: i64::from(offset),
                    },
                    args: vec![],
                    results: vec![off_val],
                },
                Instruction {
                    opcode: Opcode::Iadd,
                    args: vec![base, off_val],
                    results: vec![dst],
                },
            ]);
        }

        // Bounds check per target type. Signed types also accept the unsigned
        // bit-pattern range because the backend treats `Iconst.imm` as a raw
        // bit pattern (sign/zero extension happens at use sites based on
        // per-instruction signedness), and trust_ir frontends commonly emit
        // u64-typed constants such as hash mixing primes via `Ty::I64`.
        let (min, max): (i128, i128) = match ty {
            Ty::Bool => (0, 1),
            Ty::I8 => (i8::MIN as i128, u8::MAX as i128),
            Ty::I16 => (i16::MIN as i128, u16::MAX as i128),
            Ty::I32 => (i32::MIN as i128, u32::MAX as i128),
            Ty::I64 => (i64::MIN as i128, u64::MAX as i128),
            Ty::I128 => (i128::MIN, i128::MAX),
            Ty::U8 => (0, u8::MAX as i128),
            Ty::U16 => (0, u16::MAX as i128),
            Ty::U32 => (0, u32::MAX as i128),
            Ty::U64 => (0, u64::MAX as i128),
            // `Constant::Int` is the canonical U128 carrier only for the
            // non-negative half representable by i128. Values above i128::MAX
            // must use `Constant::U128`; negative Int values are not raw bits.
            Ty::U128 => (0, i128::MAX),
            // B1 pointer-width / char scalars: isize is signed 64-bit, usize is
            // unsigned 64-bit, and char is a Unicode scalar carrier here.
            Ty::Isize => (i64::MIN as i128, i64::MAX as i128),
            Ty::Usize => (0, u64::MAX as i128),
            Ty::Char => (0, 0x10FFFF),
            Ty::Ptr | Ty::Ref(_) | Ty::RefMut(_) | Ty::PtrConst(_) | Ty::PtrMut(_) | Ty::Rc(_) => {
                (i64::MIN as i128, u64::MAX as i128)
            }
            _ => {
                return Err(AdapterError::UnsupportedInstruction(format!(
                    "Constant::Int on non-integer type {:?}",
                    ty
                )));
            }
        };
        if value < min || value > max {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Constant::Int({}) does not fit in {:?} (range [{}, {}])",
                value, ty, min, max
            )));
        }
        if matches!(ty, Ty::Char) && (0xD800..=0xDFFF).contains(&value) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "Constant::Int({value}) is not a Unicode scalar value for Char (surrogate range)"
            )));
        }

        // Materialize. For values that fit in i64 we pass through to the
        // existing `Opcode::Iconst { imm: i64 }` path, which sign-extends
        // (or for unsigned types, zero-extends at use sites — the backend
        // treats the imm as a bit-pattern and width truncation applies).
        match i64::try_from(value) {
            Ok(v64) => self.translate_const(ty, v64, results),
            Err(_) => {
                // Value fits in neither i64 nor u64 (as signed). Check
                // whether it fits as a u64 bit-pattern for 64-bit targets.
                if matches!(
                    ty,
                    Ty::I64
                        | Ty::U64
                        | Ty::Usize
                        | Ty::Ptr
                        | Ty::PtrConst(_)
                        | Ty::PtrMut(_)
                        | Ty::Ref(_)
                        | Ty::RefMut(_)
                        | Ty::Rc(_)
                ) && (0..=(u64::MAX as i128)).contains(&value)
                {
                    // Reinterpret the u64 bit pattern as i64 so Iconst carries
                    // the same 64 bits; the backend treats it as a raw
                    // bit-pattern for address-space constants.
                    let bits = value as u64;
                    return self.translate_const(ty, bits as i64, results);
                }
                // Wide 128-bit constant whose high 64 bits are NOT the sign
                // extension of the low 64 bits. The bounds check above already
                // proved `value` is a valid I128/U128 value, so split it into
                // its two independent 64-bit halves and emit `Iconst128`. The
                // x86 ISel lowers this to two `MovRI`s (one per half of the
                // i128 GPR pair), each an already-proven primitive. The
                // unsigned value `value as u128` reproduces `value` exactly:
                // for non-negative `value` the cast is identity; for negative
                // `value` (only reachable via Ty::I128) it is the two's
                // complement bit pattern, whose low/high u64 halves are the
                // physical register contents — exactly what the pair carries.
                if matches!(ty, Ty::I128 | Ty::U128) {
                    let bits = value as u128;
                    let lo = (bits & u128::from(u64::MAX)) as u64;
                    let hi = (bits >> 64) as u64;
                    let dst = self.map_result(results)?;
                    self.define_value_type(dst, Type::I128);
                    return Ok(vec![Instruction {
                        opcode: Opcode::Iconst128 {
                            lo: lo as i64,
                            hi: hi as i64,
                        },
                        args: vec![],
                        results: vec![dst],
                    }]);
                }
                Err(AdapterError::UnsupportedInstruction(format!(
                    "Constant::Int({}) outside i64 range and {:?} wide-imm \
                     materialization not supported for this type",
                    value, ty
                )))
            }
        }
    }

    /// Decode the importer's `0xFADE`-tagged global-address stub constant into
    /// `(symbol name, byte offset, is_external_data_import)`. The importer
    /// materializes the address of a module global (e.g. from `load ptr, ptr
    /// @g`) as a magic i64 `0xFADE_<idx:16>_<offset:32>`; the `is_external_data_import`
    /// flag mirrors [`global_is_external_data_import`] so the caller can route
    /// an external DATA import (like `@__stderrp`) through the GOT-indirect
    /// `ExternRef` sequence rather than a direct `GlobalRef` — the same
    /// definedness split [`translate_global_addr`] applies to `Inst::GlobalAddr`.
    fn decode_imported_global_addr(
        &self,
        value: i128,
    ) -> Result<Option<(String, u32, bool)>, AdapterError> {
        if !(0..=(u64::MAX as i128)).contains(&value) {
            return Ok(None);
        }
        let bits = value as u64;
        if bits >> 48 != 0xFADE {
            return Ok(None);
        }

        let idx = ((bits >> 32) & 0xFFFF) as usize;
        let offset = (bits & 0xFFFF_FFFF) as u32;
        let module = self.module.as_ref().ok_or(AdapterError::ModuleNotSet)?;
        let global = module.globals.get(idx).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "global address stub references missing global index {}",
                idx
            ))
        })?;
        Ok(Some((
            global.name.clone(),
            offset,
            global_is_external_data_import(global),
        )))
    }

    fn translate_fconst(
        &mut self,
        ty: &Ty,
        value: f64,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let lir_ty = self.translate_ty(ty)?;
        let dst = self.map_result(results)?;

        Ok(vec![Instruction {
            opcode: Opcode::Fconst {
                ty: lir_ty,
                imm: value,
            },
            args: vec![],
            results: vec![dst],
        }])
    }

    fn translate_vector_pack_lanes_stack(
        &mut self,
        lanes: &[ValueId],
        lane_count: u32,
        lane_ty: Type,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let vector_ty = Type::V128;
        let total_lane_bytes = lane_ty.bytes().checked_mul(lane_count).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "vector.pack_lanes byte size overflows: {lane_count} lanes of {lane_ty:?}"
            ))
        })?;
        if total_lane_bytes != vector_ty.bytes() {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector.pack_lanes lane storage is {total_lane_bytes} bytes, expected {} bytes",
                vector_ty.bytes()
            )));
        }

        let slot = self.alloc_stack_slot(vector_ty.bytes(), vector_ty.align());
        let base = self.fresh_value();
        self.define_value_type(base, Type::I64);
        let dst = self.map_result(results)?;
        self.define_value_type(dst, vector_ty.clone());

        let mut instrs = Vec::with_capacity(lanes.len() * 3 + 2);
        instrs.push(Instruction {
            opcode: Opcode::StackAddr { slot },
            args: vec![],
            results: vec![base],
        });

        for (idx, lane) in lanes.iter().enumerate() {
            let lane_index = self.fresh_value();
            self.define_value_type(lane_index, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::Iconst {
                    ty: Type::I64,
                    imm: idx as i64,
                },
                args: vec![],
                results: vec![lane_index],
            });

            let lane_ptr = self.fresh_value();
            self.define_value_type(lane_ptr, Type::I64);
            instrs.push(Instruction {
                opcode: Opcode::ArrayGep {
                    elem_ty: lane_ty.clone(),
                },
                args: vec![base, lane_index],
                results: vec![lane_ptr],
            });

            instrs.push(Instruction {
                opcode: Opcode::Store {
                    ty: lane_ty.clone(),
                    align: None,
                },
                args: vec![self.map_value(*lane), lane_ptr],
                results: vec![],
            });
        }

        instrs.push(Instruction {
            opcode: Opcode::Load {
                ty: vector_ty,
                align: None,
            },
            args: vec![base],
            results: vec![dst],
        });

        Ok(instrs)
    }

    fn translate_v4i32_extract_lane_direct(
        &mut self,
        vector_val: Value,
        lane: u32,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        if lane > 3 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector.extract_lane requires <4 x i32> lane 0..3, got {lane}"
            )));
        }
        let dst = self.map_result(results)?;
        self.define_value_type(dst, Type::I32);
        Ok(vec![Instruction {
            opcode: Opcode::V4I32ExtractLane { lane: lane as u8 },
            args: vec![vector_val],
            results: vec![dst],
        }])
    }

