    fn translate_v4i32_extract_element(
        &mut self,
        elem_ty: &Ty,
        array: ValueId,
        index: ValueId,
        results: &[ValueId],
    ) -> Result<Vec<Instruction>, AdapterError> {
        let array_ty = self.lookup_value_ty(array).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(
                "vector ExtractElement requires <4 x i32> source, but source type is unknown"
                    .to_string(),
            )
        })?;
        if !Self::is_v4i32_ty(&array_ty) || elem_ty != &Ty::I32 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "vector ExtractElement requires <4 x i32> source and i32 result, got source={:?} result={:?}",
                array_ty, elem_ty
            )));
        }

        let lane = self.require_v4i32_lane_index(index, "vector ExtractElement")?;
        let vector_val = self.map_value(array);
        self.translate_v4i32_extract_lane_direct(vector_val, lane, results)
    }

