    /// Validate a constant lane index `0..=max_lane` (i64-typed) for a narrow
    /// integer vector extract/insert. Mirrors `require_v4i32/v2i64_lane_index`.
    fn require_const_lane_index(
        &self,
        index: ValueId,
        max_lane: u32,
        context: &str,
    ) -> Result<u32, AdapterError> {
        let index_ty = self.lookup_value_ty(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires an i64 constant lane index 0..={max_lane}, but index type is unknown"
            ))
        })?;
        if index_ty != Ty::I64 {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} requires an i64 constant lane index 0..={max_lane}, got index type {index_ty:?}"
            )));
        }
        let lane = self.lookup_const_int(index).ok_or_else(|| {
            AdapterError::UnsupportedInstruction(format!(
                "{context} requires an i64 CONSTANT lane index 0..={max_lane}"
            ))
        })?;
        if lane < 0 || lane as u64 > u64::from(max_lane) {
            return Err(AdapterError::UnsupportedInstruction(format!(
                "{context} lane index out of range 0..={max_lane}, got {lane}"
            )));
        }
        Ok(lane as u32)
    }

