    /// Helper: create a TrustIrFunc from the old test-style inline FuncTy.
    ///
    /// Old tests constructed functions with `ty: FuncTy { ... }` directly, but
    /// the new trust_ir uses `ty: FuncTyId`. This helper registers the FuncTy in a
    /// module and returns the function with the correct FuncTyId.
    fn make_func(
        id: FuncId,
        name: &str,
        func_ty: FuncTy,
        entry: BlockId,
        blocks: Vec<TrustIrBlockDef>,
        proofs: Vec<ProofAnnotation>,
    ) -> (TrustIrFunc, Module) {
        let mut module = Module::new("test");
        let ft_id = module.add_func_type(func_ty);
        let mut func = TrustIrFunc::new(id, name, ft_id, entry);
        func.blocks = blocks;
        func.proofs = proofs;
        module.add_function(func.clone());
        (func, module)
    }

    /// Helper: wraps translate_function with a module containing just the function's FuncTy.
    fn translate_func_test(
        func: &TrustIrFunc,
        module: &Module,
    ) -> Result<(Function, ProofContext), AdapterError> {
        translate_function(func, module)
    }

    #[test]
    fn atomic_rmw_min_max_ops_map_to_dedicated_lir_ops() {
        // Signed/unsigned min/max atomic RMW have a dedicated, fully-lowered LIR
        // mapping (AArch64 LDSMAXAL/LDSMINAL/LDUMAXAL/LDUMINAL + LSE/x86 CAS
        // loop). They must map to their corresponding LIR op — NOT fail closed
        // and NOT collapse to Add — matching the conformance contract.
        for (op, expected) in [
            (TrustIrAtomicRmwOp::Max, AtomicRmwOp::Max),
            (TrustIrAtomicRmwOp::Min, AtomicRmwOp::Min),
            (TrustIrAtomicRmwOp::UMax, AtomicRmwOp::UMax),
            (TrustIrAtomicRmwOp::UMin, AtomicRmwOp::UMin),
        ] {
            let mapped = translate_atomic_rmw_op(&op)
                .unwrap_or_else(|err| panic!("AtomicRMW {op:?} must map to a LIR op, got {err:?}"));
            assert_eq!(mapped, expected, "AtomicRMW {op:?} mapped to wrong LIR op");
        }
    }

