    /// Helper: build a Module from a TrustIrFunc by inferring FuncTy from block params.
    /// This replaces the old pattern of `translate_function(&func, &[])`.
    fn make_module_for_func(func: &TrustIrFunc) -> Module {
        // Infer param types from entry block params
        let params: Vec<Ty> = func
            .blocks
            .first()
            .map(|b| b.params.iter().map(|(_, ty)| ty.clone()).collect())
            .unwrap_or_default();

        // Build a value -> trust_ir type map from every block parameter and
        // every instruction result so that `returns` reflects the ACTUAL type
        // of each returned value (not a crude "first param type" guess). This
        // keeps the synthesized function signature consistent with the body so
        // the adapter's return-signature validation accepts well-typed fixtures.
        let mut value_tys: HashMap<ValueId, Ty> = HashMap::new();
        for block in &func.blocks {
            for (vid, ty) in &block.params {
                value_tys.insert(*vid, ty.clone());
            }
            for node in &block.body {
                for (idx, result) in node.results.iter().enumerate() {
                    if let Some(ty) = trust_ir_result_type_for_test(&node.inst, idx) {
                        value_tys.insert(*result, ty);
                    }
                }
            }
        }

        // Infer return types from the first Return instruction by resolving the
        // declared type of each returned value.
        let mut returns = Vec::new();
        'outer: for block in &func.blocks {
            for node in &block.body {
                if let Inst::Return { values } = &node.inst {
                    for value in values {
                        if let Some(ty) = value_tys.get(value) {
                            returns.push(ty.clone());
                        }
                    }
                    break 'outer;
                }
            }
        }

        let mut module = Module::new("test");
        module.add_func_type(FuncTy {
            params,
            returns,
            is_vararg: false,
        });
        module.add_function(func.clone());
        module
    }

    /// Resolve the trust_ir result type of an instruction result for the test
    /// module synthesizer. Mirrors the adapter's own `trust_ir_result_type` for
    /// the scalar/control instructions used by the adapter unit-test fixtures.
    fn trust_ir_result_type_for_test(inst: &Inst, result_index: usize) -> Option<Ty> {
        match inst {
            Inst::BinOp { ty, .. }
            | Inst::UnOp { ty, .. }
            | Inst::Cast { dst_ty: ty, .. }
            | Inst::Load { ty, .. }
            | Inst::AtomicLoad { ty, .. }
            | Inst::AtomicRMW { ty, .. }
            | Inst::Const { ty, .. }
            | Inst::Copy { ty, .. }
            | Inst::Select { ty, .. } => Some(ty.clone()),
            Inst::ICmp { ty, .. } | Inst::FCmp { ty, .. } => Some(ty.comparison_result_ty()),
            Inst::Overflow { ty, .. } => match result_index {
                0 => Some(ty.clone()),
                1 => Some(Ty::Bool),
                _ => None,
            },
            Inst::Alloca { .. }
            | Inst::GEP { .. }
            | Inst::NullPtr
            | Inst::Borrow { .. }
            | Inst::BorrowMut { .. } => Some(Ty::Ptr),
            _ => None,
        }
    }

    /// Build a minimal trust_ir module: fn add(a: i32, b: i32) -> i32 { a + b }
    fn build_add_module() -> Module {
        let mut module = Module::new("test");
        let ft = module.add_func_type(FuncTy {
            params: vec![Ty::I32, Ty::I32],
            returns: vec![Ty::I32],
            is_vararg: false,
        });
        let mut func = TrustIrFunc::new(FuncId::new(0), "add", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![
                (ValueId::new(0), Ty::I32), // param a
                (ValueId::new(1), Ty::I32), // param b
            ],
            body: vec![
                InstrNode {
                    inst: Inst::BinOp {
                        op: BinOp::Add,
                        ty: Ty::I32,
                        lhs: ValueId::new(0),
                        rhs: ValueId::new(1),
                    },
                    results: vec![ValueId::new(2)],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
                InstrNode {
                    inst: Inst::Return {
                        values: vec![ValueId::new(2)],
                    },
                    results: vec![],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
            ],
        }];
        module.add_function(func);
        module
    }

