    #[test]
    fn test_translate_type_unit_is_a_zst_and_never_still_errors() {
        // `()` IS representable — a zero-byte, 1-aligned aggregate — and a parent
        // struct places it exactly where rustc does. (c) MEASURED against rustc's
        // `#[repr(C)] { a: u8, z: (), b: u64 }`: size 16, align 8, z@1.
        let unit = translate_type(&Ty::Unit).expect("() lowers to a zero-sized aggregate");
        assert_eq!(unit, Type::Struct(Vec::new()));
        assert_eq!((unit.bytes(), unit.align()), (0, 1));
        let parent = Type::Struct(vec![Type::I8, unit, Type::I64]);
        assert_eq!(
            (
                parent.bytes(),
                parent.align(),
                parent.offset_of(1),
                parent.offset_of(2)
            ),
            (16, 8, Some(1), Some(8)),
            "a ZST field must occupy no bytes and must not displace its siblings"
        );

        // `Never` is NOT the same question: uninhabited means UNREACHABLE, not
        // empty, so giving it a zero-sized value would assert that a value exists
        // where none can. It stays fail-closed.
        assert!(translate_type(&Ty::Never).is_err());
    }

