    #[test]
    fn test_translate_valid_refinement_lowers_to_base_carrier() {
        for (base_ty, expected) in [(Ty::I32, Type::I32), (Ty::Usize, Type::I64)] {
            let mut module = Module::new("valid_refinement");
            let base = module.add_type(base_ty);
            let pred = module
                .intern_pred(trust_ir::Pred::Top)
                .expect("Top is a canonical predicate");
            let refined = Ty::Refine(base, pred);
            let func_ty = module.add_func_type(FuncTy {
                params: vec![refined.clone()],
                returns: vec![refined.clone()],
                is_vararg: false,
            });
            let mut func =
                TrustIrFunc::new(FuncId::new(0), "refined_identity", func_ty, BlockId::new(0));
            func.blocks = vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), refined)],
                body: vec![InstrNode {
                    inst: Inst::Return {
                        values: vec![ValueId::new(0)],
                    },
                    results: vec![],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                }],
            }];
            module.add_function(func);

            let lowered = translate_module(&module).expect("valid refinement must lower");
            assert_eq!(lowered[0].0.signature.params, vec![expected.clone()]);
            assert_eq!(lowered[0].0.signature.returns, vec![expected]);
        }
    }

