    #[test]
    fn test_translate_type_graph_cycles_fail_closed_without_stack_overflow() {
        let recursive_array = Ty::Array(TyId::new(0), 1);
        let err = translate_type_with_tables(
            &recursive_array,
            &[],
            std::slice::from_ref(&recursive_array),
        )
        .unwrap_err();
        assert!(matches!(
            err,
            AdapterError::UnsupportedType(msg) if msg.contains("recursion limit")
        ));

        let recursive_refine = Ty::Refine(TyId::new(0), trust_ir::PredId::new(0));
        let err = translate_type_with_enum_tables(
            &recursive_refine,
            &[],
            std::slice::from_ref(&recursive_refine),
            &[],
            &[],
            &[],
        )
        .unwrap_err();
        assert!(matches!(
            err,
            AdapterError::InvalidRefinement(msg) if msg.contains("nested or cyclic")
        ));
    }

