    #[test]
    fn trust_ir_vector_pack_lanes_lowers_to_stack_materialized_v128() {
        let mut module = Module::new("test");
        let ft = module.add_func_type(FuncTy {
            params: vec![Ty::I32, Ty::I32, Ty::I32, Ty::I32],
            returns: vec![Ty::v4_i32()],
            is_vararg: false,
        });
        let mut func = TrustIrFunc::new(FuncId::new(0), "pack_lanes", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![
                (ValueId::new(0), Ty::I32),
                (ValueId::new(1), Ty::I32),
                (ValueId::new(2), Ty::I32),
                (ValueId::new(3), Ty::I32),
            ],
            body: vec![
                InstrNode::new(Inst::DialectOp(Box::new(vector_dialect::pack_lanes(
                    Ty::v4_i32(),
                    [
                        ValueId::new(0),
                        ValueId::new(1),
                        ValueId::new(2),
                        ValueId::new(3),
                    ],
                ))))
                .with_result(ValueId::new(4)),
                InstrNode::new(Inst::Return {
                    values: vec![ValueId::new(4)],
                }),
            ],
        }];
        module.add_function(func);

        let results = translate_module(&module).unwrap();
        let func = &results[0].0;
        let instructions = &func.blocks[&Block(0)].instructions;

        if let Some(pack) = instructions
            .iter()
            .find(|inst| matches!(&inst.opcode, Opcode::V4I32PackLanes))
        {
            assert_eq!(pack.args, vec![Value(0), Value(1), Value(2), Value(3)]);
            assert_eq!(func.value_types.get(&pack.results[0]), Some(&Type::V128));
            return;
        }

        assert_eq!(func.stack_slots.len(), 1);
        assert_eq!(func.stack_slots[0].size, Type::V128.bytes());
        assert_eq!(
            instructions
                .iter()
                .filter(|inst| matches!(&inst.opcode, Opcode::Store { ty, .. } if *ty == Type::I32))
                .count(),
            4
        );
        let vector_load = instructions
            .iter()
            .find(|inst| matches!(&inst.opcode, Opcode::Load { ty, .. } if *ty == Type::V128))
            .expect("pack_lanes should finish with a V128 load");
        assert_eq!(
            func.value_types.get(&vector_load.results[0]),
            Some(&Type::V128)
        );
    }

    #[test]
    fn trust_ir_vector_extract_and_insert_lane_v2i64_lower_to_direct_lir_without_stack_slots() {
        let mut module = Module::new("test");
        let ft = module.add_func_type(FuncTy {
            params: vec![Ty::v2_i64(), Ty::I64],
            returns: vec![Ty::v2_i64()],
            is_vararg: false,
        });
        let mut func = TrustIrFunc::new(FuncId::new(0), "lanes", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), Ty::v2_i64()), (ValueId::new(1), Ty::I64)],
            body: vec![
                InstrNode::new(Inst::DialectOp(Box::new(vector_dialect::extract_lane(
                    Ty::v2_i64(),
                    ValueId::new(0),
                    1,
                ))))
                .with_result(ValueId::new(2)),
                InstrNode::new(Inst::DialectOp(Box::new(vector_dialect::insert_lane(
                    Ty::v2_i64(),
                    ValueId::new(0),
                    0,
                    ValueId::new(1),
                ))))
                .with_result(ValueId::new(3)),
                InstrNode::new(Inst::Return {
                    values: vec![ValueId::new(3)],
                }),
            ],
        }];
        module.add_function(func);

        let results = translate_module(&module).unwrap();
        let func = &results[0].0;
        let instructions = &func.blocks[&Block(0)].instructions;

        assert!(
            func.stack_slots.is_empty(),
            "v2i64 extract_lane/insert_lane should avoid adapter stack materialization"
        );
        assert_eq!(instructions.len(), 3);
        assert_eq!(instructions[0].opcode, Opcode::V2I64ExtractLane { lane: 1 });
        assert_eq!(instructions[0].args, vec![Value(0)]);
        assert_eq!(instructions[0].results, vec![Value(2)]);
        assert_eq!(instructions[1].opcode, Opcode::V2I64InsertLane { lane: 0 });
        assert_eq!(instructions[1].args, vec![Value(0), Value(1)]);
        assert_eq!(instructions[1].results, vec![Value(3)]);
        assert_eq!(
            func.value_types.get(&instructions[0].results[0]),
            Some(&Type::I64)
        );
        assert_eq!(
            func.value_types.get(&instructions[1].results[0]),
            Some(&Type::V128)
        );
    }

