    #[test]
    fn trust_cg_bitfield_dialect_lowers_to_lir_bitfield_opcodes() {
        let mut module = Module::new("test");
        let ft = module.add_func_type(FuncTy {
            params: vec![Ty::I64, Ty::I64],
            returns: vec![Ty::I64],
            is_vararg: false,
        });
        let mut func = TrustIrFunc::new(FuncId::new(0), "bitfields", ft, BlockId::new(0));
        func.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
            body: vec![
                InstrNode::new(Inst::DialectOp(Box::new(bitfield_dialect::extract_bits(
                    Ty::I64,
                    ValueId::new(0),
                    8,
                    16,
                ))))
                .with_result(ValueId::new(2)),
                InstrNode::new(Inst::DialectOp(Box::new(bitfield_dialect::sextract_bits(
                    Ty::I64,
                    ValueId::new(0),
                    4,
                    12,
                ))))
                .with_result(ValueId::new(3)),
                InstrNode::new(Inst::DialectOp(Box::new(bitfield_dialect::insert_bits(
                    Ty::I64,
                    ValueId::new(0),
                    ValueId::new(1),
                    16,
                    12,
                ))))
                .with_result(ValueId::new(4)),
                InstrNode::new(Inst::Return {
                    values: vec![ValueId::new(4)],
                }),
            ],
        }];
        module.add_function(func);

        let results = translate_module(&module).unwrap();
        let instructions = &results[0].0.blocks[&Block(0)].instructions;
        assert!(matches!(
            instructions[0].opcode,
            Opcode::ExtractBits { lsb: 8, width: 16 }
        ));
        assert!(matches!(
            instructions[1].opcode,
            Opcode::SextractBits { lsb: 4, width: 12 }
        ));
        assert!(matches!(
            instructions[2].opcode,
            Opcode::InsertBits { lsb: 16, width: 12 }
        ));
        assert_eq!(instructions[2].args, vec![Value(0), Value(1)]);
        assert_eq!(results[0].0.value_types.get(&Value(4)), Some(&Type::I64));
    }

