    #[test]
    fn trust_cg_v2i64_bool_mask_extract_lowers_compare_result_without_select() {
        for result_ty in [Ty::I32, Ty::I64] {
            let v2_i64 = Ty::Vector(Box::new(Ty::I64), 2);
            let mut module = Module::new("test");
            let ft = module.add_func_type(FuncTy {
                params: vec![v2_i64.clone(), v2_i64.clone()],
                returns: vec![result_ty.clone()],
                is_vararg: false,
            });
            let mut func =
                TrustIrFunc::new(FuncId::new(0), "cmp_bool_mask_extract", ft, BlockId::new(0));
            func.blocks = vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![
                    (ValueId::new(0), v2_i64.clone()),
                    (ValueId::new(1), v2_i64.clone()),
                ],
                body: vec![
                    InstrNode::new(Inst::ICmp {
                        op: ICmpOp::Slt,
                        ty: v2_i64,
                        lhs: ValueId::new(0),
                        rhs: ValueId::new(1),
                    })
                    .with_result(ValueId::new(2)),
                    InstrNode::new(Inst::DialectOp(Box::new(
                        bitfield_dialect::v2i64_bool_mask_extract(
                            ValueId::new(2),
                            result_ty.clone(),
                        ),
                    )))
                    .with_result(ValueId::new(3)),
                    InstrNode::new(Inst::Return {
                        values: vec![ValueId::new(3)],
                    }),
                ],
            }];
            module.add_function(func);

            let results = translate_module(&module).unwrap();
            let instructions = &results[0].0.blocks[&Block(0)].instructions;
            let expected_ty = translate_type(&result_ty).unwrap();
            let mask_extract = instructions
                .iter()
                .find(|inst| matches!(inst.opcode, Opcode::V2I64MaskExtract { .. }))
                .expect("v2i64 bool mask extract should lower to LIR mask extract");
            assert_eq!(
                mask_extract.opcode,
                Opcode::V2I64MaskExtract {
                    result_ty: expected_ty.clone(),
                }
            );
            assert_eq!(
                results[0].0.value_types.get(&mask_extract.results[0]),
                Some(&expected_ty)
            );
            assert!(
                !instructions
                    .iter()
                    .any(|inst| matches!(inst.opcode, Opcode::Select { .. })),
                "direct bool mask extract must not materialize a select before extraction"
            );
        }
    }

