    /// Load of an AGGREGATE is a by-value copy: a fresh stack slot + Memmove,
    /// not an 8-byte scalar Load (and not aliasing the source pointer).
    #[test]
    fn test_load_aggregate_copies_via_stack() {
        let agg_ty = Ty::Tuple(vec![Ty::I64, Ty::I64]);
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "ld".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::Ptr)],
                body: vec![
                    InstrNode {
                        inst: Inst::Load {
                            ty: agg_ty.clone(),
                            ptr: ValueId::new(0),
                            volatile: false,
                            align: None,
                        },
                        results: vec![ValueId::new(1)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return { values: vec![] },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };
        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let insts: Vec<_> = lir_func
            .blocks
            .values()
            .flat_map(|bb| bb.instructions.iter())
            .collect();
        assert!(
            insts
                .iter()
                .any(|i| matches!(i.opcode, Opcode::StackAddr { .. })),
            "aggregate Load must allocate a fresh stack slot"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|i| matches!(i.opcode, Opcode::Memmove))
                .count(),
            1,
            "aggregate Load must Memmove into the fresh slot"
        );
        assert_eq!(
            insts
                .iter()
                .filter(|i| matches!(i.opcode, Opcode::Load { .. }))
                .count(),
            0,
            "aggregate Load must not use a scalar Load"
        );
    }

