    // --- Global-address stub with a (possibly non-zero) addend ---------------
    //
    // Producers encode `&global + offset` as the magic 64-bit constant
    // `0xFADE_<idx:16>_<offset:32>`. The LLVM importer uses `Ptr`; rustc const
    // operands may retain a supported thin reference/raw-pointer type, and its
    // vtable path retains the legacy I64 carrier. `translate_int_const` decodes
    // these exact typed positions and materializes the symbol address; an
    // EXTERNAL data import routes GOT-indirect (`ExternRef`), a DEFINED global
    // direct (`GlobalRef`). A NON-ZERO addend is added AFTER the base address is
    // formed (`Iconst` + `Iadd`) — never folded into the relocation, which
    // addresses the GOT slot / bare symbol, not `symbol+offset`.

    /// Build the `0xFADE`-tagged stub constant for global index 0 at `offset`.
    fn global_addr_stub_const(offset: u32) -> i128 {
        (((0xFADEu64) << 48) | (offset as u64)) as i128
    }

    #[test]
    fn global_addr_stub_tag_is_numeric_for_unsigned_constants() {
        let tagged = global_addr_stub_const(0x1234);
        for ty in [Ty::U64, Ty::U128, Ty::Usize] {
            let func = const_func("tag_shaped_numeric_constant", ty.clone(), tagged);
            let module = make_module_for_func(&func);
            let (lir_func, _) = translate_func_test(&func, &module)
                .unwrap_or_else(|error| panic!("{ty:?} tag-shaped numeric constant: {error}"));
            let entry = &lir_func.blocks[&lir_func.entry_block];
            assert!(
                entry.instructions.iter().all(|inst| !matches!(
                    &inst.opcode,
                    Opcode::GlobalRef { .. } | Opcode::ExternRef { .. }
                )),
                "{ty:?} tag-shaped numeric constant must not decode as a global-address stub"
            );
        }
    }

    /// Lower a single typed `Inst::Const { Int(stub) }` returning the address,
    /// and hand back the entry block's opcodes for inspection. `external`
    /// selects an initializer-less external-linkage global (a data import ->
    /// `ExternRef`) vs an initializer-bearing defined global (-> `GlobalRef`).
    fn lower_global_addr_stub_with_carrier(
        carrier: Ty,
        offset: u32,
        external: bool,
    ) -> Vec<Opcode> {
        let global = if external {
            trust_ir::Global {
                name: "stub_ext".to_string(),
                ty: Ty::Ptr,
                mutable: false,
                initializer: None,
                linkage: Linkage::External,
                tls: None,
                align: None,
            }
        } else {
            trust_ir::Global {
                name: "stub_def".to_string(),
                ty: Ty::I32,
                mutable: true,
                initializer: Some(Constant::Int(0)),
                linkage: Linkage::Internal,
                tls: None,
                align: None,
            }
        };
        let stub = global_addr_stub_const(offset);
        let (func, mut module) = make_func(
            FuncId::new(0),
            "load_global_addr",
            FuncTy {
                params: vec![],
                returns: vec![carrier.clone()],
                is_vararg: false,
            },
            BlockId::new(0),
            vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    InstrNode {
                        inst: Inst::Const {
                            ty: carrier,
                            value: Constant::Int(stub),
                        },
                        results: vec![ValueId::new(0)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(0)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            vec![],
        );
        module.globals.push(global);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];
        entry
            .instructions
            .iter()
            .map(|i| i.opcode.clone())
            .collect()
    }

    fn lower_global_addr_stub(offset: u32, external: bool) -> Vec<Opcode> {
        lower_global_addr_stub_with_carrier(Ty::Ptr, offset, external)
    }

    #[test]
    fn global_addr_stub_decodes_for_all_intentional_thin_pointer_carriers() {
        for carrier in [
            Ty::I64,
            Ty::Ptr,
            Ty::Ref(Box::new(Ty::I32)),
            Ty::RefMut(Box::new(Ty::I32)),
            Ty::PtrConst(Box::new(Ty::I32)),
            Ty::PtrMut(Box::new(Ty::I32)),
        ] {
            let ops = lower_global_addr_stub_with_carrier(carrier.clone(), 4, false);
            assert!(
                matches!(&ops[0], Opcode::GlobalRef { name } if name == "stub_def"),
                "{carrier:?} must decode the producer's data-global stub: {ops:?}"
            );
            assert!(matches!(ops[1], Opcode::Iconst { imm: 4, .. }));
            assert!(matches!(ops[2], Opcode::Iadd));
        }
    }

    #[test]
    fn global_addr_stub_external_zero_addend_is_bare_extern_ref() {
        let ops = lower_global_addr_stub(0, /* external */ true);
        // Exactly the bare GOT-indirect base reference — no Iconst/Iadd, so a
        // zero-addend external global is BYTE-IDENTICAL to the prior behavior.
        match &ops[0] {
            Opcode::ExternRef { name } => assert_eq!(name, "stub_ext"),
            other => panic!("expected ExternRef, got {other:?}"),
        }
        assert!(
            !ops.iter()
                .any(|op| matches!(op, Opcode::Iadd | Opcode::Iconst { .. })),
            "zero-addend must not synthesize an offset add: {ops:?}"
        );
    }

    #[test]
    fn global_addr_stub_defined_zero_addend_is_bare_global_ref() {
        let ops = lower_global_addr_stub(0, /* external */ false);
        match &ops[0] {
            Opcode::GlobalRef { name } => assert_eq!(name, "stub_def"),
            other => panic!("expected GlobalRef, got {other:?}"),
        }
        assert!(
            !ops.iter()
                .any(|op| matches!(op, Opcode::Iadd | Opcode::Iconst { .. })),
            "zero-addend must not synthesize an offset add: {ops:?}"
        );
    }

    #[test]
    fn global_addr_stub_external_nonzero_addend_is_extern_ref_plus_add() {
        // `&extern_sym + 8`: GOT-load the base, then ADD the constant addend.
        let ops = lower_global_addr_stub(8, /* external */ true);
        match &ops[0] {
            Opcode::ExternRef { name } => assert_eq!(name, "stub_ext"),
            other => panic!("expected ExternRef base, got {other:?}"),
        }
        match &ops[1] {
            Opcode::Iconst { ty, imm } => {
                assert_eq!(*ty, Type::I64);
                assert_eq!(*imm, 8);
            }
            other => panic!("expected Iconst(8), got {other:?}"),
        }
        assert!(
            matches!(ops[2], Opcode::Iadd),
            "expected Iadd(base, offset), got {:?}",
            ops[2]
        );
    }

    #[test]
    fn global_addr_stub_defined_nonzero_addend_is_global_ref_plus_add() {
        // `&defined_arr[3]` (12-byte addend into an i32 array): direct base + ADD.
        let ops = lower_global_addr_stub(12, /* external */ false);
        match &ops[0] {
            Opcode::GlobalRef { name } => assert_eq!(name, "stub_def"),
            other => panic!("expected GlobalRef base, got {other:?}"),
        }
        match &ops[1] {
            Opcode::Iconst { ty, imm } => {
                assert_eq!(*ty, Type::I64);
                assert_eq!(*imm, 12);
            }
            other => panic!("expected Iconst(12), got {other:?}"),
        }
        assert!(
            matches!(ops[2], Opcode::Iadd),
            "expected Iadd(base, offset), got {:?}",
            ops[2]
        );
    }

    #[test]
    fn global_addr_stub_large_addend_beyond_add_imm_range() {
        // A byte offset far beyond the 12-bit ADD-immediate range (0x12345 =
        // 74565 > 4095) is still materialized as a plain Iconst (movz/movk) +
        // register-register Iadd — no add-immediate limit, no fail-closed case.
        let offset: u32 = 0x1_2345;
        let ops = lower_global_addr_stub(offset, /* external */ true);
        assert!(matches!(ops[0], Opcode::ExternRef { .. }));
        match &ops[1] {
            Opcode::Iconst { ty, imm } => {
                assert_eq!(*ty, Type::I64);
                assert_eq!(*imm, i64::from(offset));
            }
            other => panic!("expected Iconst({offset}), got {other:?}"),
        }
        assert!(matches!(ops[2], Opcode::Iadd));
    }

    #[test]
    fn global_addr_stub_max_u32_addend_is_exact_unsigned() {
        // The stub offset is a u32; the maximum value must materialize as its
        // exact non-negative i64 (no sign extension to a negative addend).
        let offset: u32 = u32::MAX;
        let ops = lower_global_addr_stub(offset, /* external */ false);
        assert!(matches!(ops[0], Opcode::GlobalRef { .. }));
        match &ops[1] {
            Opcode::Iconst { imm, .. } => {
                assert_eq!(*imm, i64::from(offset));
                assert!(*imm > 0, "u32::MAX addend must stay positive, got {imm}");
            }
            other => panic!("expected Iconst(u32::MAX), got {other:?}"),
        }
        assert!(matches!(ops[2], Opcode::Iadd));
    }

