    #[test]
    fn test_translate_not_null_load_store_prepends_guard_null() {
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "load_store_not_null".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::Ptr), (ValueId::new(2), Ty::I32)],
                body: vec![
                    InstrNode {
                        inst: Inst::Load {
                            ty: Ty::I32,
                            ptr: ValueId::new(0),
                            volatile: false,
                            align: None,
                        },
                        results: vec![ValueId::new(1)],
                        proofs: vec![ProofAnnotation::NotNull],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Store {
                            ty: Ty::I32,
                            ptr: ValueId::new(0),
                            value: ValueId::new(2),
                            volatile: false,
                            align: None,
                        },
                        results: vec![],
                        proofs: vec![ProofAnnotation::NotNull],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return { values: vec![] },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        assert_eq!(entry.instructions.len(), 5);
        // Each NotNull-annotated memory node (no explicit ProofRef) synthesizes a Discharged
        // obligation from the NotNull proof, exactly as InBounds carriers do. The synthesized id lives
        // in the reserved high range so it can never alias a real module obligation id.
        assert!(matches!(
            entry.instructions[0].opcode,
            Opcode::GuardNull { obligation: Some(id) }
                if id >= ProofContext::SYNTHESIZED_OBLIGATION_BASE
        ));
        assert_eq!(entry.instructions[0].args, vec![Value(0)]);
        assert!(matches!(entry.instructions[1].opcode, Opcode::Load { .. }));
        assert!(matches!(
            entry.instructions[2].opcode,
            Opcode::GuardNull { obligation: Some(id) }
                if id >= ProofContext::SYNTHESIZED_OBLIGATION_BASE
        ));
        assert_eq!(entry.instructions[2].args, vec![Value(0)]);
        assert!(matches!(entry.instructions[3].opcode, Opcode::Store { .. }));
        assert!(proof_ctx.has_not_null(&Value(0)));
        // Two NotNull carriers => two synthesized Discharged obligations recorded for the kernel gate.
        assert_eq!(proof_ctx.synthesized_discharged.len(), 2);
    }

