    #[test]
    fn test_translate_volatile_load_store_lowers_to_barrier_opcodes() {
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "volatile_load_store".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::Ptr)],
                body: vec![
                    InstrNode {
                        inst: Inst::Load {
                            ty: Ty::I32,
                            ptr: ValueId::new(0),
                            volatile: true,
                            align: None,
                        },
                        results: vec![ValueId::new(1)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Store {
                            ty: Ty::I32,
                            ptr: ValueId::new(0),
                            value: ValueId::new(1),
                            volatile: true,
                            align: None,
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return { values: vec![] },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        // Volatile load/store now lower to the DISTINCT `VolatileLoad`/
        // `VolatileStore` LIR opcodes, which isel maps to byte-identical machine
        // loads/stores classified as memory barriers (MemoryEffect::Call) so the
        // optimizer never elides/CSEs/forwards/hoists them. Verified end-to-end:
        // two volatile reads emit two machine loads while two plain reads CSE to
        // one (see the scratchpad vcse disassembly test).
        let (func_lir, _) = translate_func_test(&func, &module)
            .expect("volatile load/store now lower to VolatileLoad/VolatileStore");
        let ops: Vec<_> = func_lir
            .blocks
            .values()
            .flat_map(|bb| bb.instructions.iter())
            .collect();
        assert_eq!(
            ops.iter()
                .filter(|i| matches!(i.opcode, Opcode::VolatileLoad { .. }))
                .count(),
            1,
            "volatile load must emit exactly one VolatileLoad"
        );
        assert_eq!(
            ops.iter()
                .filter(|i| matches!(i.opcode, Opcode::VolatileStore { .. }))
                .count(),
            1,
            "volatile store must emit exactly one VolatileStore"
        );
        // The plain (non-volatile) Load/Store opcodes must NOT appear — volatile
        // accesses take the distinct barrier opcodes.
        assert_eq!(
            ops.iter()
                .filter(|i| matches!(i.opcode, Opcode::Load { .. } | Opcode::Store { .. }))
                .count(),
            0,
            "volatile accesses must not lower to plain Load/Store"
        );
    }

    #[test]
    fn volatile_i128_and_u128_load_store_fail_closed_before_lir() {
        for ty in [Ty::I128, Ty::U128] {
            let (load_func, load_module) = make_func(
                FuncId::new(0),
                "volatile_wide_load",
                FuncTy {
                    params: vec![Ty::Ptr],
                    returns: vec![],
                    is_vararg: false,
                },
                BlockId::new(0),
                vec![TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![(ValueId::new(0), Ty::Ptr)],
                    body: vec![
                        InstrNode::new(Inst::Load {
                            ty: ty.clone(),
                            ptr: ValueId::new(0),
                            volatile: true,
                            align: Some(16),
                        })
                        .with_result(ValueId::new(1)),
                        InstrNode::new(Inst::Return { values: vec![] }),
                    ],
                }],
                vec![],
            );
            let load_err = translate_func_test(&load_func, &load_module)
                .expect_err("wide volatile load must fail closed");
            assert!(
                matches!(load_err, AdapterError::UnsupportedInstruction(ref message)
                    if message.contains("volatile Load")
                        && message.contains("two 64-bit accesses"))
            );

            let (store_func, store_module) = make_func(
                FuncId::new(0),
                "volatile_wide_store",
                FuncTy {
                    params: vec![Ty::Ptr, ty.clone()],
                    returns: vec![],
                    is_vararg: false,
                },
                BlockId::new(0),
                vec![TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![(ValueId::new(0), Ty::Ptr), (ValueId::new(1), ty.clone())],
                    body: vec![
                        InstrNode::new(Inst::Store {
                            ty: ty.clone(),
                            ptr: ValueId::new(0),
                            value: ValueId::new(1),
                            volatile: true,
                            align: Some(16),
                        }),
                        InstrNode::new(Inst::Return { values: vec![] }),
                    ],
                }],
                vec![],
            );
            let store_err = translate_func_test(&store_func, &store_module)
                .expect_err("wide volatile store must fail closed");
            assert!(
                matches!(store_err, AdapterError::UnsupportedInstruction(ref message)
                    if message.contains("volatile Store")
                        && message.contains("two 64-bit accesses"))
            );
        }
    }

