    #[test]
    fn test_translate_div_nonzero_prepends_guard_div_zero() {
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "proven_sdiv".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
                body: vec![
                    InstrNode {
                        inst: Inst::BinOp {
                            op: BinOp::SDiv,
                            ty: Ty::I64,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![ProofAnnotation::DivNonZero],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        assert_eq!(entry.instructions.len(), 3);
        // DivNonZero IS the upstream safety proof, so the adapter synthesizes a Discharged obligation
        // and binds it to the carrier (exactly as NotNull does for the null guard). With no upstream
        // ProofRef, the synthesized id is SYNTHESIZED_OBLIGATION_BASE.
        assert_eq!(
            entry.instructions[0].opcode,
            Opcode::GuardDivZero {
                obligation: Some(ProofContext::SYNTHESIZED_OBLIGATION_BASE)
            }
        );
        assert_eq!(entry.instructions[0].args, vec![Value(1)]);
        assert!(entry.instructions[0].results.is_empty());
        assert_eq!(entry.instructions[1].opcode, Opcode::Sdiv);
        assert_eq!(entry.instructions[1].args, vec![Value(0), Value(1)]);
        assert_eq!(entry.instructions[2].opcode, Opcode::Return);
    }

