    // ---------------------------------------------------------------------
    // DivNonZero PRODUCER (constant-divisor guard elision) unit tests.
    //
    // The producer (`div_nonzero_const_annotate_module`) attaches
    // `ProofAnnotation::DivNonZero` to a div/rem node whose divisor is a
    // proven-nonzero compile-time integer literal, so the eliminable
    // `GuardDivZero` carrier replaces the real div-by-zero trap. Below:
    //   * a POSITIVE case per op (const nonzero -> annotated + guard elided),
    //   * REFUTATION cases (non-constant / zero / truncates-to-zero -> NOT
    //     annotated, guard kept — the fail-safe holds),
    //   * the signed `-1` edge (annotated for the div-ZERO guard; the SEPARATE
    //     INT_MIN/-1 overflow guard is untouched by this pass).
    // ---------------------------------------------------------------------

    /// Build a single-block function: `cN = const(k : ty); r = op(param0, cN)`
    /// returning `r`. `k` is the LITERAL divisor. No proofs are pre-attached, so
    /// the producer alone decides whether to annotate.
    fn div_by_const_func(op: BinOp, ty: Ty, k: i128) -> TrustIrFunc {
        let param0 = ValueId::new(0);
        let cval = ValueId::new(1);
        let res = ValueId::new(2);
        TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "div_by_const".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(param0, ty.clone())],
                body: vec![
                    InstrNode {
                        inst: Inst::Const {
                            ty: ty.clone(),
                            value: Constant::Int(k),
                        },
                        results: vec![cval],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::BinOp {
                            op,
                            ty,
                            lhs: param0,
                            rhs: cval,
                        },
                        results: vec![res],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return { values: vec![res] },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        }
    }

    /// The div/rem node (index 1) of a `div_by_const_func`-shaped module.
    fn div_node_proofs_after_annotate(func: &TrustIrFunc) -> Vec<ProofAnnotation> {
        let module = make_module_for_func(func);
        let annotated = div_nonzero_const_annotate_module(&module);
        let m = annotated.as_ref().unwrap_or(&module);
        m.functions[0].blocks[0].body[1].proofs.clone()
    }

    #[test]
    fn divnonzero_producer_annotates_nonzero_const_all_ops() {
        // Every integer div/rem op with a genuine nonzero literal divisor is
        // annotated `DivNonZero`.
        for op in [BinOp::UDiv, BinOp::SDiv, BinOp::URem, BinOp::SRem] {
            let func = div_by_const_func(op, Ty::I64, 1009);
            let proofs = div_node_proofs_after_annotate(&func);
            assert!(
                proofs.contains(&ProofAnnotation::DivNonZero),
                "{op:?} by nonzero const 1009 must be annotated DivNonZero, got {proofs:?}"
            );
        }
    }

    #[test]
    fn divnonzero_producer_elides_guard_end_to_end() {
        // End-to-end: an annotated SDiv by a nonzero const lowers to the
        // ELIMINABLE `GuardDivZero` carrier (bound to a synthesized discharged
        // obligation), NOT the raw trap — proving the producer feeds the
        // consumer path. The Sdiv itself remains.
        let func = div_by_const_func(BinOp::SDiv, Ty::I64, 1009);
        let module = make_module_for_func(&func);
        let annotated = div_nonzero_const_annotate_module(&module).expect("should annotate");
        let f = &annotated.functions[0];
        let (lir_func, _) = translate_function(f, &annotated).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];
        // const materialization is folded into the divisor operand path; the
        // guard carrier precedes the Sdiv.
        assert!(
            entry.instructions.iter().any(|i| matches!(
                i.opcode,
                Opcode::GuardDivZero {
                    obligation: Some(_)
                }
            )),
            "annotated SDiv-by-const must emit an eliminable GuardDivZero carrier, got {:?}",
            entry
                .instructions
                .iter()
                .map(|i| &i.opcode)
                .collect::<Vec<_>>()
        );
        assert!(
            entry.instructions.iter().any(|i| i.opcode == Opcode::Sdiv),
            "the Sdiv itself must remain"
        );
    }

    #[test]
    fn divnonzero_producer_annotates_cross_block_hoisted_const() {
        // The b01_intloop SHAPE: the divisor constant is defined in the ENTRY
        // block (loop-invariant, hoisted) and the div/rem lives in a LATER loop
        // block. A function-wide const scan must still recognize it (a
        // block-local scan would MISS it — the original bug). SSA: the entry
        // `Const` def dominates the loop use.
        let c1009 = ValueId::new(0);
        let prod = ValueId::new(1); // entry block param (stands in for the acc)
        let res = ValueId::new(2);
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "hoisted_rem".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![
                // entry: define the constant, then jump to the loop block.
                TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![(prod, Ty::I64)],
                    body: vec![
                        InstrNode {
                            inst: Inst::Const {
                                ty: Ty::I64,
                                value: Constant::Int(1009),
                            },
                            results: vec![c1009],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        InstrNode {
                            inst: Inst::Br {
                                target: BlockId::new(1),
                                args: vec![],
                            },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                    ],
                },
                // loop block: URem by the entry-block constant.
                TrustIrBlockDef {
                    id: BlockId::new(1),
                    params: vec![],
                    body: vec![
                        InstrNode {
                            inst: Inst::BinOp {
                                op: BinOp::URem,
                                ty: Ty::I64,
                                lhs: prod,
                                rhs: c1009,
                            },
                            results: vec![res],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        InstrNode {
                            inst: Inst::Return { values: vec![res] },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                    ],
                },
            ],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };
        assert!(
            func_has_annotatable_const_divisor(&func),
            "cross-block hoisted const divisor must be recognized"
        );
        let module = make_module_for_func(&func);
        let annotated = div_nonzero_const_annotate_module(&module).expect("should annotate");
        // div node is body[0] of block index 1.
        assert!(
            annotated.functions[0].blocks[1].body[0]
                .proofs
                .contains(&ProofAnnotation::DivNonZero),
            "hoisted-const URem in the loop block must be annotated DivNonZero"
        );
    }

    #[test]
    fn divnonzero_producer_refuses_nonconstant_divisor() {
        // REFUTATION: a runtime (block-param) divisor is NOT a literal, so NO
        // annotation is attached — the real div-by-zero guard is preserved
        // (fail-safe). Reuses the existing `plain_sdiv` shape: divisor is a
        // block param, never a Const.
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "runtime_div".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
                body: vec![
                    InstrNode {
                        inst: Inst::BinOp {
                            op: BinOp::UDiv,
                            ty: Ty::I64,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };
        let module = make_module_for_func(&func);
        // No annotatable constant divisor anywhere -> the pass returns None (no
        // clone) and the node stays unannotated.
        assert!(
            div_nonzero_const_annotate_module(&module).is_none(),
            "a runtime divisor must not trigger any annotation / clone"
        );
        assert!(!func_has_annotatable_const_divisor(&func));
    }

    #[test]
    fn divnonzero_producer_refuses_zero_const_divisor() {
        // REFUTATION: a ZERO literal divisor is NOT annotated (the hardware
        // would still trap; annotating it would be an unsound dropped-guard
        // miscompile). Note trust_ir permits constructing `x / 0` as an IR node;
        // the pass must leave the guard intact.
        for op in [BinOp::UDiv, BinOp::SDiv, BinOp::URem, BinOp::SRem] {
            let func = div_by_const_func(op, Ty::I64, 0);
            assert!(
                !func_has_annotatable_const_divisor(&func),
                "{op:?} by ZERO const must never be annotated"
            );
            let proofs = div_node_proofs_after_annotate(&func);
            assert!(
                !proofs.contains(&ProofAnnotation::DivNonZero),
                "{op:?} by ZERO const must keep the guard, got {proofs:?}"
            );
        }
    }

    #[test]
    fn divnonzero_producer_refuses_truncates_to_zero_const() {
        // REFUTATION: a literal that is nonzero as an i128 but ZERO at the
        // operation width (256 masked to I8 == 0) is a zero divisor at that
        // width and MUST NOT be annotated.
        let func = div_by_const_func(BinOp::UDiv, Ty::I8, 256);
        assert!(
            !func_has_annotatable_const_divisor(&func),
            "256 at width I8 truncates to 0 -> must not annotate"
        );
        // ...but 256 at a WIDER width (I16) is genuinely nonzero -> annotated.
        let func_wide = div_by_const_func(BinOp::UDiv, Ty::I16, 256);
        assert!(
            func_has_annotatable_const_divisor(&func_wide),
            "256 at width I16 is nonzero -> must annotate"
        );
    }

    #[test]
    fn divnonzero_producer_signed_neg_one_only_elides_zero_guard() {
        // The signed `-1` edge. `-1` is a nonzero literal, so the div-ZERO guard
        // IS elided (annotated). The SEPARATE INT_MIN/-1 signed-OVERFLOW guard
        // is emitted UNCONDITIONALLY by x86 ISel regardless of any proof and is
        // NOT a `GuardDivZero`, so eliding the zero guard cannot drop it. Here
        // we assert (a) the node is annotated DivNonZero, and (b) the lowering
        // still contains the div-by-zero guard's ABSENCE is fine while the
        // overflow-guard machinery (CMP rhs,-1 / CMOV) is unaffected — verified
        // structurally by the presence of the Sdiv (the overflow patch wraps it
        // in ISel, tested there and by the differential corpus).
        let func = div_by_const_func(BinOp::SDiv, Ty::I64, -1);
        let proofs = div_node_proofs_after_annotate(&func);
        assert!(
            proofs.contains(&ProofAnnotation::DivNonZero),
            "-1 is a nonzero literal; the div-ZERO guard may be elided, got {proofs:?}"
        );
    }

    #[test]
    fn divnonzero_producer_idempotent() {
        // Running the producer on already-annotated input does not double-attach
        // and does not force a clone (nothing new to annotate).
        let mut func = div_by_const_func(BinOp::SDiv, Ty::I64, 7);
        annotate_func_const_divisors(&mut func);
        let n = func.blocks[0].body[1]
            .proofs
            .iter()
            .filter(|p| **p == ProofAnnotation::DivNonZero)
            .count();
        assert_eq!(n, 1, "exactly one DivNonZero after first pass");
        // Second pass: no new annotation, and the module-level pass sees nothing
        // to do.
        let module = make_module_for_func(&func);
        assert!(
            div_nonzero_const_annotate_module(&module).is_none(),
            "already-annotated module must not be re-cloned"
        );
    }

    #[test]
    fn test_translate_shift_in_range_prepends_guard_shift_range() {
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "proven_lshr".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
                body: vec![
                    InstrNode {
                        inst: Inst::BinOp {
                            op: BinOp::LShr,
                            ty: Ty::I64,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![ProofAnnotation::ShiftInRange],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        assert_eq!(entry.instructions.len(), 3);
        // ShiftInRange IS the upstream safety proof, so the adapter synthesizes a Discharged
        // obligation and binds it to the carrier (exactly as InBounds does for the bounds guard).
        assert_eq!(
            entry.instructions[0].opcode,
            Opcode::GuardShiftRange {
                bitwidth: 64,
                obligation: Some(ProofContext::SYNTHESIZED_OBLIGATION_BASE)
            }
        );
        assert_eq!(entry.instructions[0].args, vec![Value(1)]);
        assert!(entry.instructions[0].results.is_empty());
        assert_eq!(entry.instructions[1].opcode, Opcode::Ushr);
        assert_eq!(entry.instructions[1].args, vec![Value(0), Value(1)]);
        assert_eq!(entry.instructions[2].opcode, Opcode::Return);
        assert_eq!(
            proof_ctx.value_proofs.get(&Value(1)),
            Some(&vec![Proof::ValidShift {
                amount: ValueId::new(1),
                bitwidth: 64,
            }])
        );
    }

