    /// MISCOMPILE #51 (adapter level): a shift whose COUNT operand is a
    /// DIFFERENT integer width than the shifted value must translate cleanly —
    /// in Rust MIR (and LLVM/trust_ir) the shift amount need not share the
    /// shifted type, e.g. `i8 >> 1` carries an I32 count literal and `i64 << (x
    /// as u32)` an I32 count. Before the fix the operand-type validator required
    /// the count to equal the declared shifted type and failed such a well-typed
    /// shift CLOSED ("rhs operand type mismatch"). The x86 ISel already supports
    /// a different-width count (it is taken from CL), so admitting it is sound.
    #[test]
    fn test_shift_count_may_be_narrower_than_shifted_value() {
        for op in [BinOp::Shl, BinOp::LShr, BinOp::AShr] {
            let func = TrustIrFunc {
                summary: None,
                producer: None,
                value_names: None,
                scopes: None,
                source_provenance: None,
                attrs: Default::default(),
                id: FuncId::new(0),
                name: format!("shift_narrow_count_{op:?}"),
                ty: FuncTyId::new(0),
                entry: BlockId::new(0),
                blocks: vec![TrustIrBlockDef {
                    id: BlockId::new(0),
                    // value is I8; the shift COUNT is a wider I32.
                    params: vec![(ValueId::new(0), Ty::I8), (ValueId::new(1), Ty::I32)],
                    body: vec![
                        InstrNode {
                            inst: Inst::BinOp {
                                op,
                                ty: Ty::I8,
                                lhs: ValueId::new(0),
                                rhs: ValueId::new(1),
                            },
                            results: vec![ValueId::new(2)],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        InstrNode {
                            inst: Inst::Return {
                                values: vec![ValueId::new(2)],
                            },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                    ],
                }],
                proofs: vec![],
                calling_conv: CallingConv::default(),
                linkage: Linkage::default(),
            };

            let module = make_module_for_func(&func);
            let result = translate_func_test(&func, &module);
            assert!(
                result.is_ok(),
                "BinOp::{op:?} with a wider shift count must translate, got: {:?}",
                result.err()
            );
        }
    }

