    #[test]
    fn trust_ir_narrow_i8_i16_select_lowers_canonical_compare_masks() {
        for (payload_ty, mask_ty, cmp_op, expected_cmp) in [
            (
                Ty::Vector(Box::new(Ty::I8), 16),
                Ty::Vector(Box::new(Ty::Bool), 16),
                ICmpOp::Eq,
                Opcode::V16I8Icmp { cond: IntCC::Equal },
            ),
            (
                Ty::Vector(Box::new(Ty::I16), 8),
                Ty::Vector(Box::new(Ty::Bool), 8),
                ICmpOp::Sgt,
                Opcode::V8I16Icmp {
                    cond: IntCC::SignedGreaterThan,
                },
            ),
        ] {
            let func = TrustIrFunc {
                summary: None,
                producer: None,
                value_names: None,
                scopes: None,
                source_provenance: None,
                attrs: Default::default(),
                id: FuncId::new(0),
                name: "narrow_select_compare_mask".to_string(),
                ty: FuncTyId::new(0),
                entry: BlockId::new(0),
                blocks: vec![TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![
                        (ValueId::new(0), payload_ty.clone()),
                        (ValueId::new(1), payload_ty.clone()),
                        (ValueId::new(2), payload_ty.clone()),
                        (ValueId::new(3), payload_ty.clone()),
                    ],
                    body: vec![
                        InstrNode {
                            inst: Inst::ICmp {
                                op: cmp_op,
                                ty: payload_ty.clone(),
                                lhs: ValueId::new(0),
                                rhs: ValueId::new(1),
                            },
                            results: vec![ValueId::new(4)],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        InstrNode {
                            inst: Inst::Select {
                                ty: payload_ty.clone(),
                                cond: ValueId::new(4),
                                then_val: ValueId::new(2),
                                else_val: ValueId::new(3),
                            },
                            results: vec![ValueId::new(5)],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        InstrNode {
                            inst: Inst::Return {
                                values: vec![ValueId::new(5)],
                            },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                    ],
                }],
                proofs: vec![],
                calling_conv: CallingConv::default(),
                linkage: Linkage::default(),
            };

            let module = make_module_for_func(&func);
            let (lir_func, _) = translate_func_test(&func, &module).unwrap();
            let entry = &lir_func.blocks[&lir_func.entry_block];
            assert_eq!(entry.instructions[0].opcode, expected_cmp);
            let select = entry
                .instructions
                .iter()
                .find(|inst| matches!(inst.opcode, Opcode::Select { .. }))
                .unwrap_or_else(|| panic!("{mask_ty:?} select should lower to LIR Select"));
            assert_eq!(
                select.opcode,
                Opcode::Select {
                    cond: IntCC::NotEqual
                }
            );
            assert_eq!(select.args, vec![Value(4), Value(2), Value(3)]);
            assert_eq!(lir_func.value_types.get(&Value(5)), Some(&Type::V128));
        }
    }

