    #[test]
    fn test_frem_f64_lowers_to_fmod_libcall() {
        let func = build_frem_func_unit("frem_f64", Ty::F64);
        let module = make_module_for_func(&func);
        let (lir, _) =
            translate_func_test(&func, &module).expect("f64 FRem should lower to fmod call");
        let entry = &lir.blocks[&lir.entry_block];
        assert!(
            entry
                .instructions
                .iter()
                .any(|inst| matches!(&inst.opcode, Opcode::Call { name } if name == "fmod")),
            "expected f64 FRem to lower to a call to fmod, got {:?}",
            entry.instructions
        );
    }

