    #[test]
    fn test_frem_f16_lowers_via_promoted_fmodf() {
        // f16 FRem lowers to promote(f16->f32) x2, `fmodf`, demote(f32->f16):
        // fmod is exact, so the f32 remainder is the f16-representable f16 rem.
        let func = build_frem_func_unit("frem_f16", Ty::F16);
        let module = make_module_for_func(&func);
        let (lir, _) =
            translate_func_test(&func, &module).expect("f16 FRem should lower via fmodf");
        let entry = &lir.blocks[&lir.entry_block];
        assert!(
            entry
                .instructions
                .iter()
                .any(|inst| matches!(&inst.opcode, Opcode::Call { name } if name == "fmodf")),
            "expected f16 FRem to call fmodf on the promoted operands, got {:?}",
            entry.instructions
        );
        assert!(
            entry
                .instructions
                .iter()
                .filter(|inst| matches!(inst.opcode, Opcode::FPExt))
                .count()
                == 2,
            "expected two f16->f32 promotions"
        );
        assert!(
            entry
                .instructions
                .iter()
                .any(|inst| matches!(inst.opcode, Opcode::FPTrunc)),
            "expected an f32->f16 demotion of the remainder"
        );
    }

