    #[test]
    fn test_extract_proofs_wrapping_yields_no_cpu_proof() {
        // `Wrapping` marks modular arithmetic: wrap-around IS the defined
        // result. The plain machine lowering (Iadd) already wraps, so the
        // annotation maps to no CPU proof — and it must NEVER surface as
        // `Proof::NoOverflow`, which asserts the opposite fact and would
        // license unsound check-elision/range optimizations.
        let node = InstrNode {
            inst: Inst::BinOp {
                op: BinOp::Add,
                ty: Ty::I32,
                lhs: ValueId::new(0),
                rhs: ValueId::new(1),
            },
            results: vec![ValueId::new(2)],
            proofs: vec![ProofAnnotation::Wrapping],
            span: None,
            proof_context: None,
            scope: None,
        };
        let proofs = extract_proofs(&node);
        assert!(
            proofs.is_empty(),
            "Wrapping must not fabricate any CPU proof, got {proofs:?}"
        );
        // Not a drop either: wrap semantics are the machine default, so no
        // drop diagnostic should be emitted.
        assert!(
            proof_drop_diagnostic_for_node(&ProofAnnotation::Wrapping, Some(&node)).is_none(),
            "Wrapping is not lost information; it must not produce a drop diagnostic"
        );
    }

