    #[test]
    fn test_extract_proof_drop_diagnostics_have_reason_codes() {
        let node = InstrNode {
            inst: Inst::Return { values: vec![] },
            results: vec![],
            proofs: vec![
                ProofAnnotation::AtomicOrdering(trust_ir::Ordering::SeqCst),
                ProofAnnotation::Custom(trust_ir::ProofTag::new(42)),
            ],
            span: None,
            proof_context: None,
            scope: None,
        };

        let diagnostics = extract_proof_diagnostics(&node);
        assert_eq!(diagnostics.len(), 2);
        assert_eq!(diagnostics[0].fact, "AtomicOrdering");
        assert_eq!(diagnostics[0].payload.as_deref(), Some("seq_cst"));
        assert_eq!(diagnostics[0].code, ProofDropCode::Unrepresentable);
        assert_eq!(diagnostics[0].code.as_str(), "present_unrepresentable");
        assert_eq!(diagnostics[1].fact, "Custom");
        assert_eq!(diagnostics[1].payload.as_deref(), Some("42"));
        assert_eq!(diagnostics[1].code, ProofDropCode::Custom);
        assert_eq!(diagnostics[1].code.as_str(), "custom_unsupported");
    }

    #[test]
    fn test_proof_propagation_through_adapter() {
        // Build a trust_ir function where the add instruction has NoOverflow proof.
        // Verify that after translation, the ProofContext has the proof on the
        // corresponding LIR value.
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "add_no_overflow".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I32), (ValueId::new(1), Ty::I32)],
                body: vec![
                    InstrNode {
                        inst: Inst::BinOp {
                            op: BinOp::Add,
                            ty: Ty::I32,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![ProofAnnotation::NoOverflow],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (_lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();

        // The result of the add (ValueId::new(2) -> some Value) should have NoOverflow.
        // Find the value that has proofs.
        assert!(
            !proof_ctx.value_proofs.is_empty(),
            "ProofContext should have proofs after translation"
        );

        // There should be exactly one value with proofs.
        let values_with_proofs: Vec<_> = proof_ctx
            .value_proofs
            .iter()
            .filter(|(_, proofs)| !proofs.is_empty())
            .collect();
        assert_eq!(
            values_with_proofs.len(),
            1,
            "Expected 1 value with proofs, got {}",
            values_with_proofs.len()
        );

        let (val, proofs) = values_with_proofs[0];
        assert!(
            proof_ctx.has_no_overflow(val),
            "The add result should have NoOverflow proof"
        );
        assert_eq!(proofs.len(), 1);
    }

    #[test]
    fn test_wrapping_annotated_add_lowers_with_no_overflow_claim() {
        // Mirror of test_proof_propagation_through_adapter, with `Wrapping`
        // instead of `NoOverflow`. The function must still lower successfully
        // (the plain machine add already implements the promised wrap
        // semantics), but the ProofContext must NOT claim NoOverflow for the
        // result — `Wrapping` asserts the opposite of `NoOverflow` — and no
        // drop diagnostic should be recorded.
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "add_wrapping".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I32), (ValueId::new(1), Ty::I32)],
                body: vec![
                    InstrNode {
                        inst: Inst::BinOp {
                            op: BinOp::Add,
                            ty: Ty::I32,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![ProofAnnotation::Wrapping],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (_lir_func, proof_ctx) = translate_func_test(&func, &module)
            .expect("Wrapping-annotated add must lower (plain machine add wraps)");

        // No CPU proof may be fabricated from `Wrapping` — in particular no
        // NoOverflow claim on any value.
        assert!(
            proof_ctx
                .value_proofs
                .values()
                .all(|proofs| !proofs.iter().any(|p| matches!(p, Proof::NoOverflow { .. }))),
            "Wrapping must not surface as a NoOverflow proof: {:?}",
            proof_ctx.value_proofs
        );
        // And it is not a dropped/unrepresentable annotation.
        assert!(
            proof_ctx.diagnostics.is_empty(),
            "Wrapping must not produce drop diagnostics: {:?}",
            proof_ctx.diagnostics
        );
    }

    #[test]
    fn test_no_overflow_on_overflow_inst_attaches_only_to_arithmetic_result() {
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "overflow_no_overflow_carrier".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
                body: vec![
                    InstrNode {
                        inst: Inst::Overflow {
                            op: OverflowOp::AddOverflow,
                            ty: Ty::I64,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2), ValueId::new(3)],
                        proofs: vec![ProofAnnotation::NoOverflow],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    // Keep the overflow FLAG (ValueId 3) LIVE so this stays on the legacy entangled
                    // path: this test pins the proof-ATTACHMENT mapping (NoOverflow lands on the
                    // arithmetic result, never the flag), independent of the carrier rewrite (which
                    // only fires when the flag is dead and seeds operand proofs — covered separately
                    // by `overflow_inst_*` tests).
                    InstrNode {
                        inst: Inst::Cast {
                            op: CastOp::ZExt,
                            src_ty: Ty::Bool,
                            dst_ty: Ty::I64,
                            operand: ValueId::new(3),
                        },
                        results: vec![ValueId::new(4)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (_, proof_ctx) = translate_func_test(&func, &module).unwrap();

        assert!(proof_ctx.has_no_overflow(&Value(2)));
        assert!(
            !proof_ctx.has_no_overflow(&Value(3)),
            "overflow flag result must not carry the arithmetic NoOverflow proof"
        );
        assert_eq!(proof_ctx.value_proofs.len(), 1);
    }

    /// Collect every emitted LIR opcode (across all blocks, in block order) for a translated fn.
    fn collect_lir_opcodes(func: &Function) -> Vec<Opcode> {
        func.block_order
            .iter()
            .filter_map(|b| func.blocks.get(b))
            .flat_map(|bb| bb.instructions.iter())
            .map(|inst| inst.opcode.clone())
            .collect()
    }

    /// Build a single-function module containing one `Inst::Overflow { I64 signed add }` whose flag
    /// result (result[1]) is DEAD (only the wrapped value is returned), optionally proof-annotated.
    fn overflow_inst_func_with_dead_flag(name: &str, proofs: Vec<ProofAnnotation>) -> TrustIrFunc {
        TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: name.to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
                body: vec![
                    InstrNode {
                        inst: Inst::Overflow {
                            op: OverflowOp::AddOverflow,
                            ty: Ty::I64,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        // result[0] = wrapped value (returned), result[1] = overflow flag (DEAD).
                        results: vec![ValueId::new(2), ValueId::new(3)],
                        proofs,
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        }
    }

    /// PRODUCTION rewrite: a real `Inst::Overflow` with a DISCHARGED NoOverflow proof whose flag is
    /// DEAD lowers through the eliminable `GuardOverflow` carrier (plain Iadd value op + carrier),
    /// NOT the legacy entangled `CheckedSadd` path. This is what lets the kernel gate eliminate the
    /// redundant overflow check in production code (default-on AArch64 carrier arch).
    #[test]
    fn overflow_inst_with_discharged_proof_dead_flag_emits_guard_overflow_carrier() {
        let func = overflow_inst_func_with_dead_flag(
            "overflow_proven_dead_flag",
            vec![ProofAnnotation::NoOverflow],
        );
        let module = make_module_for_func(&func);
        let (lir_func, _proof_ctx) = translate_func_test(&func, &module).unwrap();
        let opcodes = collect_lir_opcodes(&lir_func);

        // The decoupled carrier shape: a plain wrapping Iadd value op + a self-contained
        // GuardOverflow carrier (the overflow check). The legacy CheckedSadd must be GONE.
        assert!(
            opcodes
                .iter()
                .any(|op| matches!(op, Opcode::GuardOverflow { .. })),
            "a discharged-NoOverflow Inst::Overflow with a dead flag must emit a GuardOverflow \
             carrier; opcodes={opcodes:?}"
        );
        assert!(
            opcodes.iter().any(|op| matches!(op, Opcode::Iadd)),
            "the carrier path must materialize the value via a plain Iadd; opcodes={opcodes:?}"
        );
        assert!(
            !opcodes.iter().any(|op| matches!(op, Opcode::CheckedSadd)),
            "the carrier path must REPLACE the legacy entangled CheckedSadd; opcodes={opcodes:?}"
        );

        // The op-tag must encode (SignedAdd, width 64) so the kernel fingerprint binds the signed
        // proof to THIS carrier (a wrong op/width could never discharge it).
        let expected_tag = trust_cg_ir::pack_overflow_tag(trust_cg_ir::OverflowOp::SignedAdd, 64);
        let tag = opcodes.iter().find_map(|op| match op {
            Opcode::GuardOverflow { op_tag, .. } => Some(*op_tag),
            _ => None,
        });
        assert_eq!(
            tag,
            Some(expected_tag),
            "GuardOverflow op-tag must fold (SignedAdd, 64); opcodes={opcodes:?}"
        );
    }

    /// CRITERION-2 FRAGMENT (trust-cg side) — REFLEXIVITY-FORMULA emit + lineage.
    ///
    /// A REAL trust-cg lowering of a small TrustIr function (`fn(a:i64,b:i64) -> i64`
    /// computing a discharged-`NoOverflow` checked add with a dead overflow flag)
    /// produces a self-contained `GuardOverflow` carrier bound to a GENUINE proof
    /// obligation id. This test extracts that obligation and derives the `CleanCic`
    /// lineage digest the kernel re-derives for it. HONEST: the obligation's formula
    /// is a reflexivity tautology (see `overflow_carrier_reflexivity_formula`), so the
    /// lineage discriminates the (op,width) LABEL, not lowering correctness.
    ///
    /// This is the producer half of the live "compiler out of the TCB" leg: the
    /// obligation here is NOT hand-built; it is what `translate_function` actually
    /// emits. The clean-side companion (`clean-auto`
    /// `tests_trust_cg_obligation::*`) takes the SAME i64 signed-add no-overflow
    /// claim, routes it through the C1 BV path to a kernel-checked
    /// `ProofEvidence::CleanCic { term }` re-checked to `trust_count == 0`, and
    /// binds the lineage. The two halves are joined by the obligation descriptor,
    /// not by a cargo dependency (clean and trust-cg are deliberately decoupled).
    #[test]
    // HONEST: the "lineage" below is a digest of a REFLEXIVITY-TAUTOLOGY formula
    // (`overflow_carrier_reflexivity_formula`); it discriminates the (op,width)
    // LABEL, not correct-vs-incorrect lowerings, and no consumer gates on it.
    fn overflow_lowering_emits_obligation_with_reflexivity_formula_lineage() {
        use trust_ir::proof::{
            ObligationKind, ProofFormula, ProofObligation, ProofStatus, clean_cic_lineage_digest,
        };
        use trust_ir::value::ProofId;

        // 1. A REAL lowering of a real TrustIr function.
        let func = overflow_inst_func_with_dead_flag(
            "overflow_proven_dead_flag",
            vec![ProofAnnotation::NoOverflow],
        );
        let module = make_module_for_func(&func);
        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();

        // 2. The carrier the lowering emitted, and the obligation id bound to it.
        let opcodes = collect_lir_opcodes(&lir_func);
        let obligation_id = opcodes
            .iter()
            .find_map(|op| match op {
                Opcode::GuardOverflow { obligation, .. } => Some(*obligation),
                _ => None,
            })
            .expect("lowering must emit a GuardOverflow carrier")
            .expect("the discharged-NoOverflow carrier must carry an obligation id");

        // The obligation is GENUINE: the adapter synthesized it as Discharged FROM
        // the NoOverflow proof (no explicit ProofRef in this fixture), so it lives
        // in the reserved synthesized-id range and is recorded in the proof ctx.
        assert!(
            obligation_id >= ProofContext::SYNTHESIZED_OBLIGATION_BASE,
            "a synthesized-from-NoOverflow obligation must live in the reserved range; \
             got {obligation_id}"
        );
        assert!(
            proof_ctx.synthesized_discharged.contains(&obligation_id),
            "the carrier's obligation id must be the one the lowering actually synthesized; \
             id={obligation_id} synthesized={:?}",
            proof_ctx.synthesized_discharged
        );

        // 3. The trust-ir obligation this carrier discharges: an ArithmeticSafety
        //    NoOverflow claim on a 64-bit signed add. The carrier's op-tag pins
        //    (SignedAdd, 64), and — crucially — the obligation's BV formula is the
        //    one the LOWERING ITSELF emitted (not hand-built here): the adapter
        //    recorded the QF_BV reflexivity formula for this synthesized obligation,
        //    which we pull back out of the proof ctx. This is the producer-side BV
        //    currency the clean-side C1 path consumes.
        let emitted_formula = proof_ctx
            .synthesized_obligation_formula(obligation_id)
            .cloned()
            .expect("the lowering must have emitted a BV reflexivity formula for the carrier");
        assert_eq!(
            emitted_formula,
            ProofFormula::smtlib2("(not (= (bvadd a b) (bvadd a b)))", "(_ BitVec 64)"),
            "the emitted formula must be the SignedAdd@64 reflexivity tautology (bvadd a b == bvadd a b)"
        );
        let obligation = ProofObligation {
            id: ProofId::new(
                u32::try_from(obligation_id & u64::from(u32::MAX)).unwrap_or(u32::MAX),
            ),
            kind: ObligationKind::ArithmeticSafety,
            status: ProofStatus::Certified,
            description: "no signed overflow of i64 add".to_string(),
            // The BV-shaped claim the lowering emitted: `(bvadd a b) == (bvadd a b)`
            // — the add equals ITSELF (reflexivity tautology, NOT a machine-vs-IR
            // identity; certifies nothing about lowering faithfulness).
            formula: Some(emitted_formula),
            function: Some(func.id),
            // Synthetic test-only obligation: there is no frontend source span
            // or public obligation identity to claim.
            source: None,
            // No IR position: these are synthetic fixtures, and `site: None`
            // is the fail-closed reading (unbindable, never a wildcard).
            site: None,
        };

        // 4. The lineage digest for this obligation, folded into the kernel's u128
        //    lineage key by `guard_evidence::build_discharged_evidence_table` (see
        //    `obligation_lineage_key`). A DIFFERENT obligation (different
        //    id/kind/formula STRING) yields a DIFFERENT digest. HONEST: this is
        //    injectivity on the descriptor only — the formula is a tautology and no
        //    consumer gates on the digest, so "cannot be replayed" overstates it.
        let lineage = clean_cic_lineage_digest(&obligation);
        assert!(
            !lineage.is_zero(),
            "the lineage digest binding the CleanCic to this lowering must be non-trivial"
        );

        // Op-label check: change the claimed op (sub instead of add) ⇒ different
        // lineage. The sub formula is what a SignedSub@64 carrier WOULD emit. This
        // only shows the digest is injective on the op label (both formulas are
        // reflexivity tautologies); it is NOT a correctness gate.
        let tampered = ProofObligation {
            formula: Some(ProofContext::overflow_carrier_reflexivity_formula(
                trust_cg_ir::OverflowOp::SignedSub,
                64,
            )),
            ..obligation.clone()
        };
        assert_ne!(
            clean_cic_lineage_digest(&tampered).bytes,
            lineage.bytes,
            "a tampered lowering obligation must NOT produce the same lineage digest"
        );

        // 5. The matching lineage remains visible in the report, but production authority stays
        //    empty.  This is exactly why a self-consistent label/lineage pair cannot eliminate.
        let cert = trust_ir::proof::ProofCertificate {
            obligation: obligation.id,
            prover: "clean".to_string(),
            evidence: trust_ir::proof::ProofEvidence::CleanCic {
                // Non-empty kernel term: `obligation_has_matching_clean_cic`
                // certifies only a CleanCic cert that actually carries a term
                // (an empty term carries no real evidence).
                term: vec![1],
                context: vec![],
                lineage,
                kernel_recheck: None,
            },
        };
        let report = crate::guard_evidence::build_guard_evidence_report(
            std::slice::from_ref(&obligation),
            std::slice::from_ref(&cert),
        );
        let expected_lineage_key = crate::guard_evidence::obligation_lineage_key(&obligation);
        assert_eq!(
            report.observations()[0].lineage_key,
            Some(expected_lineage_key)
        );
        assert!(crate::guard_evidence::production_guard_replay_evidence().is_empty());
    }

    /// EMIT SIDE: the lowering attaches a QF_BV `ProofFormula` to the carrier's obligation.
    ///
    /// HONEST STATUS (downgraded 2026-06-18 after review): the emitted formula is a
    /// REFLEXIVITY TAUTOLOGY `(not (= (bvadd a b) (bvadd a b)))` over `(_ BitVec 64)`, NOT a
    /// lowering-correctness (TranslationValidation) identity. Both sides are the SAME IR term;
    /// it is built from the op-tag only and never references the machine instructions, so it
    /// cannot catch a lowering error. The clean C1 path re-checks its goal to
    /// `trust_count == 0`, but that count certifies a tautology.
    ///
    /// Asserts: (1) the formula is PRESENT and is the expected `(bvadd a b) == (bvadd a b)`
    /// reflexivity tautology; (2) it is genuine SMT-LIB2 (schema/payload/smtlib/sort all
    /// populated); (3) a DIFFERENT op LABEL (sub) or width yields a DIFFERENT formula STRING —
    /// i.e. the formula varies with the op-tag label. NOTE: (3) is injectivity on the label,
    /// NOT non-vacuity: every such string is itself a reflexivity tautology.
    #[test]
    fn overflow_lowering_emits_reflexivity_bv_formula_varying_by_op_label() {
        use trust_ir::proof::ProofFormula;

        // A REAL lowering of fn(a:i64,b:i64)->i64 — a discharged-NoOverflow signed checked
        // add with a dead overflow flag — through the eliminable GuardOverflow carrier.
        let func = overflow_inst_func_with_dead_flag(
            "overflow_emit_bv_formula",
            vec![ProofAnnotation::NoOverflow],
        );
        let module = make_module_for_func(&func);
        let (lir_func, proof_ctx) = translate_func_test(&func, &module).unwrap();

        // The synthesized obligation id the carrier was bound to.
        let opcodes = collect_lir_opcodes(&lir_func);
        let obligation_id = opcodes
            .iter()
            .find_map(|op| match op {
                Opcode::GuardOverflow { obligation, .. } => Some(*obligation),
                _ => None,
            })
            .expect("lowering must emit a GuardOverflow carrier")
            .expect("the discharged-NoOverflow carrier must carry an obligation id");

        // (1) The lowering recorded a BV formula for THIS obligation id.
        let formula = proof_ctx
            .synthesized_obligation_formula(obligation_id)
            .expect("the lowering must emit a BV reflexivity formula for the carrier");

        // (2) It is the expected SignedAdd@64 reflexivity tautology, as genuine SMT-LIB2.
        let expected = ProofFormula::smtlib2("(not (= (bvadd a b) (bvadd a b)))", "(_ BitVec 64)");
        assert_eq!(
            *formula, expected,
            "the emitted formula must be the SignedAdd@64 reflexivity tautology"
        );
        assert_eq!(formula.schema, "smtlib2");
        assert_eq!(formula.payload, "(not (= (bvadd a b) (bvadd a b)))");
        assert_eq!(
            formula.smtlib.as_deref(),
            Some("(not (= (bvadd a b) (bvadd a b)))"),
            "the formula must carry a machine-readable SMT-LIB2 rendering"
        );
        assert_eq!(formula.sort.as_deref(), Some("(_ BitVec 64)"));

        // (3) The formula VARIES BY OP LABEL: a different op tag (bvsub/bvmul) or width
        //     emits a DIFFERENT formula STRING. NOTE: this is injectivity on the label, NOT
        //     non-vacuity — each of add64/sub64/add32/mul64 is itself a reflexivity tautology.
        let add64 = ProofContext::overflow_carrier_reflexivity_formula(
            trust_cg_ir::OverflowOp::SignedAdd,
            64,
        );
        assert_eq!(*formula, add64, "the emitted formula must be SignedAdd@64");
        let sub64 = ProofContext::overflow_carrier_reflexivity_formula(
            trust_cg_ir::OverflowOp::SignedSub,
            64,
        );
        let add32 = ProofContext::overflow_carrier_reflexivity_formula(
            trust_cg_ir::OverflowOp::SignedAdd,
            32,
        );
        let mul64 = ProofContext::overflow_carrier_reflexivity_formula(
            trust_cg_ir::OverflowOp::SignedMul,
            64,
        );
        assert_ne!(
            *formula, sub64,
            "a bvsub op-label must yield a DIFFERENT formula string"
        );
        assert_ne!(
            *formula, add32,
            "a different width must yield a DIFFERENT formula string"
        );
        assert_ne!(
            *formula, mul64,
            "a bvmul op-label must yield a DIFFERENT formula string"
        );

        // And those distinct formula strings fold to distinct clean_cic lineage digests
        // (injectivity on the op-label/width; NOT a replay-rejection — no consumer gates on
        // the digest, and every formula here is a reflexivity tautology).
        use trust_ir::proof::{
            ObligationKind, ProofObligation, ProofStatus, clean_cic_lineage_digest,
        };
        use trust_ir::value::ProofId;
        let obl = |f: ProofFormula| ProofObligation {
            id: ProofId::new(7),
            kind: ObligationKind::TranslationValidation,
            status: ProofStatus::Certified,
            description: String::new(),
            formula: Some(f),
            function: None,
            // Synthetic digest-injectivity fixture, not a frontend claim.
            source: None,
            // No IR position: these are synthetic fixtures, and `site: None`
            // is the fail-closed reading (unbindable, never a wildcard).
            site: None,
        };
        let add_digest = clean_cic_lineage_digest(&obl(add64));
        assert_ne!(
            add_digest.bytes,
            clean_cic_lineage_digest(&obl(sub64)).bytes,
            "add vs sub op-label must yield distinct lineage digests (injectivity only)"
        );
        assert_ne!(
            add_digest.bytes,
            clean_cic_lineage_digest(&obl(mul64)).bytes,
            "add vs mul op-label must yield distinct lineage digests (injectivity only)"
        );
    }

    /// FAIL-SAFE: the SAME `Inst::Overflow` shape WITHOUT a NoOverflow proof keeps the LEGACY
    /// trapping/flagging `CheckedSadd` lowering byte-for-byte — NO GuardOverflow carrier is emitted.
    /// This is the prime-directive default-to-KEEP: an unproven overflow check is never eliminated.
    #[test]
    fn overflow_inst_without_proof_keeps_legacy_checked_path() {
        let func = overflow_inst_func_with_dead_flag("overflow_unproven", vec![]);
        let module = make_module_for_func(&func);
        let (lir_func, _proof_ctx) = translate_func_test(&func, &module).unwrap();
        let opcodes = collect_lir_opcodes(&lir_func);

        assert!(
            opcodes.iter().any(|op| matches!(op, Opcode::CheckedSadd)),
            "an unproven Inst::Overflow must keep the legacy CheckedSadd path; opcodes={opcodes:?}"
        );
        assert!(
            !opcodes
                .iter()
                .any(|op| matches!(op, Opcode::GuardOverflow { .. })),
            "an unproven Inst::Overflow must NOT emit a GuardOverflow carrier (default to KEEP); \
             opcodes={opcodes:?}"
        );
    }

    /// FAIL-SAFE: `ProofAnnotation::Wrapping` is NOT a no-overflow proof — it asserts the OPPOSITE
    /// (intentional two's-complement wrap). A Wrapping-annotated Inst::Overflow must keep the legacy
    /// path and must never be routed through the eliminable carrier.
    #[test]
    fn overflow_inst_with_wrapping_annotation_keeps_legacy_checked_path() {
        let func =
            overflow_inst_func_with_dead_flag("overflow_wrapping", vec![ProofAnnotation::Wrapping]);
        let module = make_module_for_func(&func);
        let (lir_func, _proof_ctx) = translate_func_test(&func, &module).unwrap();
        let opcodes = collect_lir_opcodes(&lir_func);

        assert!(
            opcodes.iter().any(|op| matches!(op, Opcode::CheckedSadd)),
            "a Wrapping-annotated Inst::Overflow must keep the legacy CheckedSadd path; \
             opcodes={opcodes:?}"
        );
        assert!(
            !opcodes
                .iter()
                .any(|op| matches!(op, Opcode::GuardOverflow { .. })),
            "Wrapping must NEVER be treated as no-overflow (it means intentional wrap); \
             opcodes={opcodes:?}"
        );
    }

    /// FAIL-SAFE: when the overflow FLAG (result[1]) is genuinely CONSUMED, the carrier rewrite must
    /// NOT fire even with a discharged NoOverflow proof — the legacy entangled CheckedSadd path is
    /// kept so the observable flag value is materialized, not folded away.
    #[test]
    fn overflow_inst_with_live_flag_keeps_legacy_checked_path() {
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "overflow_live_flag".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(0), Ty::I64), (ValueId::new(1), Ty::I64)],
                body: vec![
                    InstrNode {
                        inst: Inst::Overflow {
                            op: OverflowOp::AddOverflow,
                            ty: Ty::I64,
                            lhs: ValueId::new(0),
                            rhs: ValueId::new(1),
                        },
                        results: vec![ValueId::new(2), ValueId::new(3)],
                        proofs: vec![ProofAnnotation::NoOverflow],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    // The flag (ValueId 3) is CONSUMED here -> it is LIVE.
                    InstrNode {
                        inst: Inst::Cast {
                            op: CastOp::ZExt,
                            src_ty: Ty::Bool,
                            dst_ty: Ty::I64,
                            operand: ValueId::new(3),
                        },
                        results: vec![ValueId::new(4)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(4)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };
        let module = make_module_for_func(&func);
        let (lir_func, _proof_ctx) = translate_func_test(&func, &module).unwrap();
        let opcodes = collect_lir_opcodes(&lir_func);

        assert!(
            opcodes.iter().any(|op| matches!(op, Opcode::CheckedSadd)),
            "a LIVE overflow flag must keep the legacy CheckedSadd path so the flag is \
             materialized; opcodes={opcodes:?}"
        );
        assert!(
            !opcodes
                .iter()
                .any(|op| matches!(op, Opcode::GuardOverflow { .. })),
            "the carrier rewrite must not fire while the overflow flag is consumed; \
             opcodes={opcodes:?}"
        );
    }

    /// PRODUCTION rewrite (task #30): a discharged-NoOverflow signed checked MUL at width 64 with a
    /// DEAD flag routes through the eliminable `GuardOverflow` carrier (plain Imul value op + carrier
    /// with a SignedMul@64 op-tag), NOT the legacy entangled `CheckedSmul`. This is the mul mirror of
    /// `overflow_inst_with_discharged_proof_dead_flag_emits_guard_overflow_carrier`.
    #[test]
    fn overflow_inst_mul_with_proof_emits_guard_overflow_carrier() {
        let mut func = overflow_inst_func_with_dead_flag(
            "overflow_mul_proven",
            vec![ProofAnnotation::NoOverflow],
        );
        // Swap the op to MulOverflow (the helper builds an I64 add; type stays I64).
        if let Inst::Overflow { op, .. } = &mut func.blocks[0].body[0].inst {
            *op = OverflowOp::MulOverflow;
        }
        let module = make_module_for_func(&func);
        let (lir_func, _proof_ctx) = translate_func_test(&func, &module).unwrap();
        let opcodes = collect_lir_opcodes(&lir_func);

        assert!(
            opcodes
                .iter()
                .any(|op| matches!(op, Opcode::GuardOverflow { .. })),
            "a discharged-NoOverflow checked MUL@64 with a dead flag must emit a GuardOverflow \
             carrier; opcodes={opcodes:?}"
        );
        assert!(
            opcodes.iter().any(|op| matches!(op, Opcode::Imul)),
            "the mul carrier path must materialize the value via a plain Imul; opcodes={opcodes:?}"
        );
        assert!(
            !opcodes.iter().any(|op| matches!(op, Opcode::CheckedSmul)),
            "the carrier path must REPLACE the legacy entangled CheckedSmul; opcodes={opcodes:?}"
        );

        let expected_tag = trust_cg_ir::pack_overflow_tag(trust_cg_ir::OverflowOp::SignedMul, 64);
        let tag = opcodes.iter().find_map(|op| match op {
            Opcode::GuardOverflow { op_tag, .. } => Some(*op_tag),
            _ => None,
        });
        assert_eq!(
            tag,
            Some(expected_tag),
            "GuardOverflow op-tag must fold (SignedMul, 64); opcodes={opcodes:?}"
        );
    }

