    #[test]
    fn test_translate_call_preserves_symbol() {
        // Module with two functions: "callee" and "caller" which calls "callee".
        let module = Module {
            name: "call_test".to_string(),
            functions: vec![
                TrustIrFunc {
                    summary: None,
                    producer: None,
                    value_names: None,
                    scopes: None,
                    source_provenance: None,
                    attrs: Default::default(),
                    id: FuncId::new(0),
                    name: "callee".to_string(),
                    ty: FuncTyId::new(0),
                    entry: BlockId::new(0),
                    blocks: vec![TrustIrBlockDef {
                        id: BlockId::new(0),
                        params: vec![(ValueId::new(0), Ty::I32)],
                        body: vec![InstrNode {
                            inst: Inst::Return {
                                values: vec![ValueId::new(0)],
                            },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        }],
                    }],
                    proofs: vec![],
                    calling_conv: CallingConv::default(),
                    linkage: Linkage::default(),
                },
                TrustIrFunc {
                    summary: None,
                    producer: None,
                    value_names: None,
                    scopes: None,
                    source_provenance: None,
                    attrs: Default::default(),
                    id: FuncId::new(1),
                    name: "caller".to_string(),
                    ty: FuncTyId::new(0),
                    entry: BlockId::new(0),
                    blocks: vec![TrustIrBlockDef {
                        id: BlockId::new(0),
                        params: vec![(ValueId::new(0), Ty::I32)],
                        body: vec![
                            InstrNode {
                                inst: Inst::Call {
                                    callee: FuncId::new(0), // calls "callee"
                                    args: vec![ValueId::new(0)],
                                },
                                results: vec![ValueId::new(1)],
                                proofs: vec![],
                                span: None,
                                proof_context: None,
                                scope: None,
                            },
                            InstrNode {
                                inst: Inst::Return {
                                    values: vec![ValueId::new(1)],
                                },
                                results: vec![],
                                proofs: vec![],
                                span: None,
                                proof_context: None,
                                scope: None,
                            },
                        ],
                    }],
                    proofs: vec![],
                    calling_conv: CallingConv::default(),
                    linkage: Linkage::default(),
                },
            ],
            structs: vec![],
            records: vec![],
            closure_types: vec![],
            globals: vec![],
            func_types: vec![FuncTy {
                params: vec![Ty::I32],
                returns: vec![Ty::I32],
                is_vararg: false,
            }],
            types: vec![],
            proof_obligations: vec![],
            proof_certificates: vec![],
            enums: vec![],
            target_info: None,
            files: vec![],
            obligation_diagnostics: vec![],
            spec_modules: vec![],
            universes: vec![],
            predicates: vec![],
        };

        let results = translate_module(&module).unwrap();
        assert_eq!(results.len(), 2);

        // The caller function's first instruction should be Call with "callee" name.
        let (caller_func, _) = &results[1];
        assert_eq!(caller_func.name, "caller");
        let entry = &caller_func.blocks[&caller_func.entry_block];

        // First instruction should be Call with the resolved callee name.
        match &entry.instructions[0].opcode {
            Opcode::Call { name } => {
                assert_eq!(name, "callee", "Call target should resolve to 'callee'");
            }
            other => panic!("expected Call opcode, got {:?}", other),
        }

        // Call should have 1 arg (the parameter passed to callee).
        assert_eq!(entry.instructions[0].args.len(), 1);
        // Call should have 1 result (the return value).
        assert_eq!(entry.instructions[0].results.len(), 1);
    }

    #[test]
    fn test_translate_call_unknown_func_fails_closed() {
        // A direct Call to a FuncId that is not registered in the module
        // function table must FAIL CLOSED. Emitting a synthetic `__func_99`
        // GlobalRef would create a dangling relocation to a non-existent
        // symbol — a soundness hole this verified backend must not introduce
        // (see the conformance contract `check_call_unregistered_callee_fail_closed`).
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "main".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    InstrNode {
                        inst: Inst::Call {
                            callee: FuncId::new(99), // not in module
                            args: vec![],
                        },
                        results: vec![ValueId::new(0)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(0)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let err = translate_func_test(&func, &module)
            .expect_err("Call to an unregistered FuncId must fail closed");
        match err {
            AdapterError::UnsupportedInstruction(message) => {
                assert!(
                    message.contains("unregistered FuncId(99)"),
                    "expected unregistered-callee diagnostic, got `{message}`"
                );
            }
            other => panic!("expected UnsupportedInstruction, got {other:?}"),
        }
    }

    #[test]
    fn test_translate_condbr_preserves_condition_value() {
        // Build: fn choose(cond: bool, a: i32, b: i32) -> i32
        // entry: cmp a < b -> cond_val, condbr cond_val -> then, else
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "choose".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![
                TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![(ValueId::new(0), Ty::I32), (ValueId::new(1), Ty::I32)],
                    body: vec![
                        // Compare: cond = a < b
                        InstrNode {
                            inst: Inst::ICmp {
                                op: ICmpOp::Slt,
                                ty: Ty::I32,
                                lhs: ValueId::new(0),
                                rhs: ValueId::new(1),
                            },
                            results: vec![ValueId::new(2)],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        // CondBr: branch on comparison result
                        InstrNode {
                            inst: Inst::CondBr {
                                cond: ValueId::new(2),
                                then_target: BlockId::new(1),
                                then_args: vec![],
                                else_target: BlockId::new(2),
                                else_args: vec![],
                            },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                    ],
                },
                TrustIrBlockDef {
                    id: BlockId::new(1),
                    params: vec![],
                    body: vec![InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(0)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    }],
                },
                TrustIrBlockDef {
                    id: BlockId::new(2),
                    params: vec![],
                    body: vec![InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(1)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    }],
                },
            ],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];

        // First: Icmp with SignedLessThan condition
        match &entry.instructions[0].opcode {
            Opcode::Icmp { cond } => {
                assert_eq!(
                    *cond,
                    IntCC::SignedLessThan,
                    "CondCode should be preserved through adapter"
                );
            }
            other => panic!("expected Icmp, got {:?}", other),
        }

        // Second: Brif with condition value referencing the Icmp result
        match &entry.instructions[1].opcode {
            Opcode::Brif {
                cond,
                then_dest,
                else_dest,
            } => {
                // The cond value in Brif should match the result of the Icmp.
                let icmp_result = entry.instructions[0].results[0];
                assert_eq!(
                    *cond, icmp_result,
                    "Brif cond should reference the Icmp result value"
                );
                // Both destinations should be mapped.
                assert_ne!(
                    then_dest, else_dest,
                    "Then and else destinations should be different blocks"
                );
            }
            other => panic!("expected Brif, got {:?}", other),
        }
    }

