    #[test]
    fn test_translate_type_uint_variants() {
        // Unsigned types should map to the same LIR type as signed
        assert_eq!(translate_type(&Ty::I8).unwrap(), Type::I8);
        assert_eq!(translate_type(&Ty::I16).unwrap(), Type::I16);
        assert_eq!(translate_type(&Ty::I128).unwrap(), Type::I128);
    }

    #[test]
    fn test_translate_type_unsupported_types_error() {
        // With nested enum representation, invalid bit widths are prevented by
        // construction (IntWidth/FloatWidth enums). Test that other unsupported
        // types produce errors.
        // `Ty::Unit` now lowers to a ZST — see
        // `test_translate_type_unit_is_a_zst_and_never_still_errors`.
        assert!(translate_type(&Ty::Never).is_err());
        // `Ty::Enum` requires the module enum table; the public
        // `translate_type` helper has none, so it must still reject here.
        // `Ty::Func` now lowers to I64 — see `test_translate_type_func_is_i64`.
    }

    #[test]
    fn test_translate_type_func_is_i64() {
        // #443 Phase 2c: function-pointer types lower to 64-bit scalars
        // (AArch64 pointer width), enabling closure-style aggregates.
        let func_ty = Ty::Func(FuncTyId::new(0));
        assert_eq!(translate_type(&func_ty).unwrap(), Type::I64);
    }

    #[test]
    fn test_translate_type_nested_ptr() {
        // Ptr(Ptr(Int(32))) -> I64 (all pointers are 64-bit)
        let ty = Ty::Ptr;
        assert_eq!(translate_type(&ty).unwrap(), Type::I64);
    }

    #[test]
    fn pointer_metadata_ops_lower_thin_and_fat_pointer_shapes() {
        let fat_ptr = Ty::FatPtr(FatPtrKind::Str);
        let (func, module) = make_func(
            FuncId::new(0),
            "ptr_metadata_ops",
            FuncTy {
                params: vec![Ty::Ptr, Ty::U64, Ty::Ptr],
                returns: vec![Ty::Ptr, Ty::U64, Ty::Ptr],
                is_vararg: false,
            },
            BlockId::new(0),
            vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![
                    (ValueId::new(0), Ty::Ptr),
                    (ValueId::new(1), Ty::U64),
                    (ValueId::new(6), Ty::Ptr),
                ],
                body: vec![
                    InstrNode::new(Inst::PtrFromParts {
                        ptr_ty: fat_ptr.clone(),
                        metadata_ty: Ty::U64,
                        data: ValueId::new(0),
                        metadata: ValueId::new(1),
                    })
                    .with_result(ValueId::new(2)),
                    InstrNode::new(Inst::PtrData {
                        ptr_ty: fat_ptr.clone(),
                        ptr: ValueId::new(2),
                    })
                    .with_result(ValueId::new(3)),
                    InstrNode::new(Inst::PtrMetadata {
                        ptr_ty: fat_ptr,
                        metadata_ty: Ty::U64,
                        ptr: ValueId::new(2),
                    })
                    .with_result(ValueId::new(4)),
                    InstrNode::new(Inst::PtrData {
                        ptr_ty: Ty::Ptr,
                        ptr: ValueId::new(6),
                    })
                    .with_result(ValueId::new(7)),
                    InstrNode::new(Inst::Return {
                        values: vec![ValueId::new(3), ValueId::new(4), ValueId::new(7)],
                    }),
                ],
            }],
            vec![],
        );

        let (lowered, _) = translate_func_test(&func, &module).unwrap();
        let entry = lowered.blocks.get(&Block(0)).expect("entry block");

        assert!(entry.instructions.iter().any(|inst| {
            matches!(
                inst.opcode,
                Opcode::StackAddr { .. }
                    | Opcode::StructGep { .. }
                    | Opcode::Store { .. }
                    | Opcode::Load { .. }
            )
        }));
        assert!(
            entry
                .instructions
                .iter()
                .any(|inst| matches!(inst.opcode, Opcode::StructGep { field_index: 1, .. })),
            "fat pointer metadata lane should use explicit field 1 extraction"
        );
        assert!(
            entry
                .instructions
                .iter()
                .any(|inst| matches!(inst.opcode, Opcode::Copy) && inst.args == vec![Value(2)]),
            "thin PtrData should lower to a direct copy"
        );
    }

