    #[test]
    fn test_translate_multi_block_with_phi() {
        // Simple diamond: entry -> then/else -> (implicit merge via return)
        let func = TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "diamond".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![
                TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![(ValueId::new(0), Ty::Bool), (ValueId::new(1), Ty::I32)],
                    body: vec![
                        InstrNode {
                            inst: Inst::Const {
                                ty: Ty::I32,
                                value: Constant::Int(42),
                            },
                            results: vec![ValueId::new(2)],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                        InstrNode {
                            inst: Inst::CondBr {
                                cond: ValueId::new(0),
                                then_target: BlockId::new(1),
                                then_args: vec![],
                                else_target: BlockId::new(2),
                                else_args: vec![],
                            },
                            results: vec![],
                            proofs: vec![],
                            span: None,
                            proof_context: None,
                            scope: None,
                        },
                    ],
                },
                TrustIrBlockDef {
                    id: BlockId::new(1),
                    params: vec![],
                    body: vec![InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(1)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    }],
                },
                TrustIrBlockDef {
                    id: BlockId::new(2),
                    params: vec![],
                    body: vec![InstrNode {
                        inst: Inst::Return {
                            values: vec![ValueId::new(2)],
                        },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    }],
                },
            ],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        };

        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        assert_eq!(lir_func.blocks.len(), 3);

        // Entry block should have: Iconst + Brif = 2 instructions
        let entry = &lir_func.blocks[&lir_func.entry_block];
        assert_eq!(entry.instructions.len(), 2);
        assert!(matches!(
            entry.instructions[0].opcode,
            Opcode::Iconst { .. }
        ));
        assert!(matches!(entry.instructions[1].opcode, Opcode::Brif { .. }));
    }

