    #[test]
    fn test_translate_module_two_functions() {
        let mut module = Module::new("two_funcs");
        let ft0 = module.add_func_type(FuncTy {
            params: vec![],
            returns: vec![Ty::I32],
            is_vararg: false,
        });
        let ft1 = module.add_func_type(FuncTy {
            params: vec![Ty::F64],
            returns: vec![Ty::F64],
            is_vararg: false,
        });

        let mut func1 = TrustIrFunc::new(FuncId::new(0), "first", ft0, BlockId::new(0));
        func1.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![],
            body: vec![
                InstrNode {
                    inst: Inst::Const {
                        ty: Ty::I32,
                        value: Constant::Int(1),
                    },
                    results: vec![ValueId::new(0)],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
                InstrNode {
                    inst: Inst::Return {
                        values: vec![ValueId::new(0)],
                    },
                    results: vec![],
                    proofs: vec![],
                    span: None,
                    proof_context: None,
                    scope: None,
                },
            ],
        }];
        module.add_function(func1);

        let mut func2 = TrustIrFunc::new(FuncId::new(1), "second", ft1, BlockId::new(0));
        func2.blocks = vec![TrustIrBlockDef {
            id: BlockId::new(0),
            params: vec![(ValueId::new(0), Ty::F64)],
            body: vec![InstrNode {
                inst: Inst::Return {
                    values: vec![ValueId::new(0)],
                },
                results: vec![],
                proofs: vec![],
                span: None,
                proof_context: None,
                scope: None,
            }],
        }];
        module.add_function(func2);

        let results = translate_module(&module).unwrap();
        assert_eq!(results.len(), 2);

        let (func1, _) = &results[0];
        assert_eq!(func1.name, "first");
        assert_eq!(func1.signature.params.len(), 0);
        assert_eq!(func1.signature.returns, vec![Type::I32]);

        let (func2, _) = &results[1];
        assert_eq!(func2.name, "second");
        assert_eq!(func2.signature.params, vec![Type::F64]);
        assert_eq!(func2.signature.returns, vec![Type::F64]);
    }

