    // ----- Stack slot aliasing fix (issue #278) -----

    /// Build a trust_ir function with 3 Alloc instructions of different types.
    ///
    /// ```pseudo
    /// fn multi_alloc() {
    ///   %0 = alloca i32      // 4 bytes, align 4
    ///   %1 = alloca i64      // 8 bytes, align 8
    ///   %2 = alloca i8       // 1 byte, align 1
    ///   return
    /// }
    /// ```
    fn build_multi_alloc_func() -> TrustIrFunc {
        TrustIrFunc {
            summary: None,
            producer: None,
            value_names: None,
            scopes: None,
            source_provenance: None,
            attrs: Default::default(),
            id: FuncId::new(0),
            name: "multi_alloc".to_string(),
            ty: FuncTyId::new(0),
            entry: BlockId::new(0),
            blocks: vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    InstrNode {
                        inst: Inst::Alloca {
                            ty: Ty::I32,
                            count: None,
                            align: None,
                        },
                        results: vec![ValueId::new(0)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Alloca {
                            ty: Ty::I64,
                            count: None,
                            align: None,
                        },
                        results: vec![ValueId::new(1)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Alloca {
                            ty: Ty::I8,
                            count: None,
                            align: None,
                        },
                        results: vec![ValueId::new(2)],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                    InstrNode {
                        inst: Inst::Return { values: vec![] },
                        results: vec![],
                        proofs: vec![],
                        span: None,
                        proof_context: None,
                        scope: None,
                    },
                ],
            }],
            proofs: vec![],
            calling_conv: CallingConv::default(),
            linkage: Linkage::default(),
        }
    }

    #[test]
    fn test_alloc_unique_slot_indices() {
        // Issue #278: multiple Alloc instructions must get distinct slot indices.
        let func = build_multi_alloc_func();
        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();

        // Collect all StackAddr slot indices from the LIR instructions.
        let mut slot_indices = Vec::new();
        for bb in lir_func.blocks.values() {
            for inst in &bb.instructions {
                if let Opcode::StackAddr { slot } = inst.opcode {
                    slot_indices.push(slot);
                }
            }
        }

        // We should have exactly 3 StackAddr instructions (one per Alloc).
        assert_eq!(
            slot_indices.len(),
            3,
            "Expected 3 StackAddr instructions, got {}",
            slot_indices.len()
        );

        // All slot indices must be distinct.
        slot_indices.sort();
        assert_eq!(slot_indices[0], 0, "First slot should be 0");
        assert_eq!(slot_indices[1], 1, "Second slot should be 1");
        assert_eq!(slot_indices[2], 2, "Third slot should be 2");
    }

    #[test]
    fn test_alloc_stack_slots_populated() {
        // Issue #278: LIR Function.stack_slots must have entries for all allocated slots.
        let func = build_multi_alloc_func();
        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();

        assert_eq!(
            lir_func.stack_slots.len(),
            3,
            "Expected 3 stack slot entries, got {}",
            lir_func.stack_slots.len()
        );

        // Verify sizes and alignments match the Alloc types.
        // Slot 0: i32 -> 4 bytes, align 4
        assert_eq!(lir_func.stack_slots[0].size, 4);
        assert_eq!(lir_func.stack_slots[0].align, 4);
        // Slot 1: i64 -> 8 bytes, align 8
        assert_eq!(lir_func.stack_slots[1].size, 8);
        assert_eq!(lir_func.stack_slots[1].align, 8);
        // Slot 2: i8 -> 1 byte, align 1
        assert_eq!(lir_func.stack_slots[2].size, 1);
        assert_eq!(lir_func.stack_slots[2].align, 1);
    }

    #[test]
    fn entry_signature_mismatch_fails_before_formal_value_aliasing() {
        let tuple_ty = Ty::Tuple(vec![Ty::I64, Ty::I64, Ty::I64]);
        let (func, module) = make_func(
            FuncId::new(0),
            "bad_shim_signature",
            FuncTy {
                params: vec![Ty::Ptr, tuple_ty.clone()],
                returns: vec![],
                is_vararg: false,
            },
            BlockId::new(0),
            vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(2), tuple_ty.clone())],
                body: vec![
                    InstrNode::new(Inst::Alloca {
                        ty: tuple_ty,
                        count: None,
                        align: Some(8),
                    })
                    .with_result(ValueId::new(4)),
                    InstrNode::new(Inst::Return { values: vec![] }),
                ],
            }],
            vec![],
        );

        let err = translate_func_test(&func, &module).unwrap_err();
        assert!(matches!(
            err,
            AdapterError::EntryParamArityMismatch(ref name, 1, 2)
                if name == "bad_shim_signature"
        ));

        let (func, module) = make_func(
            FuncId::new(0),
            "bad_shim_param_type",
            FuncTy {
                params: vec![Ty::I64],
                returns: vec![],
                is_vararg: false,
            },
            BlockId::new(0),
            vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![(ValueId::new(2), Ty::I32)],
                body: vec![InstrNode::new(Inst::Return { values: vec![] })],
            }],
            vec![],
        );

        let err = translate_func_test(&func, &module).unwrap_err();
        assert!(matches!(
            err,
            AdapterError::EntryParamTypeMismatch(ref name, 0, Type::I32, Type::I64)
                if name == "bad_shim_param_type"
        ));
    }

    #[test]
    fn entry_formals_are_reserved_before_non_entry_block_values() {
        let entry_param = ValueId::new(99);
        let non_entry_result = ValueId::new(7);
        let (func, module) = make_func(
            FuncId::new(0),
            "out_of_order_blocks",
            FuncTy {
                params: vec![Ty::I64],
                returns: vec![Ty::I64],
                is_vararg: false,
            },
            BlockId::new(0),
            // Deliberately store a non-entry block first. Formal Values must
            // still occupy the leading internal indices used by ISel.
            vec![
                TrustIrBlockDef {
                    id: BlockId::new(1),
                    params: vec![],
                    body: vec![
                        InstrNode::new(Inst::Const {
                            ty: Ty::I64,
                            value: Constant::Int(7),
                        })
                        .with_result(non_entry_result),
                        InstrNode::new(Inst::Unreachable),
                    ],
                },
                TrustIrBlockDef {
                    id: BlockId::new(0),
                    params: vec![(entry_param, Ty::I64)],
                    body: vec![InstrNode::new(Inst::Return {
                        values: vec![entry_param],
                    })],
                },
            ],
            vec![],
        );

        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let entry = &lir_func.blocks[&lir_func.entry_block];
        assert_eq!(entry.params[0].0, Value(0));
        let non_entry = &lir_func.blocks[&Block(1)];
        assert_eq!(non_entry.instructions[0].results, vec![Value(1)]);
    }

    #[test]
    fn aggregate_alloca_result_is_an_i64_pointer_carrier() {
        let tuple_ty = Ty::Tuple(vec![Ty::I64, Ty::I64, Ty::I64]);
        let alloca = ValueId::new(4);
        let loaded = ValueId::new(5);
        let (func, module) = make_func(
            FuncId::new(0),
            "aggregate_alloca_pointer",
            FuncTy {
                params: vec![],
                returns: vec![],
                is_vararg: false,
            },
            BlockId::new(0),
            vec![TrustIrBlockDef {
                id: BlockId::new(0),
                params: vec![],
                body: vec![
                    InstrNode::new(Inst::Alloca {
                        ty: tuple_ty,
                        count: None,
                        align: Some(8),
                    })
                    .with_result(alloca),
                    InstrNode::new(Inst::Load {
                        ty: Ty::I64,
                        ptr: alloca,
                        volatile: false,
                        align: Some(8),
                    })
                    .with_result(loaded),
                    InstrNode::new(Inst::Return { values: vec![] }),
                ],
            }],
            vec![],
        );

        let (lir_func, _) = translate_func_test(&func, &module).unwrap();
        let stack_addr = lir_func.blocks[&lir_func.entry_block]
            .instructions
            .iter()
            .find(|inst| matches!(inst.opcode, Opcode::StackAddr { .. }))
            .expect("aggregate Alloca must lower to StackAddr");
        assert_eq!(
            lir_func.value_types.get(&stack_addr.results[0]),
            Some(&Type::I64)
        );
    }

    #[test]
    fn test_alloc_fixed_scalar_debug_locals_use_provenance_vars() {
        let func = build_multi_alloc_func();
        let module = make_module_for_func(&func);
        let (lir_func, _) = translate_func_test(&func, &module).unwrap();

        assert_eq!(lir_func.debug_meta.local_variables.len(), 3);
        for (slot, local) in lir_func.debug_meta.local_variables.iter().enumerate() {
            assert_eq!(local.name, format!("local_{slot}"));
            assert_eq!(
                local.storage,
                DebugVariableStorage::ProvenanceVar(TrustIrVarId(
                    ALLOCA_DEBUG_PROVENANCE_VAR_TAG | slot as u32
                ))
            );
        }
    }

