    #[test]
    fn is_objectsize_intrinsic_detection() {
        assert_eq!(
            super::objectsize_intrinsic_bitwidth("llvm.objectsize.i64.p0"),
            Some(64)
        );
        assert_eq!(
            super::objectsize_intrinsic_bitwidth("llvm.objectsize.i32.p0"),
            Some(32)
        );
        assert_eq!(
            super::objectsize_intrinsic_bitwidth("llvm.objectsize.i64.p1"),
            None
        );
        assert_eq!(super::objectsize_intrinsic_bitwidth("objectsize"), None);
    }

    #[test]
    fn fma_intrinsic_contract_distinguishes_optional_and_required_fusion() {
        assert_eq!(
            super::fma_intrinsic_contract("llvm.fmuladd.f32"),
            Some((Type::F32, true))
        );
        assert_eq!(
            super::fma_intrinsic_contract("llvm.fmuladd.f64"),
            Some((Type::F64, true))
        );
        assert_eq!(
            super::fma_intrinsic_contract("llvm.fma.f32"),
            Some((Type::F32, false))
        );
        assert_eq!(
            super::fma_intrinsic_contract("llvm.fma.f64"),
            Some((Type::F64, false))
        );
        assert_eq!(super::fma_intrinsic_contract("llvm.fma.f16"), None);
    }

    #[test]
    fn adapter_lowers_objectsize_static_unknown_without_call() {
        let module = objectsize_test_module(false, true, false);

        let results = translate_module(&module).unwrap();
        assert_eq!(
            results.len(),
            1,
            "external declarations are not codegen units"
        );
        let (caller_func, _) = &results[0];
        let entry = &caller_func.blocks[&caller_func.entry_block];
        let opcodes: Vec<&Opcode> = entry.instructions.iter().map(|i| &i.opcode).collect();

        assert!(
            !entry.instructions.iter().any(|inst| {
                matches!(&inst.opcode, Opcode::Call { name } if name.starts_with("llvm.objectsize"))
            }),
            "objectsize intrinsic should fold instead of leaving a call: {opcodes:?}"
        );
        assert!(
            entry.instructions.iter().any(|inst| {
                matches!(
                    &inst.opcode,
                    Opcode::Iconst {
                        ty: Type::I64,
                        imm: -1
                    }
                )
            }),
            "expected conservative unknown object size -1: {opcodes:?}"
        );
    }

    #[test]
    fn adapter_rejects_objectsize_dynamic_mode() {
        let module = objectsize_test_module(false, true, true);

        let err = translate_module(&module).expect_err("dynamic objectsize should fail closed");
        let msg = err.to_string();
        assert!(
            msg.contains("llvm.objectsize") && msg.contains("dynamic=true"),
            "unexpected error: {msg}"
        );
    }

